INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95955, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "全等是两个图形大小形状都一样，放在一起正好盖住。", "primary_collocate": null, "pronunciation": "quán děng", "ipa": "tɕʰɥɛn˧˥ tɤŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这两张卡片大小一样，是全等的。", "target_word": "全等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把两个全等的图形放在一起，正好盖住。", "target_word": "全等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个三角形全等吗？", "target_word": "全等", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "全等的意思是大小和形状都一样。", "target_word": "全等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个长方形不是全等的。", "target_word": "全等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能找出图中全等的三角形吗？", "target_word": "全等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "课本上有两个全等的梯形。", "target_word": "全等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我用尺子量了一下，发现两个图形全等。", "target_word": "全等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大小形状都一样，它们就全等。", "target_word": "全等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子上的两张纸片全等。", "target_word": "全等", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "全等三角形", "label": "复合"}, {"form": "全等形", "label": "复合"}], "register": "书面", "sense_fingerprint": "两个图形大小形状一样，叠放能正好盖住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ea03b26-13d4-42c6-b4dd-6754678089d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95955, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "全等", "is_correct": true, "explanation": "正确答案。全等（quán děng）：两个图形大小形状一样，叠放能正好盖住。"}, {"text": "全能", "is_correct": false, "explanation": "quán néng 与 quán děng 声母不同（n 与 d），声调也不同（第二声），意思是全能、无所不能。"}, {"text": "全党", "is_correct": false, "explanation": "quán dǎng 与 quán děng 韵母不同（ang 与 eng），声调相同，意思是全党、整个政党。"}, {"text": "全当", "is_correct": false, "explanation": "quán dāng 与 quán děng 韵母不同（ang 与 eng），声调也不同（第一声），意思是全当作、全当成。"}], "explanations": {"全等": "正确答案。全等（quán děng）：两个图形大小形状一样，叠放能正好盖住。", "全能": "quán néng 与 quán děng 声母不同（n 与 d），声调也不同（第二声），意思是全能、无所不能。", "全党": "quán dǎng 与 quán děng 韵母不同（ang 与 eng），声调相同，意思是全党、整个政党。", "全当": "quán dāng 与 quán děng 韵母不同（ang 与 eng），声调也不同（第一声），意思是全当作、全当成。"}, "sentence_index": null, "correct_answer": "全等"}, "level_3": {"options": [{"text": "全等", "is_correct": true, "explanation": "正确答案。“全等”作“是……的”的谓语，表示两张卡片大小形状一样，符合句意。"}, {"text": "悬殊", "is_correct": false, "explanation": "语义：“悬殊”指差距很大，与前句“大小一样”相矛盾。"}, {"text": "滚烫", "is_correct": false, "explanation": "语义：“滚烫”描写温度，与卡片大小形状一样的句意无关。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描写个头或体型，与卡片不搭配。"}], "explanations": {"全等": "正确答案。“全等”作“是……的”的谓语，表示两张卡片大小形状一样，符合句意。", "悬殊": "语义：“悬殊”指差距很大，与前句“大小一样”相矛盾。", "滚烫": "语义：“滚烫”描写温度，与卡片大小形状一样的句意无关。", "高大": "体貌：“高大”描写个头或体型，与卡片不搭配。"}, "sentence_index": 0, "correct_answer": "全等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两张照片全等，只是大小不同。", "explanation": "这里应该用〈相似〉。全等要求大小和形状都相同，这里说大小不同，应用〈相似〉。"}, {"text": "我们两个班的人数全等。", "explanation": "这里应该用〈相等〉。全等只用于图形，人数的多少应说“相等”。"}, {"text": "我和你的个子全等。", "explanation": "这里应该用〈一样高〉。全等是图形的术语，人的身高不能说全等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95955, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全等", "is_correct": true, "explanation": "正确答案。“全等”作定语修饰“梯形”，表示两个梯形形状和大小相同，符合句意。"}, {"text": "迷人", "is_correct": false, "explanation": "语义：“迷人”形容吸引人的魅力，不能用来描述梯形。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：“高兴”描写情绪，只能修饰有感情的人，不能修饰“梯形”。"}, {"text": "柔软", "is_correct": false, "explanation": "体貌：“柔软”描写质地，梯形是几何图形，不能是柔软的。"}], "explanations": {"全等": "正确答案。“全等”作定语修饰“梯形”，表示两个梯形形状和大小相同，符合句意。", "迷人": "语义：“迷人”形容吸引人的魅力，不能用来描述梯形。", "高兴": "搭配：“高兴”描写情绪，只能修饰有感情的人，不能修饰“梯形”。", "柔软": "体貌：“柔软”描写质地，梯形是几何图形，不能是柔软的。"}, "sentence_index": 6, "correct_answer": "全等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两本书的价钱全等。", "explanation": "这里应该用〈一样〉。全等只用于图形的形状和大小，价钱不能说全等。"}, {"text": "两片树叶全等在一起。", "explanation": "这里应该用〈重叠〉。全等描述两个图形的形状和大小，不描述位置关系。"}, {"text": "我们俩的看法全等。", "explanation": "这里应该用〈相同〉。全等只用于图形，人的看法不能说全等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95955, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个图形很全等。", "corrected_sentence": "这两个图形全等。", "error_description": "“全等”是绝对形容词，表示完全相同，不能用“很”修饰。错误句“很全等”应改为“全等”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95955, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两块地砖是全等地。", "corrected_sentence": "这两块地砖是全等的。", "error_description": "“是……的”结构中的“全等”后面要用“的”，不用“地”（“地”只用于修饰动词、形容词的状语）。错误句“是全等地”应改为“是全等的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
