INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95956, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "数学上指两个图形的形状和大小完全相同，能够重合。", "primary_collocate": null, "pronunciation": "quán děng", "ipa": "tɕʰɥɛn˧˥ tɤŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这两个三角形是全等的。", "target_word": "全等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全等图形的大小和形状都相同。", "target_word": "全等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说这两个三角形全等。", "target_word": "全等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个全等的三角形可以完全重合。", "target_word": "全等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要证明这两个图形全等。", "target_word": "全等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个正方形不全等，因为大小不同。", "target_word": "全等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学了全等的条件。", "target_word": "全等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两块地砖看起来全等。", "target_word": "全等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个三角形三条边分别相等，所以它们全等。", "target_word": "全等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在黑板上画了两个全等的圆。", "target_word": "全等", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "全等三角形", "label": "复合"}, {"form": "全等形", "label": "复合"}], "register": "书面", "sense_fingerprint": "数学中两个图形形状大小完全相同、能够重合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ea03b26-13d4-42c6-b4dd-6754678089d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, v