INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95956, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "全等", "is_correct": true, "explanation": "正确答案。全等（quán děng）：数学上指两个图形形状和大小完全相同，能够重合。"}, {"text": "全能", "is_correct": false, "explanation": "quán néng 与 quán děng 声母不同（n 与 d），声调也不同（第二声），意思是全能、无所不能。"}, {"text": "全党", "is_correct": false, "explanation": "quán dǎng 与 quán děng 韵母不同（ang 与 eng），声调相同，意思是全党、整个政党。"}, {"text": "全当", "is_correct": false, "explanation": "quán dāng 与 quán děng 韵母不同（ang 与 eng），声调也不同（第一声），意思是全当作、全当成。"}], "explanations": {"全等": "正确答案。全等（quán děng）：数学上指两个图形形状和大小完全相同，能够重合。", "全能": "quán néng 与 quán děng 声母不同（n 与 d），声调也不同（第二声），意思是全能、无所不能。", "全党": "quán dǎng 与 quán děng 韵母不同（ang 与 eng），声调相同，意思是全党、整个政党。", "全当": "quán dāng 与 quán děng 韵母不同（ang 与 eng），声调也不同（第一声），意思是全当作、全当成。"}, "sentence_index": null, "correct_answer": "全等"}, "level_3": {"options": [{"text": "全等", "is_correct": true, "explanation": "正确答案。“全等”作谓语，描述两个三角形形状和大小都相同，符合句意。"}, {"text": "平行", "is_correct": false, "explanation": "搭配：“平行”多用于直线、平面，不能说三角形整体是平行的。"}, {"text": "圆", "is_correct": false, "explanation": "语义：三角形有三条直边，不能说它是圆的。"}, {"text": "弯曲", "is_correct": false, "explanation": "体貌：“弯曲”描写形状，与三角形的直边相矛盾。"}], "explanations": {"全等": "正确答案。“全等”作谓语，描述两个三角形形状和大小都相同，符合句意。", "平行": "搭配：“平行”多用于直线、平面，不能说三角形整体是平行的。", "圆": "语义：三角形有三条直边，不能说它是圆的。", "弯曲": "体貌：“弯曲”描写形状，与三角形的直边相矛盾。"}, "sentence_index": 0, "correct_answer": "全等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两个三角形全等，但大小不同。", "explanation": "这里应该用〈相似〉。全等要求形状和大小都相同，而句子说大小不同，应用〈相似〉。"}, {"text": "我和你的身高全等。", "explanation": "这里应该用〈一样高〉。全等是数学术语，只用于图形，人的身高不能说全等。"}, {"text": "这两个数全等。", "explanation": "这里应该用〈相等〉。全等只用于两个图形，两个数的大小一样应说“相等”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET 