INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95956, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全等", "is_correct": true, "explanation": "正确答案。“全等”作定语修饰“条件”，指图形相等的条件，符合句意。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：“条件”是抽象的标准，不能说是甜蜜的。"}, {"text": "流行", "is_correct": false, "explanation": "搭配：“流行”修饰的是歌曲、款式等，不能修饰“条件”。"}, {"text": "鲜艳", "is_correct": false, "explanation": "体貌：“鲜艳”描写颜色，与“条件”不搭配。"}], "explanations": {"全等": "正确答案。“全等”作定语修饰“条件”，指图形相等的条件，符合句意。", "甜蜜": "语义：“条件”是抽象的标准，不能说是甜蜜的。", "流行": "搭配：“流行”修饰的是歌曲、款式等，不能修饰“条件”。", "鲜艳": "体貌：“鲜艳”描写颜色，与“条件”不搭配。"}, "sentence_index": 6, "correct_answer": "全等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两本书的价钱全等。", "explanation": "这里应该用〈一样〉。全等只用于图形的形状和大小，价钱不能说全等。"}, {"text": "两片树叶全等在一起。", "explanation": "这里应该用〈重叠〉。全等描述两个图形的形状和大小，不描述位置关系。"}, {"text": "我们俩的看法全等。", "explanation": "这里应该用〈相同〉。全等只用于图形，人的看法不能说全等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95956, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个正方形很全等。", "corrected_sentence": "这两个正方形全等。", "error_description": "“全等”是绝对形容词，表示完全相同，不能用“很”修饰。错误句“很全等”应改为“全等”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95956, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个圆形是全等地。", "corrected_sentence": "这两个圆形是全等的。", "error_description": "“是……的”结构中的“全等”后面要用“的”，不用“地”（“地”只用于修饰动词、形容词的状语）。错误句“是全等地”应改为“是全等的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
