INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95957, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水在低温下凝结成的、覆在地面或水面上的又硬又滑的冰层。", "primary_collocate": null, "pronunciation": "bīng", "ipa": "piŋ˥", "syllable_count": 1, "sentences": [{"text": "地上有冰，很滑。", "target_word": "冰", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "冰又硬又滑。", "target_word": "冰", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "路上的冰很滑，请你慢点走。", "target_word": "冰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他踩到冰，摔倒了。", "target_word": "冰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湖面的冰硬得像石头一样。", "target_word": "冰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "台阶上的冰太滑了，我差点摔倒。", "target_word": "冰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪后路上结了很多冰，开车要小心。", "target_word": "冰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在冰上走得很小心，怕滑倒。", "target_word": "冰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰很硬，你得用力才能敲开。", "target_word": "冰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人踩着冰慢慢走过了马路。", "target_word": "冰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "层", "label": "量词"}, {"form": "冰面", "label": "复合词"}, {"form": "结冰", "label": "复合词"}], "register": "中性", "sense_fingerprint": "地面或水面上又硬又滑的冰层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea0b2d16-fd3c-4652-81a5-d83fbc5fa0b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95957, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "冰", "is_correct": true, "explanation": "冰（bīng，第一声）指水凝结成的又硬又滑的冰层，即本词。"}, {"text": "病", "is_correct": false, "explanation": "病（bìng，第四声）与 bīng（第一声）声调不同，意思是疾病。"}, {"text": "滨", "is_correct": false, "explanation": "滨（bīn，第一声）与 bīng 韵母不同（-in 与 -ing），意思是水边，如海滨。"}, {"text": "柄", "is_correct": false, "explanation": "柄（bǐng，第三声）与 bīng 声调不同，意思是器物的把手。"}], "explanations": {"冰": "冰（bīng，第一声）指水凝结成的又硬又滑的冰层，即本词。", "病": "病（bìng，第四声）与 bīng（第一声）声调不同，意思是疾病。", "滨": "滨（bīn，第一声）与 bīng 韵母不同（-in 与 -ing），意思是水边，如海滨。", "柄": "柄（bǐng，第三声）与 bīng 声调不同，意思是器物的把手。"}, "sentence_index": null, "correct_answer": "冰"}, "level_3": {"options": [{"text": "冰", "is_correct": true, "explanation": "冰：地上的冰层又硬又滑，符合句中的“很滑”。"}, {"text": "钱", "is_correct": false, "explanation": "语义：钱币不会让地面打滑，与“很滑”没有关系。"}, {"text": "书", "is_correct": false, "explanation": "语义：书本不会让地面打滑，与“很滑”不合。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会让地面变滑，与“很滑”不合。"}], "explanations": {"冰": "冰：地上的冰层又硬又滑，符合句中的“很滑”。", "钱": "语义：钱币不会让地面打滑，与“很滑”没有关系。", "书": "语义：书本不会让地面打滑，与“很滑”不合。", "桌子": "语义：桌子不会让地面变滑，与“很滑”不合。"}, "sentence_index": 0, "correct_answer": "冰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "湖面上的冰软软的，孩子们在上面踩来踩去。", "explanation": "这里应该用〈雪〉。雪是松软的，可以踩出脚印；冰又硬又滑，不能说“软软的”。"}, {"text": "湖面上结了一头冰，大家都不敢走。", "explanation": "这里应该用〈层〉。冰层是一层一层的，量词用“层”；“头”多用于牲畜，不能用于冰。"}, {"text": "雨后路上的冰被风吹干了。", "explanation": "这里应该用〈水〉。被风吹干的是水，冰是固体，不能说“吹干”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95957, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "冰", "is_correct": true, "explanation": "冰（bīng，第一声）指水凝结成的又硬又滑的冰层，即本词。"}, {"text": "饼", "is_correct": false, "explanation": "饼（bǐng，第三声）与 bīng（第一声）声调不同，意思是饼干、饼子。"}, {"text": "并", "is_correct": false, "explanation": "并（bìng，第四声）与 bīng 声调不同，意思是合并，也可作“并且”。"}, {"text": "宾", "is_correct": false, "explanation": "宾（bīn，第一声）与 bīng 韵母不同（-in 与 -ing），意思是宾客。"}, {"text": "丙", "is_correct": false, "explanation": "丙（bǐng，第三声）与 bīng 声调不同，意思是天干的第三位，也指第三等。"}], "explanations": {"冰": "冰（bīng，第一声）指水凝结成的又硬又滑的冰层，即本词。", "饼": "饼（bǐng，第三声）与 bīng（第一声）声调不同，意思是饼干、饼子。", "并": "并（bìng，第四声）与 bīng 声调不同，意思是合并，也可作“并且”。", "宾": "宾（bīn，第一声）与 bīng 韵母不同（-in 与 -ing），意思是宾客。", "丙": "丙（bǐng，第三声）与 bīng 声调不同，意思是天干的第三位，也指第三等。"}, "sentence_index": null, "correct_answer": "冰"}, "level_3": {"options": [{"text": "冰", "is_correct": true, "explanation": "冰：雪后路面结成的冰层，符合“结”的搭配，也与“开车要小心”相合。"}, {"text": "树叶", "is_correct": false, "explanation": "搭配：“结”多用于冰、果实等，不说“结了很多树叶”。"}, {"text": "脚印", "is_correct": false, "explanation": "搭配：脚印是踩出的痕迹，不会“结”出来。"}, {"text": "石子", "is_correct": false, "explanation": "语义：石子是坚硬的小石块，不会在路上“结”成一片，与语境不合。"}], "explanations": {"冰": "冰：雪后路面结成的冰层，符合“结”的搭配，也与“开车要小心”相合。", "树叶": "搭配：“结”多用于冰、果实等，不说“结了很多树叶”。", "脚印": "搭配：脚印是踩出的痕迹，不会“结”出来。", "石子": "语义：石子是坚硬的小石块，不会在路上“结”成一片，与语境不合。"}, "sentence_index": 6, "correct_answer": "冰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "路面上结了一匹冰，很滑。", "explanation": "这里应该用〈层〉。“匹”多用于马等动物，冰层应用“层”。"}, {"text": "外面的冰很大，我们带把伞吧。", "explanation": "这里应该用〈雨〉。下雨才要带伞，地上的冰层不会让人需要打伞。"}, {"text": "他用冰打了一个鸡蛋，准备做蛋糕。", "explanation": "这里应该用〈搅拌器〉。冰是固体，不能用来打鸡蛋；打鸡蛋要用搅拌器等工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95957, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "早上起来，路面结了一头薄冰，走路要小心。", "corrected_sentence": "早上起来，路面结了一层薄冰，走路要小心。", "error_description": "“冰”作为路面上的一层，量词应用“层”；“头”多用于牲畜，不能用于冰。应说“一层薄冰”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95957, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他踩碎了一层冰薄，继续走。", "corrected_sentence": "他踩碎了一层薄冰，继续走。", "error_description": "“薄”修饰名词“冰”，应放在“冰”之前，说“一层薄冰”，不能说“一层冰薄”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
