INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95958, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水在零度以下凝结成的固体。", "primary_collocate": null, "pronunciation": "bīng", "ipa": "piŋ˥", "syllable_count": 1, "sentences": [{"text": "水变成冰。", "target_word": "冰", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水到零度就会结成冰。", "target_word": "冰", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天气太热，桌上的冰很快就化成水了。", "target_word": "冰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天湖面上有厚厚的冰。", "target_word": "冰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把冰放进热茶里，想让茶快点凉。", "target_word": "冰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在结了冰的湖上玩。", "target_word": "冰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰比水轻，所以浮在水面上。", "target_word": "冰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天我喜欢往果汁里加几块冰。", "target_word": "冰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北极的冰正在一年比一年少。", "target_word": "冰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在零下十度，河面上的水全都变成了冰。", "target_word": "冰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "冰块", "label": "复合词"}, {"form": "冰箱", "label": "复合词"}], "register": "中性", "sense_fingerprint": "水凝结成的固体，即冰块、冰层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea0b2d16-fd3c-4652-81a5-d83fbc5fa0b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95958, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "冰", "is_correct": true, "explanation": "冰（bīng，第一声）指水在零度以下凝结成的固体，即本词。"}, {"text": "饼", "is_correct": false, "explanation": "饼（bǐng，第三声）与 bīng（第一声）声调不同，意思是饼干、饼子。"}, {"text": "病", "is_correct": false, "explanation": "病（bìng，第四声）与 bīng（第一声）声调不同，意思是疾病。"}, {"text": "宾", "is_correct": false, "explanation": "宾（bīn，第一声）与 bīng 韵母不同（-in 与 -ing），意思是宾客。"}], "explanations": {"冰": "冰（bīng，第一声）指水在零度以下凝结成的固体，即本词。", "饼": "饼（bǐng，第三声）与 bīng（第一声）声调不同，意思是饼干、饼子。", "病": "病（bìng，第四声）与 bīng（第一声）声调不同，意思是疾病。", "宾": "宾（bīn，第一声）与 bīng 韵母不同（-in 与 -ing），意思是宾客。"}, "sentence_index": null, "correct_answer": "冰"}, "level_3": {"options": [{"text": "冰", "is_correct": true, "explanation": "冰：水变冷后凝结成的固体，符合“水变成”的物态变化。"}, {"text": "石头", "is_correct": false, "explanation": "语义：水不会变成石头，石头是矿物固体，与水的物态变化不符。"}, {"text": "金子", "is_correct": false, "explanation": "语义：水不会变成金子，这既不是物态变化，也不是日常可能发生的转化。"}, {"text": "烟", "is_correct": false, "explanation": "搭配：“变成烟”多指物质燃烧后产生的烟，水不会变成烟，应说“变成水蒸气”。"}], "explanations": {"冰": "冰：水变冷后凝结成的固体，符合“水变成”的物态变化。", "石头": "语义：水不会变成石头，石头是矿物固体，与水的物态变化不符。", "金子": "语义：水不会变成金子，这既不是物态变化，也不是日常可能发生的转化。", "烟": "搭配：“变成烟”多指物质燃烧后产生的烟，水不会变成烟，应说“变成水蒸气”。"}, "sentence_index": 0, "correct_answer": "冰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天太热了，他从冰箱里拿出了一台冰。", "explanation": "这里应该用〈块〉。冰是一块块的固体，量词不能用“台”，“台”多用于机器。"}, {"text": "我在杯子里放了一只冰，然后倒入果汁。", "explanation": "这里应该用〈块〉。冰是一块块的固体，量词用“块”；“只”多用于动物，不能用于冰。"}, {"text": "夜里窗外飘起了冰，早上地上都是白的。", "explanation": "这里应该用〈雪〉。冰是凝结成的固体块，不会像雪一样飘落，应说“飘起了雪”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95958, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "冰", "is_correct": true, "explanation": "冰（bīng，第一声）指水在零度以下凝结成的固体，即本词。"}, {"text": "柄", "is_correct": false, "explanation": "柄（bǐng，第三声）与 bīng（第一声）声调不同，意思是器物的把手，如刀柄。"}, {"text": "并", "is_correct": false, "explanation": "并（bìng，第四声）与 bīng 声调不同，意思是合并，也可作“并且”。"}, {"text": "滨", "is_correct": false, "explanation": "滨（bīn，第一声）与 bīng 韵母不同（-in 与 -ing），意思是水边，如海滨。"}, {"text": "丙", "is_correct": false, "explanation": "丙（bǐng，第三声）与 bīng 声调不同，意思是天干的第三位，也指第三等。"}], "explanations": {"冰": "冰（bīng，第一声）指水在零度以下凝结成的固体，即本词。", "柄": "柄（bǐng，第三声）与 bīng（第一声）声调不同，意思是器物的把手，如刀柄。", "并": "并（bìng，第四声）与 bīng 声调不同，意思是合并，也可作“并且”。", "滨": "滨（bīn，第一声）与 bīng 韵母不同（-in 与 -ing），意思是水边，如海滨。", "丙": "丙（bǐng，第三声）与 bīng 声调不同，意思是天干的第三位，也指第三等。"}, "sentence_index": null, "correct_answer": "冰"}, "level_3": {"options": [{"text": "冰", "is_correct": true, "explanation": "冰：水凝结成的固体，密度比水小，所以能浮在水面上。"}, {"text": "铁", "is_correct": false, "explanation": "语义：铁比水重，会沉入水中，与“浮在水面上”矛盾。"}, {"text": "铅", "is_correct": false, "explanation": "语义：铅也比水重，不会浮在水面上，与句中的因果关系不符。"}, {"text": "沙子", "is_correct": false, "explanation": "搭配：“浮在水面上”一般用于比水轻的物体，沙子比水重，不能说浮起来。"}], "explanations": {"冰": "冰：水凝结成的固体，密度比水小，所以能浮在水面上。", "铁": "语义：铁比水重，会沉入水中，与“浮在水面上”矛盾。", "铅": "语义：铅也比水重，不会浮在水面上，与句中的因果关系不符。", "沙子": "搭配：“浮在水面上”一般用于比水轻的物体，沙子比水重，不能说浮起来。"}, "sentence_index": 6, "correct_answer": "冰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨房里的冰坏了，牛奶都变质了。", "explanation": "这里应该用〈冰箱〉。冰指固体的水，不能指储存食物的电器。"}, {"text": "我每天早上都要喝一杯温冰。", "explanation": "这里应该用〈水〉。冰是固体，不能是“温”的，要说“一杯温水”。"}, {"text": "锅里的水烧开了，冒出了白色的冰。", "explanation": "这里应该用〈汽〉。水烧开后冒出的是水蒸气，冰是固体，不会从锅里冒出来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95958, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我用一只冰敷在脸上，觉得舒服多了。", "corrected_sentence": "我用一块冰敷在脸上，觉得舒服多了。", "error_description": "“冰”作为一块块固体，量词应用“块”，不能用“只”（“只”多用于动物）。应改为“一块冰”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95958, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们在一只厚厚的冰上玩耍。", "corrected_sentence": "孩子们在一块厚厚的冰上玩耍。", "error_description": "“冰”是一块块的固体，量词应用“块”，不能用“只”（“只”多用于动物等单个个体）。应改为“一块厚厚的冰”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
