INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95959, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "出租车是给钱就可以坐的小汽车。", "primary_collocate": null, "pronunciation": "chū zū chē", "ipa": "ʈʂʰu˥ tsu˥ ʈʂʰɤ˥", "syllable_count": 3, "sentences": [{"text": "我们打一辆出租车去机场吧。", "target_word": "出租车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，路边很难叫到出租车。", "target_word": "出租车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆出租车的司机很客气。", "target_word": "出租车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出租车停在门口，他上车了。", "target_word": "出租车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐出租车去火车站要二十分钟。", "target_word": "出租车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把手机忘在了出租车上。", "target_word": "出租车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上这里的出租车很多。", "target_word": "出租车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开出租车已经十年了。", "target_word": "出租车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出租车司机告诉我，前面在堵车。", "target_word": "出租车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐着出租车，慢慢地穿过了市中心。", "target_word": "出租车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "出租汽车", "label": "复合词"}, {"form": "出租车司机", "label": "复合词"}], "register": "中性", "sense_fingerprint": "付钱就能乘坐的小汽车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e91ed0ea-a5b4-4e39-8719-01c98cf926fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95959, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出租车", "is_correct": true, "explanation": "正确：“打”可用于叫出租车，与“去机场”的语境吻合。"}, {"text": "公交车", "is_correct": false, "explanation": "搭配：“打”多用于叫出租车，不说“打一辆公交车”。"}, {"text": "自行车", "is_correct": false, "explanation": "搭配：自行车是自己骑的，不说“打一辆自行车”。"}, {"text": "救护车", "is_correct": false, "explanation": "语义：救护车是用来急救、送病人的，不用于去机场。"}], "explanations": {"出租车": "正确：“打”可用于叫出租车，与“去机场”的语境吻合。", "公交车": "搭配：“打”多用于叫出租车，不说“打一辆公交车”。", "自行车": "搭配：自行车是自己骑的，不说“打一辆自行车”。", "救护车": "语义：救护车是用来急救、送病人的，不用于去机场。"}, "sentence_index": 0, "correct_answer": "出租车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他突然生病了，出租车马上把他送进了急救室抢救。", "explanation": "这里应该用〈救护车〉。出租车是普通载客车，送病人急救要用救护车。"}, {"text": "我们在海边租了一辆出租车，自己开着兜风。", "explanation": "这里应该用〈汽车〉。出租车由司机驾驶、按路程收费，乘客不能自己开；自驾要说“租一辆汽车”。"}, {"text": "工人们开着出租车运送建筑材料。", "explanation": "这里应该用〈货车〉。出租车只用来载客，不用来运送材料；运货要用“货车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95959, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出租车", "is_correct": true, "explanation": "正确：“出租车”是晚上街上常见的车，与“很多”搭配自然。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：一天只有一个太阳，晚上也不会有，不能说“很多”。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮只有一个，不能说“晚上这里的月亮很多”。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日是日子，不会在某个地方“很多”，句子意思不通。"}], "explanations": {"出租车": "正确：“出租车”是晚上街上常见的车，与“很多”搭配自然。", "太阳": "语义：一天只有一个太阳，晚上也不会有，不能说“很多”。", "月亮": "语义：月亮只有一个，不能说“晚上这里的月亮很多”。", "生日": "语义：生日是日子，不会在某个地方“很多”，句子意思不通。"}, "sentence_index": 6, "correct_answer": "出租车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "出租车每天早上来收垃圾。", "explanation": "这里应该用〈垃圾车〉。出租车只用来载客，不负责收垃圾。"}, {"text": "出租车在马路上洒水。", "explanation": "这里应该用〈洒水车〉。出租车用于载客，不用于在路上洒水。"}, {"text": "出租车把泥土推到路边。", "explanation": "这里应该用〈推土机〉。出租车是载客车，不能用来推土。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95959, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨太大了，我们终于打到了一只出租车。", "corrected_sentence": "雨太大了，我们终于打到了一辆出租车。", "error_description": "量词错误：“出租车”应用量词“辆”，不能用“只”。“只”多用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95959, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "路边停着一排出租车们。", "corrected_sentence": "路边停着一排出租车。", "error_description": "加词尾错误：“们”一般只加在指人或有生命的名词后面，“出租车”是无生命的车辆，不能加“们”表示复数。应为“一排出租车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
