INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95960, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "按路程或时间收费、供人租用的载客汽车。", "primary_collocate": null, "pronunciation": "chū zū chē", "ipa": "ʈʂʰu˥ tsu˥ ʈʂʰɤ˥", "syllable_count": 3, "sentences": [{"text": "出租车按路程收费，也按时间收费。", "target_word": "出租车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的出租车都是绿色的。", "target_word": "出租车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在机场门口排队等出租车。", "target_word": "出租车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下车前，乘客要先付清出租车的车费。", "target_word": "出租车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司有两百辆出租车。", "target_word": "出租车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出租车上有一个计价器。", "target_word": "出租车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出租车司机要遵守交通规则。", "target_word": "出租车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "深夜还有出租车在街上跑。", "target_word": "出租车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府增加了出租车的数量。", "target_word": "出租车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出租车的起步价是十元。", "target_word": "出租车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "出租汽车", "label": "复合词"}, {"form": "出租车司机", "label": "复合词"}], "register": "中性", "sense_fingerprint": "按路程或时间收费、供人租用的载客汽车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e91ed0ea-a5b4-4e39-8719-01c98cf926fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95960, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出租车", "is_correct": true, "explanation": "正确：“出租车”按路程和时间收费，与句意相合。"}, {"text": "公园", "is_correct": false, "explanation": "搭配：“按路程收费”只用于交通工具或运送服务，“公园”不能与之搭配。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：电梯是升降设备，不按路程计费。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆一般不按路程收费，与句意不合。"}], "explanations": {"出租车": "正确：“出租车”按路程和时间收费，与句意相合。", "公园": "搭配：“按路程收费”只用于交通工具或运送服务，“公园”不能与之搭配。", "电梯": "语义：电梯是升降设备，不按路程计费。", "图书馆": "语义：图书馆一般不按路程收费，与句意不合。"}, "sentence_index": 0, "correct_answer": "出租车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "出租车每天按固定路线停靠几十个车站。", "explanation": "这里应该用〈公交车〉。按固定路线、在车站停靠的是公交车；出租车按乘客要去的地方走。"}, {"text": "出租车运送了一批海鲜。", "explanation": "这里应该用〈冷藏车〉。出租车只载客，不用来运货；运送海鲜要用“冷藏车”。"}, {"text": "出租车把故障的汽车拖走了。", "explanation": "这里应该用〈清障车〉。出租车用于载客，拖走故障车要用“清障车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95960, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出租车", "is_correct": true, "explanation": "正确：“出租车”司机需要驾驶车辆，与“遵守交通规则”相合。"}, {"text": "书店", "is_correct": false, "explanation": "搭配：“司机”需要驾驶车辆，“书店”不能与之搭配。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是车辆，与交通规则无关。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜不能驾驶车辆，不能有“司机”。"}], "explanations": {"出租车": "正确：“出租车”司机需要驾驶车辆，与“遵守交通规则”相合。", "书店": "搭配：“司机”需要驾驶车辆，“书店”不能与之搭配。", "厨房": "语义：厨房不是车辆，与交通规则无关。", "蔬菜": "语义：蔬菜不能驾驶车辆，不能有“司机”。"}, "sentence_index": 6, "correct_answer": "出租车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "出租车在田里耕地。", "explanation": "这里应该用〈拖拉机〉。出租车只载客，耕地要用拖拉机。"}, {"text": "出租车清理了积雪。", "explanation": "这里应该用〈扫雪车〉。出租车用于载客，清理积雪要用扫雪车。"}, {"text": "出租车赶到火场灭火。", "explanation": "这里应该用〈消防车〉。出租车不负责灭火，要用消防车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下班高峰期，他在路口排队等一条出租车。", "corrected_sentence": "下班高峰期，他在路口排队等一辆出租车。", "error_description": "量词错误：“出租车”是车辆，应用量词“辆”，“条”多用于细长的东西，不能用于车辆，应为“等一辆出租车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "城里新增了两百条出租车。", "corrected_sentence": "城里新增了两百辆出租车。", "error_description": "量词错误：“出租车”应用量词“辆”，“条”多用于细长的东西，不能用于车辆。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
