INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95961, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "（话语、词语、典故等）来源于某本书、某篇作品或某个人。", "primary_collocate": null, "pronunciation": "chū zì", "ipa": "tʂʰu˥ tsz̩˥˩", "syllable_count": 2, "sentences": [{"text": "这句话出自《论语》。", "target_word": "出自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个成语出自一个古老的故事。", "target_word": "出自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗出自哪本书？", "target_word": "出自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“温故知新”出自孔子的话。", "target_word": "出自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个笑话出自一部老电影。", "target_word": "出自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段话出自老师昨天讲的课文。", "target_word": "出自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这句歌词出自哪首歌吗？", "target_word": "出自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词出自一本很老的小说。", "target_word": "出自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些数字出自去年的新闻报道。", "target_word": "出自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那句名言出自一位法国作家。", "target_word": "出自", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "出自：话语、词语、典故等的出处，来自哪本书、哪个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d4986a0-230f-4048-a49e-666580b97150') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95961, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出自", "is_correct": true, "explanation": "正确：出自（chū zì），表示话语、词语等的出处。"}, {"text": "初次", "is_correct": false, "explanation": "cì（第四声）与 zì（第四声）声母不同（c 与 z），意思是第一次，与“出自”不同。"}, {"text": "出资", "is_correct": false, "explanation": "zī（第一声）与 zì（第四声）声调不同，意思是出钱、投资。"}, {"text": "厨子", "is_correct": false, "explanation": "chú zi（第二声、轻声）与 chū zì 的第一个音节声调不同，意思是厨师。"}], "explanations": {"出自": "正确：出自（chū zì），表示话语、词语等的出处。", "初次": "cì（第四声）与 zì（第四声）声母不同（c 与 z），意思是第一次，与“出自”不同。", "出资": "zī（第一声）与 zì（第四声）声调不同，意思是出钱、投资。", "厨子": "chú zi（第二声、轻声）与 chū zì 的第一个音节声调不同，意思是厨师。"}, "sentence_index": null, "correct_answer": "出自"}, "level_3": {"options": [{"text": "出自", "is_correct": true, "explanation": "正确：出自表示话语的出处，这句话来自《论语》，符合语境。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”的对象应是书、报等出版物，不能说“这句话出版《论语》”。"}, {"text": "收录", "is_correct": false, "explanation": "配价：“收录”的主语应是书或文集，应说“《论语》收录了这句话”，这里方向说反了。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指演唱歌曲，《论语》不能被“唱”，这里说不通。"}], "explanations": {"出自": "正确：出自表示话语的出处，这句话来自《论语》，符合语境。", "出版": "搭配：“出版”的对象应是书、报等出版物，不能说“这句话出版《论语》”。", "收录": "配价：“收录”的主语应是书或文集，应说“《论语》收录了这句话”，这里方向说反了。", "唱": "语义：“唱”指演唱歌曲，《论语》不能被“唱”，这里说不通。"}, "sentence_index": 0, "correct_answer": "出自"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孔子出自这句话。", "explanation": "这里应该用〈说〉。出自表示话语或文字的出处，主语应是话语本身，不能把人当作话语的来源；应说“这句话出自孔子”，或“孔子说了这句话”。"}, {"text": "这篇文章出自一九二〇年。", "explanation": "这里应该用〈写于〉。出处指话语或文字来自哪本书、哪个人，不能用来说明时间；说明写作时间要用“写于”。"}, {"text": "博物馆出自这幅画。", "explanation": "这里应该用〈收藏〉。出处的主语应是话语或文字，不能说博物馆“出自”一幅画；应说“博物馆收藏这幅画”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ea2e41-fe4c-4e22-b114-3834ebfb0285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95961, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出自", "is_correct": true, "explanation": "正确：出自表示出处，问这句歌词来自哪首歌，符合语境。"}, {"text": "谱写", "is_correct": false, "explanation": "语义：“谱写”指作曲，歌词不能去“谱写”哪首歌，这里说不通。"}, {"text": "演唱", "is_correct": false, "explanation": "配价：“演唱”的主语应是歌手，“这句歌词”不能作演唱的主语，这里说不通。"}, {"text": "录制", "is_correct": false, "explanation": "搭配：“录制”指把声音或画面录下来，不表示歌词的出处，这里不搭配。"}], "explanations": {"出自": "正确：出自表示出处，问这句歌词来自哪首歌，符合语境。", "谱写": "语义：“谱写”指作曲，歌词不能去“谱写”哪首歌，这里说不通。", "演唱": "配价：“演唱”的主语应是歌手，“这句歌词”不能作演唱的主语，这里说不通。", "录制": "搭配：“录制”指把声音或画面录下来，不表示歌词的出处，这里不搭配。"}, "sentence_index": 6, "correct_answer": "出自"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他出自这首诗。", "explanation": "这里应该用〈创作〉。出自表示话语来自哪里，主语应是话语或文字，不能说人“出自”一首诗；应说“他创作了这首诗”。"}, {"text": "老师出自这个故事。", "explanation": "这里应该用〈讲述〉。出自表示出处，不能让人作主语，应说“老师讲述这个故事”。"}, {"text": "他出自别人的作品。", "explanation": "这里应该用〈抄袭〉。出自表示话语的来源，人不能“出自”别人的作品；应说“他抄袭了别人的作品”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ea2e41-fe4c-4e22-b114-3834ebfb0285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95961, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这句诗出自了一本老诗集。", "corrected_sentence": "这句诗出自一本老诗集。", "error_description": "错误在“出自”后面加了“了”。“出自”表示出处，是关系动词，不能带“了”。正确说法是“这句诗出自一本老诗集”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ea2e41-fe4c-4e22-b114-3834ebfb0285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95961, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个典故出自过《史记》。", "corrected_sentence": "这个典故出自《史记》。", "error_description": "错误在“出自”后面加了“过”。“出自”表示出处，是关系动词，表示事物来源于某处，不能带体标“过”。正确说法是“这个典故出自《史记》”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ea2e41-fe4c-4e22-b114-3834ebfb0285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
