INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95962, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "从某处产生或来源于某处。", "primary_collocate": null, "pronunciation": "chū zì", "ipa": "tʂʰu˥ tsz̩˥˩", "syllable_count": 2, "sentences": [{"text": "这件礼物出自一位老工匠之手。", "target_word": "出自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出自一个普通的农民家庭。", "target_word": "出自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个好主意出自一次小小的失败。", "target_word": "出自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张画出自一个十岁孩子之手。", "target_word": "出自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些茶叶都出自南方的小山村。", "target_word": "出自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的勇气出自对家人的爱。", "target_word": "出自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的灵感出自一次旅行。", "target_word": "出自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好医生大多出自这所老学校。", "target_word": "出自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些故事出自老人们的口中。", "target_word": "出自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告出自我们公司的研究组。", "target_word": "出自", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "出自：人或事物产生于、来源于某个地方、家庭或人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d4986a0-230f-4048-a49e-666580b97150') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95962, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出自", "is_correct": true, "explanation": "正确：出自（chū zì），表示事物来源于某人、某地或某物。"}, {"text": "初次", "is_correct": false, "explanation": "cì（第四声）与 zì（第四声）声母不同（c 与 z），意思是第一次，与“出自”不同。"}, {"text": "出资", "is_correct": false, "explanation": "zī（第一声）与 zì（第四声）声调不同，意思是出钱、投资。"}, {"text": "厨子", "is_correct": false, "explanation": "chú zi（第二声、轻声）与 chū zì 的第一个音节声调不同，意思是厨师。"}], "explanations": {"出自": "正确：出自（chū zì），表示事物来源于某人、某地或某物。", "初次": "cì（第四声）与 zì（第四声）声母不同（c 与 z），意思是第一次，与“出自”不同。", "出资": "zī（第一声）与 zì（第四声）声调不同，意思是出钱、投资。", "厨子": "chú zi（第二声、轻声）与 chū zì 的第一个音节声调不同，意思是厨师。"}, "sentence_index": null, "correct_answer": "出自"}, "level_3": {"options": [{"text": "出自", "is_correct": true, "explanation": "正确：出自表示“来源于某人之手”，符合“这件礼物”与“老工匠之手”的搭配。"}, {"text": "属于", "is_correct": false, "explanation": "语义：“属于”表示归属，礼物不是“属于”一双手，这里说不通。"}, {"text": "交给", "is_correct": false, "explanation": "搭配：“交给”后接接受者，应说“交到……手里”，不能说“交给……之手”。"}, {"text": "出产", "is_correct": false, "explanation": "配价：“出产”的宾语是产品，不能接人作来源，这里说不通。"}], "explanations": {"出自": "正确：出自表示“来源于某人之手”，符合“这件礼物”与“老工匠之手”的搭配。", "属于": "语义：“属于”表示归属，礼物不是“属于”一双手，这里说不通。", "交给": "搭配：“交给”后接接受者，应说“交到……手里”，不能说“交给……之手”。", "出产": "配价：“出产”的宾语是产品，不能接人作来源，这里说不通。"}, "sentence_index": 0, "correct_answer": "出自"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张画出自去年的夏天。", "explanation": "这里应该用〈作于〉。出自表示来源于某人、某地或某物，不能用来说明时间；说明创作时间要用“作于”或“画于”。"}, {"text": "一只小鸟出自窗口飞了进来。", "explanation": "这里应该用〈从〉。出自表示来源，不表示动作的起点；“从窗口飞进来”才是对的。"}, {"text": "他的身影突然出自门口。", "explanation": "这里应该用〈出现〉。出自表示来源，不表示人或物突然显现；应说“突然出现在门口”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ea2e41-fe4c-4e22-b114-3834ebfb0285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95962, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出自", "is_correct": true, "explanation": "正确：出自表示灵感的来源，符合“这首歌的灵感”与“一次旅行”的语境。"}, {"text": "产生", "is_correct": false, "explanation": "配价：“产生”后要用“于”引出来源，应说“产生于一次旅行”，这里直接接宾语不通。"}, {"text": "吸收", "is_correct": false, "explanation": "语义：“吸收”指接纳养分或知识，灵感不能“吸收”一次旅行。"}, {"text": "评价", "is_correct": false, "explanation": "语义：“评价”指对事物做出判断，与灵感的来源无关，这里说不通。"}], "explanations": {"出自": "正确：出自表示灵感的来源，符合“这首歌的灵感”与“一次旅行”的语境。", "产生": "配价：“产生”后要用“于”引出来源，应说“产生于一次旅行”，这里直接接宾语不通。", "吸收": "语义：“吸收”指接纳养分或知识，灵感不能“吸收”一次旅行。", "评价": "语义：“评价”指对事物做出判断，与灵感的来源无关，这里说不通。"}, "sentence_index": 6, "correct_answer": "出自"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工程师出自这座大桥。", "explanation": "这里应该用〈设计〉。出自表示事物来自某人或某地，不能倒过来说人来自某个事物；应说“工程师设计了这座大桥”。"}, {"text": "我国出自大量茶叶。", "explanation": "这里应该用〈出口〉。出自表示事物的来源，不能用国家作主语说“出自”货物；应说“我国出口大量茶叶”。"}, {"text": "他出自一个好成绩。", "explanation": "这里应该用〈取得〉。出自说明事物的来源，人不能“出自”成绩；应说“他取得了好成绩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ea2e41-fe4c-4e22-b114-3834ebfb0285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95962, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这幅字出自了一位老书法家之手。", "corrected_sentence": "这幅字出自一位老书法家之手。", "error_description": "错误在“出自”后面加了“了”。“出自”表示来源关系，是关系动词，不能带“了”。正确说法是“这幅字出自一位老书法家之手”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ea2e41-fe4c-4e22-b114-3834ebfb0285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95962, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首曲子出自在一位老音乐家之手。", "corrected_sentence": "这首曲子出自一位老音乐家之手。", "error_description": "错误在“出自”后面多了“在”。“出自”的“自”已经表示“从”，后面直接带来源，不能再加介词“在”。应说“这首曲子出自一位老音乐家之手”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ea2e41-fe4c-4e22-b114-3834ebfb0285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
