INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95963, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "前景是以后会变成什么样。", "primary_collocate": null, "pronunciation": "qián jǐng", "ipa": "tɕʰjɛn˧˥ tɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "小城的旅游业前景不错。", "target_word": "前景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店的前景怎么样？", "target_word": "前景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友问我这个行业有没有前景。", "target_word": "前景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看好电动车的前景。", "target_word": "前景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种茶的前景很好，农民都很高兴。", "target_word": "前景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工作没有前景，他想换一个。", "target_word": "前景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，他的康复前景很好。", "target_word": "前景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都很关心这个项目的前景。", "target_word": "前景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门技术的前景十分光明。", "target_word": "前景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人选工作，常常先看前景。", "target_word": "前景", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发展前景", "label": "复合"}, {"form": "市场前景", "label": "复合"}], "register": "中性", "sense_fingerprint": "前景：以后会变成什么样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4cfc666-8119-44d9-9cb1-da1cda7a5a1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95963, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人的性情，不能用来形容一个行业。"}, {"text": "前景", "is_correct": true, "explanation": "“前景”指以后会变成什么样，“小城的旅游业前景不错”说的是旅游业以后发展得好。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人或物的高矮，不能用来评价旅游业。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“尺寸”说大小，不跟“不错”搭配在行业上。"}], "explanations": {"脾气": "语义：“脾气”指人的性情，不能用来形容一个行业。", "前景": "“前景”指以后会变成什么样，“小城的旅游业前景不错”说的是旅游业以后发展得好。", "身高": "语义：“身高”指人或物的高矮，不能用来评价旅游业。", "尺寸": "搭配：“尺寸”说大小，不跟“不错”搭配在行业上。"}, "sentence_index": 0, "correct_answer": "前景"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把前景装进了行李箱。", "explanation": "这里应该用〈衣服〉。“衣服”可以装进行李箱；“前景”是抽象的将来情形，不能装进箱子。"}, {"text": "妈妈用前景炒了一盘菜。", "explanation": "这里应该用〈青菜〉。“青菜”可以用来炒菜；“前景”指将来的情形，不能用来炒菜。"}, {"text": "这台机器的前景很吵。", "explanation": "这里应该用〈声音〉。“声音很吵”是常见说法；“前景”指将来的情形，不能用来说吵不吵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95963, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不能用来说一个人的康复。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“重量”说轻重，不说“很好”。"}, {"text": "音量", "is_correct": false, "explanation": "语义：“音量”指声音的大小，与康复情况无关。"}, {"text": "前景", "is_correct": true, "explanation": "“前景”指以后会变成什么样，“他的康复前景很好”说康复以后的情况很好。"}], "explanations": {"颜色": "语义：“颜色”指色彩，不能用来说一个人的康复。", "重量": "搭配：“重量”说轻重，不说“很好”。", "音量": "语义：“音量”指声音的大小，与康复情况无关。", "前景": "“前景”指以后会变成什么样，“他的康复前景很好”说康复以后的情况很好。"}, "sentence_index": 6, "correct_answer": "前景"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶把前景放进了冰箱。", "explanation": "这里应该用〈鸡蛋〉。“鸡蛋”可以放进冰箱；“前景”是抽象的将来情形，不能放进冰箱。"}, {"text": "我骑着前景去上学。", "explanation": "这里应该用〈自行车〉。“骑自行车”是常见说法；“前景”是抽象的将来情形，不能骑。"}, {"text": "这道题的前景很简单。", "explanation": "这里应该用〈答案〉。“答案”可以说“很简单”；“前景”指将来的情形，不用来形容题目的答案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95963, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校的前景的很好。", "corrected_sentence": "这所学校的前景很好。", "error_description": "“的”多加了：“前景”后面不能再加“的”，应说“这所学校的前景很好”，“的”只用在“学校”后面一次。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95963, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小店的前景好很。", "corrected_sentence": "这个小店的前景好得很。", "error_description": "补语错误：“好得很”中间要有“得”，“好很”不能说；应说“前景好得很”或“前景很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
