INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95967, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "叫道是大声喊着说。", "primary_collocate": null, "pronunciation": "jiào dào", "ipa": "tɕjɑʊ˥˩ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "小红在门口叫道：“爸爸，快来看！”", "target_word": "叫道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站在山上叫道：“你们能听见吗？”", "target_word": "叫道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球进了，大家叫道：“好球！”", "target_word": "叫道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察在后面叫道：“站住，别跑！”", "target_word": "叫道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在教室外叫道：“上课了，快进来！”", "target_word": "叫道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她着急地叫道：“等等我！”", "target_word": "叫道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一边跑一边叫道：“车来了，让开！”", "target_word": "叫道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩子在河边叫道：“妈妈，有鱼！”", "target_word": "叫道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟叫道：“哥哥，我的帽子呢？”", "target_word": "叫道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船长叫道：“大家抓紧，风很大！”", "target_word": "叫道", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "叫道：大声喊着说", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c43fe7c5-4c98-4d5a-8365-b48b04768234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95967, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "叫道", "is_correct": true, "explanation": "叫道：jiào dào，大声喊着说。"}, {"text": "教导", "is_correct": false, "explanation": "jiào dǎo 与 jiào dào 只有第二个音节声调不同（第三声与第四声），意思是教育、指导。"}, {"text": "交道", "is_correct": false, "explanation": "jiāo dào 与 jiào dào 只有第一个音节声调不同（第一声与第四声），意思是交往、打交道。"}, {"text": "跳到", "is_correct": false, "explanation": "tiào dào 与 jiào dào 只有第一个音节声母不同（t 与 j），意思是跳到某处。"}, {"text": "料到", "is_correct": false, "explanation": "liào dào 与 jiào dào 只有第一个音节声母不同（l 与 j），意思是预料到。"}], "explanations": {"叫道": "叫道：jiào dào，大声喊着说。", "教导": "jiào dǎo 与 jiào dào 只有第二个音节声调不同（第三声与第四声），意思是教育、指导。", "交道": "jiāo dào 与 jiào dào 只有第一个音节声调不同（第一声与第四声），意思是交往、打交道。", "跳到": "tiào dào 与 jiào dào 只有第一个音节声母不同（t 与 j），意思是跳到某处。", "料到": "liào dào 与 jiào dào 只有第一个音节声母不同（l 与 j），意思是预料到。"}, "sentence_index": null, "correct_answer": "叫道"}, "level_3": {"options": [{"text": "叫道", "is_correct": true, "explanation": "叫道：大声喊着说，后面引出说的话，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指用乐调歌唱，不是说话，句中引出的是喊的内容。"}, {"text": "摇头", "is_correct": false, "explanation": "配价：“摇头”是动作，不能引出说的话。"}, {"text": "叹气", "is_correct": false, "explanation": "配价：“叹气”不带直接引语，后面不能接这样的话。"}], "explanations": {"叫道": "叫道：大声喊着说，后面引出说的话，符合句意。", "唱": "语义：“唱”指用乐调歌唱，不是说话，句中引出的是喊的内容。", "摇头": "配价：“摇头”是动作，不能引出说的话。", "叹气": "配价：“叹气”不带直接引语，后面不能接这样的话。"}, "sentence_index": 0, "correct_answer": "叫道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察轻声叫道：“站住，别跑！”", "explanation": "这里应该用〈说道〉。叫道是大声喊着说，与“轻声”矛盾；轻声说话应用“说道”。"}, {"text": "警察在纸条上叫道：“站住，别跑！”", "explanation": "叫道要出声，不能用在纸条上；写下来应该用“写道”。"}, {"text": "警察默默地叫道：“站住，别跑！”", "explanation": "这里应该用〈想〉。叫道是大声说，“默默地”与之矛盾，无声的念头不能用叫道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95967, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "叫道", "is_correct": true, "explanation": "叫道：大声喊着说，后面引出说的话，符合句意。"}, {"text": "点头", "is_correct": false, "explanation": "配价：“点头”是动作，不能引出说的话。"}, {"text": "鼓掌", "is_correct": false, "explanation": "配价：“鼓掌”是拍手的动作，不能引出说的话。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”表示称赞，与“车来了，让开”的警告内容不符。"}], "explanations": {"叫道": "叫道：大声喊着说，后面引出说的话，符合句意。", "点头": "配价：“点头”是动作，不能引出说的话。", "鼓掌": "配价：“鼓掌”是拍手的动作，不能引出说的话。", "赞美": "语义：“赞美”表示称赞，与“车来了，让开”的警告内容不符。"}, "sentence_index": 6, "correct_answer": "叫道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "船长无声地叫道：“大家抓紧，风很大！”", "explanation": "这里应该用〈示意〉。叫道是大声说，“无声地”与之矛盾，无声只能用手势示意。"}, {"text": "船长闭着嘴叫道：“大家抓紧，风很大！”", "explanation": "这里应该用〈比划〉。叫道需要张口出声，“闭着嘴”与之矛盾，只能比划。"}, {"text": "船长一言不发地叫道：“大家抓紧，风很大！”", "explanation": "这里应该用〈点头〉。叫道需要出声，“一言不发”与之矛盾，只能用动作表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95967, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在山下大声叫道的：“快下来！”", "corrected_sentence": "他在山下大声叫道：“快下来！”", "error_description": "助词错误：“叫道”后直接接冒号引出所说的话，不能再加“的”。正确说法是“大声叫道：”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
