INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95968, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大声说；喊着说。", "primary_collocate": null, "pronunciation": "jiào dào", "ipa": "tɕjɑʊ˥˩ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "小明叫道：“妈妈，我回来了！”", "target_word": "叫道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人在远处叫道：“别过去，危险！”", "target_word": "叫道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在楼下叫道：“快点儿，要迟到了！”", "target_word": "叫道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看见我，叫道：“你怎么来了？”", "target_word": "叫道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们高兴地叫道：“下雪了，下雪了！”", "target_word": "叫道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机在前面叫道：“请坐好，车要开了！”", "target_word": "叫道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他跑过来叫道：“我找到钥匙了！”", "target_word": "叫道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗不见了，她着急地叫道：“来福，你在哪儿？”", "target_word": "叫道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家叫道：“生日快乐！”", "target_word": "叫道", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板叫道：“小王，过来一下！”", "target_word": "叫道", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "叫道：大声喊着说，后面引出所说的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c43fe7c5-4c98-4d5a-8365-b48b04768234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation