INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95968, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "叫道", "is_correct": true, "explanation": "叫道：大声喊着说，后面引出所说的话，符合句意。"}, {"text": "点头", "is_correct": false, "explanation": "配价：“点头”是动作，不能引出说的话。"}, {"text": "叹息", "is_correct": false, "explanation": "配价：“叹息”不带直接引语，后面不能接这样的话。"}, {"text": "摇头", "is_correct": false, "explanation": "配价：“摇头”是动作，不能引出说的话。"}], "explanations": {"叫道": "叫道：大声喊着说，后面引出所说的话，符合句意。", "点头": "配价：“点头”是动作，不能引出说的话。", "叹息": "配价：“叹息”不带直接引语，后面不能接这样的话。", "摇头": "配价：“摇头”是动作，不能引出说的话。"}, "sentence_index": 6, "correct_answer": "叫道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板悄悄地叫道：“小王，过来一下！”", "explanation": "这里应该用〈小声说〉。叫道是大声喊着说，“悄悄地”与之矛盾，应说“小声说道”。"}, {"text": "老板闭着嘴叫道：“小王，过来一下！”", "explanation": "这里应该用〈示意〉。叫道需要张口大声说，“闭着嘴”与之矛盾，只能用手势示意。"}, {"text": "老板一声不响地叫道：“小王，过来一下！”", "explanation": "这里应该用〈示意〉。叫道需要出声，“一声不响”与之矛盾，只能用动作示意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95968, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一看见我就大声叫道的：“快来帮忙！”", "corrected_sentence": "他一看见我就大声叫道：“快来帮忙！”", "error_description": "助词错误：“叫道”后直接接冒号引出所说的话，不能再加“的”。正确说法是“大声叫道：”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95968, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈在厨房里大声的叫道：“饭好了，快来吃！”", "corrected_sentence": "妈妈在厨房里大声叫道：“饭好了，快来吃！”", "error_description": "助词错误：副词“大声”修饰动词“叫道”时不用“的”，应直接说“大声叫道”。“的”用于修饰名词，不用于此处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ff3292-5780-4671-be55-6380743f174d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
