INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95969, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可心是东西正合你的心意，你很喜欢。", "primary_collocate": null, "pronunciation": "kě xīn", "ipa": "kʰɤ˨˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "这件礼物真可心，我太喜欢了。", "target_word": "可心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她找了很久，终于买到一条可心的裙子。", "target_word": "可心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双鞋又轻又好看，我觉得很可心。", "target_word": "可心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈送我的生日礼物很可心。", "target_word": "可心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想找一间可心的小房子住。", "target_word": "可心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他给女朋友挑了一份可心的礼物。", "target_word": "可心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的东西很多，可是没有一样可心。", "target_word": "可心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新买的沙发颜色很可心，我天天坐着看书。", "target_word": "可心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "逛了一下午，我还是没看到可心的包。", "target_word": "可心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个杯子用起来特别可心。", "target_word": "可心", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "东西正合心意、让人喜欢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a29a7b14-7b68-4d81-8215-6c329d1fefba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95969, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可心", "is_correct": true, "explanation": "可心：东西正合心意，令人喜欢，与后半句“我太喜欢了”一致。"}, {"text": "无聊", "is_correct": false, "explanation": "语义：“无聊”是乏味、没意思，与后半句“我太喜欢了”矛盾。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：“陌生”是不熟悉、没见过，与后半句“我太喜欢了”的喜爱之情不合。"}, {"text": "破旧", "is_correct": false, "explanation": "语义：“破旧”指陈旧残损，与“我太喜欢了”的语气不合。"}], "explanations": {"可心": "可心：东西正合心意，令人喜欢，与后半句“我太喜欢了”一致。", "无聊": "语义：“无聊”是乏味、没意思，与后半句“我太喜欢了”矛盾。", "陌生": "语义：“陌生”是不熟悉、没见过，与后半句“我太喜欢了”的喜爱之情不合。", "破旧": "语义：“破旧”指陈旧残损，与“我太喜欢了”的语气不合。"}, "sentence_index": 0, "correct_answer": "可心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到这个好消息，我很可心。", "explanation": "这里应该用〈高兴〉。可心说的是东西合心意，不用来形容人自己的情绪。"}, {"text": "孩子终于平安到家，妈妈很可心。", "explanation": "这里应该用〈放心〉。可心只说东西合人的心意，不表示人卸下心来的安心感。"}, {"text": "他把我的秘密说给了别人，我十分可心。", "explanation": "这里应该用〈生气〉。可心说的是东西合心意，不用来形容对他人背信的愤怒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95969, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可心", "is_correct": true, "explanation": "可心：东西合心意，与“没有一样”搭配，指一样都不合意。"}, {"text": "深刻", "is_correct": false, "explanation": "搭配：“深刻”形容思想或言论，不用来形容商品。"}, {"text": "动听", "is_correct": false, "explanation": "搭配：“动听”形容声音或歌曲，不能用来形容店里的东西。"}, {"text": "稀少", "is_correct": false, "explanation": "语义：“稀少”是数量少，与前句“东西很多”矛盾。"}], "explanations": {"可心": "可心：东西合心意，与“没有一样”搭配，指一样都不合意。", "深刻": "搭配：“深刻”形容思想或言论，不用来形容商品。", "动听": "搭配：“动听”形容声音或歌曲，不能用来形容店里的东西。", "稀少": "语义：“稀少”是数量少，与前句“东西很多”矛盾。"}, "sentence_index": 6, "correct_answer": "可心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直不肯吃饭，妈妈看着很可心。", "explanation": "这里应该用〈发愁〉。可心表示东西合心意，不用来形容为别人的饮食而忧虑。"}, {"text": "这个包的来路很可心。", "explanation": "这里应该用〈可疑〉。可心表示东西合心意，不用来形容来路可疑的情况。"}, {"text": "比赛输了，他很可心。", "explanation": "这里应该用〈失望〉。可心不用来表示人因失利而产生的失望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95969, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把伞轻便好用，拿着可心很。", "corrected_sentence": "这把伞轻便好用，拿着可心得很。", "error_description": "补语错误：程度补语应说“可心得很”，“得”不能省略；“可心很”把程度副词“很”直接放在形容词后，不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95969, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套碗碟用起来特别可心地。", "corrected_sentence": "这套碗碟用起来特别可心。", "error_description": "助词误用：“可心”作谓语，后面不加“地”；多加的“地”不对，应为“特别可心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
