INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95970, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "合乎心意，称心。", "primary_collocate": null, "pronunciation": "kě xīn", "ipa": "kʰɤ˨˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "他一直没找到可心的工作。", "target_word": "可心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份工作薪水高，离家又近，真可心。", "target_word": "可心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想找一位可心的老师。", "target_word": "可心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸换了新手机，用着特别可心。", "target_word": "可心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找到可心的搭档不容易。", "target_word": "可心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次旅行住的酒店很可心。", "target_word": "可心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我给孩子选了一所可心的学校。", "target_word": "可心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书正合我的口味，读起来很可心。", "target_word": "可心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他终于住进了一套可心的房子。", "target_word": "可心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在商场里看到一件可心的衣服。", "target_word": "可心", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "合乎心意、称心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a29a7b14-7b68-4d81-8215-6c329d1fefba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95970, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可心", "is_correct": true, "explanation": "可心：合乎心意、称心，符合“一直没找到”所说的寻找合意工作的语境。"}, {"text": "憨厚", "is_correct": false, "explanation": "搭配：“憨厚”形容人的品性，不能用来形容工作。"}, {"text": "懒惰", "is_correct": false, "explanation": "搭配：“懒惰”形容人的习性，工作不能说懒惰。"}, {"text": "狡猾", "is_correct": false, "explanation": "语义：“狡猾”含贬义，与一直在找合心意工作的语境不合。"}], "explanations": {"可心": "可心：合乎心意、称心，符合“一直没找到”所说的寻找合意工作的语境。", "憨厚": "搭配：“憨厚”形容人的品性，不能用来形容工作。", "懒惰": "搭配：“懒惰”形容人的习性，工作不能说懒惰。", "狡猾": "语义：“狡猾”含贬义，与一直在找合心意工作的语境不合。"}, "sentence_index": 0, "correct_answer": "可心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子不小心摔倒了，我看着很可心。", "explanation": "这里应该用〈心疼〉。可心表示称心、合心意，不用来形容看到孩子受伤时的怜惜。"}, {"text": "他一直吵个不停，我听着很可心。", "explanation": "这里应该用〈恼火〉。可心表示称心，不用来形容被吵闹后的烦躁。"}, {"text": "走夜路时，我一直很可心。", "explanation": "这里应该用〈害怕〉。可心表示称心，不用来表达走夜路时的恐惧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95970, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可心", "is_correct": true, "explanation": "可心：合乎心意、称心，与“给孩子选”时挑选合意学校的语境相合。"}, {"text": "调皮", "is_correct": false, "explanation": "搭配：“调皮”形容人或动物的性情，不能用来形容学校。"}, {"text": "幽默", "is_correct": false, "explanation": "搭配：“幽默”形容人的风趣，不能用来形容学校。"}, {"text": "危险", "is_correct": false, "explanation": "语义：“危险”与“给孩子选”的用意相反，句子说不通。"}], "explanations": {"可心": "可心：合乎心意、称心，与“给孩子选”时挑选合意学校的语境相合。", "调皮": "搭配：“调皮”形容人或动物的性情，不能用来形容学校。", "幽默": "搭配：“幽默”形容人的风趣，不能用来形容学校。", "危险": "语义：“危险”与“给孩子选”的用意相反，句子说不通。"}, "sentence_index": 6, "correct_answer": "可心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛输了，他很可心。", "explanation": "这里应该用〈失望〉。可心形容东西合心意，不用来表示人因输掉比赛而失望。"}, {"text": "他把钱全花光了，现在很可心。", "explanation": "这里应该用〈后悔〉。可心表示称心、合心意，不用来表达事后的悔恨。"}, {"text": "听说他病了，我很可心。", "explanation": "这里应该用〈担心〉。可心不用来表示人对他人的牵挂与忧虑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95970, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想给女儿找一位可心地家教。", "corrected_sentence": "他想给女儿找一位可心的家教。", "error_description": "助词误用：“可心”修饰名词“家教”，应用“的”，不能用“地”；“地”用于修饰动词，作状语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95970, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小房子住起来可心很。", "corrected_sentence": "这个小房子住起来可心得很。", "error_description": "补语错误：程度补语应说“可心得很”，“得”不能省略；“可心很”把程度副词“很”直接放在形容词后，不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95971, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "耻辱", "is_correct": true, "explanation": "正确。名誉指别人对人的好评价，耻辱指丢脸、受辱，二者意思相反。"}, {"text": "天气", "is_correct": false, "explanation": "天气与名誉的任何义项都没有近义或反义关系。"}, {"text": "石头", "is_correct": false, "explanation": "石头与名誉的任何义项都没有近义或反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "河流与名誉的任何义项都没有近义或反义关系。"}], "correct_answer": "耻辱", "explanations": {"耻辱": "正确。名誉指别人对人的好评价，耻辱指丢脸、受辱，二者意思相反。", "天气": "天气与名誉的任何义项都没有近义或反义关系。", "石头": "石头与名誉的任何义项都没有近义或反义关系。", "河流": "河流与名誉的任何义项都没有近义或反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
