INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95971, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名誉是别人对你的好看法。", "primary_collocate": null, "pronunciation": "míng yù", "ipa": "miŋ˧˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "他很爱惜自己的名誉。", "target_word": "名誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事影响了公司的名誉。", "target_word": "名誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的名誉一直很好。", "target_word": "名誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做坏事会毁掉一个人的名誉。", "target_word": "名誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师很看重自己的名誉，从来不说假话。", "target_word": "名誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了保住名誉，主动向大家道了歉。", "target_word": "名誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都知道他很看重自己的名誉。", "target_word": "名誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想为了钱丢掉名誉。", "target_word": "名誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不允许别人随便破坏他的名誉。", "target_word": "名誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谣言伤害了他的名誉。", "target_word": "名誉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名誉权", "label": "复合词"}, {"form": "名誉主席", "label": "复合词"}, {"form": "名誉教授", "label": "复合词"}], "register": "中性", "sense_fingerprint": "别人对一个人的好看法、好评价", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e91ed0ea-a5b4-4e39-8719-01c98cf926fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95971, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "名誉", "is_correct": true, "explanation": "正确。名誉（míng yù）指别人对一个人的好看法。"}, {"text": "名义", "is_correct": false, "explanation": "yì 与 yù 韵母不同（i / ü），名义指名称上或身份上的说法，意思不同。"}, {"text": "名录", "is_correct": false, "explanation": "lù 与 yù 首音不同（l / y），名录指名单、名册。"}, {"text": "名句", "is_correct": false, "explanation": "jù 与 yù 首音不同（j / y），名句指有名的句子。"}, {"text": "明月", "is_correct": false, "explanation": "yuè 与 yù 韵母不同（üe / ü），明月指明亮的月亮。"}, {"text": "名医", "is_correct": false, "explanation": "yī（第一声）与 yù（第四声）声调和韵母都不同，名医指有名的医生。"}], "explanations": {"名誉": "正确。名誉（míng yù）指别人对一个人的好看法。", "名义": "yì 与 yù 韵母不同（i / ü），名义指名称上或身份上的说法，意思不同。", "名录": "lù 与 yù 首音不同（l / y），名录指名单、名册。", "名句": "jù 与 yù 首音不同（j / y），名句指有名的句子。", "明月": "yuè 与 yù 韵母不同（üe / ü），明月指明亮的月亮。", "名医": "yī（第一声）与 yù（第四声）声调和韵母都不同，名医指有名的医生。"}, "sentence_index": null, "correct_answer": "名誉"}, "level_3": {"options": [{"text": "名誉", "is_correct": true, "explanation": "正确。“爱惜”可以用于名誉，指珍视别人对自己的好评价。"}, {"text": "饭量", "is_correct": false, "explanation": "搭配：“爱惜”多用于物品、身体、名誉等，不说爱惜饭量。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人可以爱惜的对象，句子意思不通。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不值得爱惜，与“自己的”搭配在一起语义荒谬。"}], "explanations": {"名誉": "正确。“爱惜”可以用于名誉，指珍视别人对自己的好评价。", "饭量": "搭配：“爱惜”多用于物品、身体、名誉等，不说爱惜饭量。", "天气": "语义：天气不是人可以爱惜的对象，句子意思不通。", "垃圾": "语义：垃圾不值得爱惜，与“自己的”搭配在一起语义荒谬。"}, "sentence_index": 0, "correct_answer": "名誉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他以老师的名誉给学生讲课。", "explanation": "这里应该用〈名义〉。“以……名义”表示身份或名目，名誉指别人对人的好评价，不能用来表示身份。"}, {"text": "请在表格上写下你的名誉。", "explanation": "这里应该用〈姓名〉。表格上要写的是姓名，名誉指社会评价，不是可以写在表格上的名字。"}, {"text": "他这次考试的名誉很好。", "explanation": "这里应该用〈成绩〉。名誉指别人对人的好评价，考试结果要说成绩，不能说名誉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95971, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名誉", "is_correct": true, "explanation": "正确。“看重自己的名誉”指很在意别人对自己的好评价。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾是没用的东西，不会被人看重。"}, {"text": "灰尘", "is_correct": false, "explanation": "语义：灰尘没有价值，“看重自己的灰尘”说不通。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：噪音让人讨厌，不是人看重的东西。"}], "explanations": {"名誉": "正确。“看重自己的名誉”指很在意别人对自己的好评价。", "垃圾": "语义：垃圾是没用的东西，不会被人看重。", "灰尘": "语义：灰尘没有价值，“看重自己的灰尘”说不通。", "噪音": "语义：噪音让人讨厌，不是人看重的东西。"}, "sentence_index": 6, "correct_answer": "名誉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校给我们班分了名誉。", "explanation": "这里应该用〈名额〉。名额是可以分配的数量，名誉指社会评价，不能被分配。"}, {"text": "这件衣服是名誉的，很贵。", "explanation": "这里应该用〈名牌〉。名牌指有名的商标，名誉指别人对人的好评价，不能用来形容商品。"}, {"text": "他把名誉递给了我。", "explanation": "这里应该用〈名片〉。“递”的对象是可以拿在手里的东西，名誉是社会评价，不能递给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95971, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "谣言打扰了他的名誉。", "corrected_sentence": "谣言损害了他的名誉。", "error_description": "搭配错误：“名誉”常与“损害、伤害”搭配；“打扰”用于人或人的活动，不能说“打扰名誉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95971, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一只名誉都没有了。", "corrected_sentence": "他一点名誉都没有了。", "error_description": "错误：“一只名誉”，正确应为“一点名誉”。“只”用于动物或单件物品，名誉是抽象的评价，不能用“只”计量；表示少量可以用“点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
