INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95972, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "个人或集体获得的社会评价和声望。", "primary_collocate": null, "pronunciation": "míng yù", "ipa": "miŋ˧˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "这所大学在国际上享有很高的名誉。", "target_word": "名誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院靠好服务赢得了名誉。", "target_word": "名誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家的名誉比个人的得失更重要。", "target_word": "名誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家在文坛上享有很高的名誉。", "target_word": "名誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队为集体的名誉努力比赛。", "target_word": "名誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的行为损害了学校的名誉。", "target_word": "名誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老字号的名誉是一百年积累下来的。", "target_word": "名誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生因为医术好而名誉很高。", "target_word": "名誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司必须保护自己的名誉。", "target_word": "名誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者不能随便损害别人的名誉。", "target_word": "名誉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名誉权", "label": "复合词"}, {"form": "名誉主席", "label": "复合词"}, {"form": "名誉教授", "label": "复合词"}], "register": "书面", "sense_fingerprint": "个人或集体获得的社会评价和声望", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e91ed0ea-a5b4-4e39-8719-01c98cf926fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95972, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "名誉", "is_correct": true, "explanation": "正确。名誉（míng yù）指个人或集体获得的社会评价和声望。"}, {"text": "名义", "is_correct": false, "explanation": "yì 与 yù 韵母不同（i / ü），名义指名称上或身份上的说法，意思不同。"}, {"text": "名录", "is_correct": false, "explanation": "lù 与 yù 首音不同（l / y），名录指名单、名册。"}, {"text": "名句", "is_correct": false, "explanation": "jù 与 yù 首音不同（j / y），名句指有名的句子。"}, {"text": "明月", "is_correct": false, "explanation": "yuè 与 yù 韵母不同（üe / ü），明月指明亮的月亮。"}, {"text": "名医", "is_correct": false, "explanation": "yī（第一声）与 yù（第四声）声调和韵母都不同，名医指有名的医生。"}], "explanations": {"名誉": "正确。名誉（míng yù）指个人或集体获得的社会评价和声望。", "名义": "yì 与 yù 韵母不同（i / ü），名义指名称上或身份上的说法，意思不同。", "名录": "lù 与 yù 首音不同（l / y），名录指名单、名册。", "名句": "jù 与 yù 首音不同（j / y），名句指有名的句子。", "明月": "yuè 与 yù 韵母不同（üe / ü），明月指明亮的月亮。", "名医": "yī（第一声）与 yù（第四声）声调和韵母都不同，名医指有名的医生。"}, "sentence_index": null, "correct_answer": "名誉"}, "level_3": {"options": [{"text": "名誉", "is_correct": true, "explanation": "正确。“享有”可以接名誉，指大学在国际上获得的社会声望。"}, {"text": "人数", "is_correct": false, "explanation": "搭配：“享有”后接的是名誉、权利、声望等抽象事物，不接“人数”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指人或动物的重量，大学没有体重，句子语义不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能被“享有”，句中要的是社会声望。"}], "explanations": {"名誉": "正确。“享有”可以接名誉，指大学在国际上获得的社会声望。", "人数": "搭配：“享有”后接的是名誉、权利、声望等抽象事物，不接“人数”。", "体重": "语义：体重指人或动物的重量，大学没有体重，句子语义不通。", "颜色": "语义：颜色不能被“享有”，句中要的是社会声望。"}, "sentence_index": 0, "correct_answer": "名誉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大会给每个代表分配了名誉。", "explanation": "这里应该用〈名额〉。名额是可以分配的数量，名誉指社会评价，不能分配给代表。"}, {"text": "他在这次比赛中得了第三名誉。", "explanation": "这里应该用〈名次〉。名次是比赛中的排列位次，名誉指社会评价，不能用来表示比赛的名次。"}, {"text": "她把名誉交给了客户。", "explanation": "这里应该用〈名片〉。“交给”的对象是可以拿在手里的东西，名誉是社会评价，不能交给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95972, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名誉", "is_correct": true, "explanation": "正确。“积累”可以用于名誉，指经过长时间积攒下来的社会声望。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指人体的高度，老字号没有身高，句子语义不通。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是人或动物的温度，不是靠时间积累下来的。"}, {"text": "视力", "is_correct": false, "explanation": "搭配：“积累”不搭配视力，视力不是一百年积累下来的。"}], "explanations": {"名誉": "正确。“积累”可以用于名誉，指经过长时间积攒下来的社会声望。", "身高": "语义：身高指人体的高度，老字号没有身高，句子语义不通。", "体温": "语义：体温是人或动物的温度，不是靠时间积累下来的。", "视力": "搭配：“积累”不搭配视力，视力不是一百年积累下来的。"}, "sentence_index": 6, "correct_answer": "名誉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我读了一本名誉的小说。", "explanation": "这里应该用〈名著〉。名著指有名的文学作品，名誉指社会评价，不能用来形容小说。"}, {"text": "快递员找不到我的名誉。", "explanation": "这里应该用〈地址〉。快递员找的是地址，名誉不能用来寻找投递位置。"}, {"text": "请在信封上写下收件人的名誉。", "explanation": "这里应该用〈名字〉。信封上要写的是收件人的名字，名誉指社会评价，不能写在信封上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95972, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那篇假新闻打扰了这家医院的名誉。", "corrected_sentence": "那篇假新闻损害了这家医院的名誉。", "error_description": "搭配错误：“名誉”常与“损害”搭配，“打扰”不能用于名誉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95972, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每个队员都应该保管球队的名誉。", "corrected_sentence": "每个队员都应该保护球队的名誉。", "error_description": "搭配错误：“保管”用于具体物品，名誉是抽象评价，应说“保护名誉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '363dea80-3df7-4a5d-be65-031b82f29f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
