INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95974, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "古代婚礼“六礼”之一，男方请媒人询问女方的姓名和生辰。", "primary_collocate": null, "pronunciation": "wèn míng", "ipa": "wən˥˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "问名是古代婚礼六礼之一。", "target_word": "问名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古代婚礼有六礼，问名是第二个。", "target_word": "问名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "纳采以后，就是问名。", "target_word": "问名", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "问名时，媒人要问女方的生辰。", "target_word": "问名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "男方请媒人去女方家行问名之礼。", "target_word": "问名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "问名的时候，女方家要写下姓名和生辰。", "target_word": "问名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，古人结婚要经过纳采、问名等六礼。", "target_word": "问名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "问名以后，男方才去占卜吉凶。", "target_word": "问名", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在博物馆里看到了问名的介绍。", "target_word": "问名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们说说问名是什么。", "target_word": "问名", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "問名", "label": "繁体"}], "register": "书面", "sense_fingerprint": "古代婚礼六礼中的第二礼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bc3fefe-ca22-418d-b568-6a52acd06a5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95974, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "问名", "is_correct": true, "explanation": "“问名”是古代婚礼六礼之一，符合句意。"}, {"text": "婚纱", "is_correct": false, "explanation": "语义：婚纱是现代婚礼用品，不属于古代六礼。"}, {"text": "喜宴", "is_correct": false, "explanation": "搭配：“六礼之一”只能接礼节名称，不能说喜宴是其中一礼。"}, {"text": "蜜月", "is_correct": false, "explanation": "语义：蜜月是婚后的假期，不是古代婚礼的步骤。"}], "explanations": {"问名": "“问名”是古代婚礼六礼之一，符合句意。", "婚纱": "语义：婚纱是现代婚礼用品，不属于古代六礼。", "喜宴": "搭配：“六礼之一”只能接礼节名称，不能说喜宴是其中一礼。", "蜜月": "语义：蜜月是婚后的假期，不是古代婚礼的步骤。"}, "sentence_index": 0, "correct_answer": "问名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校的开学问名很隆重，全校同学都参加了。", "explanation": "这里应该用〈仪式〉。“问名”是婚礼六礼中的一礼，专指男方请媒人问女方姓名和生辰，不能用于开学活动。"}, {"text": "我们班来了一个问名。", "explanation": "这里应该用〈同学〉。“问名”是礼节名称，不能指班里来的人。"}, {"text": "他把问名放进了书包。", "explanation": "这里应该用〈礼物〉。“问名”是抽象的礼节，不是具体的东西，不能像礼物一样装进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95974, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "问名", "is_correct": true, "explanation": "“问名”是六礼之一，与“纳采、……等六礼”的列举相合。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是现代物品，不是古代六礼的步骤。"}, {"text": "请柬", "is_correct": false, "explanation": "语义：请柬是现代邀约用的，不在古代六礼之内。"}, {"text": "礼堂", "is_correct": false, "explanation": "搭配：礼堂是场所，不能作为六礼中的一礼。"}], "explanations": {"问名": "“问名”是六礼之一，与“纳采、……等六礼”的列举相合。", "手机": "语义：手机是现代物品，不是古代六礼的步骤。", "请柬": "语义：请柬是现代邀约用的，不在古代六礼之内。", "礼堂": "搭配：礼堂是场所，不能作为六礼中的一礼。"}, "sentence_index": 6, "correct_answer": "问名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "女方准备了很多问名。", "explanation": "这里应该用〈嫁妆〉。“问名”是礼节名称，不能像嫁妆一样去准备。"}, {"text": "这次问名的价格很贵。", "explanation": "这里应该用〈彩礼〉。“问名”是礼节，本身不能标价。"}, {"text": "我的问名很好看，你要不要看看？", "explanation": "这里应该用〈照片〉。“问名”是礼节名称，不能用来形容好看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古代婚礼有六礼，其中一只是问名。", "corrected_sentence": "古代婚礼有六礼，其中一项是问名。", "error_description": "量词错误：“问名”是礼节名称，计量应用“项”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在博物馆看到了六礼中问名。", "corrected_sentence": "我们在博物馆看到了六礼中的问名。", "error_description": "缺少“的”：“六礼中”修饰“问名”，中间须用“的”连接，应说“六礼中的问名”，不能省去“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95975, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "停用", "is_correct": true, "explanation": "停用：与“启用”相对，指不再投入使用，两者构成反义关系。"}, {"text": "设计", "is_correct": false, "explanation": "设计：表示事先规划、画图，与“启用”没有反义关系。"}, {"text": "修建", "is_correct": false, "explanation": "修建：表示建造，与“启用”没有反义关系。"}, {"text": "购买", "is_correct": false, "explanation": "购买：表示花钱买进，与“启用”没有反义关系。"}], "correct_answer": "停用", "explanations": {"停用": "停用：与“启用”相对，指不再投入使用，两者构成反义关系。", "设计": "设计：表示事先规划、画图，与“启用”没有反义关系。", "修建": "修建：表示建造，与“启用”没有反义关系。", "购买": "购买：表示花钱买进，与“启用”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
