INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95975, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "启用是把新东西开始拿来用。", "primary_collocate": null, "pronunciation": "qǐ yòng", "ipa": "tɕʰi˨˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "学校下个月启用新的教学楼。", "target_word": "启用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座新桥今天正式启用。", "target_word": "启用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司启用了新的办公系统。", "target_word": "启用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新机场已经启用，飞机不再用旧机场。", "target_word": "启用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院启用了一台新设备。", "target_word": "启用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆的新阅览室明天启用。", "target_word": "启用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新大楼启用后，市民办事方便多了。", "target_word": "启用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个新软件我们公司刚启用。", "target_word": "启用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂启用新机器后，产量提高了不少。", "target_word": "启用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新车站启用那天，来了很多人。", "target_word": "启用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "启用了", "label": "体标"}, {"form": "启用过", "label": "体标"}, {"form": "重新启用", "label": "复合"}], "register": "书面", "sense_fingerprint": "新建或新购的设施、设备、系统开始投入使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea0b2d16-fd3c-4652-81a5-d83fbc5fa0b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95975, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "启用", "is_correct": true, "explanation": "启用：开始投入使用，符合“下个月”的安排和“新的教学楼”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”只用于食物，不能说“吃新的教学楼”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”只用于饮品，不能说“喝新的教学楼”。"}, {"text": "偷", "is_correct": false, "explanation": "语义：偷是非法取走，学校不会被偷，与句中的正常安排不符。"}], "explanations": {"启用": "启用：开始投入使用，符合“下个月”的安排和“新的教学楼”的语境。", "吃": "搭配：“吃”只用于食物，不能说“吃新的教学楼”。", "喝": "搭配：“喝”只用于饮品，不能说“喝新的教学楼”。", "偷": "语义：偷是非法取走，学校不会被偷，与句中的正常安排不符。"}, "sentence_index": 0, "correct_answer": "启用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上都启用这台电脑工作。", "explanation": "这里应该用〈使用〉。“启用”强调开始投入使用，不用于每天反复的日常使用。"}, {"text": "大家一起启用了丰盛的晚餐。", "explanation": "这里应该用〈享用〉。“启用”用于设施、系统开始投入使用，不能用于食物。"}, {"text": "这种新技术已经启用到日常生活中。", "explanation": "这里应该用〈应用〉。“启用”强调开始投入使用，“应用到……中”的说法不能换成“启用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95975, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "启用", "is_correct": true, "explanation": "启用：新大楼投入使用，才能让市民办事更方便，符合句意。"}, {"text": "关闭", "is_correct": false, "explanation": "语义：关闭后市民无法办事，与“方便多了”的结果矛盾。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：拆除大楼后市民办事不可能更方便，与句意相反。"}, {"text": "放大", "is_correct": false, "explanation": "搭配：“放大”多用于图像、声音等，不说“放大新大楼”。"}], "explanations": {"启用": "启用：新大楼投入使用，才能让市民办事更方便，符合句意。", "关闭": "语义：关闭后市民无法办事，与“方便多了”的结果矛盾。", "拆除": "语义：拆除大楼后市民办事不可能更方便，与句意相反。", "放大": "搭配：“放大”多用于图像、声音等，不说“放大新大楼”。"}, "sentence_index": 6, "correct_answer": "启用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他启用门走了出去。", "explanation": "这里应该用〈开〉。“启用”只用于新设施或系统开始投入使用，开门是日常动作。"}, {"text": "他很会启用这些知识，成绩很好。", "explanation": "这里应该用〈运用〉。“启用”指设施或系统开始投入使用，知识的运用应说“运用”。"}, {"text": "这场比赛明天启用。", "explanation": "这里应该用〈开始〉。“启用”指设施或系统开始投入使用，比赛不能用“启用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95975, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套新系统今天还没启用了。", "corrected_sentence": "这套新系统今天还没启用。", "error_description": "“没”否定尚未发生的事，句末不加“了”。应说“还没启用”，不能说“还没启用了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95975, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个功能还不启用过，你可以先试试。", "corrected_sentence": "这个功能还没启用过，你可以先试试。", "error_description": "表示经历未发生时用“没”，不用“不”。“不”用于习惯或主观意愿，应说“还没启用过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
