INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95976, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "备用或新的设施、设备等开始投入使用。", "primary_collocate": null, "pronunciation": "qǐ yòng", "ipa": "tɕʰi˨˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "备用电脑已经启用。", "target_word": "启用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校启用了新的校园卡。", "target_word": "启用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旧办公室不用了，新办公室下周启用。", "target_word": "启用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院启用了新的挂号系统。", "target_word": "启用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个新账号明天就启用。", "target_word": "启用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "停电后，工厂启用了备用发电机。", "target_word": "启用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "景区的新入口从周一起启用。", "target_word": "启用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们启用新软件后，工作快多了。", "target_word": "启用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条新路启用了一个星期，就出现了问题。", "target_word": "启用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先启用这个新的安全功能，再登录系统。", "target_word": "启用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "启用了", "label": "体标"}, {"form": "启用过", "label": "体标"}, {"form": "重新启用", "label": "复合"}], "register": "书面", "sense_fingerprint": "备用或新的东西开始投入使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea0b2d16-fd3c-4652-81a5-d83fbc5fa0b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95976, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "启用", "is_correct": true, "explanation": "启用：开始使用，与“备用电脑”的语境相合。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”只用于食物，不能说“备用电脑已经吃”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：电脑不会唱歌，与句子的陈述不符。"}, {"text": "哭", "is_correct": false, "explanation": "语义：电脑不会哭，这是把物拟人化的说法，与句中语境不符。"}], "explanations": {"启用": "启用：开始使用，与“备用电脑”的语境相合。", "吃": "搭配：“吃”只用于食物，不能说“备用电脑已经吃”。", "唱": "语义：电脑不会唱歌，与句子的陈述不符。", "哭": "语义：电脑不会哭，这是把物拟人化的说法，与句中语境不符。"}, "sentence_index": 0, "correct_answer": "启用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很会启用这些知识，成绩很好。", "explanation": "这里应该用〈运用〉。“启用”指设施或系统开始投入使用，知识的运用应说“运用”。"}, {"text": "大家一起启用丰盛的晚餐。", "explanation": "这里应该用〈享用〉。“启用”用于设施、系统，不能用于食物。"}, {"text": "他每天都启用这把旧锤子修东西。", "explanation": "这里应该用〈使用〉。“启用”强调开始投入使用，旧工具的日常使用应说“使用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95976, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "启用", "is_correct": true, "explanation": "启用：从周一开始投入使用，与“从周一起”的时间安排相合。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣物等，不能说“景区的新入口从周一起穿”。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：入口不会呼吸，这一动作与句子的陈述不符。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：入口不会微笑，这一动作与句子的陈述不符。"}], "explanations": {"启用": "启用：从周一开始投入使用，与“从周一起”的时间安排相合。", "穿": "搭配：“穿”用于衣物等，不能说“景区的新入口从周一起穿”。", "呼吸": "语义：入口不会呼吸，这一动作与句子的陈述不符。", "微笑": "语义：入口不会微笑，这一动作与句子的陈述不符。"}, "sentence_index": 6, "correct_answer": "启用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要充分启用空闲时间。", "explanation": "这里应该用〈利用〉。“启用”指设施或系统开始投入使用，空闲时间的充分运用应说“利用”。"}, {"text": "这次讲座下周启用。", "explanation": "这里应该用〈开始〉。“启用”指设施或系统开始投入使用，讲座是活动，应说“开始”。"}, {"text": "他们启用了三天的假期。", "explanation": "这里应该用〈享受〉。“启用”用于设施、系统等，假期是用来享受的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台备用打印机还没启用了，你先别用。", "corrected_sentence": "这台备用打印机还没启用，你先别用。", "error_description": "“了”不能用于“没”否定的未发生动作之后。应说“还没启用”，不能说“还没启用了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "景区的新入口上周已经启用着了。", "corrected_sentence": "景区的新入口上周已经启用了。", "error_description": "“启用”表示开始投入使用，是一次完成的变化，不能加持续体“着”。应说“已经启用了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
