INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95977, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "启发是用话帮助别人自己想明白。", "primary_collocate": null, "pronunciation": "qǐ fā", "ipa": "tɕʰi˨˩˦ fa˥", "syllable_count": 2, "sentences": [{"text": "老师用问题启发学生。", "target_word": "启发", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他没有直接告诉我，只是启发我自己想。", "target_word": "启发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的老师善于启发孩子。", "target_word": "启发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈慢慢启发他，他终于明白了。", "target_word": "启发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友几句话就启发了我，我一下子想明白了。", "target_word": "启发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师先问了几个问题来启发大家。", "target_word": "启发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸不批评他，只是耐心地启发他。", "target_word": "启发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教练一边做示范，一边启发队员。", "target_word": "启发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用提问的办法启发孩子学数学。", "target_word": "启发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道题很难，老师启发了我们好几次。", "target_word": "启发", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "启发了", "label": "体标"}, {"form": "启发过", "label": "体标"}, {"form": "启发着", "label": "体标"}, {"form": "启发性", "label": "复合"}, {"form": "启发式", "label": "复合"}, {"form": "啟發", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用话引导别人自己想明白", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a29a7b14-7b68-4d81-8215-6c329d1fefba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95977, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "启发", "is_correct": true, "explanation": "启发：用问题引导学生自己想明白，与句意相符。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象是需要喂食的动物或婴儿，不能用来指学生。"}, {"text": "押送", "is_correct": false, "explanation": "语义：“押送”是把人带到某处看管，与用问题引导学习的做法不合。"}, {"text": "放牧", "is_correct": false, "explanation": "搭配：“放牧”的对象是牲畜，不能用于学生。"}], "explanations": {"启发": "启发：用问题引导学生自己想明白，与句意相符。", "喂": "搭配：“喂”的对象是需要喂食的动物或婴儿，不能用来指学生。", "押送": "语义：“押送”是把人带到某处看管，与用问题引导学习的做法不合。", "放牧": "搭配：“放牧”的对象是牲畜，不能用于学生。"}, "sentence_index": 0, "correct_answer": "启发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天启发那块地，种上了蔬菜。", "explanation": "这里应该用〈耕种〉。启发是引导人想明白，不能用于对土地作业。"}, {"text": "他按下按钮，启发了电脑。", "explanation": "这里应该用〈开启〉。启发是引导人思考，不用于打开电脑这类设备。"}, {"text": "保安一直启发着大门。", "explanation": "这里应该用〈监视〉。启发指引导人明白道理，不用于看守大门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95977, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "启发", "is_correct": true, "explanation": "启发：耐心引导他自己想明白，与“不批评”形成对照，符合语境。"}, {"text": "责骂", "is_correct": false, "explanation": "语义：“责骂”是严厉斥责，与“不批评”和“耐心地”相矛盾。"}, {"text": "殴打", "is_correct": false, "explanation": "语义：“殴打”是动手伤人，与“耐心地”的做法完全不合。"}, {"text": "焊接", "is_correct": false, "explanation": "搭配：“焊接”的对象是金属等物件，不能用于人。"}], "explanations": {"启发": "启发：耐心引导他自己想明白，与“不批评”形成对照，符合语境。", "责骂": "语义：“责骂”是严厉斥责，与“不批评”和“耐心地”相矛盾。", "殴打": "语义：“殴打”是动手伤人，与“耐心地”的做法完全不合。", "焊接": "搭配：“焊接”的对象是金属等物件，不能用于人。"}, "sentence_index": 6, "correct_answer": "启发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈认真启发了蔬菜。", "explanation": "这里应该用〈清洗〉。启发的对象是人，不用于洗涤蔬菜。"}, {"text": "他明天启发去北京。", "explanation": "这里应该用〈启程〉。启发指引导人想明白，不表示出发。"}, {"text": "他花了一下午启发那台电视。", "explanation": "这里应该用〈修理〉。启发的对象是人，不指修理器械。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95977, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她擅长很启发孩子思考。", "corrected_sentence": "她擅长启发孩子思考。", "error_description": "副词位置错误：程度副词“很”不能直接修饰动词“启发”，“擅长”后应直接接动词，应为“擅长启发孩子思考”；“擅长很启发”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95977, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师耐心的启发学生独立思考。", "corrected_sentence": "老师耐心地启发学生独立思考。", "error_description": "助词误用：修饰动词“启发”的状语要用“地”，写成“的”不对，应为“耐心地启发”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
