INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95978, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "阐明事理，引导人思考并有所领悟。", "primary_collocate": null, "pronunciation": "qǐ fā", "ipa": "tɕʰi˨˩˦ fa˥", "syllable_count": 2, "sentences": [{"text": "老师的一句话启发了我。", "target_word": "启发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事启发我们要爱护环境。", "target_word": "启发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好老师会启发学生自己思考。", "target_word": "启发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书启发了很多年轻人。", "target_word": "启发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷用一个小故事启发了我。", "target_word": "启发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的成功启发我不要轻易放弃。", "target_word": "启发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈想启发孩子多问为什么。", "target_word": "启发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次旅行启发她开始写作。", "target_word": "启发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生的话启发了他改变生活习惯。", "target_word": "启发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师没有直接说答案，而是启发大家去想。", "target_word": "启发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "启发了", "label": "体标"}, {"form": "启发过", "label": "体标"}, {"form": "启发着", "label": "体标"}, {"form": "启发性", "label": "复合"}, {"form": "启发式", "label": "复合"}, {"form": "啟發", "label": "繁体"}], "register": "中性", "sense_fingerprint": "阐明事理、引人思考领悟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a29a7b14-7b68-4d81-8215-6c329d1fefba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95978, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "启发", "is_correct": true, "explanation": "启发：阐明道理，引导我思考并有所领悟，与句意相符。"}, {"text": "粉刷", "is_correct": false, "explanation": "搭配：“粉刷”的对象是墙壁等物体，不能说一句话粉刷了人。"}, {"text": "关押", "is_correct": false, "explanation": "语义：“关押”指拘禁，与一句话带来领悟的作用完全不合。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”的对象是需要供给食物的人或动物，不用来指一句话。"}], "explanations": {"启发": "启发：阐明道理，引导我思考并有所领悟，与句意相符。", "粉刷": "搭配：“粉刷”的对象是墙壁等物体，不能说一句话粉刷了人。", "关押": "语义：“关押”指拘禁，与一句话带来领悟的作用完全不合。", "喂养": "搭配：“喂养”的对象是需要供给食物的人或动物，不用来指一句话。"}, "sentence_index": 0, "correct_answer": "启发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民每天启发庄稼。", "explanation": "这里应该用〈灌溉〉。启发是引导人想明白，对象是人，不用于给庄稼浇水。"}, {"text": "他划着火柴，启发了炉子。", "explanation": "这里应该用〈点燃〉。启发是引导人思考，不用于点火。"}, {"text": "这台机器一按按钮就启发了。", "explanation": "这里应该用〈启动〉。启发指引导人思考，不用于机器开动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95978, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "启发", "is_correct": true, "explanation": "启发：引导孩子自己思考，与“多问为什么”的语境相合。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”的对象是动物或植物，不能用于孩子。"}, {"text": "清洗", "is_correct": false, "explanation": "语义：“清洗”是洗刷，与“多问为什么”无关，句子不通。"}, {"text": "购买", "is_correct": false, "explanation": "配价：“购买”要带所买的物品作宾语，不能带“孩子多问为什么”这样的小句。"}], "explanations": {"启发": "启发：引导孩子自己思考，与“多问为什么”的语境相合。", "饲养": "搭配：“饲养”的对象是动物或植物，不能用于孩子。", "清洗": "语义：“清洗”是洗刷，与“多问为什么”无关，句子不通。", "购买": "配价：“购买”要带所买的物品作宾语，不能带“孩子多问为什么”这样的小句。"}, "sentence_index": 6, "correct_answer": "启发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他轻轻一推，启发了房门。", "explanation": "这里应该用〈推开〉。启发是引导人思考，不能用来表示推门。"}, {"text": "他把成绩启发给全班同学。", "explanation": "这里应该用〈公布〉。启发是引导人思考，不用于把成绩告知众人。"}, {"text": "工人每天启发钢铁，做出了零件。", "explanation": "这里应该用〈锻造〉。启发是引导人思考，不用于加工金属。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师会很启发学生。", "corrected_sentence": "这位老师很会启发学生。", "error_description": "语序错误：程度副词“很”应放在能愿动词“会”前，说“很会启发”；“会很启发”语序不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师耐心的启发大家自己去想。", "corrected_sentence": "老师耐心地启发大家自己去想。", "error_description": "助词误用：修饰动词“启发”的状语要用“地”，写成“的”不对，应为“耐心地启发”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95979, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拙于", "is_correct": true, "explanation": "正确：“拙于”与“善于”是反义词，指不擅长做某事。"}, {"text": "参加", "is_correct": false, "explanation": "参加与“善于”没有反义关系，是“参与”的意思。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论与“善于”没有反义关系，指交换意见。"}, {"text": "同意", "is_correct": false, "explanation": "同意与“善于”没有反义关系，指赞成某个看法。"}], "correct_answer": "拙于", "explanations": {"拙于": "正确：“拙于”与“善于”是反义词，指不擅长做某事。", "参加": "参加与“善于”没有反义关系，是“参与”的意思。", "讨论": "讨论与“善于”没有反义关系，指交换意见。", "同意": "同意与“善于”没有反义关系，指赞成某个看法。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95979, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拙于", "is_correct": true, "explanation": "正确：“拙于”与“善于”是反义词，指不擅长做某事。"}, {"text": "愿意", "is_correct": false, "explanation": "愿意与“善于”没有反义关系，指乐意做某事。"}, {"text": "赞成", "is_correct": false, "explanation": "赞成与“善于”没有反义关系，指支持某个主张。"}, {"text": "选择", "is_correct": false, "explanation": "选择与“善于”没有反义关系，指从若干中挑出一个。"}], "correct_answer": "拙于", "explanations": {"拙于": "正确：“拙于”与“善于”是反义词，指不擅长做某事。", "愿意": "愿意与“善于”没有反义关系，指乐意做某事。", "赞成": "赞成与“善于”没有反义关系，指支持某个主张。", "选择": "选择与“善于”没有反义关系，指从若干中挑出一个。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95979, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "善于是做某件事做得特别好。", "primary_collocate": null, "pronunciation": "shàn yú", "ipa": "ʂan˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "他很善于讲故事，孩子们都爱听。", "target_word": "善于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李善于和陌生人聊天。", "target_word": "善于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师善于用简单的话讲难题。", "target_word": "善于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈善于做各种家常菜。", "target_word": "善于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她善于发现生活中的小美好。", "target_word": "善于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的经理善于听别人的意见。", "target_word": "善于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟不善于说谎，一说就脸红。", "target_word": "善于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他善于画画，墙上都是他的作品。", "target_word": "善于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友善于照顾病人。", "target_word": "善于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师善于让课堂变得有趣。", "target_word": "善于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不善于", "label": "否定"}], "register": "中性", "sense_fingerprint": "善于+动词：做某件事做得特别好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53ba7404-397a-4364-acdd-387f7357410c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95979, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "善于", "is_correct": true, "explanation": "正确：“很善于”可以修饰能力，“很善于讲故事”通顺，且与“孩子们都爱听”相符。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“很”不修饰“拒绝”这类一次性动作，“很拒绝讲故事”不通。"}, {"text": "结束", "is_correct": false, "explanation": "语义：“结束”表示停止，不能用“很”修饰，与“讲故事”这种持续能力的语境不符。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”要带人和物的宾语，不能直接带“讲故事”这样的动作短语。"}], "explanations": {"善于": "正确：“很善于”可以修饰能力，“很善于讲故事”通顺，且与“孩子们都爱听”相符。", "拒绝": "搭配：“很”不修饰“拒绝”这类一次性动作，“很拒绝讲故事”不通。", "结束": "语义：“结束”表示停止，不能用“很”修饰，与“讲故事”这种持续能力的语境不符。", "送": "配价：“送”要带人和物的宾语，不能直接带“讲故事”这样的动作短语。"}, "sentence_index": 0, "correct_answer": "善于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他善于打开那扇门。", "explanation": "这里应该用〈会〉。善于强调经过练习后擅长的本领，打开门只是一次动作，只能用“会”。"}, {"text": "我善于每天早起。", "explanation": "这里应该用〈习惯〉。善于表示擅长某种本领，“每天早起”是生活习惯，不是本领。"}, {"text": "他善于怕狗，见到狗就躲。", "explanation": "这里应该用〈害怕〉。善于表示擅长某种本领，“怕狗”是情绪，不是本领，要说“害怕狗”，不能用善于。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95979, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "善于", "is_correct": true, "explanation": "正确：“不善于说谎”表示不擅长说谎，与“一说就脸红”相符。"}, {"text": "便于", "is_correct": false, "explanation": "语义：“便于”表示有利于做某事，“不便于说谎”语义不通。"}, {"text": "关于", "is_correct": false, "explanation": "语法：“关于”是介词，引出话题，不能受“不”修饰，“不关于说谎”不通。"}, {"text": "善待", "is_correct": false, "explanation": "配价：“善待”要带人作宾语，“善待说谎”不通。"}], "explanations": {"善于": "正确：“不善于说谎”表示不擅长说谎，与“一说就脸红”相符。", "便于": "语义：“便于”表示有利于做某事，“不便于说谎”语义不通。", "关于": "语法：“关于”是介词，引出话题，不能受“不”修饰，“不关于说谎”不通。", "善待": "配价：“善待”要带人作宾语，“善待说谎”不通。"}, "sentence_index": 6, "correct_answer": "善于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈善于忘带钥匙，每次出门都要回来拿。", "explanation": "这里应该用〈总是〉。善于表示擅长某种本领，“忘带钥匙”是坏习惯，不是本领。"}, {"text": "他很善于感冒，一到冬天就生病。", "explanation": "这里应该用〈容易〉。善于指擅长做某事，描述容易发生的情况要用“容易”。"}, {"text": "我善于失眠，晚上很难入睡。", "explanation": "这里应该用〈经常〉。善于说明擅长的本领，“失眠”是身体状况，不是本领。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95979, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她善于了跟孩子沟通。", "corrected_sentence": "她善于跟孩子沟通。", "error_description": "错误：“善于”表示擅长的状态，后面不能加“了”。正确说法是“她善于跟孩子沟通”，去掉“了”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95979, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她善于过讲故事，所以朋友很多。", "corrected_sentence": "她善于讲故事，所以朋友很多。", "error_description": "错误：“善于”表示擅长的状态，不能在后面加“过”。正确说法是“她善于讲故事”，去掉“过”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
