INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95982, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "到处；各个地方。", "primary_collocate": null, "pronunciation": "sì chù", "ipa": "sɨ˥˩ ʈʂʰu˥˩", "syllable_count": 2, "sentences": [{"text": "爸爸四处打电话，想借一辆车。", "target_word": "四处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了工作四处跑。", "target_word": "四处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们四处找老师的办公室。", "target_word": "四处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，大家四处躲雨。", "target_word": "四处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直四处旅行，没有固定的家。", "target_word": "四处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水洒了，地上四处都是水。", "target_word": "四处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她四处看看，想找个座位。", "target_word": "四处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消息很快就四处传开了。", "target_word": "四处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟在树上四处张望。", "target_word": "四处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们四处逛逛，买了一些东西。", "target_word": "四处", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：到处、各个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '996bd829-ae6b-4c7b-887c-9cabc20a2540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95982, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "四处", "is_correct": true, "explanation": "副词，指到各个地方，与“打电话找车”的四处奔走相符。"}, {"text": "当面", "is_correct": false, "explanation": "搭配：“当面”指面对面，与“打电话”这种远程联络的方式矛盾。"}, {"text": "一齐", "is_correct": false, "explanation": "语义：“一齐”要求多个主体同时行动，句子主语只是“爸爸”一人。"}, {"text": "手机", "is_correct": false, "explanation": "词性：“手机”是名词，不能直接作状语修饰“打电话”，应说“用手机打电话”。"}], "explanations": {"四处": "副词，指到各个地方，与“打电话找车”的四处奔走相符。", "当面": "搭配：“当面”指面对面，与“打电话”这种远程联络的方式矛盾。", "一齐": "语义：“一齐”要求多个主体同时行动，句子主语只是“爸爸”一人。", "手机": "词性：“手机”是名词，不能直接作状语修饰“打电话”，应说“用手机打电话”。"}, "sentence_index": 0, "correct_answer": "四处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他四处坐在教室的第一排。", "explanation": "这里应该用〈总是〉。“四处”表示分散在各处、来回走动，不能描写固定坐在一个位置，应说“他总是坐在教室的第一排”。"}, {"text": "我们四处在操场上集合。", "explanation": "这里应该用〈集中〉。“四处”指分散在各个地方，与要求大家聚到一处的意思相反，应说“集中”。"}, {"text": "他四处在学校门口等我。", "explanation": "这里应该用〈一直〉。“四处”指分散在多个地方，只在一个固定地点等人要用“一直”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95982, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "四处", "is_correct": true, "explanation": "副词，指到各处看看，与“想找个座位”的寻找相符。"}, {"text": "一并", "is_correct": false, "explanation": "语义：“一并”表示把多件事合在一起办，与“她看看”这一个动作不合。"}, {"text": "亲手", "is_correct": false, "explanation": "搭配：“亲手”强调用手亲自做某事，不能修饰“看看”这种随意的动作。"}, {"text": "顿时", "is_correct": false, "explanation": "语义：“顿时”表示突然发生的变化，与“看看”这种随意的动作不符。"}], "explanations": {"四处": "副词，指到各处看看，与“想找个座位”的寻找相符。", "一并": "语义：“一并”表示把多件事合在一起办，与“她看看”这一个动作不合。", "亲手": "搭配：“亲手”强调用手亲自做某事，不能修饰“看看”这种随意的动作。", "顿时": "语义：“顿时”表示突然发生的变化，与“看看”这种随意的动作不符。"}, "sentence_index": 6, "correct_answer": "四处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他四处躺在床上。", "explanation": "这里应该用〈一直〉。“四处”表示分散在各处，躺在床上是固定的地方，要用“一直”。"}, {"text": "他被四处关在房间里。", "explanation": "这里应该用〈一直〉。“四处”表示分散在各处，被关在一个房间里是固定的地点，要用“一直”。"}, {"text": "我们四处一起开会。", "explanation": "这里应该用〈集中〉。“四处”指分散在各处，与“一起开会”要求的聚在一处相反，应说“集中开会”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他为了生活四处了奔波。", "corrected_sentence": "他为了生活四处奔波。", "error_description": "错误：“四处”后多了“了”；正确：“四处奔波”。“了”表示完成，不能插在副词“四处”与动词“奔波”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们四处了打听消息。", "corrected_sentence": "他们四处打听消息。", "error_description": "错误：“四处”后多了“了”；正确：“四处打听”。“了”不能插在副词“四处”和动词“打听”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
