INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95985, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "型号是同一种东西里不同的样子或大小的名字。", "primary_collocate": null, "pronunciation": "xíng hào", "ipa": "ɕiŋ˧˥ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这双鞋有三种型号，你穿哪个型号？", "target_word": "型号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的型号太小了，我穿不上。", "target_word": "型号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我你要的型号，我帮你找。", "target_word": "型号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同一种螺丝有大小不同的型号。", "target_word": "型号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子有大、中、小三个型号。", "target_word": "型号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里这种帽子的型号很全。", "target_word": "型号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的脚大，要买大一点的型号。", "target_word": "型号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种运动鞋有好几个型号，要选适合自己的。", "target_word": "型号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道孩子该穿哪个型号。", "target_word": "型号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买错了型号，鞋子穿着太挤。", "target_word": "型号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "型號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "同类物品的样式或大小名称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a29a7b14-7b68-4d81-8215-6c329d1fefba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95985, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "型号", "is_correct": true, "explanation": "正确：“三种型号”指鞋子的规格，与后一句的“穿哪个”呼应。"}, {"text": "味道", "is_correct": false, "explanation": "语义：鞋子没有“三种味道”可以选来穿，句子不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：鞋子不会有“河流”这一类别，“三种河流”没有意义。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间是抽象概念，不能说“三种时间”让人去“穿”。"}], "explanations": {"型号": "正确：“三种型号”指鞋子的规格，与后一句的“穿哪个”呼应。", "味道": "语义：鞋子没有“三种味道”可以选来穿，句子不通。", "河流": "语义：鞋子不会有“河流”这一类别，“三种河流”没有意义。", "时间": "语义：时间是抽象概念，不能说“三种时间”让人去“穿”。"}, "sentence_index": 0, "correct_answer": "型号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间的型号很大。", "explanation": "这里应该用〈尺寸〉。型号是同类产品的规格名称，房间不是产品，不能用型号。"}, {"text": "这家店有三只型号。", "explanation": "量词用错。〈只〉用于动物或成对物品中的一件，型号应用〈种〉或〈个〉。"}, {"text": "他的型号很幽默。", "explanation": "型号指产品的规格名称，不能用来形容人的性格，应说〈性格〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95985, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "型号", "is_correct": true, "explanation": "正确：脚大需要买大一号的鞋，“大一点的型号”合理。"}, {"text": "亮度", "is_correct": false, "explanation": "搭配：“买”的对象应是可买的东西，“亮度”不能买。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是可以买的大小规格，语义不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能用“大一点”来购买，也与脚的大小无关。"}], "explanations": {"型号": "正确：脚大需要买大一号的鞋，“大一点的型号”合理。", "亮度": "搭配：“买”的对象应是可买的东西，“亮度”不能买。", "河流": "语义：河流不是可以买的大小规格，语义不通。", "天气": "语义：天气不能用“大一点”来购买，也与脚的大小无关。"}, "sentence_index": 6, "correct_answer": "型号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的身份证型号是多少？", "explanation": "这里应该用〈号码〉。身份证上的是个人编号，不是产品规格，型号只用于产品。"}, {"text": "我买了一双型号。", "explanation": "量词用错。〈双〉用于成对的物品，型号应用〈种〉或〈个〉。"}, {"text": "这首歌的型号很好听。", "explanation": "这里应该用〈旋律〉。型号是产品的规格名称，不能用来评价歌曲；说歌曲好听要用〈旋律〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95985, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想换一双大一点的型号。", "corrected_sentence": "我想换一个大一点的型号。", "error_description": "量词错误：“型号”应用“个”或“种”，“双”用于成对的鞋等，不能用于型号。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95985, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈选了一个大一点型号。", "corrected_sentence": "妈妈选了一个大一点的型号。", "error_description": "的字缺失：“大一点”修饰名词“型号”时要加“的”，应为“大一点的型号”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
