INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95986, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "产品按规格、性能等划分的类别编号。", "primary_collocate": null, "pronunciation": "xíng hào", "ipa": "ɕiŋ˧˥ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "手机背面写着它的型号。", "target_word": "型号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把电脑的型号告诉客服。", "target_word": "型号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台冰箱的型号已经停产了。", "target_word": "型号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买电池以前，要先看清型号。", "target_word": "型号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修理工问我空调是什么型号。", "target_word": "型号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个零件型号不同，不能换着用。", "target_word": "型号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说明书上有这台机器的型号。", "target_word": "型号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新型号的相机比旧型号轻很多。", "target_word": "型号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我记不住这辆车的型号。", "target_word": "型号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂每年都会推出新的型号。", "target_word": "型号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "型號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "产品规格性能的类别编号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a29a7b14-7b68-4d81-8215-6c329d1fefba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95986, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "型号", "is_correct": true, "explanation": "正确：手机背面通常印有型号，与“写着”搭配。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“写着”后面接的是文字或数字，不能写“味道”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：手机没有脾气，不能说“它的脾气”。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：手机不会有脚步，句子不通。"}], "explanations": {"型号": "正确：手机背面通常印有型号，与“写着”搭配。", "味道": "搭配：“写着”后面接的是文字或数字，不能写“味道”。", "脾气": "语义：手机没有脾气，不能说“它的脾气”。", "脚步": "语义：手机不会有脚步，句子不通。"}, "sentence_index": 0, "correct_answer": "型号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只猫的型号很可爱。", "explanation": "型号是产品的规格名称，不能用来形容动物，应说〈样子〉或〈性格〉。"}, {"text": "这种电池有两台型号。", "explanation": "量词用错。〈台〉用于机器，型号应用〈种〉。"}, {"text": "买食品以前，要先看清型号。", "explanation": "这里应该用〈保质期〉。食品一般用保质期来判断，型号用于规格名称，不用于食品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95986, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "型号", "is_correct": true, "explanation": "正确：说明书上会写机器的型号，符合语境。"}, {"text": "心情", "is_correct": false, "explanation": "语义：机器没有心情，不能说“这台机器的心情”。"}, {"text": "口味", "is_correct": false, "explanation": "语义：机器没有口味，句子不通。"}, {"text": "眼神", "is_correct": false, "explanation": "语义：眼神只用于人或动物，机器没有眼神。"}], "explanations": {"型号": "正确：说明书上会写机器的型号，符合语境。", "心情": "语义：机器没有心情，不能说“这台机器的心情”。", "口味": "语义：机器没有口味，句子不通。", "眼神": "语义：眼神只用于人或动物，机器没有眼神。"}, "sentence_index": 6, "correct_answer": "型号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电视台每年都会推出新的型号。", "explanation": "这里应该用〈节目〉。型号是产品的规格名称，电视节目不用型号。"}, {"text": "工厂每年都会推出一座型号。", "explanation": "量词用错。〈座〉用于山、楼等大型建筑，型号应用〈种〉或〈款〉。"}, {"text": "他的型号很严肃。", "explanation": "型号指产品的规格名称，不能用来形容人的性格，应说〈性格〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95986, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种手机有三台型号。", "corrected_sentence": "这种手机有三种型号。", "error_description": "量词错误：数“型号”应用“种”，“台”用于机器本身，不能用来数型号。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95986, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个很多人喜欢型号。", "corrected_sentence": "这是一个很多人喜欢的型号。", "error_description": "的字缺失：修饰“型号”的定语从句“很多人喜欢”后需要“的”，应为“很多人喜欢的型号”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
