INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95988, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "埋葬死人的地方。", "primary_collocate": null, "pronunciation": "mù", "ipa": "mu˥˩", "syllable_count": 1, "sentences": [{"text": "这座墓是一百年前修的。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的墓在海边。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老人的墓很简单。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在墓前鞠了三个躬。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墓前有一块大石头。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外婆的墓离我家不远。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们不敢走近那座旧墓。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他死后，大家把他埋在山边的墓里。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园旁边有一座很大的墓。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，他还在墓前站着。", "target_word": "墓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一座墓", "label": "量词"}, {"form": "坟墓", "label": "复合"}, {"form": "墓碑", "label": "复合"}], "register": "中性", "sense_fingerprint": "埋葬死人的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dd71c1-9209-4d12-a308-62a2880ffae2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95988, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "墓", "is_correct": true, "explanation": "正确：“墓”是埋葬死人的地方，可以说“这座墓是一百年前修的”。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“歌”不用量词“座”，也不能说“修”歌，“这座歌是…修的”不成立。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是可以修建的建筑，句子说的是修建埋葬的地方。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被修建，句子说的是一座墓。"}], "explanations": {"墓": "正确：“墓”是埋葬死人的地方，可以说“这座墓是一百年前修的”。", "歌": "搭配：“歌”不用量词“座”，也不能说“修”歌，“这座歌是…修的”不成立。", "作业": "语义：作业不是可以修建的建筑，句子说的是修建埋葬的地方。", "空气": "语义：空气不能被修建，句子说的是一座墓。"}, "sentence_index": 0, "correct_answer": "墓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山脚下有一只墓，很老了。", "explanation": "这里应该用〈座〉。墓多为建筑式的大型物，应用“座”；“只”用于动物。"}, {"text": "奶奶在墓里住了一个月。", "explanation": "这里应该用〈医院〉。墓是埋葬死人的地方，不能用来住人。"}, {"text": "孩子们在墓里踢足球。", "explanation": "这里应该用〈操场〉。墓是埋葬死人的地方，不能用来踢球，踢球应在操场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95988, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "墓", "is_correct": true, "explanation": "正确：“那座旧墓”指旧的墓地，孩子们因此不敢走近，符合句意。"}, {"text": "树", "is_correct": false, "explanation": "搭配：树应用量词“棵”，“那座旧树”的量词搭配不当。"}, {"text": "烦恼", "is_correct": false, "explanation": "语义：“烦恼”是抽象的心理状态，不能被孩子们走近。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是书，句子说的是孩子们不敢走近的场所或物体，与小说不合。"}], "explanations": {"墓": "正确：“那座旧墓”指旧的墓地，孩子们因此不敢走近，符合句意。", "树": "搭配：树应用量词“棵”，“那座旧树”的量词搭配不当。", "烦恼": "语义：“烦恼”是抽象的心理状态，不能被孩子们走近。", "小说": "语义：小说是书，句子说的是孩子们不敢走近的场所或物体，与小说不合。"}, "sentence_index": 6, "correct_answer": "墓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在墓里玩水。", "explanation": "这里应该用〈游泳池〉。墓是埋葬死人的地方，不能用来玩水。"}, {"text": "他每天都在墓里工作。", "explanation": "这里应该用〈办公室〉。墓不是工作的场所，工作应在办公室。"}, {"text": "村口有一条墓，很大。", "explanation": "这里应该用〈座〉。墓应用“座”，“条”用于河、路等细长的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95988, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条墓很大，很多人来参观。", "corrected_sentence": "这座墓很大，很多人来参观。", "error_description": "量词错误：墓应用“座”，“条”用于细长的东西，不能用来数墓。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95988, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每年清明都去墓扫。", "corrected_sentence": "他每年清明都去扫墓。", "error_description": "离合词错误：“扫墓”是离合词，“扫”和“墓”的顺序不能颠倒，应说“去扫墓”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95990, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内贸", "is_correct": true, "explanation": "反义：内贸指国内的商品买卖，与对外的外贸相对。"}, {"text": "书店", "is_correct": false, "explanation": "无关：书店是卖书的地方，与外贸没有反义关系。"}, {"text": "医院", "is_correct": false, "explanation": "无关：医院是看病的地方，与外贸不构成反义。"}, {"text": "花园", "is_correct": false, "explanation": "无关：花园是种植花草的地方，与外贸没有反义关系。"}], "correct_answer": "内贸", "explanations": {"内贸": "反义：内贸指国内的商品买卖，与对外的外贸相对。", "书店": "无关：书店是卖书的地方，与外贸没有反义关系。", "医院": "无关：医院是看病的地方，与外贸不构成反义。", "花园": "无关：花园是种植花草的地方，与外贸没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95990, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内贸", "is_correct": true, "explanation": "反义：内贸指国内的商品买卖，与对外的外贸相对。"}, {"text": "银行", "is_correct": false, "explanation": "无关：银行是办理存贷款的机构，与外贸没有反义关系。"}, {"text": "学校", "is_correct": false, "explanation": "无关：学校是教学的地方，与外贸不构成反义。"}, {"text": "厨房", "is_correct": false, "explanation": "无关：厨房是做饭的地方，与外贸没有反义关系。"}], "correct_answer": "内贸", "explanations": {"内贸": "反义：内贸指国内的商品买卖，与对外的外贸相对。", "银行": "无关：银行是办理存贷款的机构，与外贸没有反义关系。", "学校": "无关：学校是教学的地方，与外贸不构成反义。", "厨房": "无关：厨房是做饭的地方，与外贸没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95990, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对外贸易，本国与外国之间的商品买卖。", "primary_collocate": null, "pronunciation": "wài mào", "ipa": "waɪ˥˩ maʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这个城市的外贸发展得很快。", "target_word": "外贸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在公司负责外贸，常常很忙。", "target_word": "外贸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年我国的外贸增长了很多。", "target_word": "外贸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学好英语对做外贸很有帮助。", "target_word": "外贸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "港口是外贸的重要通道。", "target_word": "外贸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他大学时学的是外贸。", "target_word": "外贸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这两年外贸订单少了很多。", "target_word": "外贸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府想帮小公司做外贸。", "target_word": "外贸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她做了十年外贸，认识很多外国客户。", "target_word": "外贸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的外贸主要靠出口。", "target_word": "外贸", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "外贸公司", "label": "复合词"}, {"form": "外贸业务", "label": "复合词"}], "register": "中性", "sense_fingerprint": "本国与外国之间的商品买卖，即对外贸易", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9b23817-999c-46c1-a554-f63ab669589a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95990, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "外贸", "is_correct": true, "explanation": "外贸（wài mào）：对外的商品买卖，即本题的正确答案。"}, {"text": "外卖", "is_correct": false, "explanation": "mài（第四声）与 mào 韵母不同（ai／ao），意思是外卖。"}, {"text": "外套", "is_correct": false, "explanation": "tào 与 mào 声母不同（t／m），意思是外套。"}, {"text": "外号", "is_correct": false, "explanation": "hào 与 mào 声母不同（h／m），意思是外号（绰号）。"}], "explanations": {"外贸": "外贸（wài mào）：对外的商品买卖，即本题的正确答案。", "外卖": "mài（第四声）与 mào 韵母不同（ai／ao），意思是外卖。", "外套": "tào 与 mào 声母不同（t／m），意思是外套。", "外号": "hào 与 mào 声母不同（h／m），意思是外号（绰号）。"}, "sentence_index": null, "correct_answer": "外贸"}, "level_3": {"options": [{"text": "外贸", "is_correct": true, "explanation": "符合语境：外贸指对外贸易，“这个城市的外贸发展得很快”说得通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“发展”不用于天气，天气只说变化，“天气发展得很快”不成立。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是岁数，不会“发展”，与“城市的……发展得很快”语义不合。"}, {"text": "文盲", "is_correct": false, "explanation": "语义：文盲指不识字的人，不能说“发展得很快”，与城市发展的语境不合。"}], "explanations": {"外贸": "符合语境：外贸指对外贸易，“这个城市的外贸发展得很快”说得通。", "天气": "搭配：“发展”不用于天气，天气只说变化，“天气发展得很快”不成立。", "年龄": "语义：年龄是岁数，不会“发展”，与“城市的……发展得很快”语义不合。", "文盲": "语义：文盲指不识字的人，不能说“发展得很快”，与城市发展的语境不合。"}, "sentence_index": 0, "correct_answer": "外贸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要严格控制外贸的流出。", "explanation": "这里应该用〈外汇〉。外贸指对外的商品买卖，不指资金的流动，控制钱款流出要说外汇。"}, {"text": "这位大使每天忙于外贸，负责与各国的军事会谈。", "explanation": "这里应该用〈外交〉。外交指国家之间的政治往来，外贸是商品买卖，不能用来指军事会谈。"}, {"text": "他的外贸说得很流利，能和外国人聊天。", "explanation": "这里应该用〈外语〉。外贸是贸易活动，不是语言，不能说“外贸说得很流利”，说语言流利要用外语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95990, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外贸", "is_correct": true, "explanation": "符合语境：“这两年”订单减少，外贸与订单搭配，语义通顺。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口是人的总数，不接“订单”，“人口订单少了很多”语义不通。"}, {"text": "股市", "is_correct": false, "explanation": "搭配：“订单”属于生意往来，股市不能下订单，搭配不当。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以下订单的对象，“空气订单少了很多”语义不通。"}], "explanations": {"外贸": "符合语境：“这两年”订单减少，外贸与订单搭配，语义通顺。", "人口": "语义：人口是人的总数，不接“订单”，“人口订单少了很多”语义不通。", "股市": "搭配：“订单”属于生意往来，股市不能下订单，搭配不当。", "空气": "语义：空气不是可以下订单的对象，“空气订单少了很多”语义不通。"}, "sentence_index": 6, "correct_answer": "外贸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市每年接待很多外贸。", "explanation": "这里应该用〈外国人〉。外贸指商品买卖的活动，不能用来指来访的人。"}, {"text": "酒店里住着很多外贸。", "explanation": "这里应该用〈外宾〉。外贸是经济活动，不指住店的客人。"}, {"text": "这家公司去年只做外贸，从不与外国客户打交道。", "explanation": "这里应该用〈内贸〉。外贸指与外国之间的买卖，内贸指国内的买卖；这句说“从不与外国客户打交道”，与“外贸”的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95990, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司把外贸做。", "corrected_sentence": "我们公司把外贸做好了。", "error_description": "“把”字句的动词后必须带补语或其他成分，单独说“把外贸做”不完整，应补上结果或完成的成分，说“把外贸做好了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95990, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他明天做过外贸。", "corrected_sentence": "他明天要做外贸。", "error_description": "“过”表示曾经有过的经历，不能用于“明天”这样的将来时间；说将来的打算要用“要”，应说“明天要做外贸”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95992, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白天", "is_correct": true, "explanation": "白天与夜晚是反义词：夜晚指从天黑到天亮的时间，白天指从天亮到天黑的时间。"}, {"text": "中午", "is_correct": false, "explanation": "中午是白天里的一个时刻，与夜晚不构成反义。"}, {"text": "春天", "is_correct": false, "explanation": "春天是季节，不是与夜晚相对的时段，二者不构成反义。"}, {"text": "星期", "is_correct": false, "explanation": "星期是计时单位，与夜晚不构成反义。"}], "correct_answer": "白天", "explanations": {"白天": "白天与夜晚是反义词：夜晚指从天黑到天亮的时间，白天指从天亮到天黑的时间。", "中午": "中午是白天里的一个时刻，与夜晚不构成反义。", "春天": "春天是季节，不是与夜晚相对的时段，二者不构成反义。", "星期": "星期是计时单位，与夜晚不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95992, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "白天", "is_correct": true, "explanation": "白天与夜晚是反义词：夜晚指从天黑到天亮的时间，白天指从天亮到天黑的时间。"}, {"text": "早上", "is_correct": false, "explanation": "早上是白天的开始阶段，与夜晚不构成反义。"}, {"text": "冬天", "is_correct": false, "explanation": "冬天是季节，与夜晚不构成反义。"}, {"text": "周末", "is_correct": false, "explanation": "周末是一周中的两天，与夜晚不构成反义。"}], "correct_answer": "白天", "explanations": {"白天": "白天与夜晚是反义词：夜晚指从天黑到天亮的时间，白天指从天亮到天黑的时间。", "早上": "早上是白天的开始阶段，与夜晚不构成反义。", "冬天": "冬天是季节，与夜晚不构成反义。", "周末": "周末是一周中的两天，与夜晚不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95992, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从天黑到天亮的时间。", "primary_collocate": null, "pronunciation": "yè wǎn", "ipa": "jɛ˥˩ wan˨˩˦", "syllable_count": 2, "sentences": [{"text": "夜晚很安静。", "target_word": "夜晚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夏天的夜晚不太热。", "target_word": "夜晚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夜晚我常常在家看书。", "target_word": "夜晚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夜晚的街上没有几个人。", "target_word": "夜晚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她白天工作，夜晚学英语。", "target_word": "夜晚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "整个夜晚，外面都在下雨。", "target_word": "夜晚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夜晚的风比白天凉，你要多穿点衣服。", "target_word": "夜晚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个夜晚下了一场大雨。", "target_word": "夜晚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市的夜晚很亮，可以看到很多灯。", "target_word": "夜晚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在山里，夜晚能看到很多星星。", "target_word": "夜晚", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "从天黑到天亮的一整段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '277212ec-c05c-4f82-b617-5b3b2e2110c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95992, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夜晚", "is_correct": true, "explanation": "夜晚指从天黑到天亮的时间，句中指夜里的环境，可以说“很安静”。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，没有安静与否的状态，“面包很安静”说不通。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不能被说成“很安静”。"}, {"text": "牛奶", "is_correct": false, "explanation": "搭配：“很安静”形容环境或人的状态，不与牛奶这类饮品搭配。"}], "explanations": {"夜晚": "夜晚指从天黑到天亮的时间，句中指夜里的环境，可以说“很安静”。", "面包": "语义：面包是食物，没有安静与否的状态，“面包很安静”说不通。", "饼干": "语义：饼干是食品，不能被说成“很安静”。", "牛奶": "搭配：“很安静”形容环境或人的状态，不与牛奶这类饮品搭配。"}, "sentence_index": 0, "correct_answer": "夜晚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的夜晚很好吃。", "explanation": "这里应该用〈夜宵〉。“好吃”形容食物，夜晚只指时间，不能用来形容吃的东西。"}, {"text": "他这个月每周要值两次夜晚。", "explanation": "这里应该用〈夜班〉。“值”搭配“夜班”（夜里轮流上的班），夜晚只指一段时间，不能用来指值班。"}, {"text": "我们昨晚吃了夜晚。", "explanation": "这里应该用〈夜宵〉。“吃”搭配食物，夜晚只指一段时间，不能用来吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95992, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夜晚", "is_correct": true, "explanation": "夜晚指一段黑夜的时间，句中说夜里的风比白天凉，需要多穿衣服。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是房间，不是有风、可以与白天比较温度的时段，句子说不通。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子是食物，不会刮风，“饺子的风”说不通。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“……的风”要说自然环境中的风，不说书包的风。"}], "explanations": {"夜晚": "夜晚指一段黑夜的时间，句中说夜里的风比白天凉，需要多穿衣服。", "厨房": "语义：厨房是房间，不是有风、可以与白天比较温度的时段，句子说不通。", "饺子": "语义：饺子是食物，不会刮风，“饺子的风”说不通。", "书包": "搭配：“……的风”要说自然环境中的风，不说书包的风。"}, "sentence_index": 6, "correct_answer": "夜晚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在路边摊点了一份夜晚。", "explanation": "这里应该用〈夜宵〉。“点”和“一份”搭配食物，夜晚只指时间，不能用来点。"}, {"text": "周末我们去逛夜晚，人特别多。", "explanation": "这里应该用〈夜市〉。“逛”搭配夜市、商场等地方，夜晚指时间，不能用来逛。"}, {"text": "我每周三都去上夜晚。", "explanation": "这里应该用〈夜校〉。“上”可以搭配夜校，夜晚只指时间，不能说“上夜晚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95992, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在海边度过了一条难忘的夜晚。", "corrected_sentence": "我们在海边度过了一个难忘的夜晚。", "error_description": "“夜晚”的量词应用“个”，“条”用于长条形的事物，不能用来数夜晚。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95992, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在山里露营了一条夜晚，星星特别亮。", "corrected_sentence": "我们在山里露营了一个夜晚，星星特别亮。", "error_description": "错误：“一条夜晚”；正确：“一个夜晚”。“夜晚”的量词用“个”，“条”用于细长的事物，不能用来数夜晚。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
