INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95994, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个国家派驻他国首都的外交代表机关。", "primary_collocate": null, "pronunciation": "dà shǐ guǎn", "ipa": "ta˥˩ ʂɨ˨˩˦ kwan˨˩˦", "syllable_count": 3, "sentences": [{"text": "法国在北京有一座大使馆。", "target_word": "大使馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大使馆代表自己的国家和别国交往。", "target_word": "大使馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国大使馆都设在首都。", "target_word": "大使馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大使馆保护本国公民在国外的安全。", "target_word": "大使馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座大使馆的外面挂着国旗。", "target_word": "大使馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新大使馆下个月在市中心开馆。", "target_word": "大使馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者在大使馆外等着消息。", "target_word": "大使馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国决定在对方首都设立大使馆。", "target_word": "大使馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大使馆的大门关着，没有人进出。", "target_word": "大使馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把抗议信送到了大使馆。", "target_word": "大使馆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "大使馆：派驻他国首都的外交代表机关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53ba7404-397a-4364-acdd-387f7357410c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95994, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大使馆", "is_correct": true, "explanation": "正确：“法国在北京有一座大使馆”表示派驻机构，量词“座”搭配建筑，通顺。"}, {"text": "大使", "is_correct": false, "explanation": "搭配：量词“座”用于建筑，不用于人，“一座大使”不通。"}, {"text": "外交官", "is_correct": false, "explanation": "搭配：量词“座”用于建筑，外交官是人，“一座外交官”不通。"}, {"text": "国旗", "is_correct": false, "explanation": "语义：国旗不是建筑，不能用“座”计量，应说“一面国旗”。"}], "explanations": {"大使馆": "正确：“法国在北京有一座大使馆”表示派驻机构，量词“座”搭配建筑，通顺。", "大使": "搭配：量词“座”用于建筑，不用于人，“一座大使”不通。", "外交官": "搭配：量词“座”用于建筑，外交官是人，“一座外交官”不通。", "国旗": "语义：国旗不是建筑，不能用“座”计量，应说“一面国旗”。"}, "sentence_index": 0, "correct_answer": "大使馆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法国在北京有一只大使馆。", "explanation": "这里应该用〈座〉。大使馆是建筑，不用“只”，“只”多用于动物或成对物品中的一个。"}, {"text": "这家大使馆生产手机。", "explanation": "这里应该用〈公司〉。大使馆是外交机构，不生产商品，生产手机要说公司。"}, {"text": "大使馆是一位外交官，来自法国。", "explanation": "这里应该用〈大使〉（指人）。大使馆是机构，不是人，不能说它是一位外交官。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95994, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大使馆", "is_correct": true, "explanation": "正确：“记者在大使馆外等着消息”表示记者在使馆门外等候，通顺。"}, {"text": "消息", "is_correct": false, "explanation": "语义：“消息”不是处所词，“在消息外”语义不通。"}, {"text": "发言人", "is_correct": false, "explanation": "搭配：“在……外”需要处所词，发言人是人，不能作处所。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋不能作处所，“在鸡蛋外等着消息”语义不通。"}], "explanations": {"大使馆": "正确：“记者在大使馆外等着消息”表示记者在使馆门外等候，通顺。", "消息": "语义：“消息”不是处所词，“在消息外”语义不通。", "发言人": "搭配：“在……外”需要处所词，发言人是人，不能作处所。", "鸡蛋": "语义：鸡蛋不能作处所，“在鸡蛋外等着消息”语义不通。"}, "sentence_index": 6, "correct_answer": "大使馆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天去大使馆挂号看病。", "explanation": "这里应该用〈医院〉。大使馆是外交机构，不办理挂号看病，要去医院。"}, {"text": "我们去大使馆上课。", "explanation": "这里应该用〈学校〉。大使馆不是上课的地方，上课要去学校。"}, {"text": "妈妈去大使馆买菜。", "explanation": "这里应该用〈超市〉。大使馆不卖菜，买菜要去超市或菜市场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "英国大使馆们在朝阳区。", "corrected_sentence": "英国大使馆在朝阳区。", "error_description": "错误：“大使馆”是机构名词，后面不能加“们”。正确说法是“英国大使馆在朝阳区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国决定在对方首都设立一条大使馆。", "corrected_sentence": "两国决定在对方首都设立一座大使馆。", "error_description": "错误在量词“条”：大使馆是建筑和机构，量词用“座”或“个”，不用“条”。正确说法是“设立一座大使馆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
