INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95995, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "好不好是问别人同不同意，行不行。", "primary_collocate": null, "pronunciation": "hǎo bu hǎo", "ipa": "xɑu˨˩ pu xɑu˨˩", "syllable_count": 3, "sentences": [{"text": "我们明天去公园玩，好不好？", "target_word": "好不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先坐下，听我说，好不好？", "target_word": "好不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天太晚了，明天再做，好不好？", "target_word": "好不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我请你吃饭，好不好？", "target_word": "好不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你小声一点，好不好？", "target_word": "好不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们一起看电影，好不好？", "target_word": "好不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书借我看几天，好不好？", "target_word": "好不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别生气了，我们好好说，好不好？", "target_word": "好不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我帮你拿包，好不好？", "target_word": "好不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先吃饭，然后再写作业，好不好？", "target_word": "好不好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "放在句末，征求对方同意，相当于“行不行”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53ba7404-397a-4364-acdd-387f7357410c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95995, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好不好", "is_correct": true, "explanation": "正确。“好不好”表示征求对方同意，读作 hǎo bu hǎo。"}, {"text": "考不好", "is_correct": false, "explanation": "kǎo 与 hǎo 声母不同（k/h），意思是考试成绩不理想。"}, {"text": "搞不好", "is_correct": false, "explanation": "gǎo 与 hǎo 声母不同（g/h），意思是说不定、可能。"}, {"text": "很不好", "is_correct": false, "explanation": "hěn 与 hǎo 韵母不同（en/ao），意思是很差。"}], "explanations": {"好不好": "正确。“好不好”表示征求对方同意，读作 hǎo bu hǎo。", "考不好": "kǎo 与 hǎo 声母不同（k/h），意思是考试成绩不理想。", "搞不好": "gǎo 与 hǎo 声母不同（g/h），意思是说不定、可能。", "很不好": "hěn 与 hǎo 韵母不同（en/ao），意思是很差。"}, "sentence_index": null, "correct_answer": "好不好"}, "level_3": {"options": [{"text": "好不好", "is_correct": true, "explanation": "正确。“好不好”用于征求对方同意，与“去公园玩”的提议相符。"}, {"text": "多不多", "is_correct": false, "explanation": "语义：“多不多”问数量，与“去公园玩”的提议无关，不能放在句末作问句。"}, {"text": "有没有", "is_correct": false, "explanation": "搭配：“有没有”问是否存在，不能接在提议句后面作问句。"}, {"text": "会不会", "is_correct": false, "explanation": "搭配：“会不会”问可能性，不能接在提议后面征求同意。"}], "explanations": {"好不好": "正确。“好不好”用于征求对方同意，与“去公园玩”的提议相符。", "多不多": "语义：“多不多”问数量，与“去公园玩”的提议无关，不能放在句末作问句。", "有没有": "搭配：“有没有”问是否存在，不能接在提议句后面作问句。", "会不会": "搭配：“会不会”问可能性，不能接在提议后面征求同意。"}, "sentence_index": 0, "correct_answer": "好不好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你昨天去了医院，好不好？", "explanation": "这里应该用〈对不对〉。“好不好”用于征求对方同意，不用于确认已经发生的事。"}, {"text": "你是这个班的学生，好不好？", "explanation": "这里应该用〈是不是〉。“好不好”只用于征求对方同意，不用于确认对方的身份。"}, {"text": "你今天没来上课，好不好？", "explanation": "这里应该用〈对吗〉。“好不好”用于征求对方同意，不用于核实已经发生的事实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95995, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "好不好", "is_correct": true, "explanation": "正确。“好不好”表示征求对方同意，读作 hǎo bu hǎo。"}, {"text": "烤不好", "is_correct": false, "explanation": "kǎo 与 hǎo 声母不同（k/h），意思是烤得不好。"}, {"text": "好不了", "is_correct": false, "explanation": "末字 liǎo 与 hǎo 声母不同（l/h），意思是好不起来。"}, {"text": "好不少", "is_correct": false, "explanation": "末字 shǎo 与 hǎo 声母不同（sh/h），意思是好了很多。"}], "explanations": {"好不好": "正确。“好不好”表示征求对方同意，读作 hǎo bu hǎo。", "烤不好": "kǎo 与 hǎo 声母不同（k/h），意思是烤得不好。", "好不了": "末字 liǎo 与 hǎo 声母不同（l/h），意思是好不起来。", "好不少": "末字 shǎo 与 hǎo 声母不同（sh/h），意思是好了很多。"}, "sentence_index": null, "correct_answer": "好不好"}, "level_3": {"options": [{"text": "好不好", "is_correct": true, "explanation": "正确。“好不好”用于征求对方同意，与“借我看几天”的请求相符。"}, {"text": "对吗", "is_correct": false, "explanation": "语义：“对吗”问是非对错，不是征求对方同意借书。"}, {"text": "是吗", "is_correct": false, "explanation": "语义：“是吗”表示求证或惊讶，不用于征求同意。"}, {"text": "懂不懂", "is_correct": false, "explanation": "搭配：“懂不懂”问是否理解，不能用于征求“借我看几天”的同意。"}], "explanations": {"好不好": "正确。“好不好”用于征求对方同意，与“借我看几天”的请求相符。", "对吗": "语义：“对吗”问是非对错，不是征求对方同意借书。", "是吗": "语义：“是吗”表示求证或惊讶，不用于征求同意。", "懂不懂": "搭配：“懂不懂”问是否理解，不能用于征求“借我看几天”的同意。"}, "sentence_index": 6, "correct_answer": "好不好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他会做这道题，好不好？", "explanation": "这里应该用〈对吧〉。“好不好”只用于征求对方同意，不用于推测或确认别人的能力。"}, {"text": "今天是星期三，好不好？", "explanation": "这里应该用〈对吧〉。“好不好”用于征求对方同意，不用于核实陈述的内容是否正确。"}, {"text": "你已经写完作业了，好不好？", "explanation": "这里应该用〈是不是〉。“好不好”只用于征求对方同意，不能用来确认已经发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95995, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天一起去看展，好不好吗？", "corrected_sentence": "明天一起去看展，好不好？", "error_description": "错误在“吗”：“好不好”本身已是疑问形式，后面不能再加“吗”。正确说法是“好不好？”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
