INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95996, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "用来征求对方意见的问句。", "primary_collocate": null, "pronunciation": "hǎo bu hǎo", "ipa": "xɑu˨˩ pu xɑu˨˩", "syllable_count": 3, "sentences": [{"text": "我们换一个地方聊天，好不好？", "target_word": "好不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈，今晚给我讲个故事，好不好？", "target_word": "好不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你陪我去买衣服，好不好？", "target_word": "好不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱们早点出发，好不好？", "target_word": "好不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我下午给你打电话，好不好？", "target_word": "好不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把窗户关上，好不好？", "target_word": "好不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们安静一会儿，好不好？", "target_word": "好不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次我来做饭，好不好？", "target_word": "好不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天我们去爬山，好不好？", "target_word": "好不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "让我先试一试，好不好？", "target_word": "好不好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "附在提议后面的问句，征求对方意见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53ba7404-397a-4364-acdd-387f7357410c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95996, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好不好", "is_correct": true, "explanation": "正确。“好不好”用于征求对方意见，读作 hǎo bu hǎo。"}, {"text": "烤不好", "is_correct": false, "explanation": "kǎo 与 hǎo 声母不同（k/h），意思是烤得不好。"}, {"text": "好不了", "is_correct": false, "explanation": "末字 liǎo 与 hǎo 声母不同（l/h），意思是好不起来。"}, {"text": "好不少", "is_correct": false, "explanation": "末字 shǎo 与 hǎo 声母不同（sh/h），意思是好了很多。"}], "explanations": {"好不好": "正确。“好不好”用于征求对方意见，读作 hǎo bu hǎo。", "烤不好": "kǎo 与 hǎo 声母不同（k/h），意思是烤得不好。", "好不了": "末字 liǎo 与 hǎo 声母不同（l/h），意思是好不起来。", "好不少": "末字 shǎo 与 hǎo 声母不同（sh/h），意思是好了很多。"}, "sentence_index": null, "correct_answer": "好不好"}, "level_3": {"options": [{"text": "好不好", "is_correct": true, "explanation": "正确。“好不好”用于征求对方意见，与“换一个地方聊天”的提议相符。"}, {"text": "有没有", "is_correct": false, "explanation": "搭配：“有没有”问是否存在，不能接在提议句后面作征求同意的问句。"}, {"text": "是吗", "is_correct": false, "explanation": "语义：“是吗”表示求证或惊讶，不用于征求意见。"}, {"text": "会不会", "is_correct": false, "explanation": "搭配：“会不会”问可能性，不能接在提议后面征求意见。"}], "explanations": {"好不好": "正确。“好不好”用于征求对方意见，与“换一个地方聊天”的提议相符。", "有没有": "搭配：“有没有”问是否存在，不能接在提议句后面作征求同意的问句。", "是吗": "语义：“是吗”表示求证或惊讶，不用于征求意见。", "会不会": "搭配：“会不会”问可能性，不能接在提议后面征求意见。"}, "sentence_index": 0, "correct_answer": "好不好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你已经吃过午饭了，好不好？", "explanation": "这里应该用〈对不对〉。“好不好”用于征求对方意见，不用于确认已经发生的事。"}, {"text": "你是北京人，好不好？", "explanation": "这里应该用〈是不是〉。“好不好”用于征求对方意见，不用于核实对方的籍贯等事实。"}, {"text": "你昨天没来上课，好不好？", "explanation": "这里应该用〈对吗〉。“好不好”用于征求对方意见，不用于核实已经发生的事实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, 