INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95996, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "好不好", "is_correct": true, "explanation": "正确。“好不好”用于征求对方意见，读作 hǎo bu hǎo。"}, {"text": "考不好", "is_correct": false, "explanation": "kǎo 与 hǎo 声母不同（k/h），意思是考试成绩不理想。"}, {"text": "搞不好", "is_correct": false, "explanation": "gǎo 与 hǎo 声母不同（g/h），意思是说不定、可能。"}, {"text": "很不好", "is_correct": false, "explanation": "hěn 与 hǎo 韵母不同（en/ao），意思是很差。"}], "explanations": {"好不好": "正确。“好不好”用于征求对方意见，读作 hǎo bu hǎo。", "考不好": "kǎo 与 hǎo 声母不同（k/h），意思是考试成绩不理想。", "搞不好": "gǎo 与 hǎo 声母不同（g/h），意思是说不定、可能。", "很不好": "hěn 与 hǎo 韵母不同（en/ao），意思是很差。"}, "sentence_index": null, "correct_answer": "好不好"}, "level_3": {"options": [{"text": "好不好", "is_correct": true, "explanation": "正确。“好不好”用于征求对方意见，与“安静一会儿”的请求相符。"}, {"text": "对不对", "is_correct": false, "explanation": "语义：“对不对”问是非，不是征求对方意见。"}, {"text": "是不是", "is_correct": false, "explanation": "语义：“是不是”问真假或事实，不用于征求意见。"}, {"text": "多不多", "is_correct": false, "explanation": "语义：“多不多”问数量，与“安静一会儿”的请求无关，不能放在句末。"}], "explanations": {"好不好": "正确。“好不好”用于征求对方意见，与“安静一会儿”的请求相符。", "对不对": "语义：“对不对”问是非，不是征求对方意见。", "是不是": "语义：“是不是”问真假或事实，不用于征求意见。", "多不多": "语义：“多不多”问数量，与“安静一会儿”的请求无关，不能放在句末。"}, "sentence_index": 6, "correct_answer": "好不好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中国的首都是北京，好不好？", "explanation": "这里应该用〈没错吧〉。“好不好”用于征求对方意见，不用于核实已知的事实。"}, {"text": "这件事你已经知道了，好不好？", "explanation": "这里应该用〈是不是〉。“好不好”只用于征求对方意见，不能用来确认已经发生的事。"}, {"text": "你已经学过这个单词了，好不好？", "explanation": "这里应该用〈对吗〉。“好不好”不用于核实对方是否已经学过，应用“对吗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
