INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95997, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "专栏是报纸或杂志里，专门给一个话题留的一块地方。", "primary_collocate": null, "pronunciation": "zhuān lán", "ipa": "ʈʂwan˥ lan˧˥", "syllable_count": 2, "sentences": [{"text": "这家报纸有一个专栏，专门谈健康。", "target_word": "专栏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂志的最后一页是读者专栏。", "target_word": "专栏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸给旅游留了一个专栏。", "target_word": "专栏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在报纸的体育专栏里看到了这条消息。", "target_word": "专栏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本杂志新开了一个美食专栏。", "target_word": "专栏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报纸的教育专栏很受家长欢迎。", "target_word": "专栏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天先翻到电影专栏看一看。", "target_word": "专栏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂志里的汽车专栏介绍新车。", "target_word": "专栏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸为老年人设了一个专栏。", "target_word": "专栏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个专栏的版面不大，但内容很多。", "target_word": "专栏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "專欄", "label": "繁体"}], "register": "中性", "sense_fingerprint": "报刊中专给某话题的版面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a29a7b14-7b68-4d81-8215-6c329d1fefba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95997, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专栏", "is_correct": true, "explanation": "“专栏”指报纸或杂志里专门给某个话题留的版块，与“报纸”和“谈健康”相合。"}, {"text": "仪器", "is_correct": false, "explanation": "语义：“仪器”是测量或检验用的器械，不能“专门谈健康”。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：“工厂”是生产场所，不是发表议论的载体，不能“专门谈健康”。"}, {"text": "专业", "is_correct": false, "explanation": "搭配：“有一个专业”指学科或职业范围，报纸不设专业，这样说不通。"}], "explanations": {"专栏": "“专栏”指报纸或杂志里专门给某个话题留的版块，与“报纸”和“谈健康”相合。", "仪器": "语义：“仪器”是测量或检验用的器械，不能“专门谈健康”。", "工厂": "语义：“工厂”是生产场所，不是发表议论的载体，不能“专门谈健康”。", "专业": "搭配：“有一个专业”指学科或职业范围，报纸不设专业，这样说不通。"}, "sentence_index": 0, "correct_answer": "专栏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位专栏在报纸上写了很多文章。", "explanation": "这里应该用〈作家〉。专栏指报刊中专门给某个话题的版块，不能指写文章的人；写文章的人要说作家或专栏作家。"}, {"text": "超市一楼有一个进口食品专栏。", "explanation": "这里应该用〈专区〉。专栏指报刊上专门给某类内容的版块，不能指超市里划出的商品区域。"}, {"text": "他是这方面的专栏。", "explanation": "这里应该用〈专家〉。专栏指报刊版块，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95997, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专栏", "is_correct": true, "explanation": "“电影专栏”指报刊上专谈电影的版块，可以“翻到”并“看一看”。"}, {"text": "剧院", "is_correct": false, "explanation": "语义：“翻到”的是书报页面，剧院是场所，不能被翻到。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是小物件，没有可以“翻到”的页面。"}, {"text": "栏杆", "is_correct": false, "explanation": "搭配：“翻到”搭配书报、目录等纸质材料，“栏杆”不能被翻到。"}], "explanations": {"专栏": "“电影专栏”指报刊上专谈电影的版块，可以“翻到”并“看一看”。", "剧院": "语义：“翻到”的是书报页面，剧院是场所，不能被翻到。", "钥匙": "语义：钥匙是小物件，没有可以“翻到”的页面。", "栏杆": "搭配：“翻到”搭配书报、目录等纸质材料，“栏杆”不能被翻到。"}, "sentence_index": 6, "correct_answer": "专栏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位专栏每天都要改很多稿子。", "explanation": "这里应该用〈编辑〉。专栏是报刊中的版块，不能动手改稿子。"}, {"text": "这位专栏常去现场采访。", "explanation": "这里应该用〈记者〉。专栏是版块，不会去现场采访。"}, {"text": "这家专栏每天出版一份报纸。", "explanation": "这里应该用〈报社〉。专栏不是机构，不能出版报纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95997, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在晚报上开了一本育儿专栏。", "corrected_sentence": "她在晚报上开了一个育儿专栏。", "error_description": "量词错误：“专栏”应用量词“个”，“本”用于书籍等成册的东西，不能用来数专栏。应为“开了一个育儿专栏”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95997, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份周刊每周都有一个财经地专栏。", "corrected_sentence": "这份周刊每周都有一个财经专栏。", "error_description": "助词误用：“财经”修饰名词“专栏”时不用“地”，应直接说“一个财经专栏”；“地”只用于修饰动词或形容词作状语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
