INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95998, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "报刊上定期刊登某类内容或某人文章的专门栏目。", "primary_collocate": null, "pronunciation": "zhuān lán", "ipa": "ʈʂwan˥ lan˧˥", "syllable_count": 2, "sentences": [{"text": "她每周在报上写一篇专栏。", "target_word": "专栏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的专栏每个星期三都会刊登。", "target_word": "专栏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家给杂志写了三年专栏。", "target_word": "专栏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很喜欢看他在报上的专栏。", "target_word": "专栏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生在报纸上开了一个健康专栏。", "target_word": "专栏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的专栏写得很好，读者很多。", "target_word": "专栏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不再写专栏了，想多陪陪孩子。", "target_word": "专栏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师每月给报纸交一篇专栏。", "target_word": "专栏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位记者的专栏已经连载了十年。", "target_word": "专栏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠写专栏，认识了很多读者。", "target_word": "专栏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "專欄", "label": "繁体"}], "register": "中性", "sense_fingerprint": "报刊上定期刊登的个人或类别栏目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a29a7b14-7b68-4d81-8215-6c329d1fefba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95998, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专栏", "is_correct": true, "explanation": "“写一篇专栏”指定期为报刊撰写的专门栏目文章，与“每周”“报上”相合。"}, {"text": "讲稿", "is_correct": false, "explanation": "语义：讲稿是为演讲准备的稿子，不是报上定期刊登的文章。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是交给老师批改的练习，不会在报上定期刊登。"}, {"text": "草稿", "is_correct": false, "explanation": "语义：草稿是未定稿的初稿，不会被定期刊登在报上。"}], "explanations": {"专栏": "“写一篇专栏”指定期为报刊撰写的专门栏目文章，与“每周”“报上”相合。", "讲稿": "语义：讲稿是为演讲准备的稿子，不是报上定期刊登的文章。", "作业": "语义：作业是交给老师批改的练习，不会在报上定期刊登。", "草稿": "语义：草稿是未定稿的初稿，不会被定期刊登在报上。"}, "sentence_index": 0, "correct_answer": "专栏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "记者对他进行了专栏。", "explanation": "这里应该用〈专访〉。专栏是报刊上定期刊登文章的版块，不能用于一次采访。"}, {"text": "商场一楼有一个化妆品专栏。", "explanation": "这里应该用〈专柜〉。专栏指报刊上的栏目，不能指商场里专卖某类商品的柜台。"}, {"text": "这位专栏写了很多小说。", "explanation": "这里应该用〈作者〉。专栏是版块，不能动笔写小说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95998, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专栏", "is_correct": true, "explanation": "“写专栏”指定期为报刊撰稿，与“不再写”的语境相合。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是场所，不能被“写”。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是食物，不是可以写的作品。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：“写”的对象是文字或作品，手套不能被写。"}], "explanations": {"专栏": "“写专栏”指定期为报刊撰稿，与“不再写”的语境相合。", "厨房": "语义：厨房是场所，不能被“写”。", "早餐": "语义：早餐是食物，不是可以写的作品。", "手套": "搭配：“写”的对象是文字或作品，手套不能被写。"}, "sentence_index": 6, "correct_answer": "专栏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位专栏每晚都在台上讲话。", "explanation": "这里应该用〈主持人〉。专栏是版块，不能在台上讲话。"}, {"text": "这位专栏在舞台上表演得很自然。", "explanation": "这里应该用〈演员〉。专栏不是人，不能在舞台上表演。"}, {"text": "这个专栏每天印很多报纸。", "explanation": "这里应该用〈印刷厂〉。专栏是版块，不能印报纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95998, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她每月在杂志上写一本育儿专栏。", "corrected_sentence": "她每月在杂志上写一个育儿专栏。", "error_description": "量词错误：“专栏”应用量词“个”或“篇”，“本”用于书籍，不能用来数专栏。应为“写一个育儿专栏”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95998, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他教了三年专栏，积累了很多读者。", "corrected_sentence": "他写了三年专栏，积累了很多读者。", "error_description": "搭配错误：“专栏”是写出来的，“教”不能带“专栏”作宾语。应为“写了三年专栏”，只改动“教／写”一处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
