INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95999, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小二是以前饭馆里招呼客人的人。", "primary_collocate": null, "pronunciation": "xiǎo èr", "ipa": "ɕiaʊ˨˩ aɚ˥˩", "syllable_count": 2, "sentences": [{"text": "小二笑着走过来，问客人想吃什么。", "target_word": "小二", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候饭馆的小二很会招呼客人。", "target_word": "小二", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人一进门，小二就送上热茶。", "target_word": "小二", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电视里的小二肩上搭着一条白毛巾。", "target_word": "小二", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小二，给我来一碗面！", "target_word": "小二", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板在柜台后算账，小二忙着招呼客人。", "target_word": "小二", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小二记得每位客人爱吃的菜。", "target_word": "小二", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在电视剧里演饭馆的小二。", "target_word": "小二", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小二把饭菜放到桌子上，说了一声“请慢用”。", "target_word": "小二", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老街上的小二喊道：“客人来了！”", "target_word": "小二", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "店小二", "label": "复合词"}, {"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "旧时饭馆里招呼客人、端菜上茶的伙计", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9b23817-999c-46c1-a554-f63ab669589a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95999, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小二", "is_correct": true, "explanation": "符合语境：小二是饭馆里招呼客人、端菜的伙计，“笑着走过来，问客人想吃什么”正是他的动作。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会笑，也不会走过来问话，与语境不合。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不会说话，不能问客人想吃什么，与语境不合。"}, {"text": "饭量", "is_correct": false, "explanation": "搭配：“饭量”指食量，不能“笑着走过来”，搭配不当。"}], "explanations": {"小二": "符合语境：小二是饭馆里招呼客人、端菜的伙计，“笑着走过来，问客人想吃什么”正是他的动作。", "石头": "语义：石头不会笑，也不会走过来问话，与语境不合。", "小猫": "语义：小猫不会说话，不能问客人想吃什么，与语境不合。", "饭量": "搭配：“饭量”指食量，不能“笑着走过来”，搭配不当。"}, "sentence_index": 0, "correct_answer": "小二"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小二在教室里讲课，声音很大。", "explanation": "这里应该用〈老师〉。小二是饭馆里招呼客人的伙计，不是讲课的老师。"}, {"text": "小二给病人看病，很认真。", "explanation": "这里应该用〈医生〉。小二是招呼客人、端菜的伙计，不负责给病人看病。"}, {"text": "门口站着一个小二，严肃地检查证件。", "explanation": "这里应该用〈警察〉。小二是招呼客人、端菜的伙计，不负责检查证件，检查证件的是警察。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95999, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小二", "is_correct": true, "explanation": "符合语境：小二在饭馆里招呼客人，能“记得每位客人爱吃的菜”。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“记得”要求有记忆能力的人作主语，桌子不能充当。"}, {"text": "书本", "is_correct": false, "explanation": "语义：书本不会记得客人的喜好，语义不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是地方，不能“记得”客人爱吃的菜，语义不通。"}], "explanations": {"小二": "符合语境：小二在饭馆里招呼客人，能“记得每位客人爱吃的菜”。", "桌子": "配价：“记得”要求有记忆能力的人作主语，桌子不能充当。", "书本": "语义：书本不会记得客人的喜好，语义不通。", "厨房": "语义：厨房是地方，不能“记得”客人爱吃的菜，语义不通。"}, "sentence_index": 6, "correct_answer": "小二"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小二在厨房里炒菜，香味飘满整条街。", "explanation": "这里应该用〈厨师〉。小二负责招呼客人、端菜，不负责炒菜。"}, {"text": "小二在大门口站岗，很认真。", "explanation": "这里应该用〈门卫〉。小二是饭馆里招呼客人的伙计，不负责站岗守门。"}, {"text": "小二在门口开车，送客人回家。", "explanation": "这里应该用〈司机〉。小二是饭馆里招呼客人、端菜的伙计，开车送客人是司机的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95999, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "饭馆里有一只小二，正在给客人端菜。", "corrected_sentence": "饭馆里有一位小二，正在给客人端菜。", "error_description": "量词错误：“小二”指人，应用“位”或“个”计量，“只”用于动物，不能说“一只小二”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95999, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "客人一坐下，小二就把热茶送。", "corrected_sentence": "客人一坐下，小二就把热茶送上来。", "error_description": "“把”字句的动词后要有补语等其他成分，只说“把热茶送”不完整，应说“把热茶送上来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96001, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "工人", "is_correct": false, "explanation": "工人指职业，与政治派别的左派不构成反义关系。"}, {"text": "学生", "is_correct": false, "explanation": "学生指身份，与左派不构成反义关系。"}, {"text": "右派", "is_correct": true, "explanation": "正确。左派与右派是政治上的反义词：左派想改变社会，右派主张维持现状。"}, {"text": "报纸", "is_correct": false, "explanation": "报纸是媒体，与左派没有反义关系。"}], "correct_answer": "右派", "explanations": {"工人": "工人指职业，与政治派别的左派不构成反义关系。", "学生": "学生指身份，与左派不构成反义关系。", "右派": "正确。左派与右派是政治上的反义词：左派想改变社会，右派主张维持现状。", "报纸": "报纸是媒体，与左派没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96001, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "农民", "is_correct": false, "explanation": "农民指职业或身份，与左派没有反义关系。"}, {"text": "老师", "is_correct": false, "explanation": "老师指职业，与左派没有反义关系。"}, {"text": "右派", "is_correct": true, "explanation": "正确。左派与右派是政治上的反义词：左派想改变社会，右派主张维持现状。"}, {"text": "工厂", "is_correct": false, "explanation": "工厂指生产场所，与政治派别之间没有反义关系。"}], "correct_answer": "右派", "explanations": {"农民": "农民指职业或身份，与左派没有反义关系。", "老师": "老师指职业，与左派没有反义关系。", "右派": "正确。左派与右派是政治上的反义词：左派想改变社会，右派主张维持现状。", "工厂": "工厂指生产场所，与政治派别之间没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96001, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "左派是政治上想法比较新、想改变社会的一些人。", "primary_collocate": null, "pronunciation": "zuǒ pài", "ipa": "tswo˨˩ pʰai˥˩", "syllable_count": 2, "sentences": [{"text": "他年轻时是左派，想改变社会。", "target_word": "左派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师是左派，常谈社会问题。", "target_word": "左派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "左派希望社会更公平。", "target_word": "左派", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那时的左派常常在报纸上写文章。", "target_word": "左派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的朋友都是左派，想法很新。", "target_word": "左派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "左派和右派对这件事看法不同。", "target_word": "左派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她父亲是个左派，一直想改变社会。", "target_word": "左派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家报纸的读者多半是左派。", "target_word": "左派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那些左派学生常在街上说出自己的想法。", "target_word": "左派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们都叫他左派，因为他总想改变社会。", "target_word": "左派", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "左派人士", "label": "复合"}], "register": "中性", "sense_fingerprint": "政治上想法较新、想改变社会的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddc45bb0-7584-458b-8100-4763b256d8ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96001, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "右派", "is_correct": false, "explanation": "语义：右派主张维持现状，与“想改变社会”正好相反。"}, {"text": "左派", "is_correct": true, "explanation": "正确。左派指政治上想法较新、想改变社会的人，与句中“想改变社会”相符。"}, {"text": "老人", "is_correct": false, "explanation": "语义：“老人”指年纪大的人，与“年轻时”相矛盾。"}, {"text": "退休人员", "is_correct": false, "explanation": "搭配：“退休人员”指已经离开工作岗位的人，不能用于“年轻时”。"}], "explanations": {"右派": "语义：右派主张维持现状，与“想改变社会”正好相反。", "左派": "正确。左派指政治上想法较新、想改变社会的人，与句中“想改变社会”相符。", "老人": "语义：“老人”指年纪大的人，与“年轻时”相矛盾。", "退休人员": "搭配：“退休人员”指已经离开工作岗位的人，不能用于“年轻时”。"}, "sentence_index": 0, "correct_answer": "左派"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他信奉左派，常在报纸上写文章。", "explanation": "这里应该用〈左翼思想〉。“左派”指人或派别，不指思想，不能作“信奉”的对象。"}, {"text": "他常在左派上写文章，报纸都登过。", "explanation": "这里应该用〈报纸〉。“在……上”要接载体，“左派”指人或派别，不能作写文章的载体。"}, {"text": "他的左派在那次车祸中受伤了。", "explanation": "这里应该用〈左边〉或〈左手〉。“左派”只指政治派别，不指身体部位或方向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96001, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保守派", "is_correct": false, "explanation": "语义：保守派主张维持现状，与“一直想改变社会”相矛盾。"}, {"text": "左派", "is_correct": true, "explanation": "正确。“左派”指想改变社会的人，与“一直想改变社会”相符。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：“小学生”是年幼的孩子，不可能是“她父亲”，句子不合常理。"}, {"text": "少女", "is_correct": false, "explanation": "体貌：“少女”描述年轻女性的样子，不能用来指“她父亲”。"}], "explanations": {"保守派": "语义：保守派主张维持现状，与“一直想改变社会”相矛盾。", "左派": "正确。“左派”指想改变社会的人，与“一直想改变社会”相符。", "小学生": "语义：“小学生”是年幼的孩子，不可能是“她父亲”，句子不合常理。", "少女": "体貌：“少女”描述年轻女性的样子，不能用来指“她父亲”。"}, "sentence_index": 6, "correct_answer": "左派"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天喝左派，常在报纸上写文章。", "explanation": "这里应该用〈咖啡〉。“喝”的对象是饮品，“左派”指人或派别，不能被喝。"}, {"text": "我们为他的生日办了一个左派。", "explanation": "这里应该用〈派对〉。“左派”指政治派别或人士，不指聚会。"}, {"text": "他在大会上发表了一场左派。", "explanation": "这里应该用〈演讲〉。“发表”的对象是言论、文章等，“左派”指人或派别，不能作“发表”的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96001, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一只左派，常在报纸上写文章。", "corrected_sentence": "他是一位左派，常在报纸上写文章。", "error_description": "错误：“一只左派”。正确：“一位左派”。“左派”指人，量词应用“位”或“个”，“只”多用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96001, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个政党的成员大多左派。", "corrected_sentence": "这个政党的成员大多是左派。", "error_description": "错误：缺少“是”。正确：“大多是左派”。作谓语的“左派”前需要“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96002, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "农民", "is_correct": false, "explanation": "农民指职业或身份，与左派没有反义关系。"}, {"text": "老师", "is_correct": false, "explanation": "老师指职业，与左派没有反义关系。"}, {"text": "工厂", "is_correct": false, "explanation": "工厂指生产场所，与政治派别之间没有反义关系。"}, {"text": "右派", "is_correct": true, "explanation": "正确。左派与右派是政治上的反义词：左派倾向进步或激进，右派倾向保守。"}], "correct_answer": "右派", "explanations": {"农民": "农民指职业或身份，与左派没有反义关系。", "老师": "老师指职业，与左派没有反义关系。", "工厂": "工厂指生产场所，与政治派别之间没有反义关系。", "右派": "正确。左派与右派是政治上的反义词：左派倾向进步或激进，右派倾向保守。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96002, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "工人", "is_correct": false, "explanation": "工人指职业，与政治派别的左派不构成反义关系。"}, {"text": "学生", "is_correct": false, "explanation": "学生指身份，与左派不构成反义关系。"}, {"text": "报纸", "is_correct": false, "explanation": "报纸是媒体，与左派没有反义关系。"}, {"text": "右派", "is_correct": true, "explanation": "正确。左派与右派是政治上的反义词：左派倾向进步或激进，右派倾向保守。"}], "correct_answer": "右派", "explanations": {"工人": "工人指职业，与政治派别的左派不构成反义关系。", "学生": "学生指身份，与左派不构成反义关系。", "报纸": "报纸是媒体，与左派没有反义关系。", "右派": "正确。左派与右派是政治上的反义词：左派倾向进步或激进，右派倾向保守。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96002, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政治上倾向进步或激进的派别或人士。", "primary_collocate": null, "pronunciation": "zuǒ pài", "ipa": "tswo˨˩ pʰai˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家的左派在选举中得到了很多支持。", "target_word": "左派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "左派主张提高工人的工资。", "target_word": "左派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "左派和右派在议会里常常争论。", "target_word": "左派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位议员属于左派，支持穷人。", "target_word": "左派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "左派在这次选举中输了。", "target_word": "左派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报纸说左派将提出新的法律。", "target_word": "左派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "左派的主张是让社会更平等。", "target_word": "左派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个年代的左派很重视教育。", "target_word": "左派", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他加入了左派，参加了许多活动。", "target_word": "左派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "左派最近发表了一份新的声明。", "target_word": "左派", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "左派人士", "label": "复合"}], "register": "书面", "sense_fingerprint": "政治上倾向进步或激进的派别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddc45bb0-7584-458b-8100-4763b256d8ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96002, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国王", "is_correct": false, "explanation": "语义：国王不经选举产生，与“在选举中得到支持”相矛盾。"}, {"text": "左派", "is_correct": true, "explanation": "正确。“左派”指政治派别或人士，可以在选举中得到支持。"}, {"text": "小屁孩", "is_correct": false, "explanation": "语域：“小屁孩”是口语，与这句书面语不协调；孩子没有选举权，语义上也不合。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不能参加选举，也不会得到选票，与句意不合。"}], "explanations": {"国王": "语义：国王不经选举产生，与“在选举中得到支持”相矛盾。", "左派": "正确。“左派”指政治派别或人士，可以在选举中得到支持。", "小屁孩": "语域：“小屁孩”是口语，与这句书面语不协调；孩子没有选举权，语义上也不合。", "婴儿": "语义：婴儿不能参加选举，也不会得到选票，与句意不合。"}, "sentence_index": 0, "correct_answer": "左派"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位议员信仰左派，常在街上游行。", "explanation": "这里应该用〈社会主义〉。“信仰”的对象是主义或信念，“左派”指人或派别，不能作信仰的对象。"}, {"text": "这位议员为了他的生日办了一个左派。", "explanation": "这里应该用〈派对〉。“左派”指政治派别或人士，不指聚会。"}, {"text": "这位议员开车时向左派转了个弯。", "explanation": "这里应该用〈左〉。“左派”只指政治派别或人士，不表示方向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96002, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奴隶主", "is_correct": false, "explanation": "语义：奴隶主的主张不会是让社会更平等，与句意相矛盾。"}, {"text": "白菜", "is_correct": false, "explanation": "搭配：“主张”的主体应是人或派别，“白菜”不能持有主张。"}, {"text": "左派", "is_correct": true, "explanation": "正确。“左派”指政治派别或人士，其主张可以是让社会更平等。"}, {"text": "地主", "is_correct": false, "explanation": "语义：地主一般维护既有利益，与“让社会更平等”相矛盾。"}], "explanations": {"奴隶主": "语义：奴隶主的主张不会是让社会更平等，与句意相矛盾。", "白菜": "搭配：“主张”的主体应是人或派别，“白菜”不能持有主张。", "左派": "正确。“左派”指政治派别或人士，其主张可以是让社会更平等。", "地主": "语义：地主一般维护既有利益，与“让社会更平等”相矛盾。"}, "sentence_index": 6, "correct_answer": "左派"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "议员最近喝了一杯左派，常在大会上发言。", "explanation": "这里应该用〈咖啡〉。“喝”的对象是饮品，“左派”指人或派别，不能被喝。"}, {"text": "议员最近坐在会议桌的左派。", "explanation": "这里把“左派”当作方位来用，但它只指政治派别，不表示左边或位置。"}, {"text": "议员最近发表了一份新的左派。", "explanation": "这里“发表”的对象应是声明、文章等，“左派”指人或派别，不能作“发表”的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位议员是一只左派，常在大会上发言。", "corrected_sentence": "这位议员是一位左派，常在大会上发言。", "error_description": "错误：“一只左派”。正确：“一位左派”。“左派”指人，量词应用“位”或“个”，“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个团体的领导大多左派。", "corrected_sentence": "这个团体的领导大多是左派。", "error_description": "错误：缺少“是”。正确：“大多是左派”。作谓语的“左派”前需要“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
