INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96005, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96005, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想念是人不在身边，心里一直想着他。", "primary_collocate": null, "pronunciation": "xiǎng niàn", "ipa": "ɕjɑŋ˨˩ njɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我很想念我的家人。", "target_word": "想念", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "出国以后，她每天都想念妈妈。", "target_word": "想念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们想念远方的爸爸。", "target_word": "想念", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想念老朋友，常给他打电话。", "target_word": "想念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷一直想念着在国外的孙子。", "target_word": "想念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离开家三个月了，我非常想念父母。", "target_word": "想念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很想念大学时的同学。", "target_word": "想念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上一个人在房间里，我特别想念你。", "target_word": "想念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你走了以后，大家都很想念你。", "target_word": "想念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天写信，告诉妈妈他很想念她。", "target_word": "想念", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "想念了", "label": "体标"}, {"form": "想念着", "label": "体标"}, {"form": "想念过", "label": "体标"}], "register": "中性", "sense_fingerprint": "想念不在身边的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddc45bb0-7584-458b-8100-4763b256d8ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96005, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与“很”所表达的强烈情感相矛盾，表示不再记得家人。"}, {"text": "想念", "is_correct": true, "explanation": "正确。“想念”指人不在身边而心里挂着他，与“很”和“家人”相符。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、场地等，不能用于“家人”。"}, {"text": "打败", "is_correct": false, "explanation": "语义：“打败”指战胜对方，用于家人的句子不合常理。"}], "explanations": {"忘记": "语义：“忘记”与“很”所表达的强烈情感相矛盾，表示不再记得家人。", "想念": "正确。“想念”指人不在身边而心里挂着他，与“很”和“家人”相符。", "打扫": "搭配：“打扫”的对象是房间、场地等，不能用于“家人”。", "打败": "语义：“打败”指战胜对方，用于家人的句子不合常理。"}, "sentence_index": 0, "correct_answer": "想念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想念打扫房间，常在家里待到晚上。", "explanation": "这里应该用〈想〉。“想念”表示思念离开的人或事，“打扫”是日常动作，不是可以思念的事。"}, {"text": "我想念孩子的功课，常问他的作业。", "explanation": "这里应该用〈惦记〉。“想念”表示思念离开的人或事，不表示担心；牵挂功课要用“惦记”。"}, {"text": "我想念这个方法很好，常用它。", "explanation": "这里应该用〈认为〉。“想念”表示思念，不表示看法或判断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96005, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器具或设施，不能用于“同学”。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”的对象是物品或场所，不能用于“同学”。"}, {"text": "想念", "is_correct": true, "explanation": "正确。“想念”指思念离开的人，与“很”及“大学时的同学”相符。"}, {"text": "掩埋", "is_correct": false, "explanation": "语义：“掩埋”指埋入土中，与对同学的思念明显矛盾。"}], "explanations": {"修理": "搭配：“修理”的对象是器具或设施，不能用于“同学”。", "装饰": "搭配：“装饰”的对象是物品或场所，不能用于“同学”。", "想念": "正确。“想念”指思念离开的人，与“很”及“大学时的同学”相符。", "掩埋": "语义：“掩埋”指埋入土中，与对同学的思念明显矛盾。"}, "sentence_index": 6, "correct_answer": "想念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想念了那班车，只好步行回家。", "explanation": "这里应该用〈错过〉。“想念”表示思念人或事物，不表示没有赶上车。"}, {"text": "他想念明天的会议，早早去了会场。", "explanation": "这里应该用〈期待〉。“想念”指思念已经离开的人或事，不用于还没发生的事。"}, {"text": "他每天写信，告诉妈妈他很想念这个问题。", "explanation": "这里应该用〈思考〉。“想念”表示思念离开的人或事，不表示思考问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96005, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我了想念远方的朋友。", "corrected_sentence": "我很想念远方的朋友。", "error_description": "错误：“了”不能放在动词“想念”之前，此处应为程度副词“很”。正确：“我很想念远方的朋友。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96005, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "离开家以后，我一直想念过父母。", "corrected_sentence": "离开家以后，我一直想念着父母。", "error_description": "错误：“一直想念过”。正确：“一直想念着”。“一直”表示持续，应搭配持续体“着”，不能用表示经历的“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96006, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96006, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96006, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对离别的人或事物不能忘记，心中挂念。", "primary_collocate": null, "pronunciation": "xiǎng niàn", "ipa": "ɕjɑŋ˨˩ njɛn˥˩", "syllable_count": 2, "sentences": [{"text": "在国外住久了，我想念家乡的小吃。", "target_word": "想念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他离开学校十年，还想念那里的老树。", "target_word": "想念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她常常想念小时候的生活。", "target_word": "想念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想念北京的秋天。", "target_word": "想念", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "住在城市里，奶奶很想念乡下的小院。", "target_word": "想念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，我想念以前住的老房子。", "target_word": "想念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想念着故乡的河。", "target_word": "想念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业多年，她仍然想念那段时光。", "target_word": "想念", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想念妈妈做的面条。", "target_word": "想念", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "离开海边以后，他想念那里的风和海浪。", "target_word": "想念", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "想念了", "label": "体标"}, {"form": "想念着", "label": "体标"}, {"form": "想念过", "label": "体标"}], "register": "中性", "sense_fingerprint": "想念离别的事物或往事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddc45bb0-7584-458b-8100-4763b256d8ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96006, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、场地等，不能说“打扫小吃”。"}, {"text": "想念", "is_correct": true, "explanation": "正确。“想念”表示对离开的事物心中挂念，与“在国外住久了”及“家乡的小吃”相符。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是地方或机构，不能用于“小吃”。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉建筑物等，用于小吃不合常理。"}], "explanations": {"打扫": "搭配：“打扫”的对象是房间、场地等，不能说“打扫小吃”。", "想念": "正确。“想念”表示对离开的事物心中挂念，与“在国外住久了”及“家乡的小吃”相符。", "参观": "搭配：“参观”的对象是地方或机构，不能用于“小吃”。", "拆除": "语义：“拆除”指拆掉建筑物等，用于小吃不合常理。"}, "sentence_index": 0, "correct_answer": "想念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我坐在北京的窗前，想念眼前的秋叶。", "explanation": "这里应该用〈欣赏〉。“想念”指对离开的事物挂念，“眼前的秋叶”并未离开，不能用“想念”。"}, {"text": "我想念北京的电费，常去交费。", "explanation": "这里应该用〈交〉。“想念”表示思念离开的人或事，电费不能被思念，应说“交电费”。"}, {"text": "我想念手里的这支笔，正在写字。", "explanation": "这里应该用〈用〉。“想念”指对离开的事物挂念，“手里的笔”正在使用，不能用“想念”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96006, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "停止", "is_correct": false, "explanation": "搭配：“停止”后接的是动作或活动，不能直接接“河”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能用于“河”。"}, {"text": "想念", "is_correct": true, "explanation": "正确。“想念”表示对离开的地方心中挂念，与“故乡的河”相符。"}, {"text": "填埋", "is_correct": false, "explanation": "语义：“填埋”指把河填平，与“想念”的情感及河的存在相矛盾。"}], "explanations": {"停止": "搭配：“停止”后接的是动作或活动，不能直接接“河”。", "吃": "搭配：“吃”的对象是食物，不能用于“河”。", "想念": "正确。“想念”表示对离开的地方心中挂念，与“故乡的河”相符。", "填埋": "语义：“填埋”指把河填平，与“想念”的情感及河的存在相矛盾。"}, "sentence_index": 6, "correct_answer": "想念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他正在海边游泳，很想念身边的海水。", "explanation": "这里应该用〈享受〉。“想念”指对离开的事物挂念，“身边的海水”就在眼前，不能用“想念”。"}, {"text": "离开海边以后，他想念明天的会议，早早回了城里。", "explanation": "这里应该用〈期待〉。“想念”指思念已经离开的人或事，不用于还没发生的事。"}, {"text": "他站在海边，想念眼前的海浪，静静地看着。", "explanation": "这里应该用〈欣赏〉。“想念”指对离开的事物挂念，“眼前的海浪”并未离开，不能用“想念”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我一直了想念那里的秋天。", "corrected_sentence": "我一直很想念那里的秋天。", "error_description": "错误：“了”不能放在动词“想念”之前，此处应为程度副词“很”。正确：“我一直很想念那里的秋天。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人一直想念过故乡的小河。", "corrected_sentence": "老人一直想念着故乡的小河。", "error_description": "错误：“一直想念过”。正确：“一直想念着”。“一直”表示持续，应搭配“着”，不能用表示经历的“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
