INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96007, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "爱上是开始很喜欢一个人或一样东西。", "primary_collocate": null, "pronunciation": "ài shàng", "ipa": "aɪ˥˩ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "她爱上了这个城市。", "target_word": "爱上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次见到她，就爱上了她。", "target_word": "爱上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爱上了中国菜。", "target_word": "爱上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明爱上了踢足球。", "target_word": "爱上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住了一年，我爱上了这里的生活。", "target_word": "爱上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是什么时候爱上读书的？", "target_word": "爱上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕狗，可是后来爱上了一只小狗。", "target_word": "爱上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不知不觉爱上了那个老师。", "target_word": "爱上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我慢慢爱上了喝茶。", "target_word": "爱上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她爱上过一个很高的男孩。", "target_word": "爱上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "爱上了", "label": "体标"}, {"form": "爱上过", "label": "体标"}], "register": "中性", "sense_fingerprint": "开始很喜欢某人或某物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dd71c1-9209-4d12-a308-62a2880ffae2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96007, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "爱上", "is_correct": true, "explanation": "爱上（ài shàng）：开始很喜欢某人或某物，正确答案。"}, {"text": "哀伤", "is_correct": false, "explanation": "āi shāng 与 ài shàng 两个音节的声调都不同，意思是悲伤。"}, {"text": "挨上", "is_correct": false, "explanation": "āi shàng（第一声）与 ài shàng（第四声）声调不同，意思是碰上、挨到。"}, {"text": "拜上", "is_correct": false, "explanation": "bài 与 ài 声母不同（b 与零声母），意思是书信用语「拜上」，即恭敬地致意。"}], "explanations": {"爱上": "爱上（ài shàng）：开始很喜欢某人或某物，正确答案。", "哀伤": "āi shāng 与 ài shàng 两个音节的声调都不同，意思是悲伤。", "挨上": "āi shàng（第一声）与 ài shàng（第四声）声调不同，意思是碰上、挨到。", "拜上": "bài 与 ài 声母不同（b 与零声母），意思是书信用语「拜上」，即恭敬地致意。"}, "sentence_index": null, "correct_answer": "爱上"}, "level_3": {"options": [{"text": "爱上", "is_correct": true, "explanation": "爱上：开始喜欢，与「她……了这个城市」的语境相符。"}, {"text": "养成", "is_correct": false, "explanation": "搭配：「养成」后接习惯或品质，不能说养成一个城市。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：「吃掉」指把东西吃下去，与「这个城市」的语义不合。"}, {"text": "吞下", "is_correct": false, "explanation": "语义：「吞下」指咽下去，不能用来表示喜欢一个城市。"}], "explanations": {"爱上": "爱上：开始喜欢，与「她……了这个城市」的语境相符。", "养成": "搭配：「养成」后接习惯或品质，不能说养成一个城市。", "吃掉": "语义：「吃掉」指把东西吃下去，与「这个城市」的语义不合。", "吞下": "语义：「吞下」指咽下去，不能用来表示喜欢一个城市。"}, "sentence_index": 0, "correct_answer": "爱上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都爱上家乡。", "explanation": "这里应该用〈怀念〉。“爱上”强调开始喜欢的那一刻，与“每天都”搭配别扭；远在他乡的思念应说“怀念”。"}, {"text": "他爱上了明天。", "explanation": "这里应该用〈期待〉。爱上的对象是人、事物或某种活动，表示开始喜欢；对尚未到来的日子抱有盼望，应用〈期待〉。"}, {"text": "他爱上了感冒。", "explanation": "这里应该用〈患上〉。“爱上”的对象是人或事物，并表示开始喜欢；得病应说“患上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96007, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "爱上", "is_correct": true, "explanation": "爱上（ài shàng）：开始很喜欢某人或某物，正确答案。"}, {"text": "带上", "is_correct": false, "explanation": "dài 与 ài 声母不同（d 与零声母），意思是带着、戴上。"}, {"text": "派上", "is_correct": false, "explanation": "pài 与 ài 声母不同（p 与零声母），意思是派上用场。"}, {"text": "盖上", "is_correct": false, "explanation": "gài 与 ài 声母不同（g 与零声母），意思是盖上、覆盖。"}, {"text": "赖上", "is_correct": false, "explanation": "lài 与 ài 声母不同（l 与零声母），意思是纠缠、赖着。"}], "explanations": {"爱上": "爱上（ài shàng）：开始很喜欢某人或某物，正确答案。", "带上": "dài 与 ài 声母不同（d 与零声母），意思是带着、戴上。", "派上": "pài 与 ài 声母不同（p 与零声母），意思是派上用场。", "盖上": "gài 与 ài 声母不同（g 与零声母），意思是盖上、覆盖。", "赖上": "lài 与 ài 声母不同（l 与零声母），意思是纠缠、赖着。"}, "sentence_index": null, "correct_answer": "爱上"}, "level_3": {"options": [{"text": "爱上", "is_correct": true, "explanation": "爱上：先怕狗后来转而喜欢，与「后来」的转变相符。"}, {"text": "辞退", "is_correct": false, "explanation": "搭配：「辞退」用于解雇人员，不能用于小狗。"}, {"text": "毕业", "is_correct": false, "explanation": "语法：「毕业」是不及物动词，不能带宾语，不能说「毕业了一只小狗」。"}, {"text": "背诵", "is_correct": false, "explanation": "搭配：“背诵”的对象是文字或课文，不能用于小狗。"}], "explanations": {"爱上": "爱上：先怕狗后来转而喜欢，与「后来」的转变相符。", "辞退": "搭配：「辞退」用于解雇人员，不能用于小狗。", "毕业": "语法：「毕业」是不及物动词，不能带宾语，不能说「毕业了一只小狗」。", "背诵": "搭配：“背诵”的对象是文字或课文，不能用于小狗。"}, "sentence_index": 6, "correct_answer": "爱上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我一直爱上大海。", "explanation": "这里应该用〈向往〉。爱上表示开始喜欢的变化，不能与表示持续的「一直」连用；持续的喜爱应用〈向往〉。"}, {"text": "他爱上了这个消息。", "explanation": "这里应该用〈得知〉。“爱上”表示喜欢某人或某事物，不能用于获知消息；获知应说“得知”。"}, {"text": "这孩子每天都爱上这本书。", "explanation": "这里应该用〈喜欢〉。“爱上”强调开始喜欢的那一刻，与“每天都”搭配别扭；经常性的喜欢应说“每天都喜欢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96007, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从小就爱上着画画。", "corrected_sentence": "他从小就爱上了画画。", "error_description": "体标错误：“爱上”表示一次性地开始喜欢，后面应接“了”，写成“着”不合语法。正确是“爱上了画画”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96007, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子一年就把爱上了游泳。", "corrected_sentence": "这个孩子一年就爱上了游泳。", "error_description": "“把”多余：“把”字句应为“把＋宾语＋动词”，这里“把”后直接接动词“爱上”，没有宾语。去掉“把”即可，正确是“这个孩子一年就爱上了游泳”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
