INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96010, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "关爱、同情他人的心。", "primary_collocate": null, "pronunciation": "ài xīn", "ipa": "ai˥˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "她很有爱心，常常帮助街上的流浪猫。", "target_word": "爱心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们要有爱心，别伤害小动物。", "target_word": "爱心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家献出了爱心，帮助生病的小朋友。", "target_word": "爱心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位护士对病人充满爱心。", "target_word": "爱心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爱心让大家都很感动。", "target_word": "爱心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子从小有爱心，长大会关心别人。", "target_word": "爱心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你们的爱心，这些衣服能帮到很多人。", "target_word": "爱心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个有爱心的人，看见别人哭会难过。", "target_word": "爱心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己的爱心都给了孤儿院的孩子们。", "target_word": "爱心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帮助别人不一定要有钱，有爱心就行。", "target_word": "爱心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "颗", "label": "量词"}], "register": "中性", "sense_fingerprint": "爱心：关爱、同情他人的心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '277212ec-c05c-4f82-b617-5b3b2e2110c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96010, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "爱心", "is_correct": true, "explanation": "爱心指关心、同情他人的心，与“常常帮助街上的流浪猫”相符。"}, {"text": "怒气", "is_correct": false, "explanation": "语义：怒气与“常常帮助流浪猫”的善意相悖，句子说不通。"}, {"text": "恶意", "is_correct": false, "explanation": "语义：恶意指想伤害别人的心，与“帮助流浪猫”正相反。"}, {"text": "仇恨", "is_correct": false, "explanation": "搭配：“心怀仇恨”是常用说法，“很有仇恨”不成立。"}], "explanations": {"爱心": "爱心指关心、同情他人的心，与“常常帮助街上的流浪猫”相符。", "怒气": "语义：怒气与“常常帮助流浪猫”的善意相悖，句子说不通。", "恶意": "语义：恶意指想伤害别人的心，与“帮助流浪猫”正相反。", "仇恨": "搭配：“心怀仇恨”是常用说法，“很有仇恨”不成立。"}, "sentence_index": 0, "correct_answer": "爱心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的爱心有问题，要马上去医院做手术。", "explanation": "这里应该用〈心脏〉。“爱心”指关爱他人的心意，不指身体器官，说器官要用“心脏”。"}, {"text": "我的爱心是画画。", "explanation": "这里应该用〈爱好〉。爱心指关心他人的心，不能指兴趣。"}, {"text": "我今天的爱心很好，出门时还在唱歌。", "explanation": "这里应该用〈心情〉。“爱心”指关心他人的心，不用来说情绪的好坏，说心情要用“心情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96010, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爱心", "is_correct": true, "explanation": "爱心指关心、同情他人的心，这里指捐衣服所表现的关爱，与“能帮到很多人”相符。"}, {"text": "怨气", "is_correct": false, "explanation": "语义：怨气与“谢谢你们”的感激语境相反，“这些衣服能帮到很多人”也与怨气不合。"}, {"text": "冷漠", "is_correct": false, "explanation": "语义：“谢谢你们的冷漠”与“这些衣服能帮到很多人”的语境正相反。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“谢谢你们的……”后多接帮助、礼物等，“脾气”不能被感谢。"}], "explanations": {"爱心": "爱心指关心、同情他人的心，这里指捐衣服所表现的关爱，与“能帮到很多人”相符。", "怨气": "语义：怨气与“谢谢你们”的感激语境相反，“这些衣服能帮到很多人”也与怨气不合。", "冷漠": "语义：“谢谢你们的冷漠”与“这些衣服能帮到很多人”的语境正相反。", "脾气": "搭配：“谢谢你们的……”后多接帮助、礼物等，“脾气”不能被感谢。"}, "sentence_index": 6, "correct_answer": "爱心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她下定了爱心，要去山区教书。", "explanation": "这里应该用〈决心〉。“下定”搭配“决心”，爱心指关心他人的心，不能下定。"}, {"text": "他对考试很有爱心。", "explanation": "这里应该用〈信心〉。爱心指关心他人的心，不指对事情的把握。"}, {"text": "他的爱心是一位医生。", "explanation": "这里应该用〈爱人〉。“爱心”指关心他人的心，不能指配偶，说配偶要用“爱人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他捐出了一辆爱心，帮助山区的学校。", "corrected_sentence": "他捐出了一份爱心，帮助山区的学校。", "error_description": "“爱心”的量词应用“份”或“颗”，“辆”用于车，不能用来数爱心。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是一个很爱心的老师。", "corrected_sentence": "她是一个很有爱心的老师。", "error_description": "“爱心”前要加“有”，说“很有爱心”，不能直接说“很爱心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96011, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
