INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96011, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "找出是找了以后，把它拿出来。", "primary_collocate": null, "pronunciation": "zhǎo chū", "ipa": "ʈʂɑʊ̯²¹⁴ ʈʂʰu⁵⁵", "syllable_count": 2, "sentences": [{"text": "他从书包里找出了一把伞。", "target_word": "找出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈从柜子里找出一件旧毛衣。", "target_word": "找出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在抽屉里找出了那本旧相册。", "target_word": "找出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从箱子底下找出一双新鞋。", "target_word": "找出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸从工具箱里找出锤子，开始修门。", "target_word": "找出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从口袋里找出手机，打了个电话。", "target_word": "找出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶从床下找出一个小盒子。", "target_word": "找出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你从包里找出身份证给我看看。", "target_word": "找出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧照片从盒子里找出来给我看。", "target_word": "找出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到了，妈妈从衣柜里找出一床厚被子。", "target_word": "找出", "complexity_tier": "T3", "furigana": "dōng tiān dào le mā ma cóng yī guì lǐ zhǎo chū yì chuáng hòu bèi zi", "sentence_source": "generated"}], "morphological_forms": [{"form": "找出了", "label": "完成体"}, {"form": "找出来", "label": "趋向补语形式"}], "register": "口语", "sense_fingerprint": "从容器或某处翻找后把东西拿出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9b23817-999c-46c1-a554-f63ab669589a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96011, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "找出", "is_correct": true, "explanation": "正确：找出，zhǎo chū，指从容器或某处翻找后把东西拿出来。"}, {"text": "长出", "is_correct": false, "explanation": "zhǎng 与 zhǎo 只有韵母不同（ang 与 ao），声调相同，意思是“长出”，指生长出来。"}, {"text": "照出", "is_correct": false, "explanation": "zhào（第四声）与 zhǎo（第三声）声调不同，意思是“照出”，指光线使某物显现。"}, {"text": "早出", "is_correct": false, "explanation": "zǎo 与 zhǎo 只有声母不同（z 与 zh），意思是“早出”，指早早出去。"}, {"text": "找书", "is_correct": false, "explanation": "shū 与 chū 只有声母不同（sh 与 ch），意思是“找书”，指寻找图书。"}], "explanations": {"找出": "正确：找出，zhǎo chū，指从容器或某处翻找后把东西拿出来。", "长出": "zhǎng 与 zhǎo 只有韵母不同（ang 与 ao），声调相同，意思是“长出”，指生长出来。", "照出": "zhào（第四声）与 zhǎo（第三声）声调不同，意思是“照出”，指光线使某物显现。", "早出": "zǎo 与 zhǎo 只有声母不同（z 与 zh），意思是“早出”，指早早出去。", "找书": "shū 与 chū 只有声母不同（sh 与 ch），意思是“找书”，指寻找图书。"}, "sentence_index": null, "correct_answer": "找出"}, "level_3": {"options": [{"text": "找出", "is_correct": true, "explanation": "正确：“找出”指从书包里翻找后拿出一把伞，符合句意。"}, {"text": "放进", "is_correct": false, "explanation": "语义：“放进”是把东西放入书包，方向与“从书包里”取物相反。"}, {"text": "买来", "is_correct": false, "explanation": "语义：“买来”指购买，与“从书包里”的取物场景矛盾。"}, {"text": "投入", "is_correct": false, "explanation": "搭配：“投入”用于资金、精力，不能说从书包里投入一把伞。"}], "explanations": {"找出": "正确：“找出”指从书包里翻找后拿出一把伞，符合句意。", "放进": "语义：“放进”是把东西放入书包，方向与“从书包里”取物相反。", "买来": "语义：“买来”指购买，与“从书包里”的取物场景矛盾。", "投入": "搭配：“投入”用于资金、精力，不能说从书包里投入一把伞。"}, "sentence_index": 0, "correct_answer": "找出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从抽屉里找出了一片乌云。", "explanation": "这里应该用〈飘来〉。“找出”指从容器或某处翻找后把东西拿出来，乌云不能从抽屉里拿出，应说飘来。"}, {"text": "他从包里找出了一首歌。", "explanation": "这里应该用〈唱出〉。“找出”指从容器或某处翻找后拿出东西，歌是唱出来的，不能从包里拿出。"}, {"text": "工人把货物找出了仓库。", "explanation": "这里应该用〈运出〉。货物离开仓库要说运出，“找出”不能表示把东西搬离某处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96011, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "找出", "is_correct": true, "explanation": "正确：“找出”指从床下翻找后拿出一个小盒子，符合句意。"}, {"text": "送给", "is_correct": false, "explanation": "配价：“送给”需要接受者，句中缺少“送给谁”，句子不成立。"}, {"text": "放入", "is_correct": false, "explanation": "语义：“放入”是放进去，与“从床下拿出”的方向相反。"}, {"text": "买下", "is_correct": false, "explanation": "语义：“买下”指购买，与“从床下”取物的场景不符。"}], "explanations": {"找出": "正确：“找出”指从床下翻找后拿出一个小盒子，符合句意。", "送给": "配价：“送给”需要接受者，句中缺少“送给谁”，句子不成立。", "放入": "语义：“放入”是放进去，与“从床下拿出”的方向相反。", "买下": "语义：“买下”指购买，与“从床下”取物的场景不符。"}, "sentence_index": 6, "correct_answer": "找出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从书包里找出了一阵雷声。", "explanation": "这里应该用〈响起〉。“找出”指从容器或某处翻找后拿出东西，雷声不能从书包里拿出，应说响起。"}, {"text": "他从口袋里找出了一句道歉。", "explanation": "这里应该用〈说出〉。“找出”指从容器或某处翻找后拿出东西，道歉是说出来的，不能从口袋里找出。"}, {"text": "妈妈从衣柜里找出一阵风。", "explanation": "这里应该用〈刮起〉。“找出”指从容器或某处翻找后拿出东西，风不能从衣柜里拿出，应说刮起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96011, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈从抽屉里没找出了一把钥匙。", "corrected_sentence": "妈妈从抽屉里找出了一把钥匙。", "error_description": "“没找出”是否定形式，后面不加“了”；本句是肯定陈述，应去掉“没”，说“找出了一把钥匙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96011, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷从书架上找出了过一本旧书。", "corrected_sentence": "爷爷从书架上找出了一本旧书。", "error_description": "“了”与“过”不能同时用在“找出”后。这里说的是已经完成的动作，只用“了”，应去掉“过”，说“找出了一本旧书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
