INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96012, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过寻找或仔细查看，发现或查明某物、某人，或某个原因、答案。", "primary_collocate": null, "pronunciation": "zhǎo chū", "ipa": "ʈʂɑʊ̯²¹⁴ ʈʂʰu⁵⁵", "syllable_count": 2, "sentences": [{"text": "我终于找出了丢失的钥匙。", "target_word": "找出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你找出这句话里的错字。", "target_word": "找出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察很快找出了那个小偷。", "target_word": "找出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们找出文章里的生词。", "target_word": "找出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他找出了电脑坏掉的原因。", "target_word": "找出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能找出这两张图的不同吗？", "target_word": "找出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一定要找出解决问题的办法。", "target_word": "找出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他翻了很久的书，终于找出了答案。", "target_word": "找出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在图片里找出了所有的小动物。", "target_word": "找出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她仔细看了一遍，找出了三个错误。", "target_word": "找出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "找出了", "label": "完成体"}, {"form": "找出来", "label": "趋向补语形式"}], "register": "中性", "sense_fingerprint": "经过寻找发现或查明某物、某人或原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9b23817-999c-46c1-a554-f63ab669589a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96012, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "找出", "is_correct": true, "explanation": "正确：找出，zhǎo chū，指通过寻找把东西找到。"}, {"text": "长出", "is_correct": false, "explanation": "zhǎng 与 zhǎo 只有韵母不同（ang 与 ao），声调相同，意思是“长出”，指生长出来。"}, {"text": "照出", "is_correct": false, "explanation": "zhào（第四声）与 zhǎo（第三声）声调不同，意思是“照出”，指光线使某物显现。"}, {"text": "早出", "is_correct": false, "explanation": "zǎo 与 zhǎo 只有声母不同（z 与 zh），意思是“早出”，指早早出去。"}, {"text": "找书", "is_correct": false, "explanation": "shū 与 chū 只有声母不同（sh 与 ch），意思是“找书”，指寻找图书。"}], "explanations": {"找出": "正确：找出，zhǎo chū，指通过寻找把东西找到。", "长出": "zhǎng 与 zhǎo 只有韵母不同（ang 与 ao），声调相同，意思是“长出”，指生长出来。", "照出": "zhào（第四声）与 zhǎo（第三声）声调不同，意思是“照出”，指光线使某物显现。", "早出": "zǎo 与 zhǎo 只有声母不同（z 与 zh），意思是“早出”，指早早出去。", "找书": "shū 与 chū 只有声母不同（sh 与 ch），意思是“找书”，指寻找图书。"}, "sentence_index": null, "correct_answer": "找出"}, "level_3": {"options": [{"text": "找出", "is_correct": true, "explanation": "正确：“找出”指通过寻找把丢失的钥匙找到，符合句意。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：“扔掉”与“找到丢失的钥匙”的意思相反。"}, {"text": "打开", "is_correct": false, "explanation": "搭配：“打开”用于门、箱子等，不能说打开一把丢失的钥匙。"}, {"text": "查证", "is_correct": false, "explanation": "搭配：“查证”用于事实、消息，不能用于丢失的钥匙。"}], "explanations": {"找出": "正确：“找出”指通过寻找把丢失的钥匙找到，符合句意。", "扔掉": "语义：“扔掉”与“找到丢失的钥匙”的意思相反。", "打开": "搭配：“打开”用于门、箱子等，不能说打开一把丢失的钥匙。", "查证": "搭配：“查证”用于事实、消息，不能用于丢失的钥匙。"}, "sentence_index": 0, "correct_answer": "找出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他找出了一场争吵。", "explanation": "这里应该用〈引发〉。“找出”指找到已存在的人、物或答案，争吵是人与人之间引起的，不能说找出。"}, {"text": "他向老师找出了帮助。", "explanation": "这里应该用〈寻求〉。“找出”指找到已存在的人、物或答案，帮助要向人寻求，不能说找出。"}, {"text": "他找出了一场雨。", "explanation": "这里应该用〈下〉。“找出”指找到已存在的人、物或答案，雨是天气现象，不能被找出，要说下雨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96012, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "找出", "is_correct": true, "explanation": "正确：“找出”指找到解决问题的办法，符合句意。"}, {"text": "丢失", "is_correct": false, "explanation": "语义：“丢失”与“找出解决问题的办法”的意思相反。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”的对象是建筑、设施，不能说拆除办法。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：“搬运”指搬动物品，不能用于办法。"}], "explanations": {"找出": "正确：“找出”指找到解决问题的办法，符合句意。", "丢失": "语义：“丢失”与“找出解决问题的办法”的意思相反。", "拆除": "搭配：“拆除”的对象是建筑、设施，不能说拆除办法。", "搬运": "语义：“搬运”指搬动物品，不能用于办法。"}, "sentence_index": 6, "correct_answer": "找出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他找出了一声尖叫。", "explanation": "这里应该用〈发出〉。“找出”指找到已有的人、物或答案，尖叫是人发出的声音，不能说找出。"}, {"text": "她找出了一个笑容。", "explanation": "这里应该用〈露出〉。笑容是表情显现出来的，不能说找出。"}, {"text": "血从伤口里找出来了。", "explanation": "这里应该用〈流出〉。血是从伤口里流动出来的，“找出”指通过寻找发现，不能用于血的流出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈终于找出了过那张旧照片。", "corrected_sentence": "妈妈终于找出了那张旧照片。", "error_description": "“了”与“过”不能同时用在“找出”后。这里说的是已经完成的动作，只用“了”，应去掉“过”，说“找出了那张旧照片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师批改作业时找出了过两个错字。", "corrected_sentence": "老师批改作业时找出了两个错字。", "error_description": "“过”与“了”不能同时用在“找出”后。这里表示已经完成的动作，只用“了”，应去掉“过”，说“找出了两个错字”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
