INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96013, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拜托是客气地请别人帮忙。", "primary_collocate": null, "pronunciation": "bài tuō", "ipa": "pai̯˥˩ tʰuɔ˥", "syllable_count": 2, "sentences": [{"text": "拜托你帮我拿一下这个包，好吗？", "target_word": "拜托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天我有事，拜托你替我去开会。", "target_word": "拜托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拜托邻居照顾他的小狗。", "target_word": "拜托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想拜托老师给我写一封信。", "target_word": "拜托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈拜托我买一些水果回家。", "target_word": "拜托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拜托你小声一点，孩子在睡觉。", "target_word": "拜托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我拜托过他很多次，他都没有答应。", "target_word": "拜托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事就拜托你了，谢谢！", "target_word": "拜托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拜托朋友帮忙找一间便宜的房子。", "target_word": "拜托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拜托大家安静，会议马上开始。", "target_word": "拜托", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拜托了", "label": "体标"}, {"form": "拜托过", "label": "体标"}], "register": "口语", "sense_fingerprint": "客气地请别人帮忙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '996bd829-ae6b-4c7b-887c-9cabc20a2540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96013, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拜托", "is_correct": true, "explanation": "动词，客气地请人帮忙，与句末“好吗”的商量语气一致。"}, {"text": "命令", "is_correct": false, "explanation": "语义：“命令”带有强制性，与句末“好吗”的商量语气矛盾。"}, {"text": "通知", "is_correct": false, "explanation": "语义：“通知”只是告知情况，句末“好吗”带有恳切请托的语气，与“通知”不符。"}, {"text": "吩咐", "is_correct": false, "explanation": "语义：“吩咐”是上级或长辈对下级的指示，与句末“好吗”的商量语气不合。"}], "explanations": {"拜托": "动词，客气地请人帮忙，与句末“好吗”的商量语气一致。", "命令": "语义：“命令”带有强制性，与句末“好吗”的商量语气矛盾。", "通知": "语义：“通知”只是告知情况，句末“好吗”带有恳切请托的语气，与“通知”不符。", "吩咐": "语义：“吩咐”是上级或长辈对下级的指示，与句末“好吗”的商量语气不合。"}, "sentence_index": 0, "correct_answer": "拜托"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我拜托朋友吃饭，大家都很开心。", "explanation": "这里应该用〈请〉。“拜托”只表示恳切地请人帮忙，请客、宴请要用“请”。"}, {"text": "拜托你生日快乐。", "explanation": "这里应该用〈祝〉。拜托是请人帮忙，祝福别人要用“祝”，不能用“拜托”。"}, {"text": "我拜托天气变好。", "explanation": "这里应该用〈希望〉。拜托只用于能听从请求的人，对天气只能说“希望”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96013, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拜托", "is_correct": true, "explanation": "动词，恳切地请求，与“没有答应”构成请求与回应的关系。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”不是请求，后句“没有答应”无法与之对应。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”是称赞，不是请求，“没有答应”与之无关。"}, {"text": "打扰", "is_correct": false, "explanation": "搭配：“打扰”表示干扰，不能与“答应”形成请求与回应的关系。"}], "explanations": {"拜托": "动词，恳切地请求，与“没有答应”构成请求与回应的关系。", "感谢": "语义：“感谢”不是请求，后句“没有答应”无法与之对应。", "夸奖": "语义：“夸奖”是称赞，不是请求，“没有答应”与之无关。", "打扰": "搭配：“打扰”表示干扰，不能与“答应”形成请求与回应的关系。"}, "sentence_index": 6, "correct_answer": "拜托"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我拜托你考上大学，真为你高兴。", "explanation": "这里应该用〈祝贺〉。“拜托”是请人帮忙，庆贺别人的成功要用“祝贺”。"}, {"text": "雨下得很大，我拜托它停下来。", "explanation": "这里应该用〈希望〉。拜托只用于能听从请求的人，对雨这类自然现象只能说“希望”。"}, {"text": "我拜托电脑快点儿开机。", "explanation": "这里应该用〈希望〉。拜托只用于能听懂请求的人，对电脑这类东西只能说“希望”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96013, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "拜托给你帮我看一下这份文件，好吗？", "corrected_sentence": "拜托你帮我看一下这份文件，好吗？", "error_description": "错误：“拜托”后多了“给”；正确：“拜托你帮我……”。“拜托”直接带被请求的人，不需要“给”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96013, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "拜托了你把这把伞还给他。", "corrected_sentence": "拜托你把这把伞还给他。", "error_description": "错误：“了”放在了“你”前面。“拜托”后面的“了”应放在句末，应说“拜托你把这把伞还给他”或“拜托你了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
