INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96015, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "挑选是从很多东西里面，选出自己想要的。", "primary_collocate": null, "pronunciation": "tiāo xuǎn", "ipa": "tʰjɑʊ˥ ɕɥɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "我在水果店里仔细挑选苹果。", "target_word": "挑选", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她挑选了一条红色的裙子。", "target_word": "挑选", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈带我去商店挑选新书包。", "target_word": "挑选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么多衣服，我不知道怎么挑选。", "target_word": "挑选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你慢慢挑选，不用着急。", "target_word": "挑选", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他挑选了半天，最后什么也没买。", "target_word": "挑选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想挑选一份好看的生日礼物。", "target_word": "挑选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们正在挑选自己喜欢的玩具。", "target_word": "挑选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她挑选过很多次，还是不满意。", "target_word": "挑选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你帮我挑选一个大一点的西瓜。", "target_word": "挑选", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "挑选了", "label": "体标：了"}, {"form": "挑选过", "label": "体标：过"}, {"form": "挑选出", "label": "复合词"}], "register": "中性", "sense_fingerprint": "挑选：从许多东西里选出自己想要的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b21d38-673e-4382-b312-55fb37567b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96015, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "种植", "is_correct": false, "explanation": "语义：水果店里不种植苹果，与“水果店里”的语境不符。"}, {"text": "挑选", "is_correct": true, "explanation": "正确：“仔细挑选”指在许多苹果中选出好的，与水果店的语境相符。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧”多指烹饪，不能用在“仔细烧苹果”这种店里的行为上。"}, {"text": "生产", "is_correct": false, "explanation": "语义：水果店不生产苹果，句子说的是在店里的选购。"}], "explanations": {"种植": "语义：水果店里不种植苹果，与“水果店里”的语境不符。", "挑选": "正确：“仔细挑选”指在许多苹果中选出好的，与水果店的语境相符。", "烧": "搭配：“烧”多指烹饪，不能用在“仔细烧苹果”这种店里的行为上。", "生产": "语义：水果店不生产苹果，句子说的是在店里的选购。"}, "sentence_index": 0, "correct_answer": "挑选"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们挑选了坐火车去北京。", "explanation": "这里应该用〈选择〉。挑选指从许多具体东西中挑出想要的，决定去哪里要说选择。"}, {"text": "我挑选了三天，身体终于好了。", "explanation": "这里应该用〈休养〉。挑选指从许多东西中选出，养身体要说休养。"}, {"text": "医生挑选了我的体温，是三十八度。", "explanation": "这里应该用〈测量〉。体温是测量出来的数值，不能挑选。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96015, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：礼物不能吃，与“好看的生日礼物”不符。"}, {"text": "挑选", "is_correct": true, "explanation": "正确：想要一份好看的礼物，就要从许多中挑出，与“挑选”相符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象通常是衣物或餐具，不说“洗礼物”。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”只用于动物或婴儿，不说“喂礼物”。"}], "explanations": {"吃": "语义：礼物不能吃，与“好看的生日礼物”不符。", "挑选": "正确：想要一份好看的礼物，就要从许多中挑出，与“挑选”相符。", "洗": "搭配：“洗”的对象通常是衣物或餐具，不说“洗礼物”。", "喂": "搭配：“喂”只用于动物或婴儿，不说“喂礼物”。"}, "sentence_index": 6, "correct_answer": "挑选"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我挑选了他的意思，很快就明白了。", "explanation": "这里应该用〈理解〉。挑选指从许多东西中选出，理解意思不能用挑选。"}, {"text": "我挑选了很久的痛苦。", "explanation": "这里应该用〈忍受〉。挑选指从许多东西中选出，痛苦要说忍受。"}, {"text": "他挑选了我的错误。", "explanation": "这里应该用〈原谅〉。挑选指从许多东西中选出，错误要说原谅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96015, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈挑选很仔细，西瓜都很甜。", "corrected_sentence": "妈妈挑选得很仔细，西瓜都很甜。", "error_description": "“挑选”后面带程度补语时要用“得”。应说“挑选得很仔细”，“挑选很仔细”错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96015, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们挑选着好几次，都没找到满意的。", "corrected_sentence": "我们挑选过好几次，都没找到满意的。", "error_description": "表示经历过的动作要用“过”，“着”表示持续，不能与“好几次”连用。应说“挑选过好几次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
