INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96016, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96016, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从若干人或事物中选出合适的。", "primary_collocate": null, "pronunciation": "tiāo xuǎn", "ipa": "tʰjɑʊ˥ ɕɥɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "学校从学生中挑选了十个人参加比赛。", "target_word": "挑选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在挑选合适的人做经理。", "target_word": "挑选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师从我们班挑选了三个同学去唱歌。", "target_word": "挑选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练挑选队员的时候很认真。", "target_word": "挑选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们要从五个办法里挑选一个最好的。", "target_word": "挑选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理挑选了两位新同事参加会议。", "target_word": "挑选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，他们挑选出了最好的作品。", "target_word": "挑选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂挑选过很多工人，才找到他。", "target_word": "挑选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要认真挑选合适的人去做这件事。", "target_word": "挑选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从很多照片里挑选了一张最好的。", "target_word": "挑选", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "挑选了", "label": "体标：了"}, {"form": "挑选过", "label": "体标：过"}, {"form": "挑选出", "label": "复合词"}], "register": "中性", "sense_fingerprint": "挑选：从若干人或事物中选出合适的人选或方案", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b21d38-673e-4382-b312-55fb37567b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96016, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "购买", "is_correct": false, "explanation": "搭配：人不能被“购买”，“购买了十个人”不成立。"}, {"text": "测量", "is_correct": false, "explanation": "语义：“测量”的对象是身高、体重等数值，句子说的是选人参赛。"}, {"text": "挑选", "is_correct": true, "explanation": "正确：“挑选”指从许多人中选出合适的，与“学生中”“十个人”相符。"}, {"text": "拍卖", "is_correct": false, "explanation": "语义：学校不会把学生拍卖，与比赛选人的语境无关。"}], "explanations": {"购买": "搭配：人不能被“购买”，“购买了十个人”不成立。", "测量": "语义：“测量”的对象是身高、体重等数值，句子说的是选人参赛。", "挑选": "正确：“挑选”指从许多人中选出合适的，与“学生中”“十个人”相符。", "拍卖": "语义：学校不会把学生拍卖，与比赛选人的语境无关。"}, "sentence_index": 0, "correct_answer": "挑选"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他挑选了一场大雨，淋得全身都湿了。", "explanation": "这里应该用〈遇到〉。挑选指从若干人或事物中选出合适的，遇到大雨要说遇到。"}, {"text": "这个问题很难，我挑选了很久才解开。", "explanation": "这里应该用〈想〉。挑选指从若干人或事物中选出合适的，思考问题要说想，不能挑选。"}, {"text": "我们挑选了去年的收入。", "explanation": "这里应该用〈统计〉。挑选指从许多中选出合适的，收入要统计，不能挑选。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96016, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扔", "is_correct": false, "explanation": "语义：比赛不会把最好的作品扔掉，与“这次比赛”的语境相反。"}, {"text": "挑选", "is_correct": true, "explanation": "正确：“挑选出”指从许多作品中选出最好的，与比赛的评选语境相符。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”不用于作品，“踢出最好的作品”不成立。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕坏最好的作品与比赛的评选语境相反。"}], "explanations": {"扔": "语义：比赛不会把最好的作品扔掉，与“这次比赛”的语境相反。", "挑选": "正确：“挑选出”指从许多作品中选出最好的，与比赛的评选语境相符。", "踢": "搭配：“踢”不用于作品，“踢出最好的作品”不成立。", "撕": "语义：撕坏最好的作品与比赛的评选语境相反。"}, "sentence_index": 6, "correct_answer": "挑选"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他挑选了全部责任。", "explanation": "这里应该用〈承担〉。挑选指从许多中选出，责任要承担，不能挑选。"}, {"text": "医生挑选了病人的健康。", "explanation": "这里应该用〈恢复〉。挑选指从许多中选出，健康要恢复，不能挑选。"}, {"text": "我挑选了他的道歉。", "explanation": "这里应该用〈接受〉。挑选指从许多中选出，道歉要接受，不能挑选。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96016, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司从应聘者中挑选着三个人。", "corrected_sentence": "公司从应聘者中挑选了三个人。", "error_description": "体标错误：挑选是已完成的一次性选择，应用“了”（挑选了三个人）；“着”表示持续的状态，不能用于这种动作。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96016, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她从很多照片里挑选了出一张最好的。", "corrected_sentence": "她从很多照片里挑选出了一张最好的。", "error_description": "结果补语“出”要紧跟在动词后面，应说“挑选出了”，“挑选了出”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
