INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96017, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "挣扎是被抓住了，用力想动开。", "primary_collocate": null, "pronunciation": "zhēng zhá", "ipa": "ʈʂɤŋ˥ ʈʂa˧˥", "syllable_count": 2, "sentences": [{"text": "鱼在网里拼命挣扎。", "target_word": "挣扎", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小鸟在他手里挣扎。", "target_word": "挣扎", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小偷被抓住后，不停地挣扎。", "target_word": "挣扎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用力挣扎，想从绳子里逃出来。", "target_word": "挣扎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只兔子在笼子里挣扎了半天。", "target_word": "挣扎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子被妈妈抱着，一边哭一边挣扎。", "target_word": "挣扎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫被门夹住了，一直在挣扎。", "target_word": "挣扎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他被人拉住了胳膊，挣扎着想跑开。", "target_word": "挣扎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察把他按在地上，他还在挣扎。", "target_word": "挣扎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚂蚁掉进水里，挣扎了一会儿才爬出来。", "target_word": "挣扎", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "挣扎着", "label": "体标"}, {"form": "挣扎了", "label": "体标"}, {"form": "挣扎过", "label": "体标"}, {"form": "拼命挣扎", "label": "复合"}], "register": "中性", "sense_fingerprint": "被抓住或困住时身体用力扭动想挣脱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea0b2d16-fd3c-4652-81a5-d83fbc5fa0b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96017, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挣扎", "is_correct": true, "explanation": "挣扎在此指鱼在网中用力扭动，与“拼命”的语境相符。"}, {"text": "歌唱", "is_correct": false, "explanation": "语义：鱼被困在网里时不会“歌唱”，与“拼命”挣脱的情境冲突。"}, {"text": "思考", "is_correct": false, "explanation": "语义：“思考”不是身体动作，与网中被困、用力扭动的情境不合。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：被困在网里的鱼不会“赞美”，与“拼命”挣脱的情境冲突。"}], "explanations": {"挣扎": "挣扎在此指鱼在网中用力扭动，与“拼命”的语境相符。", "歌唱": "语义：鱼被困在网里时不会“歌唱”，与“拼命”挣脱的情境冲突。", "思考": "语义：“思考”不是身体动作，与网中被困、用力扭动的情境不合。", "赞美": "语义：被困在网里的鱼不会“赞美”，与“拼命”挣脱的情境冲突。"}, "sentence_index": 0, "correct_answer": "挣扎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在工厂里干活，每月挣扎的钱都寄给了父母。", "explanation": "这里应该用〈挣〉。挣扎表示被抓住后用力挣开，或在困境中苦撑，不修饰表示收入的钱；“挣的钱”要说挣。"}, {"text": "他被人轻轻拉住，却挣扎着轻松地把手伸了过去。", "explanation": "这里应删去〈挣扎着〉。挣扎含有被束缚后用力挣开之意，与“轻松地”矛盾；轻松伸手不用挣扎。"}, {"text": "他一下子挣扎到了楼下，毫不费力。", "explanation": "这里应该用〈跑〉。挣扎含有被束缚后用力挣开之意，与“毫不费力”矛盾；轻松跑到楼下不用挣扎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96017, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挣扎", "is_correct": true, "explanation": "挣扎在此指小猫被夹后身体用力扭动，与“被门夹住了”相符。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：被门夹住的小猫处于痛苦之中，不会“微笑”，与情境冲突。"}, {"text": "散步", "is_correct": false, "explanation": "语义：被门夹住的小猫不能“散步”，与“被门夹住了”的状态矛盾。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：小猫不会“翻译”，与“被门夹住”的情境毫不相关，句意荒诞。"}], "explanations": {"挣扎": "挣扎在此指小猫被夹后身体用力扭动，与“被门夹住了”相符。", "微笑": "语义：被门夹住的小猫处于痛苦之中，不会“微笑”，与情境冲突。", "散步": "语义：被门夹住的小猫不能“散步”，与“被门夹住了”的状态矛盾。", "翻译": "语义：小猫不会“翻译”，与“被门夹住”的情境毫不相关，句意荒诞。"}, "sentence_index": 6, "correct_answer": "挣扎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他被警察抓住后，舒舒服服地挣扎着喝茶。", "explanation": "这里应该用〈坐〉。挣扎含有被抓住后用力想挣开之意，与“舒舒服服”矛盾；舒服地坐着喝茶不用挣扎。"}, {"text": "小狗被人抱在怀里，安静地挣扎了很久才睡着。", "explanation": "这里应该用〈趴〉。挣扎含有用力想挣开之意，与“安静地”矛盾；安静地趴着不用挣扎。"}, {"text": "他在床上挣扎着做了一个好梦。", "explanation": "这里应删去〈挣扎着〉。挣扎含有被束缚后用力挣开之意，与安稳地做“好梦”矛盾；安睡做梦不用挣扎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96017, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他被绳子捆住，拼命把挣扎，想要脱身。", "corrected_sentence": "他被绳子捆住，拼命挣扎，想要脱身。", "error_description": "错误：“拼命把挣扎”；正确：“拼命挣扎”。“挣扎”是不及物动词，不能带“把”字，句中没有可被处置的对象。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96017, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小鸟在笼子里把挣扎了很久，终于飞了出来。", "corrected_sentence": "小鸟在笼子里挣扎了很久，终于飞了出来。", "error_description": "错误：“把挣扎”；正确：“挣扎”是不及物动词，不能放在“把”字结构里，应说“在笼子里挣扎了很久”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
