INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96018, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用力支撑或摆脱；在困难中努力支持。", "primary_collocate": null, "pronunciation": "zhēng zhá", "ipa": "ʈʂɤŋ˥ ʈʂa˧˥", "syllable_count": 2, "sentences": [{"text": "他在贫困中挣扎了很多年。", "target_word": "挣扎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病人在生死线上挣扎。", "target_word": "挣扎", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司在破产边缘挣扎着。", "target_word": "挣扎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在痛苦中挣扎，不知道怎么办。", "target_word": "挣扎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小店在激烈的竞争中艰难地挣扎。", "target_word": "挣扎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直在失败和希望之间挣扎。", "target_word": "挣扎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人为了生活每天都在挣扎。", "target_word": "挣扎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们挣扎着活下去，终于等到了春天。", "target_word": "挣扎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想放弃，又不甘心，还在困境中苦苦挣扎。", "target_word": "挣扎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人在病床上挣扎过很长时间。", "target_word": "挣扎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "挣扎着", "label": "体标"}, {"form": "挣扎了", "label": "体标"}, {"form": "挣扎过", "label": "体标"}, {"form": "垂死挣扎", "label": "复合"}], "register": "中性", "sense_fingerprint": "在困境、痛苦或危险中苦苦支撑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea0b2d16-fd3c-4652-81a5-d83fbc5fa0b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96018, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挣扎", "is_correct": true, "explanation": "挣扎在此表示在贫困中苦苦支撑，与“贫困”的语境相符。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“贫困”与“享受”意思相反，句子说的是生活艰难，不是享福。"}, {"text": "发财", "is_correct": false, "explanation": "语义：“发财”与“贫困”的情况冲突，前后语境不合。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与“贫困”的境况无关，句意不通。"}], "explanations": {"挣扎": "挣扎在此表示在贫困中苦苦支撑，与“贫困”的语境相符。", "享受": "语义：“贫困”与“享受”意思相反，句子说的是生活艰难，不是享福。", "发财": "语义：“发财”与“贫困”的情况冲突，前后语境不合。", "游泳": "语义：“游泳”与“贫困”的境况无关，句意不通。"}, "sentence_index": 0, "correct_answer": "挣扎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他家很有钱，每天都在富裕中挣扎。", "explanation": "这里应该用〈享受〉。挣扎指在困境中苦苦支撑，与“很有钱、富裕”矛盾；富裕的生活不用挣扎。"}, {"text": "他每天在工厂里干活，每月挣扎的钱都寄回了老家。", "explanation": "这里应该用〈挣〉。挣扎表示用力摆脱或在困境中苦撑，不修饰表示收入的钱；“挣的钱”要说挣。"}, {"text": "他一下子挣扎到了终点，毫不费力。", "explanation": "这里应该用〈跑〉。挣扎含有艰难用力之意，与“毫不费力”矛盾；轻松跑到终点不用挣扎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96018, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挣扎", "is_correct": true, "explanation": "挣扎在此表示为生计苦苦奔波，与“为了生活”相符。"}, {"text": "休息", "is_correct": false, "explanation": "语义：“为了生活”指谋生奔波，句子说的是每天为生计忙碌，不是休息。"}, {"text": "玩耍", "is_correct": false, "explanation": "语义：“为了生活”的目的与“玩耍”无关，句子说的是谋生的辛苦。"}, {"text": "游览", "is_correct": false, "explanation": "语义：游览是休闲活动，与“为了生活”的谋生目的相悖。"}], "explanations": {"挣扎": "挣扎在此表示为生计苦苦奔波，与“为了生活”相符。", "休息": "语义：“为了生活”指谋生奔波，句子说的是每天为生计忙碌，不是休息。", "玩耍": "语义：“为了生活”的目的与“玩耍”无关，句子说的是谋生的辛苦。", "游览": "语义：游览是休闲活动，与“为了生活”的谋生目的相悖。"}, "sentence_index": 6, "correct_answer": "挣扎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在沙发上悠闲地挣扎着，电视剧播完了。", "explanation": "这里应该用〈等待〉。挣扎含有艰难用力之意，与“悠闲”矛盾；悠闲地等待不用挣扎。"}, {"text": "他在城里打工，轻轻松松就挣扎出了学费。", "explanation": "这里应该用〈赚〉。挣扎含有艰难用力之意，与“轻轻松松”矛盾；轻松赚到学费不用挣扎。"}, {"text": "周末他在家里挣扎着睡了个懒觉，十分惬意。", "explanation": "这里应删去〈挣扎着〉。挣扎含有在困境中苦撑之意，与“睡懒觉、十分惬意”矛盾；悠闲睡懒觉不用挣扎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司在困难中把挣扎着，终于撑了过来。", "corrected_sentence": "公司在困难中挣扎着，终于撑了过来。", "error_description": "错误：“把挣扎着”；正确：“挣扎着”。“挣扎”是不及物动词，不能用“把”字结构处置，应去掉“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在困境中挣扎很辛苦。", "corrected_sentence": "他在困境中挣扎得很辛苦。", "error_description": "错误：补语前缺少“得”；正确：“挣扎得很辛苦”。“很辛苦”作程度补语，需用“得”连接动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
