INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96019, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "撸是把袖子等向上卷起，比如撸起袖子。", "primary_collocate": null, "pronunciation": "lū", "ipa": "lu˥", "syllable_count": 1, "sentences": [{"text": "他撸起袖子，开始洗碗。", "target_word": "撸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气太热，我把袖子撸到了胳膊上。", "target_word": "撸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她撸了撸袖子，准备干活。", "target_word": "撸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸撸起袖子修自行车。", "target_word": "撸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们撸着袖子在搬东西。", "target_word": "撸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先撸起裤腿，再走进河里。", "target_word": "撸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈撸起袖子和面。", "target_word": "撸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你把袖子撸上去，别弄湿了。", "target_word": "撸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他撸起袖子，对大家说：“开始吧！”", "target_word": "撸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明撸起袖子，准备打扫房间。", "target_word": "撸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "撸了", "label": "体标"}, {"form": "撸着", "label": "体标"}, {"form": "撸过", "label": "体标"}, {"form": "擼", "label": "繁体"}], "register": "口语", "sense_fingerprint": "把袖子等向上卷起，撸起袖子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddc45bb0-7584-458b-8100-4763b256d8ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96019, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "撸", "is_correct": true, "explanation": "正确。撸（lū，第一声）指把袖子等向上卷起，如撸起袖子。"}, {"text": "炉", "is_correct": false, "explanation": "lú（第二声）与 lū（第一声）声调不同，意思是炉子。"}, {"text": "路", "is_correct": false, "explanation": "lù（第四声）与 lū（第一声）声调不同，意思是道路。"}, {"text": "搂", "is_correct": false, "explanation": "lōu 与 lū 韵母不同（ou 与 u），意思是用手臂抱。"}], "explanations": {"撸": "正确。撸（lū，第一声）指把袖子等向上卷起，如撸起袖子。", "炉": "lú（第二声）与 lū（第一声）声调不同，意思是炉子。", "路": "lù（第四声）与 lū（第一声）声调不同，意思是道路。", "搂": "lōu 与 lū 韵母不同（ou 与 u），意思是用手臂抱。"}, "sentence_index": null, "correct_answer": "撸"}, "level_3": {"options": [{"text": "撸", "is_correct": true, "explanation": "正确。“撸起”指把袖子等向上卷起，符合“撸起袖子”的说法。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕是扯裂，袖子会被撕破，与卷起袖子的意思不符。"}, {"text": "剪", "is_correct": false, "explanation": "语义：剪是剪断，不是把袖子卷起或捋起。"}, {"text": "扯", "is_correct": false, "explanation": "搭配：“扯”一般说扯起来或扯下，不说扯起袖子，与“撸起袖子”的习惯说法不符。"}], "explanations": {"撸": "正确。“撸起”指把袖子等向上卷起，符合“撸起袖子”的说法。", "撕": "语义：撕是扯裂，袖子会被撕破，与卷起袖子的意思不符。", "剪": "语义：剪是剪断，不是把袖子卷起或捋起。", "扯": "搭配：“扯”一般说扯起来或扯下，不说扯起袖子，与“撸起袖子”的习惯说法不符。"}, "sentence_index": 0, "correct_answer": "撸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用力撸开门，走了出去。", "explanation": "这里应该用〈推〉。撸指把袖子等向上卷起，不用于推门。"}, {"text": "他用抹布撸了一下桌子，桌面很干净。", "explanation": "这里应该用〈擦〉。撸指把袖子等向上卷起，不用于用布擦拭桌面。"}, {"text": "他从口袋里撸出一把硬币。", "explanation": "这里应该用〈掏〉。撸指把袖子等向上卷起，不能用于从口袋里掏东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96019, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "撸", "is_correct": true, "explanation": "正确。撸（lū，第一声）指把袖子等向上卷起，如撸起袖子。"}, {"text": "鲁", "is_correct": false, "explanation": "lǔ（第三声）与 lū（第一声）声调不同，意思是鲁地或鲁莽。"}, {"text": "露", "is_correct": false, "explanation": "lù（第四声）与 lū（第一声）声调不同，意思是露水。"}, {"text": "芦", "is_correct": false, "explanation": "lú（第二声）与 lū（第一声）声调不同，意思是芦苇。"}], "explanations": {"撸": "正确。撸（lū，第一声）指把袖子等向上卷起，如撸起袖子。", "鲁": "lǔ（第三声）与 lū（第一声）声调不同，意思是鲁地或鲁莽。", "露": "lù（第四声）与 lū（第一声）声调不同，意思是露水。", "芦": "lú（第二声）与 lū（第一声）声调不同，意思是芦苇。"}, "sentence_index": null, "correct_answer": "撸"}, "level_3": {"options": [{"text": "撸", "is_correct": true, "explanation": "正确。“撸起”指把袖子等向上卷起，符合“撸起袖子和面”的句意。"}, {"text": "掰", "is_correct": false, "explanation": "语义：掰是折断或分开，与卷起袖子的动作无关。"}, {"text": "捆", "is_correct": false, "explanation": "搭配：“捆”一般说捆住、捆起来，不说捆袖子，与“撸起袖子”的习惯说法不符。"}, {"text": "拧", "is_correct": false, "explanation": "语义：拧是转动或绞干，与把袖子卷起的意思不符。"}], "explanations": {"撸": "正确。“撸起”指把袖子等向上卷起，符合“撸起袖子和面”的句意。", "掰": "语义：掰是折断或分开，与卷起袖子的动作无关。", "捆": "搭配：“捆”一般说捆住、捆起来，不说捆袖子，与“撸起袖子”的习惯说法不符。", "拧": "语义：拧是转动或绞干，与把袖子卷起的意思不符。"}, "sentence_index": 6, "correct_answer": "撸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他撸起书包，准备上学。", "explanation": "这里应该用〈背〉：背起书包。撸起用于袖子、裤腿等衣物，不能用于书包。"}, {"text": "奶奶撸起茶杯，准备喝水。", "explanation": "这里应该用〈端〉：端起茶杯。撸起用于袖子、裤腿等衣物，不能用于茶杯。"}, {"text": "姐姐撸起帽子，走出门去。", "explanation": "这里应该用〈戴〉：戴上帽子。撸起用于袖子、裤腿等衣物，不能用于帽子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96019, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他先把袖子撸，再去洗碗。", "corrected_sentence": "他先把袖子撸上去，再去洗碗。", "error_description": "错误：把字句中动词“撸”后缺少补语。正确：“把袖子撸上去”，把字句的动词后须带补语，“上去”表示袖子向上卷起。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96019, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把袖子撸，准备洗菜。", "corrected_sentence": "他把袖子撸上去，准备洗菜。", "error_description": "错误：把字句中动词“撸”后缺少补语。正确：“把袖子撸上去”，把字句的动词后须带补语，“上去”表示袖子向上卷起。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
