INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96023, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "春秋是春天和秋天。", "primary_collocate": null, "pronunciation": "chūn qiū", "ipa": "ʈʂʰuən˥ tɕʰiou˥", "syllable_count": 2, "sentences": [{"text": "这里春秋两季天气很好。", "target_word": "春秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的花园春秋都很漂亮。", "target_word": "春秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校春秋各开一次运动会。", "target_word": "春秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京的春秋很短，冬夏很长。", "target_word": "春秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服春秋穿正合适。", "target_word": "春秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春秋是旅游的好时候。", "target_word": "春秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷春秋都爱去山里走走。", "target_word": "春秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个景区春秋两季游客很多。", "target_word": "春秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春秋两季我常去公园跑步。", "target_word": "春秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种草药春秋采最好。", "target_word": "春秋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "指春天和秋天两个季节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53ba7404-397a-4364-acdd-387f7357410c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96023, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "春秋", "is_correct": true, "explanation": "“春秋”指春天和秋天，与“两季”相合，符合句意。"}, {"text": "四季", "is_correct": false, "explanation": "语义：“四季”指四个季节，与“两季”的数量相矛盾。"}, {"text": "冬天", "is_correct": false, "explanation": "搭配：“冬天”只是一个季节，不能与“两季”并列计数。"}, {"text": "中秋", "is_correct": false, "explanation": "语义：“中秋”是节日，不是季节，不能与“两季”搭配。"}], "explanations": {"春秋": "“春秋”指春天和秋天，与“两季”相合，符合句意。", "四季": "语义：“四季”指四个季节，与“两季”的数量相矛盾。", "冬天": "搭配：“冬天”只是一个季节，不能与“两季”并列计数。", "中秋": "语义：“中秋”是节日，不是季节，不能与“两季”搭配。"}, "sentence_index": 0, "correct_answer": "春秋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里春秋适合滑雪。", "explanation": "这里应该用〈冬季〉。“春秋”只指春天和秋天，不含冬季；滑雪要在冬季进行，不能用“春秋”来指。"}, {"text": "我们春秋两季一起去海边避暑。", "explanation": "这里应该用〈夏天〉。“避暑”指躲避夏季的炎热，与“春秋”所指的两季不符。"}, {"text": "春秋两季，我们都放暑假。", "explanation": "这里应该用〈夏天〉。“春秋”不含夏季，放暑假指的是夏天，不能用“春秋”来指。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96023, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "春秋", "is_correct": true, "explanation": "“春秋”指春天和秋天，“都”表示两个季节都去，符合句意。"}, {"text": "春风", "is_correct": false, "explanation": "语义：“春风”是事物而非时段，“爷爷春风都爱去山里走走”不成立。"}, {"text": "秋叶", "is_correct": false, "explanation": "语义：“秋叶”是事物而非时段，不能与“都”搭配表示一段时间。"}, {"text": "晚饭", "is_correct": false, "explanation": "语义：“晚饭”是一餐，不是时段，不能说“爷爷晚饭都爱去山里走走”。"}], "explanations": {"春秋": "“春秋”指春天和秋天，“都”表示两个季节都去，符合句意。", "春风": "语义：“春风”是事物而非时段，“爷爷春风都爱去山里走走”不成立。", "秋叶": "语义：“秋叶”是事物而非时段，不能与“都”搭配表示一段时间。", "晚饭": "语义：“晚饭”是一餐，不是时段，不能说“爷爷晚饭都爱去山里走走”。"}, "sentence_index": 6, "correct_answer": "春秋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春秋到了，湖面都结了厚厚的冰。", "explanation": "这里应该用〈冬天〉。“春秋”只指春天和秋天；湖面结厚冰是冬天的事，不能用“春秋”来指。"}, {"text": "这个小镇春秋会下很大的雪。", "explanation": "这里应该用〈冬天〉。“春秋”只指春天和秋天，不含冬天；下大雪是冬天的事，不能用“春秋”来指。"}, {"text": "春秋到了，树上的知了叫个不停。", "explanation": "这里应该用〈夏天〉。“春秋”不含夏季，知了叫得最响的是夏天，不能用“春秋”来指。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96023, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里春秋两个季都很舒服。", "corrected_sentence": "这里春秋两季都很舒服。", "error_description": "错误：“两个季”。“季”作量词前不加“个”，应说“两季”，“春秋两季”是固定说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96023, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春秋三季都是散步的好时候。", "corrected_sentence": "春秋两季都是散步的好时候。", "error_description": "错误：“三季”。“春秋”只指春天和秋天两个季节，应说“春秋两季”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
