INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96024, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96024, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指年岁、岁月。", "primary_collocate": null, "pronunciation": "chūn qiū", "ipa": "ʈʂʰuən˥ tɕʰiou˥", "syllable_count": 2, "sentences": [{"text": "老人家春秋已高，身体还很好。", "target_word": "春秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这里工作了几十个春秋。", "target_word": "春秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过多少春秋，这座老桥还在这里。", "target_word": "春秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为学校付出了二十个春秋。", "target_word": "春秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几度春秋，老朋友再没见面。", "target_word": "春秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师春秋正盛，还能工作很多年。", "target_word": "春秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山里度过了五十个春秋。", "target_word": "春秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春秋几十载，他一直没有离开家乡。", "target_word": "春秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们已经相识三十个春秋。", "target_word": "春秋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "岁月匆匆，不知不觉又过了一个春秋。", "target_word": "春秋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "借春去秋来指年岁、岁月", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53ba7404-397a-4364-acdd-387f7357410c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96024, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "春秋", "is_correct": true, "explanation": "“春秋”指年岁，“春秋已高”是对老人年纪的说法，符合句意。"}, {"text": "年轮", "is_correct": false, "explanation": "语义：“年轮”指树木的生长纹路，不指人的年纪。"}, {"text": "年代", "is_correct": false, "explanation": "语义：“年代”指一段历史时期，不能用来形容人的年纪。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：形容年纪大说“寿命长”，不说“寿命已高”。"}], "explanations": {"春秋": "“春秋”指年岁，“春秋已高”是对老人年纪的说法，符合句意。", "年轮": "语义：“年轮”指树木的生长纹路，不指人的年纪。", "年代": "语义：“年代”指一段历史时期，不能用来形容人的年纪。", "寿命": "搭配：形容年纪大说“寿命长”，不说“寿命已高”。"}, "sentence_index": 0, "correct_answer": "春秋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她为学校付出了二十个小时的春秋。", "explanation": "这里应该用〈工夫〉。“春秋”指年岁，只用于几年、几十年等长时间，不能用来计算“二十个小时”这样的短时间。"}, {"text": "她每天都为学校付出春秋。", "explanation": "这里应该用〈几年〉。“春秋”表示年岁，只用于几年、几十年这样的长时间，不能用来说“每天”。"}, {"text": "她为学校付出的春秋，只用了一个下午。", "explanation": "这里应该用〈时光〉。“春秋”指数年、数十年，不能说只用一个下午这样的短时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96024, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "春秋", "is_correct": true, "explanation": "“春秋”指多年，与“五十个”相合，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是物体，不能被“度过”，不能说“度过了五十个石头”。"}, {"text": "饭菜", "is_correct": false, "explanation": "配价：“度过”要求时间作宾语，“饭菜”不是时间，不能说“度过了五十个饭菜”。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“度过”要求时间作宾语，“窗户”是物体，不能说“度过了五十个窗户”。"}], "explanations": {"春秋": "“春秋”指多年，与“五十个”相合，符合句意。", "石头": "语义：“石头”是物体，不能被“度过”，不能说“度过了五十个石头”。", "饭菜": "配价：“度过”要求时间作宾语，“饭菜”不是时间，不能说“度过了五十个饭菜”。", "窗户": "配价：“度过”要求时间作宾语，“窗户”是物体，不能说“度过了五十个窗户”。"}, "sentence_index": 6, "correct_answer": "春秋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明天就是我的春秋。", "explanation": "这里应该用〈生日〉。“春秋”指年岁、岁月，不是某一天，不能用来说“明天就是”。"}, {"text": "岁月匆匆，一年里有四个春秋。", "explanation": "这里应该用〈季节〉。把“春秋”的年岁义误用来数一年里的四季；“春秋”指多年，四季应说“季节”。"}, {"text": "他午饭吃了一个春秋。", "explanation": "这里应该用〈一顿〉。“春秋”指数年、数十年，不能用来计算一顿饭这样的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的父母已经生活了四十只春秋。", "corrected_sentence": "我的父母已经生活了四十个春秋。", "error_description": "错误：量词“只”。“春秋”表示年岁时量词用“个”，应说“四十个春秋”，“只”用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96024, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父度过了八十的春秋，身体依然硬朗。", "corrected_sentence": "祖父度过了八十个春秋，身体依然硬朗。", "error_description": "错误：“八十的春秋”。数量短语修饰“春秋”时要用量词“个”，应说“八十个春秋”，不说“八十的春秋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
