INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96025, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对某一范围内的全部对象逐一进行调查，一个也不漏。", "primary_collocate": null, "pronunciation": "pǔ chá", "ipa": "pʰu˨˩˧ ʈʂʰa˧˥", "syllable_count": 2, "sentences": [{"text": "老师普查了全班同学的身高。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生普查了村里每一个人的血压。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们挨家挨户地普查，一家也不漏。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要普查学生的视力。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月，社区普查了所有老人的健康状况。", "target_word": "普查", "complexity_tier": "T3", "furigana": "zhè ge yuè, shè qū pǔ chá le suǒ yǒu lǎo rén de jiàn kāng zhuàng kuàng.", "sentence_source": "generated"}, {"text": "社区把小区每户的用水情况普查了一遍。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要普查每家有几口人。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员正在普查街上的商店。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司普查了全体员工的学历情况。", "target_word": "普查", "complexity_tier": "T3", "furigana": "gōng sī pǔ chá le quán tǐ yuán gōng de xué lì qíng kuàng.", "sentence_source": "generated"}, {"text": "这次普查，全市的学校一所也没漏。", "target_word": "普查", "complexity_tier": "T3", "furigana": "zhè cì pǔ chá, quán shì de xué xiào yì suǒ yě méi lòu.", "sentence_source": "generated"}], "morphological_forms": [{"form": "普查了", "label": "体标"}, {"form": "普查过", "label": "体标"}, {"form": "人口普查", "label": "复合"}], "register": "书面", "sense_fingerprint": "对全部对象逐一调查，一个不漏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dd71c1-9209-4d12-a308-62a2880ffae2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96025, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "普查", "is_correct": true, "explanation": "普查：逐个调查全部对象，与「全班同学的身高」相符。"}, {"text": "抽查", "is_correct": false, "explanation": "语义：「抽查」只检查一部分，与「全班同学」的整体范围相矛盾。"}, {"text": "批改", "is_correct": false, "explanation": "搭配：「批改」用于作业、试卷，不能用于身高。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：「打印」用于文件、材料，不能说打印身高。"}], "explanations": {"普查": "普查：逐个调查全部对象，与「全班同学的身高」相符。", "抽查": "语义：「抽查」只检查一部分，与「全班同学」的整体范围相矛盾。", "批改": "搭配：「批改」用于作业、试卷，不能用于身高。", "打印": "搭配：「打印」用于文件、材料，不能说打印身高。"}, "sentence_index": 0, "correct_answer": "普查"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生普查了他的视力。", "explanation": "这里应该用〈检查〉。普查指对大批对象逐一调查，只针对一个人时用〈检查〉。"}, {"text": "我们普查了一部分学生。", "explanation": "这里应该用〈抽查〉。普查要求对全部对象逐一调查，只查一部分时用〈抽查〉。"}, {"text": "我普查了他的性格。", "explanation": "这里应该用〈了解〉。普查用于可以统计的人口、数量、状况等，性格不能普查，应用〈了解〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96025, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "普查", "is_correct": true, "explanation": "普查：对每家逐一调查，与「每家有几口人」相符。"}, {"text": "抽样", "is_correct": false, "explanation": "语义：「抽样」只选取部分样本，与「每家」的全面范围相矛盾。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：「测量」用于长度、重量等，不能用于统计人口。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：「修理」针对器物，不能用于人口。"}], "explanations": {"普查": "普查：对每家逐一调查，与「每家有几口人」相符。", "抽样": "语义：「抽样」只选取部分样本，与「每家」的全面范围相矛盾。", "测量": "搭配：「测量」用于长度、重量等，不能用于统计人口。", "修理": "搭配：「修理」针对器物，不能用于人口。"}, "sentence_index": 6, "correct_answer": "普查"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈普查了这本作业。", "explanation": "这里应该用〈查看〉。普查针对大批对象，只看一本作业时用〈查看〉。"}, {"text": "妈妈普查了儿子的心情。", "explanation": "这里应该用〈感受〉。普查用于可统计的对象，心情不能普查，应用〈感受〉。"}, {"text": "他普查了桌上的一张照片。", "explanation": "这里应该用〈端详〉。普查指对大量对象逐一调查，只看一张照片时应用〈端详〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96025, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教育局人口普查了全县的中小学。", "corrected_sentence": "教育局普查了全县的中小学。", "error_description": "错误：在动词「普查」前加了「人口」，写成「人口普查」，这是一个名词，指人口调查。正确：「普查」是动词，直接带宾语「全县的中小学」，不能加「人口」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96025, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工作人员普查开了全城的街道。", "corrected_sentence": "工作人员普查完了全城的街道。", "error_description": "错误：结果补语「开」与「普查」搭配不当，「开」表示分离或打开，不表示调查结束。正确：「普查完了」，用「完」表示调查结束。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
