INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96026, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "普遍地调查，对全部对象逐一调查。", "primary_collocate": null, "pronunciation": "pǔ chá", "ipa": "pʰu˨˩˧ ʈʂʰa˧˥", "syllable_count": 2, "sentences": [{"text": "国家每十年普查一次人口。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个县普查了所有的农田。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院普查了全市孩子的牙齿。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了知道有多少人，政府决定普查全市。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里准备普查全部的老房子。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在普查这座山里的鸟。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校普查过一次，全校的学生都量了体重。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要普查全城的树，得花很多时间。", "target_word": "普查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校普查了全校学生的近视情况。", "target_word": "普查", "complexity_tier": "T3", "furigana": "xué xiào pǔ chá le quán xiào xué shēng de jìn shì qíng kuàng.", "sentence_source": "generated"}, {"text": "工人们普查了全市的每一座桥梁。", "target_word": "普查", "complexity_tier": "T3", "furigana": "gōng rén men pǔ chá le quán shì de měi yí zuò qiáo liáng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "普查了", "label": "体标"}, {"form": "普查过", "label": "体标"}, {"form": "人口普查", "label": "复合"}], "register": "书面", "sense_fingerprint": "对全部对象普遍调查", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dd71c1-9209-4d12-a308-62a2880ffae2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96026, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "普查", "is_correct": true, "explanation": "普查：对全部对象逐一调查，与「国家每十年……一次人口」相符。"}, {"text": "粉刷", "is_correct": false, "explanation": "搭配：「粉刷」用于墙面等，不能用于人口。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：「浇灌」用于植物、庄稼，不能用于人口。"}, {"text": "消灭", "is_correct": false, "explanation": "语义：「消灭」指彻底除掉，与「每十年调查一次」的目的相反。"}], "explanations": {"普查": "普查：对全部对象逐一调查，与「国家每十年……一次人口」相符。", "粉刷": "搭配：「粉刷」用于墙面等，不能用于人口。", "浇灌": "搭配：「浇灌」用于植物、庄稼，不能用于人口。", "消灭": "语义：「消灭」指彻底除掉，与「每十年调查一次」的目的相反。"}, "sentence_index": 0, "correct_answer": "普查"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "护士普查了这个病人的心脏。", "explanation": "这里应该用〈检查〉。普查指对大批对象逐一调查，只针对一个病人时应用〈检查〉。"}, {"text": "老师普查了一部分学生的作业。", "explanation": "这里应该用〈抽查〉。普查要求对全部对象逐一调查，只查一部分时应用〈抽查〉。"}, {"text": "我认真普查了我的未来。", "explanation": "这里应该用〈思考〉。普查用于可统计的对象，未来不能普查，应用〈思考〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96026, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "普查", "is_correct": true, "explanation": "普查：全校学生逐一参与，与「全校的学生都量了体重」相符。"}, {"text": "抽查", "is_correct": false, "explanation": "语义：「抽查」只检查一部分，与「全校的学生都」相矛盾。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：「洗」用于衣物、身体等，不能用于学校。"}, {"text": "烫", "is_correct": false, "explanation": "搭配：「烫」用于衣服、头发、食物等，不能表示对全校学生进行调查。"}], "explanations": {"普查": "普查：全校学生逐一参与，与「全校的学生都量了体重」相符。", "抽查": "语义：「抽查」只检查一部分，与「全校的学生都」相矛盾。", "洗": "搭配：「洗」用于衣物、身体等，不能用于学校。", "烫": "搭配：「烫」用于衣服、头发、食物等，不能表示对全校学生进行调查。"}, "sentence_index": 6, "correct_answer": "普查"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天都普查我的房间。", "explanation": "这里应该用〈打扫〉。普查针对大批对象逐一调查，一间房不适用「普查」；日常清理应用〈打扫〉。"}, {"text": "我们普查了这场音乐会。", "explanation": "这里应该用〈观看〉。普查针对可统计的对象，音乐会不能普查，应用〈观看〉。"}, {"text": "经理普查了一封信。", "explanation": "这里应该用〈阅读〉。普查指对大批对象逐一调查，只读一封信时应用〈阅读〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96026, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府很普查了全国的土地。", "corrected_sentence": "政府普查了全国的土地。", "error_description": "错误：程度副词「很」修饰动词「普查」。正确：去掉「很」，「普查」是动作动词，不能被程度副词修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96026, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们没普查了全区的每一家药店。", "corrected_sentence": "我们没普查全区的每一家药店。", "error_description": "错误：否定词「没」和完成体「了」同时使用，写成「没普查了」。正确：用「没」否定时，动词后去掉「了」，说「没普查」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96027, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷", "is_correct": true, "explanation": "“冷”与“暖”构成反义，指温度低，让人觉得不舒服，与“不冷”相对。"}, {"text": "远", "is_correct": false, "explanation": "“远”指距离大，与衣物的冷暖无关，不是反义词。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”指速度低，与温度无关，不是“暖”的反义词。"}, {"text": "甜", "is_correct": false, "explanation": "“甜”指味道，与衣物的冷暖无关，不是反义词。"}], "correct_answer": "冷", "explanations": {"冷": "“冷”与“暖”构成反义，指温度低，让人觉得不舒服，与“不冷”相对。", "远": "“远”指距离大，与衣物的冷暖无关，不是反义词。", "慢": "“慢”指速度低，与温度无关，不是“暖”的反义词。", "甜": "“甜”指味道，与衣物的冷暖无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96027, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷", "is_correct": true, "explanation": "“冷”与“暖”构成反义，指温度低，让人觉得不舒服，与“不冷”相对。"}, {"text": "高", "is_correct": false, "explanation": "“高”指高度或程度高，不表示与“暖”相对的感受，不是反义词。"}, {"text": "脆", "is_correct": false, "explanation": "“脆”指食物或材料易断裂，与温度无关，不是反义词。"}, {"text": "硬", "is_correct": false, "explanation": "“硬”指质地不软，与衣物或房间的冷暖无关，不是反义词。"}], "correct_answer": "冷", "explanations": {"冷": "“冷”与“暖”构成反义，指温度低，让人觉得不舒服，与“不冷”相对。", "高": "“高”指高度或程度高，不表示与“暖”相对的感受，不是反义词。", "脆": "“脆”指食物或材料易断裂，与温度无关，不是反义词。", "硬": "“硬”指质地不软，与衣物或房间的冷暖无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96027, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "暖是不冷，让人觉得舒服。", "primary_collocate": null, "pronunciation": "nuǎn", "ipa": "nwan˨˩˦", "syllable_count": 1, "sentences": [{"text": "这件羽绒服又轻又暖。", "target_word": "暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件毛衣很暖，冬天穿正好。", "target_word": "暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被子盖着很暖，我睡得很好。", "target_word": "暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我织了一条很暖的围巾。", "target_word": "暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝了一杯热茶，身上暖了。", "target_word": "暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双袜子很厚，穿着很暖。", "target_word": "暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天坐在火炉旁边，真暖。", "target_word": "暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手很暖，我不觉得冷了。", "target_word": "暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个沙发软软的，坐着又暖又舒服。", "target_word": "暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条毯子很暖，盖着很舒服。", "target_word": "暖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "暖暖的", "label": "重叠"}, {"form": "暖了", "label": "体标"}], "register": "中性", "sense_fingerprint": "衣物、被子、身体感觉不冷而舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddc45bb0-7584-458b-8100-4763b256d8ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96027, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "暖", "is_correct": true, "explanation": "正确。暖（nuǎn，第三声）指不冷、让人觉得舒服。"}, {"text": "软", "is_correct": false, "explanation": "ruǎn 与 nuǎn 开头的辅音不同（r 与 n），意思是柔软。"}, {"text": "管", "is_correct": false, "explanation": "guǎn 与 nuǎn 开头的辅音不同（g 与 n），意思是管子或管理。"}, {"text": "缓", "is_correct": false, "explanation": "huǎn 与 nuǎn 开头的辅音不同（h 与 n），意思是慢、不急。"}], "explanations": {"暖": "正确。暖（nuǎn，第三声）指不冷、让人觉得舒服。", "软": "ruǎn 与 nuǎn 开头的辅音不同（r 与 n），意思是柔软。", "管": "guǎn 与 nuǎn 开头的辅音不同（g 与 n），意思是管子或管理。", "缓": "huǎn 与 nuǎn 开头的辅音不同（h 与 n），意思是慢、不急。"}, "sentence_index": null, "correct_answer": "暖"}, "level_3": {"options": [{"text": "暖", "is_correct": true, "explanation": "正确。“暖”形容羽绒服不冷、保暖，符合句意。"}, {"text": "重", "is_correct": false, "explanation": "语义：“重”与“轻”相反，“又轻又重”自相矛盾，不符合羽绒服的特点。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”形容速度，不能用来形容衣物的轻重或保暖。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：羽绒服一般说“轻”“蓬松”“柔软”，不说“硬”。"}], "explanations": {"暖": "正确。“暖”形容羽绒服不冷、保暖，符合句意。", "重": "语义：“重”与“轻”相反，“又轻又重”自相矛盾，不符合羽绒服的特点。", "快": "语义：“快”形容速度，不能用来形容衣物的轻重或保暖。", "硬": "搭配：羽绒服一般说“轻”“蓬松”“柔软”，不说“硬”。"}, "sentence_index": 0, "correct_answer": "暖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路很暖。", "explanation": "这里应该用〈长〉：路很长。暖形容温度或让人舒服的感觉，不能形容路的长短。"}, {"text": "这个数字很暖。", "explanation": "这里应该用〈大〉：数字很大。暖形容温度或让人舒服的感觉，不能形容数字的大小。"}, {"text": "这里离市区很暖。", "explanation": "这里应该用〈远〉：离市区很远。暖形容温度或让人舒服的感觉，不能形容距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96027, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "暖", "is_correct": true, "explanation": "正确。暖（nuǎn，第三声）指不冷、让人觉得舒服。"}, {"text": "卵", "is_correct": false, "explanation": "luǎn 与 nuǎn 开头的辅音不同（l 与 n），意思是蛋。"}, {"text": "短", "is_correct": false, "explanation": "duǎn 与 nuǎn 开头的辅音不同（d 与 n），意思是长度小。"}, {"text": "馆", "is_correct": false, "explanation": "guǎn 与 nuǎn 开头的辅音不同（g 与 n），意思是场所，如饭馆。"}], "explanations": {"暖": "正确。暖（nuǎn，第三声）指不冷、让人觉得舒服。", "卵": "luǎn 与 nuǎn 开头的辅音不同（l 与 n），意思是蛋。", "短": "duǎn 与 nuǎn 开头的辅音不同（d 与 n），意思是长度小。", "馆": "guǎn 与 nuǎn 开头的辅音不同（g 与 n），意思是场所，如饭馆。"}, "sentence_index": null, "correct_answer": "暖"}, "level_3": {"options": [{"text": "暖", "is_correct": true, "explanation": "正确。“暖”形容坐在火炉旁边的温暖感觉，符合句意。"}, {"text": "冷", "is_correct": false, "explanation": "语义：坐在火炉旁边不会觉得冷，“冷”与句意矛盾。"}, {"text": "凉", "is_correct": false, "explanation": "语义：火炉旁边不会让人觉得凉，“凉”与句意矛盾。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不用来形容身体的温度感觉。"}], "explanations": {"暖": "正确。“暖”形容坐在火炉旁边的温暖感觉，符合句意。", "冷": "语义：坐在火炉旁边不会觉得冷，“冷”与句意矛盾。", "凉": "语义：火炉旁边不会让人觉得凉，“凉”与句意矛盾。", "甜": "搭配：“甜”形容味道，不用来形容身体的温度感觉。"}, "sentence_index": 6, "correct_answer": "暖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书很暖，一共有五百页。", "explanation": "这里应该用〈厚〉：书很厚。暖指不冷、让人舒服，不能形容书的厚薄。"}, {"text": "这块蛋糕的价格很暖。", "explanation": "这里应该用〈贵〉：价格很贵。暖不能形容价格。"}, {"text": "这把刀很暖。", "explanation": "这里应该用〈锋利〉：刀很锋利。暖形容温度或让人舒服的感觉，不能形容刀的锋利程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96027, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我穿上毛衣，身上慢慢暖起去。", "corrected_sentence": "我穿上毛衣，身上慢慢暖起来。", "error_description": "错误：趋向补语“来”误写为“去”（暖起去）；正确应为“暖起来”，“起来”表示身上逐渐变暖，不能用“起去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96027, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这床被子暖很，盖着很舒服。", "corrected_sentence": "这床被子很暖，盖着很舒服。", "error_description": "错误：程度副词“很”放在了形容词“暖”之后（暖很）；正确应为“很暖”，“很”须置于形容词之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96028, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷", "is_correct": true, "explanation": "“冷”与“暖”构成反义，指温度低，与“不冷不热”相对。"}, {"text": "快", "is_correct": false, "explanation": "“快”指速度快，与温度无关，不是“暖”的反义词。"}, {"text": "硬", "is_correct": false, "explanation": "“硬”指质地不软，与天气的冷暖无关，不是反义词。"}, {"text": "甜", "is_correct": false, "explanation": "“甜”指味道，与天气的温度无关，不是反义词。"}], "correct_answer": "冷", "explanations": {"冷": "“冷”与“暖”构成反义，指温度低，与“不冷不热”相对。", "快": "“快”指速度快，与温度无关，不是“暖”的反义词。", "硬": "“硬”指质地不软，与天气的冷暖无关，不是反义词。", "甜": "“甜”指味道，与天气的温度无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96028, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷", "is_correct": true, "explanation": "“冷”与“暖”构成反义，指温度低，与“暖和”相对。"}, {"text": "高", "is_correct": false, "explanation": "“高”指高度或程度高，不表示与“暖”相对的温度感受，不是反义词。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”指速度低，与温度无关，不是“暖”的反义词。"}, {"text": "脆", "is_correct": false, "explanation": "“脆”指食物或材料易断裂，与温度无关，不是反义词。"}], "correct_answer": "冷", "explanations": {"冷": "“冷”与“暖”构成反义，指温度低，与“暖和”相对。", "高": "“高”指高度或程度高，不表示与“暖”相对的温度感受，不是反义词。", "慢": "“慢”指速度低，与温度无关，不是“暖”的反义词。", "脆": "“脆”指食物或材料易断裂，与温度无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96028, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "天气或环境温度适中，不冷不热。", "primary_collocate": null, "pronunciation": "nuǎn", "ipa": "nwan˨˩˦", "syllable_count": 1, "sentences": [{"text": "今天天气很暖，我们去公园玩吧。", "target_word": "暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，天气一天比一天暖。", "target_word": "暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间温度正好，坐在里面很暖。", "target_word": "暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天下了雪，今天却不太暖。", "target_word": "暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十月的南方还很暖，不用穿厚衣服。", "target_word": "暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的冬天不冷，一直很暖。", "target_word": "暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳光照在身上，暖得让人想睡觉。", "target_word": "暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里早上冷，中午才慢慢暖起来。", "target_word": "暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气暖了，花都开了。", "target_word": "暖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南方的冬天比北方暖多了。", "target_word": "暖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "暖暖的", "label": "重叠"}, {"form": "暖了", "label": "体标"}], "register": "中性", "sense_fingerprint": "天气、气温、环境不冷不热，温度适中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddc45bb0-7584-458b-8100-4763b256d8ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96028, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "暖", "is_correct": true, "explanation": "正确。暖（nuǎn，第三声）指温度适中，不冷不热。"}, {"text": "软", "is_correct": false, "explanation": "ruǎn 与 nuǎn 开头的辅音不同（r 与 n），意思是柔软。"}, {"text": "短", "is_correct": false, "explanation": "duǎn 与 nuǎn 开头的辅音不同（d 与 n），意思是长度小。"}, {"text": "缓", "is_correct": false, "explanation": "huǎn 与 nuǎn 开头的辅音不同（h 与 n），意思是慢、不急。"}], "explanations": {"暖": "正确。暖（nuǎn，第三声）指温度适中，不冷不热。", "软": "ruǎn 与 nuǎn 开头的辅音不同（r 与 n），意思是柔软。", "短": "duǎn 与 nuǎn 开头的辅音不同（d 与 n），意思是长度小。", "缓": "huǎn 与 nuǎn 开头的辅音不同（h 与 n），意思是慢、不急。"}, "sentence_index": null, "correct_answer": "暖"}, "level_3": {"options": [{"text": "暖", "is_correct": true, "explanation": "正确。“暖”形容天气不冷不热，符合句意。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”形容味道，不能用来形容天气的冷热。"}, {"text": "贵", "is_correct": false, "explanation": "语义：“贵”形容价格，与天气的温度无关。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：天气一般说“暖”“热”“冷”，不说“硬”。"}], "explanations": {"暖": "正确。“暖”形容天气不冷不热，符合句意。", "甜": "语义：“甜”形容味道，不能用来形容天气的冷热。", "贵": "语义：“贵”形容价格，与天气的温度无关。", "硬": "搭配：天气一般说“暖”“热”“冷”，不说“硬”。"}, "sentence_index": 0, "correct_answer": "暖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的成绩很暖。", "explanation": "这里应该用〈好〉：成绩很好。暖只用于温度或温馨的感受，不能形容成绩。"}, {"text": "他的体重很暖。", "explanation": "这里应该用〈重〉：体重很重。暖只用于温度或温馨的感受，不能形容体重。"}, {"text": "这个西瓜的味道很暖。", "explanation": "这里应该用〈甜〉：味道很甜。暖只用于温度或温馨的感受，不能形容味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96028, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "暖", "is_correct": true, "explanation": "正确。暖（nuǎn，第三声）指温度适中，不冷不热。"}, {"text": "卵", "is_correct": false, "explanation": "luǎn 与 nuǎn 开头的辅音不同（l 与 n），意思是蛋。"}, {"text": "款", "is_correct": false, "explanation": "kuǎn 与 nuǎn 开头的辅音不同（k 与 n），意思是款式或款项。"}, {"text": "馆", "is_correct": false, "explanation": "guǎn 与 nuǎn 开头的辅音不同（g 与 n），意思是场所，如饭馆。"}], "explanations": {"暖": "正确。暖（nuǎn，第三声）指温度适中，不冷不热。", "卵": "luǎn 与 nuǎn 开头的辅音不同（l 与 n），意思是蛋。", "款": "kuǎn 与 nuǎn 开头的辅音不同（k 与 n），意思是款式或款项。", "馆": "guǎn 与 nuǎn 开头的辅音不同（g 与 n），意思是场所，如饭馆。"}, "sentence_index": null, "correct_answer": "暖"}, "level_3": {"options": [{"text": "暖", "is_correct": true, "explanation": "正确。“暖”形容阳光带来的温度感，符合句意。"}, {"text": "冷", "is_correct": false, "explanation": "语义：阳光照在身上，“冷”与句意矛盾。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”是味觉，不能用来形容阳光带来的感觉。"}, {"text": "苦", "is_correct": false, "explanation": "搭配：“苦”一般用于味道或心情，不用来形容阳光的温度感。"}], "explanations": {"暖": "正确。“暖”形容阳光带来的温度感，符合句意。", "冷": "语义：阳光照在身上，“冷”与句意矛盾。", "辣": "语义：“辣”是味觉，不能用来形容阳光带来的感觉。", "苦": "搭配：“苦”一般用于味道或心情，不用来形容阳光的温度感。"}, "sentence_index": 6, "correct_answer": "暖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车开得很暖。", "explanation": "这里应该用〈快〉：车开得很快。暖形容天气或环境的温度，不能形容速度。"}, {"text": "这次旅行的费用很暖。", "explanation": "这里应该用〈高〉：费用很高。暖只用于温度或温馨的感受，不能形容费用。"}, {"text": "这首歌的节奏很暖。", "explanation": "这里应该用〈轻快〉：节奏很轻快。暖形容温度或让人舒服的感觉，不能形容节奏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几天早晚冷，白天天气慢慢暖起去了。", "corrected_sentence": "这几天早晚冷，白天天气慢慢暖起来了。", "error_description": "错误：趋向补语“来”误写为“去”（暖起去了）；正确应为“暖起来了”，“起来”表示温度逐渐升高、变得温暖，不能用“起去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天的天气暖很，我们出去走走吧。", "corrected_sentence": "今天的天气很暖，我们出去走走吧。", "error_description": "错误：程度副词“很”放在了形容词“暖”之后（暖很）；正确应为“很暖”，“很”须置于形容词之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
