INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96029, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "会水是会在水里游。", "primary_collocate": null, "pronunciation": "huì shuǐ", "ipa": "xweɪ˥˩ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他从小在河边长大，很会水。", "target_word": "会水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我会水，掉进河里也不怕。", "target_word": "会水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔民都会水，不怕大风大浪。", "target_word": "会水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会水吗？那我们下河去吧。", "target_word": "会水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不会水，不敢下河。", "target_word": "会水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会水，所以一个人跳进湖里救了孩子。", "target_word": "会水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在海边的孩子大多会水。", "target_word": "会水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时在江边工作，会水。", "target_word": "会水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船翻了，会水的人游到了岸边。", "target_word": "会水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们村子里每个人都会水。", "target_word": "会水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "能在河、湖、海等水里游动，不怕水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2290f97-813e-403b-b4d6-f3b690dd389f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96029, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "会水", "is_correct": true, "explanation": "正确答案，意思是能在水里游动。"}, {"text": "回水", "is_correct": false, "explanation": "回水（huí shuǐ，第二声）与会水（huì shuǐ，第四声）第一音节声调不同，意思是水流回旋。"}, {"text": "灰水", "is_correct": false, "explanation": "灰水（huī shuǐ，第一声）与会水（huì shuǐ，第四声）第一音节声调不同，意思是草木灰浸出的水。"}, {"text": "会睡", "is_correct": false, "explanation": "会睡（huì shuì，第四声）与会水（huì shuǐ，第三声）第二音节声调不同，意思是善于睡觉。"}], "explanations": {"会水": "正确答案，意思是能在水里游动。", "回水": "回水（huí shuǐ，第二声）与会水（huì shuǐ，第四声）第一音节声调不同，意思是水流回旋。", "灰水": "灰水（huī shuǐ，第一声）与会水（huì shuǐ，第四声）第一音节声调不同，意思是草木灰浸出的水。", "会睡": "会睡（huì shuì，第四声）与会水（huì shuǐ，第三声）第二音节声调不同，意思是善于睡觉。"}, "sentence_index": null, "correct_answer": "会水"}, "level_3": {"options": [{"text": "会水", "is_correct": true, "explanation": "正确。“很会水”表示水性好，与“从小在河边长大”的语境吻合。"}, {"text": "怕水", "is_correct": false, "explanation": "语义：“从小在河边长大”的人通常熟悉水，与“很怕水”的语境相悖。"}, {"text": "不会水", "is_correct": false, "explanation": "语义：“从小在河边长大”与“很不会水”相悖，句子语境要求说明水性好。"}, {"text": "晕船", "is_correct": false, "explanation": "搭配：“晕船”需要乘船的语境，句中只说河边，不能这样搭配。"}], "explanations": {"会水": "正确。“很会水”表示水性好，与“从小在河边长大”的语境吻合。", "怕水": "语义：“从小在河边长大”的人通常熟悉水，与“很怕水”的语境相悖。", "不会水": "语义：“从小在河边长大”与“很不会水”相悖，句子语境要求说明水性好。", "晕船": "搭配：“晕船”需要乘船的语境，句中只说河边，不能这样搭配。"}, "sentence_index": 0, "correct_answer": "会水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子会水。", "explanation": "这里误用了“会水”：“会水”只指人或动物会游泳，这里把它当成了“物体能浮在水面”的意思，桌子不能这样用。"}, {"text": "这块石头会水，能游到对岸。", "explanation": "这里误用了“会水”：“会水”只指人或动物会游泳，这里把它当成了“物体能靠水流送到对岸”的意思，石头不能这样用。"}, {"text": "这盏台灯会水。", "explanation": "这里误用了“会水”：“会水”只指人或动物会游泳，这里把它当成了“器物能防水”的意思，台灯不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96029, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会水", "is_correct": true, "explanation": "正确。“大多会水”符合住在海边的孩子的常见情况。"}, {"text": "怕海", "is_correct": false, "explanation": "语义：住在海边的孩子通常不怕海，“大多怕海”与语境相悖。"}, {"text": "不敢下水", "is_correct": false, "explanation": "语义：住在海边却“大多不敢下水”，与语境的常理相悖。"}, {"text": "怕水", "is_correct": false, "explanation": "语义：住在海边的孩子常接触海水，“大多怕水”与语境相悖。"}], "explanations": {"会水": "正确。“大多会水”符合住在海边的孩子的常见情况。", "怕海": "语义：住在海边的孩子通常不怕海，“大多怕海”与语境相悖。", "不敢下水": "语义：住在海边却“大多不敢下水”，与语境的常理相悖。", "怕水": "语义：住在海边的孩子常接触海水，“大多怕水”与语境相悖。"}, "sentence_index": 6, "correct_answer": "会水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部手机会水，可以放进游泳池。", "explanation": "这里误用了“会水”：“会水”只指人或动物会游泳，这里把它当成了“器物能防水”的意思，手机不能这样用。"}, {"text": "这台电脑会水。", "explanation": "这里误用了“会水”：“会水”只指人或动物会游泳，这里把它当成了“器物能防水”的意思，电脑不能这样用。"}, {"text": "这个书包会水，能游到河对岸。", "explanation": "这里误用了“会水”：“会水”只指人或动物会游泳，书包是物品，不能自己游到对岸，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96029, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他小时候就会水着，所以不怕水。", "corrected_sentence": "他小时候就会水，所以不怕水。", "error_description": "错误形式是“会水着”，正确形式是“会水”。“会”表示具备能力，不能带动态助词“着”，“会水”后面不能加“着”，错误在于多用了“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96029, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个小孩不会水着，只能在岸边玩。", "corrected_sentence": "那个小孩不会水，只能在岸边玩。", "error_description": "错误形式是“不会水着”，正确形式是“不会水”。“会”表示具备能力，不能带动态助词“着”，错误在于多加了“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
