INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96030, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "会游泳。", "primary_collocate": null, "pronunciation": "huì shuǐ", "ipa": "xweɪ˥˩ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "小明五岁就会水了。", "target_word": "会水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暑假我想去海边，因为我会水。", "target_word": "会水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会水，每个周末都去游泳馆。", "target_word": "会水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟还不会水，正在学游泳。", "target_word": "会水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友会水，也会开车。", "target_word": "会水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会水的话，我们明天去游泳池。", "target_word": "会水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是游泳队的，当然会水。", "target_word": "会水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我女儿不会水，所以穿着救生衣。", "target_word": "会水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在学校教孩子们游泳，他很会水。", "target_word": "会水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问你们谁会水？谁来当救生员？", "target_word": "会水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "掌握游泳这项技能，口语说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2290f97-813e-403b-b4d6-f3b690dd389f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96030, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "会水", "is_correct": true, "explanation": "正确答案，意思是会游泳。"}, {"text": "回水", "is_correct": false, "explanation": "回水（huí shuǐ，第二声）与会水（huì shuǐ，第四声）第一音节声调不同，意思是水流回旋。"}, {"text": "灰水", "is_correct": false, "explanation": "灰水（huī shuǐ，第一声）与会水（huì shuǐ，第四声）第一音节声调不同，意思是草木灰浸出的水。"}, {"text": "会睡", "is_correct": false, "explanation": "会睡（huì shuì，第四声）与会水（huì shuǐ，第三声）第二音节声调不同，意思是善于睡觉。"}], "explanations": {"会水": "正确答案，意思是会游泳。", "回水": "回水（huí shuǐ，第二声）与会水（huì shuǐ，第四声）第一音节声调不同，意思是水流回旋。", "灰水": "灰水（huī shuǐ，第一声）与会水（huì shuǐ，第四声）第一音节声调不同，意思是草木灰浸出的水。", "会睡": "会睡（huì shuì，第四声）与会水（huì shuǐ，第三声）第二音节声调不同，意思是善于睡觉。"}, "sentence_index": null, "correct_answer": "会水"}, "level_3": {"options": [{"text": "会水", "is_correct": true, "explanation": "正确。“五岁就会水了”表示很小就学会了游泳，符合语境。"}, {"text": "开车", "is_correct": false, "explanation": "语义：五岁的孩子不具备驾驶能力，“五岁就开车了”与常理相悖。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：五岁的孩子不可能结婚，“五岁就结婚了”与语境相悖。"}, {"text": "退休", "is_correct": false, "explanation": "搭配：“退休”只用于工作到一定年限之后，与“五岁就”的时间范围不搭配。"}], "explanations": {"会水": "正确。“五岁就会水了”表示很小就学会了游泳，符合语境。", "开车": "语义：五岁的孩子不具备驾驶能力，“五岁就开车了”与常理相悖。", "结婚": "语义：五岁的孩子不可能结婚，“五岁就结婚了”与语境相悖。", "退休": "搭配：“退休”只用于工作到一定年限之后，与“五岁就”的时间范围不搭配。"}, "sentence_index": 0, "correct_answer": "会水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台冰箱会水。", "explanation": "这里误用了“会水”：“会水”只指人或动物会游泳，这里把它当成了“器物能防水”的意思，冰箱不能这样用。"}, {"text": "那块木板会水，能漂到对岸。", "explanation": "这里误用了“会水”：“会水”只指人或动物会游泳，这里把它当成了“物体能浮在水面”的意思，木板不能这样用。"}, {"text": "这把雨伞会水，可以在池子里游。", "explanation": "这里误用了“会水”：“会水”只指人或动物会游泳，雨伞是器物，不能在池子里游，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96030, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会水", "is_correct": true, "explanation": "正确。“游泳队的”人当然会游泳，符合语境。"}, {"text": "不会水", "is_correct": false, "explanation": "语义：游泳队的成员不会游泳，与“当然”的语境相悖。"}, {"text": "怕水", "is_correct": false, "explanation": "语义：游泳队的成员通常不怕水，“当然怕水”与语境相悖。"}, {"text": "晕船", "is_correct": false, "explanation": "搭配：“晕船”需要乘船的语境，句中只说游泳队，不能这样搭配。"}], "explanations": {"会水": "正确。“游泳队的”人当然会游泳，符合语境。", "不会水": "语义：游泳队的成员不会游泳，与“当然”的语境相悖。", "怕水": "语义：游泳队的成员通常不怕水，“当然怕水”与语境相悖。", "晕船": "搭配：“晕船”需要乘船的语境，句中只说游泳队，不能这样搭配。"}, "sentence_index": 6, "correct_answer": "会水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这架钢琴会水。", "explanation": "这里误用了“会水”：“会水”只指人或动物会游泳，这里把它当成了“器物能防水”的意思，钢琴不能这样用。"}, {"text": "这扇窗户会水，可以下去游。", "explanation": "这里误用了“会水”：“会水”只指人或动物会游泳，窗户是物体，不能说它会游泳。"}, {"text": "这只闹钟会水。", "explanation": "这里误用了“会水”：“会水”只指人或动物会游泳，这里把它当成了“器物能防水”的意思，闹钟不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹还不会水着，所以总是待在岸边。", "corrected_sentence": "我妹妹还不会水，所以总是待在岸边。", "error_description": "错误形式是“不会水着”，正确形式是“不会水”。“会”表示具备能力，不能带动态助词“着”，错误在于多加了“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我女儿现在会水着。", "corrected_sentence": "我女儿现在会水了。", "error_description": "错误形式是“会水着”，正确形式是“会水了”。表示能力变化的语境要用“了”，“着”表示动作或状态的持续，用在“会水”后不符合句意，错误在于动态助词的选择。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
