INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96033, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "梅是一种树，冬天或早春开花，花很香。", "primary_collocate": null, "pronunciation": "méi", "ipa": "mei˧˥", "syllable_count": 1, "sentences": [{"text": "墙角有一枝梅，开得很香。", "target_word": "梅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "梅、兰、竹、菊是中国人喜欢的四种植物。", "target_word": "梅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天里，只有梅敢在雪中开花。", "target_word": "梅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家门前种着一棵梅。", "target_word": "梅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪下得很大，梅却开了。", "target_word": "梅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "梅在早春开花，花很香。", "target_word": "梅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的梅开了，很多人去看。", "target_word": "梅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最爱的花是梅。", "target_word": "梅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "梅不怕冷，所以人们夸它坚强。", "target_word": "梅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画里有雪，也有梅。", "target_word": "梅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "棵", "label": "量词"}, {"form": "梅花", "label": "复合"}], "register": "书面语", "sense_fingerprint": "梅：冬末早春开花、花香的树", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53ba7404-397a-4364-acdd-387f7357410c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96033, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "梅", "is_correct": true, "explanation": "正确。梅 méi，指冬末早春开花、花香的树。"}, {"text": "美", "is_correct": false, "explanation": "měi（第三声）与 méi（第二声）声调不同，意思是美丽。"}, {"text": "妹", "is_correct": false, "explanation": "mèi（第四声）与 méi（第二声）声调不同，意思是妹妹。"}, {"text": "媚", "is_correct": false, "explanation": "mèi（第四声）与 méi（第二声）声调不同，意思是讨好、妩媚。"}, {"text": "每", "is_correct": false, "explanation": "měi（第三声）与 méi（第二声）声调不同，意思是每个。"}], "explanations": {"梅": "正确。梅 méi，指冬末早春开花、花香的树。", "美": "měi（第三声）与 méi（第二声）声调不同，意思是美丽。", "妹": "mèi（第四声）与 méi（第二声）声调不同，意思是妹妹。", "媚": "mèi（第四声）与 méi（第二声）声调不同，意思是讨好、妩媚。", "每": "měi（第三声）与 méi（第二声）声调不同，意思是每个。"}, "sentence_index": null, "correct_answer": "梅"}, "level_3": {"options": [{"text": "梅", "is_correct": true, "explanation": "正确。“梅”指开香花的树，句中“开得很香”与之相符。"}, {"text": "竹", "is_correct": false, "explanation": "语义：竹不开花，句中“开得很香”说的是花，不能用于竹。"}, {"text": "松", "is_correct": false, "explanation": "语义：松不以开香花著称，“开得很香”与松的特点不符。"}, {"text": "柳", "is_correct": false, "explanation": "搭配：“开”用于花，不说柳“开得很香”，与“一枝”后的“开”搭配不当。"}], "explanations": {"梅": "正确。“梅”指开香花的树，句中“开得很香”与之相符。", "竹": "语义：竹不开花，句中“开得很香”说的是花，不能用于竹。", "松": "语义：松不以开香花著称，“开得很香”与松的特点不符。", "柳": "搭配：“开”用于花，不说柳“开得很香”，与“一枝”后的“开”搭配不当。"}, "sentence_index": 0, "correct_answer": "梅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中秋节的晚上，院子里的梅很香。", "explanation": "这里应该用〈桂花〉。梅在冬天或早春开花，中秋时香气浓的是桂花。"}, {"text": "夏天的池塘边，梅开得很盛。", "explanation": "这里应该用〈荷花〉。梅是树，冬天或早春开花；夏天在池塘边盛开的是荷花。"}, {"text": "夏天的篱笆上，梅开满了花。", "explanation": "这里应该用〈蔷薇〉。梅冬天或早春开花；夏天篱笆上开满花的是蔷薇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96033, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "梅", "is_correct": true, "explanation": "正确。梅 méi，指冬末早春开花的树。"}, {"text": "魅", "is_correct": false, "explanation": "mèi（第四声）与 méi（第二声）声调不同，意思是吸引人的力量，如“魅力”。"}, {"text": "寐", "is_correct": false, "explanation": "mèi（第四声）与 méi（第二声）声调不同，意思是睡觉，如“假寐”。"}, {"text": "昧", "is_correct": false, "explanation": "mèi（第四声）与 méi（第二声）声调不同，意思是糊涂、不明白，如“愚昧”。"}, {"text": "镁", "is_correct": false, "explanation": "měi（第三声）与 méi（第二声）声调不同，是一种金属元素，符号 Mg。"}], "explanations": {"梅": "正确。梅 méi，指冬末早春开花的树。", "魅": "mèi（第四声）与 méi（第二声）声调不同，意思是吸引人的力量，如“魅力”。", "寐": "mèi（第四声）与 méi（第二声）声调不同，意思是睡觉，如“假寐”。", "昧": "mèi（第四声）与 méi（第二声）声调不同，意思是糊涂、不明白，如“愚昧”。", "镁": "měi（第三声）与 méi（第二声）声调不同，是一种金属元素，符号 Mg。"}, "sentence_index": null, "correct_answer": "梅"}, "level_3": {"options": [{"text": "梅", "is_correct": true, "explanation": "正确。“梅”是开花的树，“开了”“很多人去看”与梅花开放相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会开花，“开了”只能用于花或植物。"}, {"text": "雪", "is_correct": false, "explanation": "搭配：“开”用于花，不说雪“开了”，雪应说“化了”或“下了”。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不会开花，“开了”不能指房子。"}], "explanations": {"梅": "正确。“梅”是开花的树，“开了”“很多人去看”与梅花开放相符。", "石头": "语义：石头不会开花，“开了”只能用于花或植物。", "雪": "搭配：“开”用于花，不说雪“开了”，雪应说“化了”或“下了”。", "房子": "语义：房子不会开花，“开了”不能指房子。"}, "sentence_index": 6, "correct_answer": "梅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "秋天的菊园里，梅开得正盛。", "explanation": "这里应该用〈菊花〉。梅在冬天或早春开花；秋天盛开的是菊花。"}, {"text": "初夏的花园里，梅开得很盛。", "explanation": "这里应该用〈芍药〉。梅冬天或早春开花；初夏盛开的是芍药。"}, {"text": "夏天的窗外，梅的香味很浓。", "explanation": "这里应该用〈栀子花〉。梅冬天或早春开花；夏天香气很浓的是栀子花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96033, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "后院里有一个梅，每年春天都会开花。", "corrected_sentence": "后院里有一棵梅，每年春天都会开花。", "error_description": "错误在量词：梅是树，应用量词“棵”，不能用通用量词“个”。正确说法是“一棵梅”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96033, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "园子里有一只梅，春天会开出很香的花。", "corrected_sentence": "园子里有一棵梅，春天会开出很香的花。", "error_description": "错误在量词：“只”用于动物，梅是树，应用“棵”。正确说法是“一棵梅”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
