INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96034, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种落叶乔木，早春开花，果实可吃。", "primary_collocate": null, "pronunciation": "méi", "ipa": "mei˧˥", "syllable_count": 1, "sentences": [{"text": "这棵梅今年结了很多果子。", "target_word": "梅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "梅的果实又酸又甜，可以吃。", "target_word": "梅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶用梅的果实做了一瓶酒。", "target_word": "梅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天开花的梅，夏天就有果子了。", "target_word": "梅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山上种了几十棵梅，等着收果。", "target_word": "梅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种梅落叶后，春天又长新叶。", "target_word": "梅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "梅的果实熟了，村里人都去摘。", "target_word": "梅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片梅的果子卖给了酒厂。", "target_word": "梅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村后那片梅每年都结很多果子。", "target_word": "梅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的梅要到初夏才能采收。", "target_word": "梅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "棵", "label": "量词"}, {"form": "梅子", "label": "复合"}], "register": "书面语", "sense_fingerprint": "梅：落叶乔木，果实可吃", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53ba7404-397a-4364-acdd-387f7357410c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96034, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "梅", "is_correct": true, "explanation": "正确。梅 méi，指早春开花、果实可吃的落叶乔木。"}, {"text": "美", "is_correct": false, "explanation": "měi（第三声）与 méi（第二声）声调不同，意思是美丽。"}, {"text": "妹", "is_correct": false, "explanation": "mèi（第四声）与 méi（第二声）声调不同，意思是妹妹。"}, {"text": "每", "is_correct": false, "explanation": "měi（第三声）与 méi（第二声）声调不同，意思是每个。"}, {"text": "媚", "is_correct": false, "explanation": "mèi（第四声）与 méi（第二声）声调不同，意思是讨好、妩媚。"}], "explanations": {"梅": "正确。梅 méi，指早春开花、果实可吃的落叶乔木。", "美": "měi（第三声）与 méi（第二声）声调不同，意思是美丽。", "妹": "mèi（第四声）与 méi（第二声）声调不同，意思是妹妹。", "每": "měi（第三声）与 méi（第二声）声调不同，意思是每个。", "媚": "mèi（第四声）与 méi（第二声）声调不同，意思是讨好、妩媚。"}, "sentence_index": null, "correct_answer": "梅"}, "level_3": {"options": [{"text": "梅", "is_correct": true, "explanation": "正确。“梅”是结果子的落叶乔木，与“结了很多果子”相符。"}, {"text": "竹", "is_correct": false, "explanation": "语义：竹一般不结果子，“结了很多果子”指的是果树。"}, {"text": "柳", "is_correct": false, "explanation": "搭配：“结果子”多用于果树，柳树不说“结果子”。"}, {"text": "草", "is_correct": false, "explanation": "语义：草没有可以采收的果子，句中的“结了很多果子”不符合草的特点。"}], "explanations": {"梅": "正确。“梅”是结果子的落叶乔木，与“结了很多果子”相符。", "竹": "语义：竹一般不结果子，“结了很多果子”指的是果树。", "柳": "搭配：“结果子”多用于果树，柳树不说“结果子”。", "草": "语义：草没有可以采收的果子，句中的“结了很多果子”不符合草的特点。"}, "sentence_index": 0, "correct_answer": "梅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中秋的夜里，我家院子里的梅正在飘香。", "explanation": "这里应该用〈桂花〉。梅是早春开花的落叶树；中秋时香气浓的是桂花。"}, {"text": "我家院子里的梅每年秋天结果，又甜又软。", "explanation": "这里应该用〈柿子树〉。梅的果实在初夏成熟，味道偏酸；秋天结又甜又软果实的是柿子树。"}, {"text": "院子里的梅冬天也不落叶，一直是绿的。", "explanation": "这里应该用〈松树〉。梅是落叶乔木，冬天会落叶；冬天不落叶、常绿的是松树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96034, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "梅", "is_correct": true, "explanation": "正确。梅 méi，指早春开花、果实可吃的落叶乔木。"}, {"text": "魅", "is_correct": false, "explanation": "mèi（第四声）与 méi（第二声）声调不同，意思是吸引人的力量，如“魅力”。"}, {"text": "寐", "is_correct": false, "explanation": "mèi（第四声）与 méi（第二声）声调不同，意思是睡觉，如“假寐”。"}, {"text": "昧", "is_correct": false, "explanation": "mèi（第四声）与 méi（第二声）声调不同，意思是糊涂、不明白，如“愚昧”。"}, {"text": "镁", "is_correct": false, "explanation": "měi（第三声）与 méi（第二声）声调不同，是一种金属元素，符号 Mg。"}], "explanations": {"梅": "正确。梅 méi，指早春开花、果实可吃的落叶乔木。", "魅": "mèi（第四声）与 méi（第二声）声调不同，意思是吸引人的力量，如“魅力”。", "寐": "mèi（第四声）与 méi（第二声）声调不同，意思是睡觉，如“假寐”。", "昧": "mèi（第四声）与 méi（第二声）声调不同，意思是糊涂、不明白，如“愚昧”。", "镁": "měi（第三声）与 méi（第二声）声调不同，是一种金属元素，符号 Mg。"}, "sentence_index": null, "correct_answer": "梅"}, "level_3": {"options": [{"text": "梅", "is_correct": true, "explanation": "正确。“梅”是结果实的树，“果实熟了，村里人去摘”与之相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不结果实，“果实熟了”只能说植物。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户没有果实，句中的“果实”不能指窗户。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“果实”搭配植物，不说水的“果实熟了”。"}], "explanations": {"梅": "正确。“梅”是结果实的树，“果实熟了，村里人去摘”与之相符。", "桌子": "语义：桌子不结果实，“果实熟了”只能说植物。", "窗户": "语义：窗户没有果实，句中的“果实”不能指窗户。", "水": "搭配：“果实”搭配植物，不说水的“果实熟了”。"}, "sentence_index": 6, "correct_answer": "梅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏天的阳台上，梅的香气飘得很远。", "explanation": "这里应该用〈栀子花〉。梅是早春开花的落叶树；夏天香气飘得很远的是栀子花。"}, {"text": "初夏的花坛里，梅开得满满的。", "explanation": "这里应该用〈芍药〉。梅在早春开花，初夏盛开的是芍药。"}, {"text": "院子里的梅爬满了棚架，一串串挂着果子。", "explanation": "这里应该用〈葡萄〉。梅是乔木，不是藤本植物；一串串挂在棚架上的果子是葡萄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96034, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片果园里有一个梅，夏天结了很多果子。", "corrected_sentence": "这片果园里有一棵梅，夏天结了很多果子。", "error_description": "错误在量词：果树应用“棵”，“个”不能用于这里。正确说法是“一棵梅”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96034, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家后院有一块梅，夏天结了很多果子。", "corrected_sentence": "我家后院有一棵梅，夏天结了很多果子。", "error_description": "错误在量词：“块”用于块状的东西，果树应用“棵”。正确说法是“一棵梅”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85aff19b-063c-4002-8b98-51b212c20e72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
