INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96035, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "榜是贴在墙上的名单，上面有名字。", "primary_collocate": null, "pronunciation": "bǎng", "ipa": "paŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "墙上贴着一张榜，上面有很多名字。", "target_word": "榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都围在榜前找自己的名字。", "target_word": "榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看了三遍榜，也没有找到我的名字。", "target_word": "榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的名字在榜上，第一行就是。", "target_word": "榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把名单写好，贴在了教室外面的榜上。", "target_word": "榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校门口有一张新榜，大家都去看。", "target_word": "榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "榜上写着今年新生的名字。", "target_word": "榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早早来到学校看榜。", "target_word": "榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下得很大，榜上的字看不清了。", "target_word": "榜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "榜贴出来以后，很多人高兴得跳了起来。", "target_word": "榜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张榜", "label": "量词"}], "register": "中性", "sense_fingerprint": "贴在墙上写着名字的名单", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '996bd829-ae6b-4c7b-887c-9cabc20a2540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96035, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "榜", "is_correct": true, "explanation": "正确答案：bǎng，贴在墙上的名单。"}, {"text": "帮", "is_correct": false, "explanation": "bāng（第一声）与 bǎng（第三声）声调不同，意思是帮助。"}, {"text": "棒", "is_correct": false, "explanation": "bàng（第四声）与 bǎng（第三声）声调不同，意思是棍子或很好。"}, {"text": "党", "is_correct": false, "explanation": "dǎng 与 bǎng 声母不同（d 与 b），意思是政党。"}], "explanations": {"榜": "正确答案：bǎng，贴在墙上的名单。", "帮": "bāng（第一声）与 bǎng（第三声）声调不同，意思是帮助。", "棒": "bàng（第四声）与 bǎng（第三声）声调不同，意思是棍子或很好。", "党": "dǎng 与 bǎng 声母不同（d 与 b），意思是政党。"}, "sentence_index": null, "correct_answer": "榜"}, "level_3": {"options": [{"text": "榜", "is_correct": true, "explanation": "名词，指张贴在墙上写着名字的名单，与“上面有很多名字”相符。"}, {"text": "照片", "is_correct": false, "explanation": "语义：照片是拍下的影像，与“上面有很多名字”的名单内容不符。"}, {"text": "收据", "is_correct": false, "explanation": "语义：收据记录的是款项，不会写很多人的名字。"}, {"text": "床", "is_correct": false, "explanation": "语义：床不能贴在墙上，也不会上面写着很多名字。"}], "explanations": {"榜": "名词，指张贴在墙上写着名字的名单，与“上面有很多名字”相符。", "照片": "语义：照片是拍下的影像，与“上面有很多名字”的名单内容不符。", "收据": "语义：收据记录的是款项，不会写很多人的名字。", "床": "语义：床不能贴在墙上，也不会上面写着很多名字。"}, "sentence_index": 0, "correct_answer": "榜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "墙上贴着一把榜，上面有很多名字。", "explanation": "这里应该用〈张〉。榜是纸张，量词用“张”；“把”用于有柄的物件，不能用于榜。"}, {"text": "我渴了，喝了一杯榜。", "explanation": "这里“榜”被误当成了〈饮料〉，但“榜”是公布名单的纸，不能喝。"}, {"text": "他把榜当成枕头睡觉。", "explanation": "这里“榜”被误当成了〈枕头〉，但“榜”是公布名单的纸，不能用来躺卧或睡觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96035, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "榜", "is_correct": true, "explanation": "正确答案：bǎng，贴在墙上的名单。"}, {"text": "赏", "is_correct": false, "explanation": "shǎng 与 bǎng 声母不同（sh 与 b），意思是欣赏或奖赏。"}, {"text": "磅", "is_correct": false, "explanation": "bàng（第四声）与 bǎng（第三声）声调不同，意思是重量单位。"}, {"text": "挡", "is_correct": false, "explanation": "dǎng 与 bǎng 声母不同（d 与 b），意思是阻挡。"}], "explanations": {"榜": "正确答案：bǎng，贴在墙上的名单。", "赏": "shǎng 与 bǎng 声母不同（sh 与 b），意思是欣赏或奖赏。", "磅": "bàng（第四声）与 bǎng（第三声）声调不同，意思是重量单位。", "挡": "dǎng 与 bǎng 声母不同（d 与 b），意思是阻挡。"}, "sentence_index": null, "correct_answer": "榜"}, "level_3": {"options": [{"text": "榜", "is_correct": true, "explanation": "名词，指张贴的写着名字的名单，与“写着今年新生的名字”相符。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图标注的是地点，不会写新生的名字。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：菜单列的是菜名，与“新生的名字”不符。"}, {"text": "食谱", "is_correct": false, "explanation": "搭配：食谱上写的是做法和食材，与“写着新生的名字”不搭配。"}], "explanations": {"榜": "名词，指张贴的写着名字的名单，与“写着今年新生的名字”相符。", "地图": "语义：地图标注的是地点，不会写新生的名字。", "菜单": "语义：菜单列的是菜名，与“新生的名字”不符。", "食谱": "搭配：食谱上写的是做法和食材，与“写着新生的名字”不搭配。"}, "sentence_index": 6, "correct_answer": "榜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把榜吃了下去。", "explanation": "“榜”是公布名单的纸，不能当作食物来吃。"}, {"text": "我每天早上用榜洗脸。", "explanation": "这里“榜”被误当成了〈毛巾〉，但它是公布名单的纸，不能用来洗脸。"}, {"text": "我把榜当成书包背去学校。", "explanation": "这里“榜”被误当成了〈书包〉，但“榜”是公布名单的纸，不能用来背。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96035, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "放学后，大家都站在榜里看考试结果。", "corrected_sentence": "放学后，大家都站在榜前看考试结果。", "error_description": "错误：“榜里”方位词用错；正确：“榜前”。榜是贴在墙上的名单，人只能站在榜前看，不能在榜里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96035, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校的操场边贴着一本榜，许多人在看。", "corrected_sentence": "学校的操场边贴着一张榜，许多人在看。", "error_description": "错误：“榜”是纸张，应用量词“张”，不能用“本”。“本”通常用于书籍。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
