INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96037, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "乐趣是做一件事时，心里觉得快乐有趣。", "primary_collocate": null, "pronunciation": "lè qù", "ipa": "lɤ˥˩ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "读书给他带来了很多乐趣。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭对我来说是一种乐趣。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在雪地里玩，找到了不少乐趣。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "养花的乐趣只有养过花的人才知道。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行的乐趣不在目的地，而在路上。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人退休后，在种菜中找到了新的乐趣。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的生活很简单，但是充满了乐趣。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跟朋友一起踢球，是我最大的乐趣。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习外语也有很多乐趣。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有朋友的游戏，就少了很多乐趣。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种乐趣", "label": "量词"}], "register": "中性", "sense_fingerprint": "做事时感到的快乐有趣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '996bd829-ae6b-4c7b-887c-9cabc20a2540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96037, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乐趣", "is_correct": true, "explanation": "正确。“带来很多乐趣”指读书让人感到快乐有趣。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：读书不会带来汽车，这个搭配与常理不符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：读书不会带来石头，句子意思说不通。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：“带来”多用于抽象的感受或结果，手套是具体的物品。"}], "explanations": {"乐趣": "正确。“带来很多乐趣”指读书让人感到快乐有趣。", "汽车": "语义：读书不会带来汽车，这个搭配与常理不符。", "石头": "语义：读书不会带来石头，句子意思说不通。", "手套": "搭配：“带来”多用于抽象的感受或结果，手套是具体的物品。"}, "sentence_index": 0, "correct_answer": "乐趣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司去年的乐趣增长了百分之十。", "explanation": "这里应该用〈利润〉。乐趣指做事时的快乐感受，企业的盈余要说利润。"}, {"text": "他把这批乐趣运到了北京。", "explanation": "这里应该用〈货物〉。乐趣是抽象的感受，不能像货物一样运送，运输的东西要说货物。"}, {"text": "他每天早上喝一杯乐趣。", "explanation": "这里应该用〈咖啡〉。乐趣是抽象的感受，不能喝，早上喝的饮料要说咖啡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96037, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乐趣", "is_correct": true, "explanation": "正确。“充满了乐趣”指生活中有很多快乐有趣的感受。"}, {"text": "字母", "is_correct": false, "explanation": "语义：生活不会充满字母，这个说法与常理不符。"}, {"text": "台阶", "is_correct": false, "explanation": "搭配：“充满”后面要接抽象的事物或感受，台阶是具体的物体。"}, {"text": "台灯", "is_correct": false, "explanation": "语义：生活不会充满台灯，句子意思说不通。"}], "explanations": {"乐趣": "正确。“充满了乐趣”指生活中有很多快乐有趣的感受。", "字母": "语义：生活不会充满字母，这个说法与常理不符。", "台阶": "搭配：“充满”后面要接抽象的事物或感受，台阶是具体的物体。", "台灯": "语义：生活不会充满台灯，句子意思说不通。"}, "sentence_index": 6, "correct_answer": "乐趣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "生日那天，她收到了一份乐趣。", "explanation": "这里应该用〈惊喜〉。乐趣是做事时的愉快兴味，不能像礼物一样收到，意外的高兴要说惊喜。"}, {"text": "这件衣服的乐趣是两百块钱。", "explanation": "这里应该用〈价格〉。乐趣指做事时的快乐感受，衣服值多少钱要说价格。"}, {"text": "下雨了，我忘了带乐趣。", "explanation": "这里应该用〈雨伞〉。乐趣是抽象的感受，下雨时带的东西要说雨伞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96037, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "做这件事有一只特别的乐趣。", "corrected_sentence": "做这件事有一种特别的乐趣。", "error_description": "错误：“一只乐趣”。正确：“一种乐趣”。“只”用于动物等，乐趣是抽象的感受，量词应该用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96037, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在读书中吃到了很多乐趣。", "corrected_sentence": "他在读书中找到了很多乐趣。", "error_description": "错误：“吃到了乐趣”。正确：“找到了乐趣”。乐趣是抽象的感受，常说“找到 / 得到乐趣”，不能说“吃到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
