INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96038, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "使人愉快的兴味。", "primary_collocate": null, "pronunciation": "lè qù", "ipa": "lɤ˥˩ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "钓鱼的乐趣在于耐心地等待。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就爱画画，一直享受着画画的乐趣。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作太累，他已经感觉不到生活的乐趣。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏有很多乐趣，大人小孩都喜欢。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唱歌给我的生活增添了不少乐趣。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大自然里有数不清的乐趣。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，下棋的乐趣就是和朋友聊天。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们体会到了劳动的乐趣。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把照顾小狗当成每天的乐趣。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要用心，生活中处处都有乐趣。", "target_word": "乐趣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种乐趣", "label": "量词"}], "register": "中性", "sense_fingerprint": "使人愉快的兴味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '996bd829-ae6b-4c7b-887c-9cabc20a2540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96038, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乐趣", "is_correct": true, "explanation": "正确。“钓鱼的乐趣在于耐心地等待”指钓鱼让人愉快的地方。"}, {"text": "鱼竿", "is_correct": false, "explanation": "语义：鱼竿是工具，不能“在于耐心地等待”。"}, {"text": "鱼塘", "is_correct": false, "explanation": "语义：鱼塘是地方，不能说它在于耐心等待。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“钓鱼的价格”不成立，钓鱼的好处要说乐趣，不说价格。"}], "explanations": {"乐趣": "正确。“钓鱼的乐趣在于耐心地等待”指钓鱼让人愉快的地方。", "鱼竿": "语义：鱼竿是工具，不能“在于耐心地等待”。", "鱼塘": "语义：鱼塘是地方，不能说它在于耐心等待。", "价格": "搭配：“钓鱼的价格”不成立，钓鱼的好处要说乐趣，不说价格。"}, "sentence_index": 0, "correct_answer": "乐趣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "运动对身体有很多乐趣。", "explanation": "这里应该用〈益处〉。乐趣指愉快的兴味，运动对身体的好处要说益处。"}, {"text": "他坐乐趣去上班。", "explanation": "这里应该用〈公交车〉。乐趣是抽象的感受，不能乘坐，上班坐的交通工具要说公交车。"}, {"text": "他把乐趣放进了冰箱。", "explanation": "这里应该用〈食物〉。乐趣是抽象的感受，不能放进冰箱，放进冰箱的要说食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96038, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乐趣", "is_correct": true, "explanation": "正确。“下棋的乐趣就是和朋友聊天”指下棋让人愉快的地方。"}, {"text": "规则", "is_correct": false, "explanation": "语义：规则是下棋必须遵守的条文，不能等于和朋友聊天。"}, {"text": "棋盘", "is_correct": false, "explanation": "语义：棋盘是下棋用的工具，不能说它就是和朋友聊天。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“下棋的价格”不成立，下棋的好处要说乐趣，不说价格。"}], "explanations": {"乐趣": "正确。“下棋的乐趣就是和朋友聊天”指下棋让人愉快的地方。", "规则": "语义：规则是下棋必须遵守的条文，不能等于和朋友聊天。", "棋盘": "语义：棋盘是下棋用的工具，不能说它就是和朋友聊天。", "价格": "搭配：“下棋的价格”不成立，下棋的好处要说乐趣，不说价格。"}, "sentence_index": 6, "correct_answer": "乐趣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "节日里，孩子们收到了一份乐趣。", "explanation": "这里应该用〈惊喜〉。乐趣是做事时的愉快兴味，不能像礼物一样收到，意外的高兴要说惊喜。"}, {"text": "天黑了，请打开房间的乐趣。", "explanation": "这里应该用〈灯〉。乐趣指愉快的兴味，照明用的东西要说灯。"}, {"text": "这种食物含有丰富的乐趣。", "explanation": "这里应该用〈营养〉。乐趣指愉快的兴味，食物所含的有益成分要说营养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96038, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把照顾花草当作一只乐趣。", "corrected_sentence": "他把照顾花草当作一种乐趣。", "error_description": "错误：“一只乐趣”。正确：“一种乐趣”。“只”不用于抽象的感受，乐趣的量词应该用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96038, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从这件事里喝到了很多乐趣。", "corrected_sentence": "他从这件事里得到了很多乐趣。", "error_description": "错误：“喝到了乐趣”。正确：“得到了乐趣”。乐趣是抽象的感受，常说“得到 / 找到乐趣”，不能说“喝到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96039, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主流文化", "is_correct": true, "explanation": "反义：主流文化是社会上占主导的文化，次文化是其下的小群体文化，二者相对。"}, {"text": "体温", "is_correct": false, "explanation": "与次文化无反义关系，体温是身体的数值。"}, {"text": "河流", "is_correct": false, "explanation": "与次文化无反义关系，河流不属于文化范畴。"}, {"text": "厨房", "is_correct": false, "explanation": "与次文化无反义关系，厨房是场所，不是文化。"}], "correct_answer": "主流文化", "explanations": {"主流文化": "反义：主流文化是社会上占主导的文化，次文化是其下的小群体文化，二者相对。", "体温": "与次文化无反义关系，体温是身体的数值。", "河流": "与次文化无反义关系，河流不属于文化范畴。", "厨房": "与次文化无反义关系，厨房是场所，不是文化。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96039, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主流文化", "is_correct": true, "explanation": "反义：主流文化是社会上占主导的文化，与次文化相对。"}, {"text": "历史", "is_correct": false, "explanation": "与次文化无反义关系，历史是时间中的事件记录。"}, {"text": "天空", "is_correct": false, "explanation": "与次文化无反义关系，天空是自然事物。"}, {"text": "钢琴", "is_correct": false, "explanation": "与次文化无反义关系，钢琴是乐器。"}], "correct_answer": "主流文化", "explanations": {"主流文化": "反义：主流文化是社会上占主导的文化，与次文化相对。", "历史": "与次文化无反义关系，历史是时间中的事件记录。", "天空": "与次文化无反义关系，天空是自然事物。", "钢琴": "与次文化无反义关系，钢琴是乐器。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96039, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "次文化是一小群人才有的特别的玩法和爱好。", "primary_collocate": null, "pronunciation": "cì wén huà", "ipa": "tsʰɨ˥˩ wən˧˥ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "他喜欢动漫，是动漫次文化的一员。", "target_word": "次文化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "次文化常常只在小圈子里流行。", "target_word": "次文化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "街头滑板是一种年轻人的次文化。", "target_word": "次文化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她对网络次文化很有兴趣。", "target_word": "次文化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店专卖次文化的小玩意儿。", "target_word": "次文化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多种次文化一开始只有少数人喜欢。", "target_word": "次文化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们不懂年轻人的次文化。", "target_word": "次文化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们社团喜欢研究各种次文化。", "target_word": "次文化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小就迷上了摇滚次文化。", "target_word": "次文化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "次文化让爱好相同的人成了朋友。", "target_word": "次文化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "小圈子人群特有的玩法和爱好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a29a7b14-7b68-4d81-8215-6c329d1fefba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96039, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "次文化", "is_correct": true, "explanation": "正确：“动漫次文化”指动漫爱好者这一小群体的玩法和文化，“一员”指其中的成员，只有“次文化”合适。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然事物，不是一群人，不能说“是……的一员”。"}, {"text": "白天", "is_correct": false, "explanation": "语义：白天指时段，不是可以加入的群体。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“动漫窗户”不成词，与前面的“动漫”搭配不成立。"}], "explanations": {"次文化": "正确：“动漫次文化”指动漫爱好者这一小群体的玩法和文化，“一员”指其中的成员，只有“次文化”合适。", "河流": "语义：河流是自然事物，不是一群人，不能说“是……的一员”。", "白天": "语义：白天指时段，不是可以加入的群体。", "窗户": "搭配：“动漫窗户”不成词，与前面的“动漫”搭配不成立。"}, "sentence_index": 0, "correct_answer": "次文化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他有很多次文化，比如画画和踢球。", "explanation": "这里应该用〈爱好〉。次文化指某个小群体共有的玩法和文化，描述个人的兴趣要用〈爱好〉。"}, {"text": "这个国家的次文化是全国统一的。", "explanation": "这里应该用〈主流文化〉。次文化指主流之外某一小群体特有的文化，全国统一的文化属于主流文化，不是次文化。"}, {"text": "这是一本很有名的次文化。", "explanation": "量词用错。次文化是抽象概念，应用〈种〉；〈本〉用于书籍等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96039, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "次文化", "is_correct": true, "explanation": "正确：“不懂”的对象是年轻人的文化，只有“次文化”符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是可以感受的状况，不是需要“懂”的文化或道理。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是身体的数值，不是需要理解的对象。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“懂”后面接的是道理、语言这类抽象对象，不能是“厨房”。"}], "explanations": {"次文化": "正确：“不懂”的对象是年轻人的文化，只有“次文化”符合语境。", "天气": "语义：天气是可以感受的状况，不是需要“懂”的文化或道理。", "体温": "语义：体温是身体的数值，不是需要理解的对象。", "厨房": "搭配：“懂”后面接的是道理、语言这类抽象对象，不能是“厨房”。"}, "sentence_index": 6, "correct_answer": "次文化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中国次文化有几千年的历史。", "explanation": "这里应该用〈中华文化〉。次文化指主流之外某一小群体特有的文化，不能用来指整个国家的文化。"}, {"text": "他的次文化很高，大学毕业了。", "explanation": "这里应该用〈文化程度〉。次文化是某一小群体特有的文化，不能说高低；形容一个人受教育的水平要用〈文化程度〉。"}, {"text": "我们次文化赢得了比赛。", "explanation": "这里应该用〈队伍〉。次文化是文化，不是能参加比赛的团体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96039, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我弟弟最近迷上了一只网络次文化。", "corrected_sentence": "我弟弟最近迷上了一种网络次文化。", "error_description": "量词错误：“次文化”是抽象的文化，应用“种”，不能用“只”（“只”多用于动物或成对物品中的一件）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96039, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对学校里次文化很感兴趣。", "corrected_sentence": "他对学校里的次文化很感兴趣。", "error_description": "的字缺失：“学校里”修饰“次文化”时，中间需要“的”，应为“学校里的次文化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96040, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主流文化", "is_correct": true, "explanation": "反义：次文化指主流文化之下的群体文化，与主流文化相对。"}, {"text": "天空", "is_correct": false, "explanation": "与次文化无反义关系，天空是自然事物。"}, {"text": "窗户", "is_correct": false, "explanation": "与次文化无反义关系，窗户是建筑部件。"}, {"text": "钢琴", "is_correct": false, "explanation": "与次文化无反义关系，钢琴是乐器。"}], "correct_answer": "主流文化", "explanations": {"主流文化": "反义：次文化指主流文化之下的群体文化，与主流文化相对。", "天空": "与次文化无反义关系，天空是自然事物。", "窗户": "与次文化无反义关系，窗户是建筑部件。", "钢琴": "与次文化无反义关系，钢琴是乐器。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96040, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "主流文化", "is_correct": true, "explanation": "反义：次文化与主流文化相对，前者是小群体文化，后者是主导文化。"}, {"text": "历史", "is_correct": false, "explanation": "与次文化无反义关系，历史是过去的事件记录。"}, {"text": "厨房", "is_correct": false, "explanation": "与次文化无反义关系，厨房是场所。"}, {"text": "河流", "is_correct": false, "explanation": "与次文化无反义关系，河流是自然事物。"}], "correct_answer": "主流文化", "explanations": {"主流文化": "反义：次文化与主流文化相对，前者是小群体文化，后者是主导文化。", "历史": "与次文化无反义关系，历史是过去的事件记录。", "厨房": "与次文化无反义关系，厨房是场所。", "河流": "与次文化无反义关系，河流是自然事物。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96040, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "主流文化之下，某一群体所特有的文化。", "primary_collocate": null, "pronunciation": "cì wén huà", "ipa": "tsʰɨ˥˩ wən˧˥ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "次文化是主流文化中的小群体文化。", "target_word": "次文化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个年龄层都有自己的次文化。", "target_word": "次文化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校园里有各种各样的次文化。", "target_word": "次文化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位学者专门研究城市里的次文化。", "target_word": "次文化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "次文化和主流文化常常互相影响。", "target_word": "次文化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络游戏玩家有自己的次文化。", "target_word": "次文化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影介绍了嘻哈次文化的历史。", "target_word": "次文化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一些次文化后来慢慢变成了主流文化。", "target_word": "次文化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人也有自己的次文化，比如说话的方式。", "target_word": "次文化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一篇关于青少年次文化的文章。", "target_word": "次文化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "主流文化之下某群体特有的文化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a29a7b14-7b68-4d81-8215-6c329d1fefba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96040, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "次文化", "is_correct": true, "explanation": "正确：句子定义的是“主流文化中的小群体文化”，选项中只有“次文化”与之相符。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不是一种文化，不能作为这个定义句的主语。"}, {"text": "白天", "is_correct": false, "explanation": "语义：白天是时段，不能是文化类别。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“是……文化”的主语应是文化类名词，“体温”无法指代文化。"}], "explanations": {"次文化": "正确：句子定义的是“主流文化中的小群体文化”，选项中只有“次文化”与之相符。", "钢琴": "语义：钢琴是乐器，不是一种文化，不能作为这个定义句的主语。", "白天": "语义：白天是时段，不能是文化类别。", "体温": "搭配：“是……文化”的主语应是文化类名词，“体温”无法指代文化。"}, "sentence_index": 0, "correct_answer": "次文化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位学者专门研究城市里的一座次文化。", "explanation": "量词用错。〈座〉用于山、楼等大型建筑，次文化是抽象概念，应用〈种〉。"}, {"text": "这个孩子的次文化很调皮。", "explanation": "这里应该用〈性格〉。次文化指群体文化，不能用来形容一个人的性格。"}, {"text": "他有早睡的次文化。", "explanation": "这里应该用〈习惯〉。次文化指群体文化，个人的生活规律要用〈习惯〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96040, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "次文化", "is_correct": true, "explanation": "正确：“嘻哈次文化”指嘻哈这一小群体的文化，与“历史”搭配，符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“嘻哈”是音乐和文化流派，不能修饰天气。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“嘻哈”是音乐和文化流派，不能修饰厨房。"}, {"text": "胃口", "is_correct": false, "explanation": "搭配：“嘻哈”修饰的应是音乐、文化这类名词，“胃口”不能。"}], "explanations": {"次文化": "正确：“嘻哈次文化”指嘻哈这一小群体的文化，与“历史”搭配，符合语境。", "天气": "语义：“嘻哈”是音乐和文化流派，不能修饰天气。", "厨房": "语义：“嘻哈”是音乐和文化流派，不能修饰厨房。", "胃口": "搭配：“嘻哈”修饰的应是音乐、文化这类名词，“胃口”不能。"}, "sentence_index": 6, "correct_answer": "次文化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他大学读的是次文化。", "explanation": "这里应该用〈专业〉。次文化指主流之外某一群体特有的文化，不是学科，大学所学的科目要用〈专业〉。"}, {"text": "他的次文化很高，超过了两米。", "explanation": "这里应该用〈身高〉。次文化指某一群体特有的文化，不能用来描述一个人有多高。"}, {"text": "他买了一台次文化。", "explanation": "量词用错。〈台〉用于机器，次文化是抽象概念，应用〈种〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市里有很多座次文化。", "corrected_sentence": "这个城市里有很多种次文化。", "error_description": "量词错误：“次文化”应用“种”，“座”用于山、楼等大型建筑，不能用于文化。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个节目讲的是学生们次文化。", "corrected_sentence": "这个节目讲的是学生们的次文化。", "error_description": "的字缺失：“学生们”修饰“次文化”时需要“的”，应为“学生们的次文化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42ec9d03-7a06-40b5-847f-122ff20a9190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
