INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96042, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "这个地方；这里。", "primary_collocate": null, "pronunciation": "cǐ chù", "ipa": "tsʰɯ˨˩˦ ʈʂʰu˥˩", "syllable_count": 2, "sentences": [{"text": "此处禁止停车，请把车开走。", "target_word": "此处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此处风景很美，很多人来这里拍照。", "target_word": "此处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要在此处大声说话。", "target_word": "此处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此处有一家小书店，我常来买书。", "target_word": "此处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的红点就是此处。", "target_word": "此处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说，他就是在此处认识太太的。", "target_word": "此处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此处离火车站不远，走路十分钟就到。", "target_word": "此处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此处没有网络，手机打不开。", "target_word": "此处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此处的冬天很冷，要多穿衣服。", "target_word": "此处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此处是病房，必须保持安静。", "target_word": "此处", "complexity_tier": "T3", "furigana": "cǐ chù", "sentence_source": "generated"}], "morphological_forms": [{"form": "此處", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "指示代词，指说话人所在或所指的这个地方，书面语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dd71c1-9209-4d12-a308-62a2880ffae2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96042, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "此处", "is_correct": true, "explanation": "“此处”指说话人所在的这个地方，作主语，与“禁止停车”的告示语境相符。"}, {"text": "此时", "is_correct": false, "explanation": "语义：“此时”指时间，不指地点，时间不能禁止停车。"}, {"text": "这样", "is_correct": false, "explanation": "搭配：“这样”表示方式，不能作“禁止停车”的处所主语，告示里需要表示地点的词。"}, {"text": "哪里", "is_correct": false, "explanation": "语义：“哪里”是疑问代词，告示是陈述句，要用指示词表示具体地点。"}], "explanations": {"此处": "“此处”指说话人所在的这个地方，作主语，与“禁止停车”的告示语境相符。", "此时": "语义：“此时”指时间，不指地点，时间不能禁止停车。", "这样": "搭配：“这样”表示方式，不能作“禁止停车”的处所主语，告示里需要表示地点的词。", "哪里": "语义：“哪里”是疑问代词，告示是陈述句，要用指示词表示具体地点。"}, "sentence_index": 0, "correct_answer": "此处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把此处放进了书包里。", "explanation": "此处指地点，不是可以拿起来放进书包的东西；把地方当物品搬运是用错了这个词，应说“这个地方”或换成具体物品。"}, {"text": "此处是我的老师，他教了我三年。", "explanation": "语义：此处只指地点，不能用来指人。这里把老师说成“此处”，应改用“他”或直接说“老师”。"}, {"text": "我最喜欢吃此处。", "explanation": "语义：此处指地点，不是可以吃的东西，不能作“吃”的对象；想说喜欢的食物，要说具体的菜名或食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96042, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此处", "is_correct": true, "explanation": "“此处”指地点，作主语，可以表示位置离火车站不远。"}, {"text": "彼时", "is_correct": false, "explanation": "语义：“彼时”指时间，不指地点，时间不能说离火车站不远。"}, {"text": "何时", "is_correct": false, "explanation": "语义：“何时”用来问时间，句子要陈述一个地点的距离，不能用它。"}, {"text": "何处", "is_correct": false, "explanation": "搭配：“何处”是疑问词，句子却是陈述距离和走路时间，二者不搭配。"}], "explanations": {"此处": "“此处”指地点，作主语，可以表示位置离火车站不远。", "彼时": "语义：“彼时”指时间，不指地点，时间不能说离火车站不远。", "何时": "语义：“何时”用来问时间，句子要陈述一个地点的距离，不能用它。", "何处": "搭配：“何处”是疑问词，句子却是陈述距离和走路时间，二者不搭配。"}, "sentence_index": 6, "correct_answer": "此处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的狗叫此处，它很聪明。", "explanation": "语义：此处只指地点，不能当名字用。给狗起名要用“小黑”之类的名字，不能说“叫此处”。"}, {"text": "我的书包里有很多此处。", "explanation": "语义：此处是指示地点的词，不是可以计数的具体东西，不能说“很多此处”；表示多个地方要说“很多地方”。"}, {"text": "他比此处高三公分。", "explanation": "此处指地方，不能拿来和人比身高；比较身高要用人作比较对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96042, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请此处停车。", "corrected_sentence": "请在此处停车。", "error_description": "错误形式“请此处停车”，正确形式“请在此处停车”。处所词作地点状语时前面要加介词“在”，漏掉“在”就不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96042, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们此处等你，你快来吧。", "corrected_sentence": "我们在此处等你，你快来吧。", "error_description": "错误形式“我们此处等你”，正确形式“我们在此处等你”。“此处”作地点状语时，前面要加介词“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
