INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96043, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "武士是以前会打仗、会用刀剑的人。", "primary_collocate": null, "pronunciation": "wǔ shì", "ipa": "u²¹⁴ ʂʐ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "这位武士手里拿着一把长刀。", "target_word": "武士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前的武士每天都要练刀剑。", "target_word": "武士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，武士要保护国王。", "target_word": "武士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个武士骑着马走进了城。", "target_word": "武士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "武士们在山下和敌人打了一仗。", "target_word": "武士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事里的武士很勇敢。", "target_word": "武士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老武士把剑交给了年轻人。", "target_word": "武士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小城里住着一位会用剑的武士。", "target_word": "武士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "武士受了伤，还是不肯离开战场。", "target_word": "武士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想当一名武士。", "target_word": "武士", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "武士们", "label": "复数"}, {"form": "一名武士", "label": "量词"}, {"form": "一位武士", "label": "量词"}], "register": "中性", "sense_fingerprint": "古时会打仗、会用刀剑的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9b23817-999c-46c1-a554-f63ab669589a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96043, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "武士", "is_correct": true, "explanation": "正确答案：武士（wǔ shì），指以前会打仗、会用刀剑的人。"}, {"text": "舞狮", "is_correct": false, "explanation": "“狮”是第一声 shī，与“士”的第四声 shì 声调不同，意思是舞狮子。"}, {"text": "五十", "is_correct": false, "explanation": "“十”是第二声 shí，与“士”的第四声 shì 声调不同，意思是数字五十。"}, {"text": "无事", "is_correct": false, "explanation": "“无”是第二声 wú，与“武”的第三声 wǔ 声调不同，意思是没有事情。"}, {"text": "务实", "is_correct": false, "explanation": "“务”是第四声 wù，“实”是第二声 shí，与“武”“士”的声调都不同，意思是讲求实际。"}], "explanations": {"武士": "正确答案：武士（wǔ shì），指以前会打仗、会用刀剑的人。", "舞狮": "“狮”是第一声 shī，与“士”的第四声 shì 声调不同，意思是舞狮子。", "五十": "“十”是第二声 shí，与“士”的第四声 shì 声调不同，意思是数字五十。", "无事": "“无”是第二声 wú，与“武”的第三声 wǔ 声调不同，意思是没有事情。", "务实": "“务”是第四声 wù，“实”是第二声 shí，与“武”“士”的声调都不同，意思是讲求实际。"}, "sentence_index": null, "correct_answer": "武士"}, "level_3": {"options": [{"text": "武士", "is_correct": true, "explanation": "正确：武士是古时会用刀剑打仗的人，符合“手里拿着一把长刀”的画面。"}, {"text": "会计", "is_correct": false, "explanation": "语义：会计是算账的人，不会手持长刀，与画面不符。"}, {"text": "邮递员", "is_correct": false, "explanation": "语义：邮递员负责送信，不会手持长刀，与画面不符。"}, {"text": "护士", "is_correct": false, "explanation": "语义：护士负责照料病人，不会手持长刀，与画面不符。"}], "explanations": {"武士": "正确：武士是古时会用刀剑打仗的人，符合“手里拿着一把长刀”的画面。", "会计": "语义：会计是算账的人，不会手持长刀，与画面不符。", "邮递员": "语义：邮递员负责送信，不会手持长刀，与画面不符。", "护士": "语义：护士负责照料病人，不会手持长刀，与画面不符。"}, "sentence_index": 0, "correct_answer": "武士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在超市买了一只武士。", "explanation": "量词用错：〈武士〉指人，应用〈位〉或〈名〉。〈只〉多用于动物，不能用于人。"}, {"text": "他是一名武士，每天在银行帮客人存钱。", "explanation": "这里应该用〈职员〉。武士指以前会打仗、会用刀剑的人，不指在银行工作的人。"}, {"text": "这家饭店的武士做的菜很好吃。", "explanation": "这里应该用〈厨师〉。武士指古时的战士，不指做饭的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96043, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "武士", "is_correct": true, "explanation": "正确答案：武士（wǔ shì），指以前会打仗、会用刀剑的人。"}, {"text": "无视", "is_correct": false, "explanation": "“无”是第二声 wú，与“武”的第三声 wǔ 声调不同，意思是不理会、忽视。"}, {"text": "午时", "is_correct": false, "explanation": "“时”是第二声 shí，与“士”的第四声 shì 声调不同，意思是中午的时候。"}, {"text": "舞狮", "is_correct": false, "explanation": "“狮”是第一声 shī，与“士”的第四声 shì 声调不同，意思是舞狮子。"}], "explanations": {"武士": "正确答案：武士（wǔ shì），指以前会打仗、会用刀剑的人。", "无视": "“无”是第二声 wú，与“武”的第三声 wǔ 声调不同，意思是不理会、忽视。", "午时": "“时”是第二声 shí，与“士”的第四声 shì 声调不同，意思是中午的时候。", "舞狮": "“狮”是第一声 shī，与“士”的第四声 shì 声调不同，意思是舞狮子。"}, "sentence_index": null, "correct_answer": "武士"}, "level_3": {"options": [{"text": "武士", "is_correct": true, "explanation": "正确：武士是古时的专业战士，符合“老武士把剑交给了年轻人”的句子。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，不能把剑交给年轻人。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：老鼠是动物，不会把剑交给别人。"}, {"text": "老树", "is_correct": false, "explanation": "配价：“交给”需要有人作主语，老树不能把剑交给年轻人。"}], "explanations": {"武士": "正确：武士是古时的专业战士，符合“老武士把剑交给了年轻人”的句子。", "老虎": "语义：老虎是动物，不能把剑交给年轻人。", "老鼠": "语义：老鼠是动物，不会把剑交给别人。", "老树": "配价：“交给”需要有人作主语，老树不能把剑交给年轻人。"}, "sentence_index": 6, "correct_answer": "武士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位武士每天在学校里给孩子们上数学课。", "explanation": "这里应该用〈老师〉。武士指古时会打仗、会用刀剑的人，不指在学校教数学的人。"}, {"text": "他的哥哥买了一把武士。", "explanation": "量词用错：〈武士〉指人，应用〈位〉或〈名〉。〈把〉用于有柄的器物，不能用于人。"}, {"text": "他是一名武士，每天在医院给病人看病。", "explanation": "这里应该用〈医生〉。武士是古时的战士，不能指在医院看病的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96043, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两只武士在城门口站岗。", "corrected_sentence": "这两位武士在城门口站岗。", "error_description": "量词用错：〈武士〉指人，应用〈位〉或〈名〉，不能用〈只〉。正确应说“这两位武士”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96043, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "城门口站着一位会用刀武士。", "corrected_sentence": "城门口站着一位会用刀的武士。", "error_description": "定语缺少助词：“会用刀”修饰“武士”时要在后面加“的”，应说“会用刀的武士”，不能省去“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
