INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96044, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "日本古代的职业战士。", "primary_collocate": null, "pronunciation": "wǔ shì", "ipa": "u²¹⁴ ʂʐ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "日本古代的武士都带着两把刀。", "target_word": "武士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的日本武士穿着和服。", "target_word": "武士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代日本的武士是一种职业。", "target_word": "武士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的剑术像日本武士一样精湛。", "target_word": "武士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位日本武士为了主人去打仗。", "target_word": "武士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在日本古代，武士的地位很高。", "target_word": "武士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在博物馆里看到了日本武士用过的刀。", "target_word": "武士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日本武士每天都要学习武艺。", "target_word": "武士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个年轻的日本武士为主人守了三年城。", "target_word": "武士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写的是日本武士的生活。", "target_word": "武士", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "武士们", "label": "复数"}, {"form": "一名武士", "label": "量词"}, {"form": "一位武士", "label": "量词"}], "register": "中性", "sense_fingerprint": "日本古代的职业战士", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9b23817-999c-46c1-a554-f63ab669589a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96044, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "武士", "is_correct": true, "explanation": "正确答案：武士（wǔ shì），指日本古代的职业战士。"}, {"text": "舞狮", "is_correct": false, "explanation": "“狮”是第一声 shī，与“士”的第四声 shì 声调不同，意思是舞狮子。"}, {"text": "五十", "is_correct": false, "explanation": "“十”是第二声 shí，与“士”的第四声 shì 声调不同，意思是数字五十。"}, {"text": "无事", "is_correct": false, "explanation": "“无”是第二声 wú，与“武”的第三声 wǔ 声调不同，意思是没有事情。"}, {"text": "务实", "is_correct": false, "explanation": "“务”是第四声 wù，“实”是第二声 shí，与“武”“士”的声调都不同，意思是讲求实际。"}], "explanations": {"武士": "正确答案：武士（wǔ shì），指日本古代的职业战士。", "舞狮": "“狮”是第一声 shī，与“士”的第四声 shì 声调不同，意思是舞狮子。", "五十": "“十”是第二声 shí，与“士”的第四声 shì 声调不同，意思是数字五十。", "无事": "“无”是第二声 wú，与“武”的第三声 wǔ 声调不同，意思是没有事情。", "务实": "“务”是第四声 wù，“实”是第二声 shí，与“武”“士”的声调都不同，意思是讲求实际。"}, "sentence_index": null, "correct_answer": "武士"}, "level_3": {"options": [{"text": "武士", "is_correct": true, "explanation": "正确：日本古代的职业战士都佩带刀剑，符合“都带着两把刀”的描述。"}, {"text": "诗人", "is_correct": false, "explanation": "语义：诗人不是随身佩刀的职业，与“日本古代……都带着两把刀”的说法不符。"}, {"text": "书法家", "is_correct": false, "explanation": "语义：书法家用毛笔写字，不随身带刀，与描述不符。"}, {"text": "画家", "is_correct": false, "explanation": "语义：画家不是佩刀的职业，与“都带着两把刀”的描述不符。"}], "explanations": {"武士": "正确：日本古代的职业战士都佩带刀剑，符合“都带着两把刀”的描述。", "诗人": "语义：诗人不是随身佩刀的职业，与“日本古代……都带着两把刀”的说法不符。", "书法家": "语义：书法家用毛笔写字，不随身带刀，与描述不符。", "画家": "语义：画家不是佩刀的职业，与“都带着两把刀”的描述不符。"}, "sentence_index": 0, "correct_answer": "武士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我姐姐是一名武士，每天在教室里读书。", "explanation": "这里应该用〈学生〉。武士指日本古代的职业战士，不指在教室里读书的人。"}, {"text": "他是一名武士，每天在地里干活。", "explanation": "这里应该用〈农民〉。武士指古代的战士，不指在地里干活的人。"}, {"text": "他买了一条武士。", "explanation": "量词用错：〈武士〉指人，应用〈位〉或〈名〉。〈条〉多用于狗、鱼等，不能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96044, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "武士", "is_correct": true, "explanation": "正确答案：武士（wǔ shì），指日本古代的职业战士。"}, {"text": "无视", "is_correct": false, "explanation": "“无”是第二声 wú，与“武”的第三声 wǔ 声调不同，意思是不理会、忽视。"}, {"text": "午时", "is_correct": false, "explanation": "“时”是第二声 shí，与“士”的第四声 shì 声调不同，意思是中午的时候。"}, {"text": "舞狮", "is_correct": false, "explanation": "“狮”是第一声 shī，与“士”的第四声 shì 声调不同，意思是舞狮子。"}], "explanations": {"武士": "正确答案：武士（wǔ shì），指日本古代的职业战士。", "无视": "“无”是第二声 wú，与“武”的第三声 wǔ 声调不同，意思是不理会、忽视。", "午时": "“时”是第二声 shí，与“士”的第四声 shì 声调不同，意思是中午的时候。", "舞狮": "“狮”是第一声 shī，与“士”的第四声 shì 声调不同，意思是舞狮子。"}, "sentence_index": null, "correct_answer": "武士"}, "level_3": {"options": [{"text": "武士", "is_correct": true, "explanation": "正确：武士是古代的战士，符合“看到了武士用过的刀”。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不会使用刀具，与“用过的刀”的使用者应是人的语境不符。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“用”需要能施事的人作主语，石头不能用刀，与句子不符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会使用刀具，与“用过的刀”的语境矛盾。"}], "explanations": {"武士": "正确：武士是古代的战士，符合“看到了武士用过的刀”。", "电脑": "语义：电脑不会使用刀具，与“用过的刀”的使用者应是人的语境不符。", "石头": "配价：“用”需要能施事的人作主语，石头不能用刀，与句子不符。", "窗户": "语义：窗户不会使用刀具，与“用过的刀”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "武士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的邻居是一位武士，每天在学校教孩子们画画。", "explanation": "这里应该用〈老师〉。武士指日本古代的职业战士，不指在学校教画画的人。"}, {"text": "他是一名武士，每天在法院为客人辩护。", "explanation": "这里应该用〈律师〉。武士指古代的战士，不指在法院辩护的人。"}, {"text": "我买了一本武士。", "explanation": "量词用错：〈武士〉指人，应用〈位〉或〈名〉。〈本〉用于书籍，不能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在博物馆里见到一只古代武士。", "corrected_sentence": "我在博物馆里见到一位古代武士。", "error_description": "量词用错：〈武士〉指人，应用〈位〉或〈名〉，不能用〈只〉。正确应说“一位古代武士”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位会用刀武士在山里修行。", "corrected_sentence": "那位会用刀的武士在山里修行。", "error_description": "的字漏掉：修饰“武士”的“会用刀”后面要加“的”，应说“会用刀的武士”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
