INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96045, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96045, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "气温是空气有多热、有多冷。", "primary_collocate": null, "pronunciation": "qì wēn", "ipa": "tɕʰi˥˩ wən˥", "syllable_count": 2, "sentences": [{"text": "今天的气温很高，我想去游泳。", "target_word": "气温", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天北京的气温常常很低。", "target_word": "气温", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早上的气温只有五度，你要多穿衣服。", "target_word": "气温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气预报说，明天的气温会下降。", "target_word": "气温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的气温太高，大家都不想出门。", "target_word": "气温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的气温一年四季都很舒服。", "target_word": "气温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，气温一下子变低了。", "target_word": "气温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的气温比山下低很多。", "target_word": "气温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的气温是三十五度，真热。", "target_word": "气温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看今天的气温，还要穿毛衣吗？", "target_word": "气温", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "度", "label": "量词"}, {"form": "最高气温", "label": "复合词"}, {"form": "最低气温", "label": "复合词"}, {"form": "平均气温", "label": "复合词"}], "register": "中性", "sense_fingerprint": "气温：空气的冷热程度，日常说天气冷热", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b21d38-673e-4382-b312-55fb37567b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96045, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海拔", "is_correct": false, "explanation": "语义：海拔指地面的高度，不随“今天”变化，与句子说的冷热无关。"}, {"text": "气温", "is_correct": true, "explanation": "正确：气温指空气的冷热，“很高”和“想去游泳”都说明天气热。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”用“大”或“好”，不说“很高”，而且语境在说天气。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”指人或物的高矮，不能说“今天的身高”。"}], "explanations": {"海拔": "语义：海拔指地面的高度，不随“今天”变化，与句子说的冷热无关。", "气温": "正确：气温指空气的冷热，“很高”和“想去游泳”都说明天气热。", "脾气": "搭配：“脾气”用“大”或“好”，不说“很高”，而且语境在说天气。", "身高": "搭配：“身高”指人或物的高矮，不能说“今天的身高”。"}, "sentence_index": 0, "correct_answer": "气温"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他发烧了，气温是三十九度。", "explanation": "这里应该用〈体温〉。气温指空气的冷热，人发烧的温度要说体温。"}, {"text": "这盆洗澡水的气温很高，你小心烫伤。", "explanation": "这里应该用〈水温〉。气温指空气的温度，洗澡水的温度要说水温。"}, {"text": "会场里的气温很紧张，大家都不敢说话。", "explanation": "这里应该用〈气氛〉。气温只说冷热，会场的紧张感要说气氛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96045, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：年龄只会增长，不会因为下雨而变低。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色用“深”或“浅”描述，不说“变低”。"}, {"text": "气温", "is_correct": true, "explanation": "正确：下雨后气温下降，“变低了”与气温的变化相符。"}, {"text": "字数", "is_correct": false, "explanation": "搭配：字数用“多”或“少”，不说“变低”。"}], "explanations": {"年龄": "语义：年龄只会增长，不会因为下雨而变低。", "颜色": "搭配：颜色用“深”或“浅”描述，不说“变低”。", "气温": "正确：下雨后气温下降，“变低了”与气温的变化相符。", "字数": "搭配：字数用“多”或“少”，不说“变低”。"}, "sentence_index": 6, "correct_answer": "气温"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位歌手的气温很高，很多人都喜欢他。", "explanation": "这里应该用〈人气〉。气温说的是冷热，歌手受欢迎要说人气。"}, {"text": "今天的气温很大，空气也很潮湿。", "explanation": "这里应该用〈湿度〉。气温只说高低，“很大”用于湿度，说“湿度很大”。"}, {"text": "他的气温很大，经常生气。", "explanation": "这里应该用〈脾气〉。气温指天气的冷热，人的性情要说“脾气很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96045, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天的气温是二十个度，很舒服。", "corrected_sentence": "今天的气温是二十度，很舒服。", "error_description": "“度”是气温的量词，不能用“个”。应说“二十度”，不说“二十个度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96045, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨晚气温降在了零下五度。", "corrected_sentence": "昨晚气温降到了零下五度。", "error_description": "“降”后面的结果补语应为“到”，“降在”错误，应说“降到零下五度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
