INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96046, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "空气的温度。", "primary_collocate": null, "pronunciation": "qì wēn", "ipa": "tɕʰi˥˩ wən˥", "syllable_count": 2, "sentences": [{"text": "气象台每天都会记录各地的气温。", "target_word": "气温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的平均气温是十五度。", "target_word": "气温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年夏天的最高气温超过了四十度。", "target_word": "气温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气温升高，冰雪就会慢慢融化。", "target_word": "气温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚的最低气温在零度以下。", "target_word": "气温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的气温比城里低两度。", "target_word": "气温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们每天测量教室外面的气温。", "target_word": "气温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的气温在冬天会降到零下二十度。", "target_word": "气温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气温变化太大，很多人感冒了。", "target_word": "气温", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张表上写着一周的气温。", "target_word": "气温", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "度", "label": "量词"}, {"form": "最高气温", "label": "复合词"}, {"form": "最低气温", "label": "复合词"}, {"form": "平均气温", "label": "复合词"}], "register": "中性", "sense_fingerprint": "气温：气象上测量的空气温度数值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b21d38-673e-4382-b312-55fb37567b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96046, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "股价", "is_correct": false, "explanation": "语义：气象台只记录气象，不记录股票。"}, {"text": "气温", "is_correct": true, "explanation": "正确：气象台记录的是各地的空气温度，与“气象台”的职能相符。"}, {"text": "语速", "is_correct": false, "explanation": "语义：语速指说话的快慢，与气象台的记录无关。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”是人或物的属性，不说“各地的身高”。"}], "explanations": {"股价": "语义：气象台只记录气象，不记录股票。", "气温": "正确：气象台记录的是各地的空气温度，与“气象台”的职能相符。", "语速": "语义：语速指说话的快慢，与气象台的记录无关。", "身高": "搭配：“身高”是人或物的属性，不说“各地的身高”。"}, "sentence_index": 0, "correct_answer": "气温"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯茶的气温刚刚好，可以喝了。", "explanation": "这里应该用〈水温〉。气温指空气的温度，茶的温度要说水温。"}, {"text": "会场里的气温很热烈，大家都很兴奋。", "explanation": "这里应该用〈气氛〉。气温只说冷热，会场的热烈要说气氛。"}, {"text": "妈妈摸了摸我的额头，说我的气温有点高。", "explanation": "这里应该用〈体温〉。气温指空气的冷热，人身体的温度要说体温。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96046, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "语义：体重是人的测量数值，与“教室外面”的环境无关。"}, {"text": "房价", "is_correct": false, "explanation": "语义：房价不是可以用仪器“测量”的数值，与句子不符。"}, {"text": "气温", "is_correct": true, "explanation": "正确：气温可以用温度计测量，“教室外面”的环境与之相符。"}, {"text": "血压", "is_correct": false, "explanation": "搭配：“血压”是人体的数值，不说“教室外面的血压”。"}], "explanations": {"体重": "语义：体重是人的测量数值，与“教室外面”的环境无关。", "房价": "语义：房价不是可以用仪器“测量”的数值，与句子不符。", "气温": "正确：气温可以用温度计测量，“教室外面”的环境与之相符。", "血压": "搭配：“血压”是人体的数值，不说“教室外面的血压”。"}, "sentence_index": 6, "correct_answer": "气温"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的气温很大，树都在摇。", "explanation": "这里应该用〈风力〉。气温说的是冷热的高低，“很大”用于风力。"}, {"text": "他这次考试的气温很高，老师很满意。", "explanation": "这里应该用〈成绩〉。气温指天气的冷热，考试的好坏要说成绩。"}, {"text": "他的气温很高，生活很好。", "explanation": "这里应该用〈收入〉。气温指天气的冷热，生活水平与收入有关，要说收入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96046, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去年夏天的最高气温是三十八个度。", "corrected_sentence": "去年夏天的最高气温是三十八度。", "error_description": "“度”是气温的量词，不能用“个”。应说“三十八度”，不说“三十八个度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96046, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨晚的最低气温降在了零下五度。", "corrected_sentence": "昨晚的最低气温降到了零下五度。", "error_description": "结果补语应用“到”，“降在”错误，应说“降到零下五度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
