INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96047, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海关是在国家边上，检查进出的人和东西的地方。", "primary_collocate": null, "pronunciation": "hǎi guān", "ipa": "xaɪ˨˩˦ kwan˥", "syllable_count": 2, "sentences": [{"text": "我们在海关排队等了很久。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关就在机场的二楼。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过海关的时候，要拿出护照。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关里人很多，我们等了一个小时。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行李在海关要全部检查一遍。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下飞机后，我先去海关。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关门口有很多人在等朋友。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次出国，在海关有点紧张。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关旁边有一家小商店。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "通过海关以后，我们坐车去了酒店。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "海關", "label": "繁体"}, {"form": "海关人员", "label": "复合"}], "register": "中性", "sense_fingerprint": "机场、港口等处检查进出人员和物品的地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dd71c1-9209-4d12-a308-62a2880ffae2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96047, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海关", "is_correct": true, "explanation": "“海关”是检查出入境人员和物品的地点，可以作“在……排队”的场所。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李是物品，不是可以排队的场所，“在行李排队”说不通。"}, {"text": "护照", "is_correct": false, "explanation": "搭配：“排队”需要地点名词作场所，护照是证件，“在护照排队”不搭配。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是人排队的地方，句中“排队等了很久”的场所不可能是冰箱。"}], "explanations": {"海关": "“海关”是检查出入境人员和物品的地点，可以作“在……排队”的场所。", "行李": "语义：行李是物品，不是可以排队的场所，“在行李排队”说不通。", "护照": "搭配：“排队”需要地点名词作场所，护照是证件，“在护照排队”不搭配。", "冰箱": "语义：冰箱不是人排队的地方，句中“排队等了很久”的场所不可能是冰箱。"}, "sentence_index": 0, "correct_answer": "海关"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们付了很多海关。", "explanation": "这里应该用〈关税〉。海关是检查机构，交的钱是关税，不能说付了“海关”。"}, {"text": "我们去了一台海关。", "explanation": "量词用错。“台”用于机器，海关是机构，应用“个”。"}, {"text": "我住在海关，每天都很忙。", "explanation": "语义：海关是政府的检查机构，不是人住的地方，“住在海关”用错了这个词的意义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96047, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海关", "is_correct": true, "explanation": "“海关”是检查场所，有门口，可以说“海关门口”。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙没有门口，“钥匙门口”说不通。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“门口”需要建筑或场所，书包不说门口，“书包门口”不搭配。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是有门口的场所，句子说门口有很多人等朋友，手机无法成立。"}], "explanations": {"海关": "“海关”是检查场所，有门口，可以说“海关门口”。", "钥匙": "语义：钥匙没有门口，“钥匙门口”说不通。", "书包": "搭配：“门口”需要建筑或场所，书包不说门口，“书包门口”不搭配。", "手机": "语义：手机不是有门口的场所，句子说门口有很多人等朋友，手机无法成立。"}, "sentence_index": 6, "correct_answer": "海关"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们把海关寄到了北京。", "explanation": "语义：海关是机构，不是物品，不能被“寄”，这个词不这么用。"}, {"text": "我们吃了一碗海关。", "explanation": "量词和语义都错：“碗”用于盛装食物的器皿，海关是机构，不能吃；这里应说“吃了一碗面”。"}, {"text": "海关喝了一杯水。", "explanation": "语义：海关是场所，不会喝水，主语应是人，这里用错了词的意义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96047, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只海关门口很热闹。", "corrected_sentence": "这个海关门口很热闹。", "error_description": "错误形式“这只海关门口很热闹”，正确形式“这个海关门口很热闹”。“海关”在此指检查场所，量词应用“个”，用“只”是量词用错了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96047, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们吃海关的时候拿出了护照。", "corrected_sentence": "我们过海关的时候拿出了护照。", "error_description": "动词搭配错误：经过检查场所要说“过海关”。“吃”的对象是食物，不能和“海关”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
