INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96048, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "设在国境口岸，检查进出境人员、货物的机关。", "primary_collocate": null, "pronunciation": "hǎi guān", "ipa": "xaɪ˨˩˦ kwan˥", "syllable_count": 2, "sentences": [{"text": "海关规定，水果不能带进这个国家。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关工作人员每天检查很多货物。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的货要先交给海关。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关发现了一批没有申报的东西。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在海关工作，保护国家安全。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关提醒大家，不要带危险品出国。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关的网站上可以查进口的规定。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关对进口的东西收税。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国海关欢迎外国朋友来旅游。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关做了新规定，旅客要填表。", "target_word": "海关", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "海關", "label": "繁体"}, {"form": "海关人员", "label": "复合"}], "register": "中性", "sense_fingerprint": "负责监管进出境人员、货物并征收关税的国家机关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dd71c1-9209-4d12-a308-62a2880ffae2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96048, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海关", "is_correct": true, "explanation": "“海关”是管理进出境货物的机关，可以制定进境规定。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校不负责国家的进出境物品规定，句中说水果不能带进国家，学校不成立。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院的规定管不到国家的进境物品，句子的主语说不通。"}, {"text": "飞机", "is_correct": false, "explanation": "搭配：飞机不能“规定”，“规定”的主语要是机关或人，“飞机规定”不搭配。"}], "explanations": {"海关": "“海关”是管理进出境货物的机关，可以制定进境规定。", "学校": "语义：学校不负责国家的进出境物品规定，句中说水果不能带进国家，学校不成立。", "医院": "语义：医院的规定管不到国家的进境物品，句子的主语说不通。", "飞机": "搭配：飞机不能“规定”，“规定”的主语要是机关或人，“飞机规定”不搭配。"}, "sentence_index": 0, "correct_answer": "海关"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的孩子在海关学习汉字。", "explanation": "语义：海关是检查进出境人员和货物的机关，不是学习的场所，“在海关学习”用错了这个词的意义。"}, {"text": "我们在机场看见了一块海关。", "explanation": "量词用错。“块”用于片状的东西，海关是机关，应用“个”。"}, {"text": "他是一位很好的海关。", "explanation": "语义：海关指机关，不指人，说人应用“海关人员”或“海关工作人员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96048, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海关", "is_correct": true, "explanation": "“海关”的网站可以查询进口规定，与句子的语境相符。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：饭店不发布进口规定，“饭店的网站上查进口规定”说不通。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：书包没有网站，不能说“书包的网站”。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：冰箱没有网站可以查规定，“冰箱的网站”不搭配。"}], "explanations": {"海关": "“海关”的网站可以查询进口规定，与句子的语境相符。", "饭店": "语义：饭店不发布进口规定，“饭店的网站上查进口规定”说不通。", "书包": "搭配：书包没有网站，不能说“书包的网站”。", "冰箱": "搭配：冰箱没有网站可以查规定，“冰箱的网站”不搭配。"}, "sentence_index": 6, "correct_answer": "海关"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅客要带着海关出境。", "explanation": "这里应该用〈护照〉。出境时带的是护照，海关是机构，不能被携带。"}, {"text": "我的钥匙是海关。", "explanation": "语义：海关是机关名称，不是钥匙这样的物品，不能作“钥匙”的表语；这里用错了词，应说“钥匙在包里”之类。"}, {"text": "这家海关比我的朋友还高。", "explanation": "语义：海关是机关，不是可以拿来比高矮的人或物，比较对象用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96048, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市有两只海关。", "corrected_sentence": "这座城市有两个海关。", "error_description": "量词错误：“海关”是机关，应用“个”；“只”多用于动物，不能用来数海关。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96048, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海关被检查很多货物。", "corrected_sentence": "海关检查很多货物。", "error_description": "被字句误用：海关是检查货物的一方（施事），不能用“被”。删去“被”，说“海关检查很多货物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96049, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脏", "is_correct": true, "explanation": "脏：与“干净”相反，指有污垢、杂质。"}, {"text": "宽阔", "is_correct": false, "explanation": "宽阔：形容面积大，与“干净”没有反义关系。"}, {"text": "圆润", "is_correct": false, "explanation": "圆润：形容圆而光滑或声音饱满，与“干净”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹：形容人多、声音大，与“干净”没有反义关系。"}], "correct_answer": "脏", "explanations": {"脏": "脏：与“干净”相反，指有污垢、杂质。", "宽阔": "宽阔：形容面积大，与“干净”没有反义关系。", "圆润": "圆润：形容圆而光滑或声音饱满，与“干净”没有反义关系。", "热闹": "热闹：形容人多、声音大，与“干净”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96049, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脏", "is_correct": true, "explanation": "脏：与“干净”相反，指有污垢、杂质。"}, {"text": "陡峭", "is_correct": false, "explanation": "陡峭：形容山坡或地势很斜，与“干净”没有反义关系。"}, {"text": "遥远", "is_correct": false, "explanation": "遥远：形容距离很远，与“干净”没有反义关系。"}, {"text": "寂静", "is_correct": false, "explanation": "寂静：形容非常安静，与“干净”没有反义关系。"}], "correct_answer": "脏", "explanations": {"脏": "脏：与“干净”相反，指有污垢、杂质。", "陡峭": "陡峭：形容山坡或地势很斜，与“干净”没有反义关系。", "遥远": "遥远：形容距离很远，与“干净”没有反义关系。", "寂静": "寂静：形容非常安静，与“干净”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96049, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "净是干干净净，没有脏东西。", "primary_collocate": null, "pronunciation": "jìng", "ipa": "tɕiŋ˥˩", "syllable_count": 1, "sentences": [{"text": "孩子们把教室扫净，才回家。", "target_word": "净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把鞋子刷净，放在门口晒太阳。", "target_word": "净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手没洗净，不要拿东西吃。", "target_word": "净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把脸洗净，换上了新衣服。", "target_word": "净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把盘子洗净了，一点脏东西也没有。", "target_word": "净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果要洗净，不然皮上有脏东西。", "target_word": "净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把黑板擦净了，上面一个字也没有。", "target_word": "净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里的落叶扫净以后，看上去很舒服。", "target_word": "净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把汽车洗净，开去接爷爷。", "target_word": "净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧衣服洗净了，挂在阳台上。", "target_word": "净", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "淨", "label": "繁体"}, {"form": "干净", "label": "复合"}, {"form": "洁净", "label": "复合"}], "register": "中性", "sense_fingerprint": "净：干干净净，没有脏东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '277212ec-c05c-4f82-b617-5b3b2e2110c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96049, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "净", "is_correct": true, "explanation": "净 jìng（第四声）：干干净净，没有脏东西，即本词。"}, {"text": "进", "is_correct": false, "explanation": "jìn 与 jìng 韵母不同（in 与 ing），意思是“进入”。"}, {"text": "经", "is_correct": false, "explanation": "jīng（第一声）与 jìng（第四声）声调不同，意思是“经过”。"}, {"text": "精", "is_correct": false, "explanation": "jīng（第一声）与 jìng（第四声）声调不同，意思是“精细、精力”。"}, {"text": "景", "is_correct": false, "explanation": "jǐng（第三声）与 jìng（第四声）声调不同，意思是“风景”。"}, {"text": "井", "is_correct": false, "explanation": "jǐng（第三声）与 jìng（第四声）声调不同，意思是“水井”。"}], "explanations": {"净": "净 jìng（第四声）：干干净净，没有脏东西，即本词。", "进": "jìn 与 jìng 韵母不同（in 与 ing），意思是“进入”。", "经": "jīng（第一声）与 jìng（第四声）声调不同，意思是“经过”。", "精": "jīng（第一声）与 jìng（第四声）声调不同，意思是“精细、精力”。", "景": "jǐng（第三声）与 jìng（第四声）声调不同，意思是“风景”。", "井": "jǐng（第三声）与 jìng（第四声）声调不同，意思是“水井”。"}, "sentence_index": null, "correct_answer": "净"}, "level_3": {"options": [{"text": "净", "is_correct": true, "explanation": "净：“扫净”说把教室扫得干干净净，才回家，符合句意。"}, {"text": "烂", "is_correct": false, "explanation": "语义：把教室扫烂不合常理，与“扫净后才回家”的意思不合。"}, {"text": "破", "is_correct": false, "explanation": "语义：扫破的是东西或工具，不能说把教室扫破，与句意不合。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“扫”后面一般接“干净”，不接“亮”来表示扫地的结果。"}], "explanations": {"净": "净：“扫净”说把教室扫得干干净净，才回家，符合句意。", "烂": "语义：把教室扫烂不合常理，与“扫净后才回家”的意思不合。", "破": "语义：扫破的是东西或工具，不能说把教室扫破，与句意不合。", "亮": "搭配：“扫”后面一般接“干净”，不接“亮”来表示扫地的结果。"}, "sentence_index": 0, "correct_answer": "净"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的成绩很净。", "explanation": "这里应该用〈好〉。“净”指没有脏东西，不能用来评价成绩的好坏。"}, {"text": "他跑得很净。", "explanation": "这里应该用〈快〉。“净”指没有脏东西，不能用来形容跑步的速度。"}, {"text": "这道题很净。", "explanation": "这里应该用〈简单〉。“净”指没有脏东西，不能用来说题目难不难。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96049, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "净", "is_correct": true, "explanation": "净 jìng（第四声）：干干净净，没有脏东西，即本词。"}, {"text": "近", "is_correct": false, "explanation": "jìn 与 jìng 韵母不同（in 与 ing），意思是“距离短”。"}, {"text": "尽", "is_correct": false, "explanation": "jìn 与 jìng 韵母不同（in 与 ing），意思是“尽力”。"}, {"text": "惊", "is_correct": false, "explanation": "jīng（第一声）与 jìng（第四声）声调不同，意思是“吃惊”。"}, {"text": "警", "is_correct": false, "explanation": "jǐng（第三声）与 jìng（第四声）声调不同，意思是“警察”。"}, {"text": "晶", "is_correct": false, "explanation": "jīng（第一声）与 jìng（第四声）声调不同，意思是“水晶”。"}], "explanations": {"净": "净 jìng（第四声）：干干净净，没有脏东西，即本词。", "近": "jìn 与 jìng 韵母不同（in 与 ing），意思是“距离短”。", "尽": "jìn 与 jìng 韵母不同（in 与 ing），意思是“尽力”。", "惊": "jīng（第一声）与 jìng（第四声）声调不同，意思是“吃惊”。", "警": "jǐng（第三声）与 jìng（第四声）声调不同，意思是“警察”。", "晶": "jīng（第一声）与 jìng（第四声）声调不同，意思是“水晶”。"}, "sentence_index": null, "correct_answer": "净"}, "level_3": {"options": [{"text": "净", "is_correct": true, "explanation": "净：“擦净”说黑板擦得干干净净，与“上面一个字也没有”相合。"}, {"text": "软", "is_correct": false, "explanation": "搭配：“软”多用于衣料、食物变软，不用来说擦黑板。"}, {"text": "薄", "is_correct": false, "explanation": "语义：黑板擦薄不合常理，与“上面一个字也没有”的意思无关。"}, {"text": "脏", "is_correct": false, "explanation": "语义：“擦脏”与“上面一个字也没有”的意思矛盾，不能用。"}], "explanations": {"净": "净：“擦净”说黑板擦得干干净净，与“上面一个字也没有”相合。", "软": "搭配：“软”多用于衣料、食物变软，不用来说擦黑板。", "薄": "语义：黑板擦薄不合常理，与“上面一个字也没有”的意思无关。", "脏": "语义：“擦脏”与“上面一个字也没有”的意思矛盾，不能用。"}, "sentence_index": 6, "correct_answer": "净"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个方案很净。", "explanation": "这里应该用〈可行〉。“净”指没有脏东西，不能用来评价方案能不能实行。"}, {"text": "这次旅行很净。", "explanation": "这里应该用〈愉快〉。“净”指没有脏东西，不能用来形容旅行的感受。"}, {"text": "这个问题很净。", "explanation": "这里应该用〈复杂〉。“净”指没有脏东西，不能用来说问题的繁简难易。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96049, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们把操场扫了净，才离开。", "corrected_sentence": "同学们把操场扫净了，才离开。", "error_description": "错误形式：“扫了净”；正确形式：“扫净了”。“净”是“扫”的结果补语，要紧跟动词，“了”放在补语后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96049, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窗台上的油太多，擦不得净。", "corrected_sentence": "窗台上的油太多，擦不净。", "error_description": "错误形式：“擦不得净”；正确形式：“擦不净”。“净”作可能补语时，否定式是“动词＋不＋净”，中间不加“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96050, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脏", "is_correct": true, "explanation": "脏：与“干净”相反，指有污垢、杂质，正与“没有杂质”相对。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：形容光线或颜色鲜亮，与“干净”没有反义关系。"}, {"text": "光滑", "is_correct": false, "explanation": "光滑：形容表面平而滑，与“干净”没有反义关系。"}, {"text": "高大", "is_correct": false, "explanation": "高大：形容个子或体积大，与“干净”没有反义关系。"}], "correct_answer": "脏", "explanations": {"脏": "脏：与“干净”相反，指有污垢、杂质，正与“没有杂质”相对。", "明亮": "明亮：形容光线或颜色鲜亮，与“干净”没有反义关系。", "光滑": "光滑：形容表面平而滑，与“干净”没有反义关系。", "高大": "高大：形容个子或体积大，与“干净”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
