INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96050, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "干净，没有杂质。", "primary_collocate": null, "pronunciation": "jìng", "ipa": "tɕiŋ˥˩", "syllable_count": 1, "sentences": [{"text": "吃饭以前，要把手洗净。", "target_word": "净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把桌子擦净了，才放上饭菜。", "target_word": "净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蔬菜要洗净再切。", "target_word": "净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户擦净了，外面的树看得清清楚楚。", "target_word": "净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把碗筷刷净，放进了柜子里。", "target_word": "净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地板扫净以后，我们才开始做游戏。", "target_word": "净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服上的泥洗不净，只好重新买一件。", "target_word": "净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把灶台擦净了，一点儿油都没有。", "target_word": "净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用毛巾把脸擦净，然后走出了房间。", "target_word": "净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子没洗净，里面还有一点茶叶。", "target_word": "净", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "淨", "label": "繁体"}, {"form": "干净", "label": "复合"}, {"form": "洁净", "label": "复合"}], "register": "中性", "sense_fingerprint": "净：干净，没有杂质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '277212ec-c05c-4f82-b617-5b3b2e2110c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96050, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "净", "is_correct": true, "explanation": "净 jìng（第四声）：干净，没有杂质，即本词。"}, {"text": "进", "is_correct": false, "explanation": "jìn 与 jìng 韵母不同（in 与 ing），意思是“向里走”，即“进入”。"}, {"text": "近", "is_correct": false, "explanation": "jìn 与 jìng 韵母不同（in 与 ing），意思是“距离短”。"}, {"text": "经", "is_correct": false, "explanation": "jīng（第一声）与 jìng（第四声）声调不同，意思是“经过”。"}, {"text": "精", "is_correct": false, "explanation": "jīng（第一声）与 jìng（第四声）声调不同，意思是“精细、精力”。"}, {"text": "景", "is_correct": false, "explanation": "jǐng（第三声）与 jìng（第四声）声调不同，意思是“风景”。"}, {"text": "井", "is_correct": false, "explanation": "jǐng（第三声）与 jìng（第四声）声调不同，意思是“水井”。"}], "explanations": {"净": "净 jìng（第四声）：干净，没有杂质，即本词。", "进": "jìn 与 jìng 韵母不同（in 与 ing），意思是“向里走”，即“进入”。", "近": "jìn 与 jìng 韵母不同（in 与 ing），意思是“距离短”。", "经": "jīng（第一声）与 jìng（第四声）声调不同，意思是“经过”。", "精": "jīng（第一声）与 jìng（第四声）声调不同，意思是“精细、精力”。", "景": "jǐng（第三声）与 jìng（第四声）声调不同，意思是“风景”。", "井": "jǐng（第三声）与 jìng（第四声）声调不同，意思是“水井”。"}, "sentence_index": null, "correct_answer": "净"}, "level_3": {"options": [{"text": "净", "is_correct": true, "explanation": "净：“洗净”是结果补语，说手洗得干干净净，符合饭前洗手的意思。"}, {"text": "烂", "is_correct": false, "explanation": "语义：把手洗烂会伤到手，与“吃饭前洗手”的意思相反。"}, {"text": "破", "is_correct": false, "explanation": "语义：“洗破”指把东西洗出破洞，不能用于手，与“吃饭前洗手”的意思不合。"}, {"text": "白", "is_correct": false, "explanation": "搭配：“洗白”多用于衣服、布料，不用来说手洗得干净。"}], "explanations": {"净": "净：“洗净”是结果补语，说手洗得干干净净，符合饭前洗手的意思。", "烂": "语义：把手洗烂会伤到手，与“吃饭前洗手”的意思相反。", "破": "语义：“洗破”指把东西洗出破洞，不能用于手，与“吃饭前洗手”的意思不合。", "白": "搭配：“洗白”多用于衣服、布料，不用来说手洗得干净。"}, "sentence_index": 0, "correct_answer": "净"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他骑自行车骑得很净。", "explanation": "这里应该用〈熟练〉。“净”表示干净、没有杂质，不能用来说动作做得是否熟练。"}, {"text": "她过得很净。", "explanation": "这里应该用〈快乐〉。“净”只表示没有脏东西，不能用来说人生活得开心与否。"}, {"text": "这次考试他考得很净。", "explanation": "这里应该用〈轻松〉。“净”只表示没有杂质，不能用来形容考试时的感觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96050, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "净", "is_correct": true, "explanation": "净 jìng（第四声）：干净，没有杂质，即本词。"}, {"text": "尽", "is_correct": false, "explanation": "jìn 与 jìng 韵母不同（in 与 ing），意思是“尽力”。"}, {"text": "惊", "is_correct": false, "explanation": "jīng（第一声）与 jìng（第四声）声调不同，意思是“吃惊”。"}, {"text": "警", "is_correct": false, "explanation": "jǐng（第三声）与 jìng（第四声）声调不同，意思是“警察”。"}, {"text": "晶", "is_correct": false, "explanation": "jīng（第一声）与 jìng（第四声）声调不同，意思是“水晶”。"}], "explanations": {"净": "净 jìng（第四声）：干净，没有杂质，即本词。", "尽": "jìn 与 jìng 韵母不同（in 与 ing），意思是“尽力”。", "惊": "jīng（第一声）与 jìng（第四声）声调不同，意思是“吃惊”。", "警": "jǐng（第三声）与 jìng（第四声）声调不同，意思是“警察”。", "晶": "jīng（第一声）与 jìng（第四声）声调不同，意思是“水晶”。"}, "sentence_index": null, "correct_answer": "净"}, "level_3": {"options": [{"text": "净", "is_correct": true, "explanation": "净：“洗不净”说洗不干净，与“只好重新买一件”的结果相合。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“洗亮”多用于器物洗后发光，不用来说泥洗不掉的情况。"}, {"text": "软", "is_correct": false, "explanation": "语义：泥洗不掉，不会“洗软”，“软”与“泥洗不掉”的意思不合。"}, {"text": "薄", "is_correct": false, "explanation": "语义：“洗薄”指把衣服洗得变薄，与“衣服上的泥洗不掉”的情况不符。"}], "explanations": {"净": "净：“洗不净”说洗不干净，与“只好重新买一件”的结果相合。", "亮": "搭配：“洗亮”多用于器物洗后发光，不用来说泥洗不掉的情况。", "软": "语义：泥洗不掉，不会“洗软”，“软”与“泥洗不掉”的意思不合。", "薄": "语义：“洗薄”指把衣服洗得变薄，与“衣服上的泥洗不掉”的情况不符。"}, "sentence_index": 6, "correct_answer": "净"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对客人很净。", "explanation": "这里应该用〈热情〉。“净”只表示干净、没有杂质，不能用来形容对待客人的态度。"}, {"text": "这个问题他解释得很净。", "explanation": "这里应该用〈清楚〉。“净”只表示洁净、没有杂质，不能用来说讲解是否明白。"}, {"text": "这个消息让我很净。", "explanation": "这里应该用〈高兴〉。“净”只表示没有杂质，不能用来说人的心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96050, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把碗洗了净，才吃饭。", "corrected_sentence": "他把碗洗净了，才吃饭。", "error_description": "错误形式：“洗了净”；正确形式：“洗净了”。“净”是“洗”的结果补语，必须紧跟动词，“了”放在补语后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96050, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "黑板上的字太多，一下子擦不得净。", "corrected_sentence": "黑板上的字太多，一下子擦不净。", "error_description": "错误形式：“擦不得净”；正确形式：“擦不净”。“净”作可能补语时，否定式是“动词＋不＋净”，中间不加“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9250f392-104e-4b0e-b19e-4a4113f0cba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
