INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96052, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "口径较大的发射炮弹的武器。", "primary_collocate": null, "pronunciation": "pào", "ipa": "pʰɑʊ˥˩", "syllable_count": 1, "sentences": [{"text": "军队买了几门新炮，口径都很大。", "target_word": "炮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种炮可以打得很远，口径也大。", "target_word": "炮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船上装着两门炮，用来保护海港。", "target_word": "炮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在军队里学习怎么用炮打远处的目标。", "target_word": "炮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的炮对着大海，守着这座城市。", "target_word": "炮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在造一种口径更大的炮。", "target_word": "炮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门炮的口径比那门大得多。", "target_word": "炮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部队在山下摆好炮，等着命令开火。", "target_word": "炮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一听到开炮的命令，战士们马上捂住耳朵。", "target_word": "炮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种炮比枪大得多，也打得更远。", "target_word": "炮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "门", "label": "量词"}, {"form": "大炮", "label": "复合"}], "register": "中性", "sense_fingerprint": "口径较大、发射炮弹的武器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a9ccfdf-6e54-4f66-b305-2e8ae631542e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96052, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "炮", "is_correct": true, "explanation": "正确：炮（pào）指口径较大、发射炮弹的武器。"}, {"text": "跑", "is_correct": false, "explanation": "跑（pǎo）与 pào 声调不同（第三声与第四声），意思是奔跑。"}, {"text": "袍", "is_correct": false, "explanation": "袍（páo）与 pào 声调不同（第二声与第四声），意思是长衣服，如长袍。"}, {"text": "抱", "is_correct": false, "explanation": "抱（bào）与 pào 声母不同：bào 的 b 不送气，pào 的 p 送气，意思是用手臂围住。"}, {"text": "报", "is_correct": false, "explanation": "报（bào）与 pào 声母不同（b 不送气，p 送气），意思是报纸、报告。"}], "explanations": {"炮": "正确：炮（pào）指口径较大、发射炮弹的武器。", "跑": "跑（pǎo）与 pào 声调不同（第三声与第四声），意思是奔跑。", "袍": "袍（páo）与 pào 声调不同（第二声与第四声），意思是长衣服，如长袍。", "抱": "抱（bào）与 pào 声母不同：bào 的 b 不送气，pào 的 p 送气，意思是用手臂围住。", "报": "报（bào）与 pào 声母不同（b 不送气，p 送气），意思是报纸、报告。"}, "sentence_index": null, "correct_answer": "炮"}, "level_3": {"options": [{"text": "炮", "is_correct": true, "explanation": "正确：炮是口径较大的发射炮弹的武器，“口径”说的正是它。"}, {"text": "课", "is_correct": false, "explanation": "语义：课程没有口径，“口径都很大”只能用来说武器。"}, {"text": "技术", "is_correct": false, "explanation": "语义：技术不能说口径，句子说的是武器的大小。"}, {"text": "功夫", "is_correct": false, "explanation": "搭配：“口径”是枪炮的属性，不说功夫的口径。"}], "explanations": {"炮": "正确：炮是口径较大的发射炮弹的武器，“口径”说的正是它。", "课": "语义：课程没有口径，“口径都很大”只能用来说武器。", "技术": "语义：技术不能说口径，句子说的是武器的大小。", "功夫": "搭配：“口径”是枪炮的属性，不说功夫的口径。"}, "sentence_index": 0, "correct_answer": "炮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一手举起炮，瞄准了远处的目标。", "explanation": "这里应该用〈枪〉。“一手举起”只用于能单手拿的武器，炮体积大，不能这样使用。"}, {"text": "他把炮移到中间，准备吃掉对方的车。", "explanation": "这里的“炮”指象棋棋子，不是口径较大的武器；棋子义与本句的武器义不是同一个义项。"}, {"text": "那颗炮很重，士兵们抬了很久。", "explanation": "这里应该用〈门〉。炮用量词“门”，“颗”多用于炸弹、子弹等小而圆的东西，用于炮是错误的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '682f6383-c6cd-45a0-a84b-998ce6094ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96052, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "炮", "is_correct": true, "explanation": "正确：炮（pào）指口径较大、发射炮弹的武器。"}, {"text": "刨", "is_correct": false, "explanation": "刨（páo）与 pào 声调不同（第二声与第四声），意思是用刨子削平木头。"}, {"text": "豹", "is_correct": false, "explanation": "豹（bào）与 pào 声母不同：bào 的 b 不送气，pào 的 p 送气，意思是豹子。"}, {"text": "暴", "is_correct": false, "explanation": "暴（bào）与 pào 声母不同（b 不送气，p 送气），意思是猛烈、凶暴。"}, {"text": "爆", "is_correct": false, "explanation": "爆（bào）与 pào 声母不同（b 不送气，p 送气），意思是爆炸、爆开。"}], "explanations": {"炮": "正确：炮（pào）指口径较大、发射炮弹的武器。", "刨": "刨（páo）与 pào 声调不同（第二声与第四声），意思是用刨子削平木头。", "豹": "豹（bào）与 pào 声母不同：bào 的 b 不送气，pào 的 p 送气，意思是豹子。", "暴": "暴（bào）与 pào 声母不同（b 不送气，p 送气），意思是猛烈、凶暴。", "爆": "爆（bào）与 pào 声母不同（b 不送气，p 送气），意思是爆炸、爆开。"}, "sentence_index": null, "correct_answer": "炮"}, "level_3": {"options": [{"text": "炮", "is_correct": true, "explanation": "正确：炮的口径可以比较大小，符合句意。"}, {"text": "手艺", "is_correct": false, "explanation": "语义：手艺谈不上口径，句子比较的是武器的大小。"}, {"text": "学问", "is_correct": false, "explanation": "搭配：“口径”是枪炮的属性，不能用来说学问。"}, {"text": "技艺", "is_correct": false, "explanation": "语义：技艺没有口径，与“口径比那门大得多”不合。"}], "explanations": {"炮": "正确：炮的口径可以比较大小，符合句意。", "手艺": "语义：手艺谈不上口径，句子比较的是武器的大小。", "学问": "搭配：“口径”是枪炮的属性，不能用来说学问。", "技艺": "语义：技艺没有口径，与“口径比那门大得多”不合。"}, "sentence_index": 6, "correct_answer": "炮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把炮装进了弹夹。", "explanation": "这里应该用〈子弹〉。装进弹夹的是子弹，炮太大，装不进弹夹。"}, {"text": "他一把将炮抛下山坡。", "explanation": "这里应该用〈手雷〉。“抛”多用于手能拿的小件东西，炮太重，抛不动。"}, {"text": "他买了一只炮，放在院子里。", "explanation": "这里应该用〈门〉。炮用量词“门”，“只”多用于动物或成对的东西，用于炮是错误的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '682f6383-c6cd-45a0-a84b-998ce6094ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96052, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只炮的口径很大，射程也远。", "corrected_sentence": "这门炮的口径很大，射程也远。", "error_description": "量词错误：炮要用量词“门”，“只”多用于动物，不能说“这只炮”。应说“这门炮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '682f6383-c6cd-45a0-a84b-998ce6094ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96052, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那门炮打很远，士兵们都很佩服。", "corrected_sentence": "那门炮打得很远，士兵们都很佩服。", "error_description": "补语错误：“打得很远”中间要有“得”连接补语，不能说“打很远”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '682f6383-c6cd-45a0-a84b-998ce6094ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
