INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96053, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "牧师是在教堂里工作、给人讲道的人。", "primary_collocate": null, "pronunciation": "mù shī", "ipa": "mu˥˩ ʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "牧师是在教堂里工作的人。", "target_word": "牧师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牧师住在教堂后面的小房子里。", "target_word": "牧师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个星期日，牧师都在教堂里讲话。", "target_word": "牧师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爸爸是牧师，他从小就去教堂。", "target_word": "牧师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牧师穿着黑衣服站在前面。", "target_word": "牧师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牧师和教会的朋友一起帮助穷人。", "target_word": "牧师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去教堂问牧师一个问题。", "target_word": "牧师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牧师的声音很温和，大家都喜欢听他讲。", "target_word": "牧师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇只有一位牧师。", "target_word": "牧师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牧师给孩子们讲了一个故事。", "target_word": "牧师", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "牧師", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在教堂工作、向人们讲道的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dd71c1-9209-4d12-a308-62a2880ffae2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96053, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "牧师", "is_correct": true, "explanation": "正确：“牧师”指在教堂工作、讲道的人，符合句意。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生的工作地点是医院，不说在教堂工作。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷不是在教堂里工作的人，句子指的是教会的职务。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“是…的人”要求主语是人，“窗户”不能作这个句子的主语。"}], "explanations": {"牧师": "正确：“牧师”指在教堂工作、讲道的人，符合句意。", "医生": "语义：医生的工作地点是医院，不说在教堂工作。", "小偷": "语义：小偷不是在教堂里工作的人，句子指的是教会的职务。", "窗户": "配价：“是…的人”要求主语是人，“窗户”不能作这个句子的主语。"}, "sentence_index": 0, "correct_answer": "牧师"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位牧师每天早上都在工厂里修机器。", "explanation": "这里应该用〈工人〉。修机器是工人的工作，牧师是教会里的神职人员，不做这类工作。"}, {"text": "牧师在医院里给病人看病。", "explanation": "这里应该用〈医生〉。给病人看病是医生的工作，牧师是教会里的神职人员，不负责看病。"}, {"text": "教堂门口坐着一只牧师。", "explanation": "这里应该用〈位〉。指人的神职人员用“位”或“个”，“只”一般用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96053, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "牧师", "is_correct": true, "explanation": "正确：“牧师”是能回答问题、可以请教的人，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能回答问题，去教堂不会去问石头。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是教室里的物品，不能被问问题。"}, {"text": "沙发", "is_correct": false, "explanation": "配价：“问”需要能回答的对象，“沙发”无法作为提问的对象。"}], "explanations": {"牧师": "正确：“牧师”是能回答问题、可以请教的人，符合句意。", "石头": "语义：石头不能回答问题，去教堂不会去问石头。", "黑板": "语义：黑板是教室里的物品，不能被问问题。", "沙发": "配价：“问”需要能回答的对象，“沙发”无法作为提问的对象。"}, "sentence_index": 6, "correct_answer": "牧师"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "牧师每天早上都在寺庙里念经。", "explanation": "这里应该用〈和尚〉。念经、寺庙属于佛教，牧师是基督教的神职人员。"}, {"text": "牧师在道观里画符。", "explanation": "这里应该用〈道士〉。道观和画符是道教的场所与做法，牧师不能用于这种情境。"}, {"text": "我们村来了一座牧师，大家都去看。", "explanation": "这里应该用〈位〉。量词“座”用于山、桥、建筑等大型物体，指人应用“位”或“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96053, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们教堂来了一座牧师。", "corrected_sentence": "我们教堂来了一位牧师。", "error_description": "量词错误：指人的“牧师”应用“位”或“个”，“座”用于大型建筑或山，不用来数人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96053, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们教会来了一张新牧师。", "corrected_sentence": "我们教会来了一位新牧师。", "error_description": "量词错误：“张”用于桌子、纸等平面物品。指人的“牧师”应该用“位”或“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
