INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96054, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "基督教会中主持礼拜、传讲教义的神职人员。", "primary_collocate": null, "pronunciation": "mù shī", "ipa": "mu˥˩ ʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "牧师在教会里给大家讲教义。", "target_word": "牧师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星期天，牧师主持了礼拜。", "target_word": "牧师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位牧师讲得很有意思。", "target_word": "牧师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牧师请大家一起唱圣歌。", "target_word": "牧师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想长大后当牧师。", "target_word": "牧师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牧师读了一段圣经，大家安静地听。", "target_word": "牧师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新人在教堂里请牧师主持婚礼。", "target_word": "牧师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的牧师每周都去医院看病人。", "target_word": "牧师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牧师对大家说，要爱别人。", "target_word": "牧师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老牧师在这个教会工作了三十年。", "target_word": "牧师", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "牧師", "label": "繁体"}], "register": "中性", "sense_fingerprint": "基督教会中主持礼拜、讲解教义的神职人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97dd71c1-9209-4d12-a308-62a2880ffae2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96054, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "牧师", "is_correct": true, "explanation": "正确：“牧师”是教会里主持礼拜、讲解教义的人，符合句意。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生不在教会里讲教义，句子说的是讲解宗教内容的神职人员。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师的工作是做饭，不会在教会里给大家讲教义。"}, {"text": "椅子", "is_correct": false, "explanation": "配价：“讲教义”需要有生命的施讲人，“椅子”不能充当讲的主语。"}], "explanations": {"牧师": "正确：“牧师”是教会里主持礼拜、讲解教义的人，符合句意。", "医生": "语义：医生不在教会里讲教义，句子说的是讲解宗教内容的神职人员。", "厨师": "语义：厨师的工作是做饭，不会在教会里给大家讲教义。", "椅子": "配价：“讲教义”需要有生命的施讲人，“椅子”不能充当讲的主语。"}, "sentence_index": 0, "correct_answer": "牧师"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门口来了一只牧师，想跟你谈谈。", "explanation": "这里应该用〈位〉。指人的神职人员用“位”或“个”，“只”一般用于动物。"}, {"text": "这位牧师每天早上都去教堂主持弥撒。", "explanation": "这里应该用〈神父〉。弥撒是天主教的礼仪，主持弥撒的是神父；牧师是新教的神职人员，主持的是礼拜。"}, {"text": "这位牧师每天给病人开药。", "explanation": "这里应该用〈医生〉。开药是医生的工作，牧师是教会里的神职人员，不负责给病人开药。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96054, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "牧师", "is_correct": true, "explanation": "正确：“牧师”可以主持婚礼，符合“请…主持婚礼”的搭配。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机不负责主持婚礼，句中需要的是婚礼的主持人。"}, {"text": "清洁工", "is_correct": false, "explanation": "语义：清洁工的工作是打扫卫生，不会受邀主持婚礼。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“主持婚礼”需要有生命、能主持的人作施事，“窗户”不能充当。"}], "explanations": {"牧师": "正确：“牧师”可以主持婚礼，符合“请…主持婚礼”的搭配。", "司机": "语义：司机不负责主持婚礼，句中需要的是婚礼的主持人。", "清洁工": "语义：清洁工的工作是打扫卫生，不会受邀主持婚礼。", "窗户": "配价：“主持婚礼”需要有生命、能主持的人作施事，“窗户”不能充当。"}, "sentence_index": 6, "correct_answer": "牧师"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "牧师每天早上都在寺庙里念经。", "explanation": "这里应该用〈和尚〉。念经、寺庙属于佛教，牧师是基督教的神职人员，不在寺庙里念经。"}, {"text": "牧师在道观里画符。", "explanation": "这里应该用〈道士〉。道观和画符是道教的场所与做法，牧师不能用于道士的情境。"}, {"text": "我们村来了一辆牧师，大家都去看。", "explanation": "这里应该用〈位〉。量词“辆”用于车辆，指人的牧师应用“位”或“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96054, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们教会新来了一座牧师。", "corrected_sentence": "我们教会新来了一位牧师。", "error_description": "量词错误：指人的“牧师”应用“位”或“个”，“座”用于山、桥、建筑等大型物体，不用来数人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96054, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们教会请了一辆牧师。", "corrected_sentence": "我们教会请了一位牧师。", "error_description": "量词错误：“辆”用于车辆。指人的“牧师”应该用“位”或“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dbfbe5c-b015-4954-b42a-7de843d8b4e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
