INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96059, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发掘是把埋在地下的东西挖出来。", "primary_collocate": null, "pronunciation": "fā jué", "ipa": "fa˥ tɕyɛ˧˥", "syllable_count": 2, "sentences": [{"text": "考古学家在这里发掘了一座古城。", "target_word": "发掘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民在地里发掘出一个很旧的铜罐。", "target_word": "发掘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家们正在发掘这片古墓。", "target_word": "发掘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这批文物是去年在河边发掘的。", "target_word": "发掘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们发掘过很多恐龙化石。", "target_word": "发掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把地下的石碑发掘出来了。", "target_word": "发掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发掘这座古墓要花一年时间。", "target_word": "发掘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们跟着老师去山上发掘化石。", "target_word": "发掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考古队在沙漠里发掘着一座古老的城市。", "target_word": "发掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村子附近发掘出了很多古代的钱币。", "target_word": "发掘", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "发掘了", "label": "完成体"}, {"form": "发掘过", "label": "经历体"}, {"form": "发掘着", "label": "持续体"}, {"form": "发掘出来", "label": "复合趋向补语"}], "register": "中性", "sense_fingerprint": "把埋在地下的文物、化石等挖出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9b23817-999c-46c1-a554-f63ab669589a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96059, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发掘", "is_correct": true, "explanation": "正确：发掘指把埋在地下的东西挖出来，符合考古学家挖出古城的情境。"}, {"text": "邮寄", "is_correct": false, "explanation": "搭配：“邮寄”的对象是信件、包裹等，不能说“邮寄了一座古城”。"}, {"text": "掩埋", "is_correct": false, "explanation": "语义：掩埋是把东西埋起来，与“发掘了”把东西挖出来的意思相反。"}, {"text": "粉刷", "is_correct": false, "explanation": "搭配：“粉刷”多用于墙面，不能说“粉刷一座古城”。"}], "explanations": {"发掘": "正确：发掘指把埋在地下的东西挖出来，符合考古学家挖出古城的情境。", "邮寄": "搭配：“邮寄”的对象是信件、包裹等，不能说“邮寄了一座古城”。", "掩埋": "语义：掩埋是把东西埋起来，与“发掘了”把东西挖出来的意思相反。", "粉刷": "搭配：“粉刷”多用于墙面，不能说“粉刷一座古城”。"}, "sentence_index": 0, "correct_answer": "发掘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在河里发掘鱼。", "explanation": "这里应该用〈捕〉。发掘指挖出埋在地下的东西，鱼在水里要说〈捕〉（捕鱼）。"}, {"text": "农民在地里发掘了一只兔子。", "explanation": "这里应该用〈抓〉。发掘指挖出埋在地下的东西，抓活的动物要说〈抓〉。"}, {"text": "我们在森林里发掘失踪的孩子。", "explanation": "这里应该用〈寻找〉。发掘指挖出地下的东西，找人要说〈寻找〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96059, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发掘", "is_correct": true, "explanation": "正确：发掘指把埋在地下的东西挖出来，符合“这座古墓要花一年时间”的句意。"}, {"text": "烧毁", "is_correct": false, "explanation": "搭配：“烧毁”是一下子毁掉，不需要花一年时间，与句意不合。"}, {"text": "检阅", "is_correct": false, "explanation": "语义：检阅是检查队伍，不用于古墓。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”的对象多是火、烟花等，与“古墓”不搭配。"}], "explanations": {"发掘": "正确：发掘指把埋在地下的东西挖出来，符合“这座古墓要花一年时间”的句意。", "烧毁": "搭配：“烧毁”是一下子毁掉，不需要花一年时间，与句意不合。", "检阅": "语义：检阅是检查队伍，不用于古墓。", "点燃": "搭配：“点燃”的对象多是火、烟花等，与“古墓”不搭配。"}, "sentence_index": 6, "correct_answer": "发掘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人在果园里发掘苹果。", "explanation": "这里应该用〈采摘〉。发掘指挖出埋在地下的东西，苹果长在树上要说〈采摘〉。"}, {"text": "农民在地里发掘了麦子。", "explanation": "这里应该用〈割〉。发掘不用于收割庄稼，割麦子要说〈割〉。"}, {"text": "妈妈每天发掘房间。", "explanation": "这里应该用〈收拾〉。发掘指挖出东西，整理房间要说〈收拾〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96059, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "考古队正在山上发掘了着一座古墓。", "corrected_sentence": "考古队正在山上发掘着一座古墓。", "error_description": "体标用错：“正在”与持续体“着”搭配，“了”不能与“着”同用，应说“发掘着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96059, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们把那座古墓发掘出来了过。", "corrected_sentence": "工人们把那座古墓发掘出来了。", "error_description": "体标用错：“发掘出来”后只用一个体标，“了”表示完成、“过”表示经历，不能再加“过”，应说“发掘出来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
