INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96060, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指发现并找出潜在的人才、潜力或价值等。", "primary_collocate": null, "pronunciation": "fā jué", "ipa": "fa˥ tɕyɛ˧˥", "syllable_count": 2, "sentences": [{"text": "老师善于发掘学生的潜力。", "target_word": "发掘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司想发掘更多有才能的年轻人。", "target_word": "发掘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家常到农村发掘写作的素材。", "target_word": "发掘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教练从普通学生中发掘出了一个好苗子。", "target_word": "发掘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要把这个小镇的历史文化发掘出来。", "target_word": "发掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画很有价值，可惜没有人发掘。", "target_word": "发掘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理发掘了他的音乐才能，让他当了歌手。", "target_word": "发掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老校长发掘过不少有潜力的青年教师。", "target_word": "发掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好老师会帮学生发掘自己的兴趣。", "target_word": "发掘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "编辑正在发掘这位新作者的潜力。", "target_word": "发掘", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "发掘了", "label": "完成体"}, {"form": "发掘过", "label": "经历体"}, {"form": "发掘着", "label": "持续体"}, {"form": "发掘出来", "label": "复合趋向补语"}], "register": "中性", "sense_fingerprint": "发现并找出潜在的人才、潜力、价值等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9b23817-999c-46c1-a554-f63ab669589a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96060, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发掘", "is_correct": true, "explanation": "正确：发掘指发现并找出潜藏的能力，符合“善于……学生的潜力”。"}, {"text": "埋没", "is_correct": false, "explanation": "语义：埋没指使才能不被发现，与“善于”的积极语境相反。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：忽视是不重视，与“善于”所表达的积极态度相矛盾。"}, {"text": "收集", "is_correct": false, "explanation": "搭配：“收集”后面接具体事物，不能说“收集潜力”，搭配不成立。"}], "explanations": {"发掘": "正确：发掘指发现并找出潜藏的能力，符合“善于……学生的潜力”。", "埋没": "语义：埋没指使才能不被发现，与“善于”的积极语境相反。", "忽视": "语义：忽视是不重视，与“善于”所表达的积极态度相矛盾。", "收集": "搭配：“收集”后面接具体事物，不能说“收集潜力”，搭配不成立。"}, "sentence_index": 0, "correct_answer": "发掘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家农场每年发掘很多小麦。", "explanation": "这里应该用〈收获〉。发掘指发现并培养人才或潜力，庄稼要说〈收获〉。"}, {"text": "我每天晚上发掘作业，做完就睡觉。", "explanation": "这里应该用〈完成〉。发掘指发现并培养人才或潜力，不能用于作业，应说〈完成〉作业。"}, {"text": "妈妈在厨房里发掘了一锅好吃的饭。", "explanation": "这里应该用〈做〉。发掘不用于做饭，做饭要说〈做〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96060, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发掘", "is_correct": true, "explanation": "正确：发掘指发现并找出潜在的才能，符合“让他当了歌手”的结果。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：隐藏会使才能被遮住，与“让他当了歌手”的结果矛盾。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：放弃是不再重视，与“让他当了歌手”的因果关系相矛盾。"}, {"text": "消耗", "is_correct": false, "explanation": "搭配：“消耗”多用于体力、资源，“才能”不能作“消耗”的对象。"}], "explanations": {"发掘": "正确：发掘指发现并找出潜在的才能，符合“让他当了歌手”的结果。", "隐藏": "语义：隐藏会使才能被遮住，与“让他当了歌手”的结果矛盾。", "放弃": "语义：放弃是不再重视，与“让他当了歌手”的因果关系相矛盾。", "消耗": "搭配：“消耗”多用于体力、资源，“才能”不能作“消耗”的对象。"}, "sentence_index": 6, "correct_answer": "发掘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把旧家具发掘给了收藏家。", "explanation": "这里应该用〈卖〉。发掘指发现并培养人才或潜力，家具买卖要说〈卖〉。"}, {"text": "妈妈在河边发掘衣服。", "explanation": "这里应该用〈洗〉。发掘不能用于衣服，洗衣服要说〈洗〉。"}, {"text": "工人把箱子发掘进仓库。", "explanation": "这里应该用〈搬〉。发掘指发现并培养人才或潜力，搬运箱子要说〈搬〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96060, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "专家们想把这座古寺的历史发掘来。", "corrected_sentence": "专家们想把这座古寺的历史发掘出来。", "error_description": "补语用错：“发掘”后应加趋向补语“出来”，表示把潜藏的人才或潜力找出来，只说“发掘来”不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96060, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教练从队员中发掘了出一位很有潜力的球员。", "corrected_sentence": "教练从队员中发掘出了一位很有潜力的球员。", "error_description": "补语位置用错：趋向补语“出”应紧接在动词“发掘”之后，“了”放在“出”的后面。正确应说“发掘出了”，不能说“发掘了出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b90c504-1c97-402b-9e97-d3616962ee7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
