INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96062, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从事科学研究工作的人。", "primary_collocate": null, "pronunciation": "yán jiū rén yuán", "ipa": "jɛn³⁵ tɕjoʊ⁵⁵ ʐən³⁵ ɥɛn³⁵", "syllable_count": 4, "sentences": [{"text": "研究人员在实验室里做科学实验。", "target_word": "研究人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一名研究人员，在研究所工作。", "target_word": "研究人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员发现了一种新药。", "target_word": "研究人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员每个月都要写研究报告。", "target_word": "研究人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个研究所的研究人员都很年轻。", "target_word": "研究人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员用新方法做了一次实验。", "target_word": "研究人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的爸爸是研究人员，常常做科学研究。", "target_word": "研究人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员正在分析实验的结果。", "target_word": "研究人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员希望能找到治病的方法。", "target_word": "研究人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请了几位研究人员来做试验。", "target_word": "研究人员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "研究人員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从事科学研究工作的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ae03713-7b77-404a-928c-a57fedb969c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96062, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "演员", "is_correct": false, "explanation": "语义：演员的工作是表演，不在实验室里做科学实验。"}, {"text": "研究人员", "is_correct": true, "explanation": "正确：研究人员是从事科学研究工作的人，可以在实验室里做科学实验。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师的工作是做饭，与科学实验无关。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民的工作是种地，与实验室里的科学实验无关。"}], "explanations": {"演员": "语义：演员的工作是表演，不在实验室里做科学实验。", "研究人员": "正确：研究人员是从事科学研究工作的人，可以在实验室里做科学实验。", "厨师": "语义：厨师的工作是做饭，与科学实验无关。", "农民": "语义：农民的工作是种地，与实验室里的科学实验无关。"}, "sentence_index": 0, "correct_answer": "研究人员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在研究人员里看病。", "explanation": "这里应该用〈医院〉。看病的场所是医院；研究人员指人，不能作场所。"}, {"text": "张研究人员明天要参加会议。", "explanation": "这里应该用〈研究员〉。〈研究员〉是职称，“张研究员”才对；〈研究人员〉不能作职称。"}, {"text": "我们所的研究人员每天给大家炒菜。", "explanation": "这里应该用〈厨师〉。炒菜是厨师的工作；研究人员从事科学研究，不负责炒菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96062, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工人", "is_correct": false, "explanation": "语义：工人的职业与科学研究无关，与后句“常常做科学研究”矛盾。"}, {"text": "研究人员", "is_correct": true, "explanation": "正确：研究人员是从事科学研究工作的人，与“常常做科学研究”一致。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机开车，与“做科学研究”的工作内容不符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师的工作是做饭，与“常常做科学研究”不符。"}], "explanations": {"工人": "语义：工人的职业与科学研究无关，与后句“常常做科学研究”矛盾。", "研究人员": "正确：研究人员是从事科学研究工作的人，与“常常做科学研究”一致。", "司机": "语义：司机开车，与“做科学研究”的工作内容不符。", "厨师": "语义：厨师的工作是做饭，与“常常做科学研究”不符。"}, "sentence_index": 6, "correct_answer": "研究人员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "研究人员每天在火车站卖票。", "explanation": "这里应该用〈售票员〉。卖票是售票员的工作；研究人员从事科学研究，不在火车站卖票。"}, {"text": "研究人员每天在路口指挥交通。", "explanation": "这里应该用〈交警〉。指挥路口交通是交警的职责；研究人员从事科学研究，不做这项工作。"}, {"text": "他在超市当研究人员，每天收银。", "explanation": "这里应该用〈收银员〉。收银是收银员的工作；研究人员从事科学研究，不在超市收银。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96062, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只研究人员在实验室里分析数据。", "corrected_sentence": "一位研究人员在实验室里分析数据。", "error_description": "量词错误：〈研究人员〉指人，量词应用〈位〉。〈只〉用于动物，“一只研究人员”是错的，应改为“一位研究人员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96062, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她研究人员，负责做实验。", "corrected_sentence": "她是研究人员，负责做实验。", "error_description": "句式错误：表示身份的判断句缺少〈是〉，应说“是研究人员”，不能直接用名词作谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
