INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96063, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "研究报告是把研究的结果写下来的文章。", "primary_collocate": null, "pronunciation": "yán jiū bào gào", "ipa": "jɛn˧˥ tɕjoʊ˥ pɑʊ˥˩ kɑʊ˥˩", "syllable_count": 4, "sentences": [{"text": "老师让我们每人写一份研究报告。", "target_word": "研究报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的研究报告写得很清楚。", "target_word": "研究报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天把研究报告交给了老师。", "target_word": "研究报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇研究报告有二十页。", "target_word": "研究报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究报告里有很多图片。", "target_word": "研究报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你先读一下这份研究报告。", "target_word": "研究报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用一个星期写完了研究报告。", "target_word": "研究报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份研究报告的结论写得很简洁。", "target_word": "研究报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份研究报告是我们小组一起写的。", "target_word": "研究报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在网上找到一份关于睡眠的研究报告。", "target_word": "研究报告", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "篇", "label": "量词"}], "register": "书面", "sense_fingerprint": "写下研究结果的文章", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddc45bb0-7584-458b-8100-4763b256d8ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96063, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研究报告", "is_correct": true, "explanation": "正确。“一份”可以与书面文件搭配，人可以“写”研究报告。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“写”不能与“午饭”搭配，午饭不能写。"}, {"text": "大海", "is_correct": false, "explanation": "语义：“大海”不是文字，不能写成一份。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：“闹钟”是器具，不是可以写的文件。"}], "explanations": {"研究报告": "正确。“一份”可以与书面文件搭配，人可以“写”研究报告。", "午饭": "搭配：“写”不能与“午饭”搭配，午饭不能写。", "大海": "语义：“大海”不是文字，不能写成一份。", "闹钟": "语义：“闹钟”是器具，不是可以写的文件。"}, "sentence_index": 0, "correct_answer": "研究报告"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只研究报告有二十页。", "explanation": "这里应该用〈篇〉或〈份〉。“只”用于动物等，不能用来数研究报告。"}, {"text": "这台研究报告有二十页。", "explanation": "这里应该用〈篇〉或〈份〉。“台”用于机器、电器，不能用来数研究报告。"}, {"text": "这把研究报告有二十页。", "explanation": "这里应该用〈篇〉或〈份〉。“把”用于有柄的东西，不能用来数研究报告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96063, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研究报告", "is_correct": true, "explanation": "正确。“写完了”之后接书面成果，符合“一个星期”的语境。"}, {"text": "饺子", "is_correct": false, "explanation": "搭配：“写”不能与“饺子”搭配，饺子是包出来的。"}, {"text": "大桥", "is_correct": false, "explanation": "语义：“大桥”是建筑，不能用“写”完成。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是用品，不能被写完。"}], "explanations": {"研究报告": "正确。“写完了”之后接书面成果，符合“一个星期”的语境。", "饺子": "搭配：“写”不能与“饺子”搭配，饺子是包出来的。", "大桥": "语义：“大桥”是建筑，不能用“写”完成。", "雨伞": "语义：“雨伞”是用品，不能被写完。"}, "sentence_index": 6, "correct_answer": "研究报告"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "研究报告每年都有很多人来参观。", "explanation": "这里应该用〈研究所〉。研究所是机构，人们可以去参观；研究报告是文件，不能作为参观的地点。"}, {"text": "研究报告每天都在实验室里做实验。", "explanation": "这里应该用〈研究员〉。研究员是人，会在实验室做实验；研究报告是文件，不能做实验。"}, {"text": "研究报告每天都在医院里看病。", "explanation": "这里应该用〈医生〉。医生是人，会给病人看病；研究报告是文件，不能看病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96063, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我看了一只关于睡眠的研究报告。", "corrected_sentence": "我看了一份关于睡眠的研究报告。", "error_description": "量词错误：“研究报告”是文件，应用量词“份”，“只”用于动物等，不能用来数研究报告；应说“一份关于睡眠的研究报告”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96063, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她用一个星期写完了一条研究报告。", "corrected_sentence": "她用一个星期写完了一份研究报告。", "error_description": "量词错误：研究报告是文件，应用份；条用于细长的东西，不能用来数研究报告。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
