INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96064, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "记录并说明研究过程和结果的书面文件。", "primary_collocate": null, "pronunciation": "yán jiū bào gào", "ipa": "jɛn˧˥ tɕjoʊ˥ pɑʊ˥˩ kɑʊ˥˩", "syllable_count": 4, "sentences": [{"text": "研究报告要写清楚方法和结果。", "target_word": "研究报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司发表了一份新的研究报告。", "target_word": "研究报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份研究报告记录了整个实验过程。", "target_word": "研究报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生们正在讨论那份研究报告。", "target_word": "研究报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究报告的第一页是内容简介。", "target_word": "研究报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生要按时提交研究报告。", "target_word": "研究报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份研究报告说，年轻人睡得太少。", "target_word": "研究报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把研究报告打印出来了。", "target_word": "研究报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究报告需要老师签名。", "target_word": "研究报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家研究所每年出一份研究报告。", "target_word": "研究报告", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "篇", "label": "量词"}], "register": "书面", "sense_fingerprint": "记录研究过程和结果的正式书面文件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddc45bb0-7584-458b-8100-4763b256d8ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96064, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研究报告", "is_correct": true, "explanation": "正确。“要写清楚方法和结果”的主语应是书面文件。"}, {"text": "日出", "is_correct": false, "explanation": "语义：“日出”是自然现象，不是文字，无法写清楚方法和结果。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：“雨水”不是书面文件，无法写清楚方法和结果。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：“写清楚”不能与“咖啡”搭配，咖啡不能用来写。"}], "explanations": {"研究报告": "正确。“要写清楚方法和结果”的主语应是书面文件。", "日出": "语义：“日出”是自然现象，不是文字，无法写清楚方法和结果。", "雨水": "语义：“雨水”不是书面文件，无法写清楚方法和结果。", "咖啡": "搭配：“写清楚”不能与“咖啡”搭配，咖啡不能用来写。"}, "sentence_index": 0, "correct_answer": "研究报告"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生们正在讨论那棵研究报告。", "explanation": "这里应该用〈份〉或〈篇〉。“棵”用于树木、植物，不能用于研究报告。"}, {"text": "医生们正在讨论那条研究报告。", "explanation": "这里应该用〈份〉或〈篇〉。“条”用于细长的东西，不能用于研究报告。"}, {"text": "医生们正在讨论那座研究报告。", "explanation": "这里应该用〈份〉或〈篇〉。“座”用于建筑、山等，不能用于研究报告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96064, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研究报告", "is_correct": true, "explanation": "正确。研究报告是书面文件，可以“说”出结论。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：“小猫”不会说话，不能作为“说”的主语。"}, {"text": "朋友", "is_correct": false, "explanation": "搭配：“份”不用于人，“这份朋友”不能说。"}, {"text": "冰淇淋", "is_correct": false, "explanation": "语义：“冰淇淋”是食物，不会说话。"}], "explanations": {"研究报告": "正确。研究报告是书面文件，可以“说”出结论。", "小猫": "语义：“小猫”不会说话，不能作为“说”的主语。", "朋友": "搭配：“份”不用于人，“这份朋友”不能说。", "冰淇淋": "语义：“冰淇淋”是食物，不会说话。"}, "sentence_index": 6, "correct_answer": "研究报告"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份研究报告很好吃，我吃了两碗。", "explanation": "这里应该用〈面条〉。面条可以吃；研究报告是书面文件，不能吃。"}, {"text": "这份研究报告每天早上七点起床上班。", "explanation": "这里应该用〈员工〉。员工会起床上班；研究报告是文件，不能起床上班。"}, {"text": "这份研究报告一边跑步一边唱歌。", "explanation": "这里应该用〈歌手〉。歌手可以一边跑步一边唱歌；研究报告是文件，不能跑步唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96064, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些研究报告们都很长。", "corrected_sentence": "这些研究报告都很长。", "error_description": "“们”只用于指人的名词，“研究报告”是文件，不能说“研究报告们”，应说“这些研究报告”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96064, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于写完了一把研究报告。", "corrected_sentence": "他终于写完了一份研究报告。", "error_description": "量词错误：把用于有柄的东西，研究报告是文件，应用份或篇。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a593ede-8faf-4654-8649-7530da13d11e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
