INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96065, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "社长是一个社团或社里最大的负责人。", "primary_collocate": null, "pronunciation": "shè zhǎng", "ipa": "ʂɤ˥˩ tʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "摄影社的社长是小王。", "target_word": "社长", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们的社长很会组织活动。", "target_word": "社长", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "读书社的社长每个月选一本书。", "target_word": "社长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "社团开会时，社长先说话。", "target_word": "社长", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想问问社长，下周的活动在哪儿。", "target_word": "社长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她是学校戏剧社的社长，每周都排练。", "target_word": "社长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年社团换了负责人，现在的社长是大三的学生。", "target_word": "社长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社长把新同学介绍给了社里的老同学。", "target_word": "社长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要加入我们社，先去找社长报名。", "target_word": "社长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "社长一直笑着听大家的意见，没有说一句话。", "target_word": "社长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "副社长", "label": "复合"}, {"form": "社長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "社长｜学生社团、兴趣社里最大的负责人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '583bb385-0709-452e-bca1-846a97360e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96065, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "社长", "is_correct": true, "explanation": "正确。社长（shè zhǎng）指社团的负责人。"}, {"text": "设厂", "is_correct": false, "explanation": "chǎng 与 zhǎng 只差声母 ch 与 zh，声调相同；设厂意思是建立工厂。"}, {"text": "社章", "is_correct": false, "explanation": "zhāng（第一声）与 zhǎng（第三声）声调不同；社章意思是社团的章程。"}, {"text": "设障", "is_correct": false, "explanation": "zhàng（第四声）与 zhǎng（第三声）声调不同；设障意思是设置障碍。"}], "explanations": {"社长": "正确。社长（shè zhǎng）指社团的负责人。", "设厂": "chǎng 与 zhǎng 只差声母 ch 与 zh，声调相同；设厂意思是建立工厂。", "社章": "zhāng（第一声）与 zhǎng（第三声）声调不同；社章意思是社团的章程。", "设障": "zhàng（第四声）与 zhǎng（第三声）声调不同；设障意思是设置障碍。"}, "sentence_index": null, "correct_answer": "社长"}, "level_3": {"options": [{"text": "校长", "is_correct": false, "explanation": "语义：“校长”指学校的负责人，与“摄影社”不符。"}, {"text": "社长", "is_correct": true, "explanation": "正确。社长是社团的负责人，“摄影社的社长是小王”自然。"}, {"text": "厂长", "is_correct": false, "explanation": "语义：“厂长”指工厂的负责人，与“摄影社”冲突。"}, {"text": "站长", "is_correct": false, "explanation": "搭配：“站长”多用于车站、站点，不说“摄影社的站长”。"}], "explanations": {"校长": "语义：“校长”指学校的负责人，与“摄影社”不符。", "社长": "正确。社长是社团的负责人，“摄影社的社长是小王”自然。", "厂长": "语义：“厂长”指工厂的负责人，与“摄影社”冲突。", "站长": "搭配：“站长”多用于车站、站点，不说“摄影社的站长”。"}, "sentence_index": 0, "correct_answer": "社长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的社长每天收作业。", "explanation": "这里应该用〈班长〉。社长指社团的负责人，班里管事的人要用班长。"}, {"text": "我们小组的社长负责发言。", "explanation": "这里应该用〈组长〉。小组里的负责人是组长，社长只用于社团等机构。"}, {"text": "我们学院的社长明天开会。", "explanation": "这里应该用〈院长〉。学院的负责人是院长，社长不用于学院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96065, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老师", "is_correct": false, "explanation": "语义：“老师”是教书的人，与“大三的学生”身份冲突。"}, {"text": "社长", "is_correct": true, "explanation": "正确。社长是社团的负责人，大三学生可以担任，句子通顺。"}, {"text": "教授", "is_correct": false, "explanation": "语义：“教授”是教师职称，不能指大三的学生。"}, {"text": "院长", "is_correct": false, "explanation": "搭配：“院长”指学院或医院的负责人，不与“大三的学生”这一身份搭配。"}], "explanations": {"老师": "语义：“老师”是教书的人，与“大三的学生”身份冲突。", "社长": "正确。社长是社团的负责人，大三学生可以担任，句子通顺。", "教授": "语义：“教授”是教师职称，不能指大三的学生。", "院长": "搭配：“院长”指学院或医院的负责人，不与“大三的学生”这一身份搭配。"}, "sentence_index": 6, "correct_answer": "社长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们连队的社长每天早上带队跑步。", "explanation": "这里应该用〈连长〉。社长指社团等机构的负责人，部队里带队的人要用连长。"}, {"text": "我们年级的社长组织了春游。", "explanation": "这里应该用〈年级主任〉。社长不用于年级，年级的负责人要说年级主任。"}, {"text": "我们车间的社长今天调整了排班。", "explanation": "这里应该用〈车间主任〉。社长不用于车间，车间的负责人要说车间主任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96065, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们社的那只社长是个热心人。", "corrected_sentence": "我们社的那位社长是个热心人。", "error_description": "量词错误：“社长”指人，应用量词“位”（或“个”）；“只”用于动物，不能用于社长。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96065, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们社刚选着一位新社长。", "corrected_sentence": "我们社刚选了一位新社长。", "error_description": "体标错误：“选”是已完成的动作，应用“了”；“着”表示持续状态，与“刚”冲突，应说“刚选了一位新社长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
