INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96066, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "合作社、报社或出版社等机构的负责人。", "primary_collocate": null, "pronunciation": "shè zhǎng", "ipa": "ʂɤ˥˩ tʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "报社的社长很忙。", "target_word": "社长", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家报社的社长是一位老先生。", "target_word": "社长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "合作社的社长带大家种茶叶。", "target_word": "社长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的合作社选了一位新社长。", "target_word": "社长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "社长说，报社今年要办一份新报纸。", "target_word": "社长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在报社工作了二十年，去年当上了社长。", "target_word": "社长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家出版社的社长常常亲自看稿子。", "target_word": "社长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "合作社的社长把今年的收入告诉了大家。", "target_word": "社长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报社的社长对记者们说，新闻一定要真实。", "target_word": "社长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老社长退休以后，年轻的记者当上了新社长。", "target_word": "社长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "副社长", "label": "复合"}, {"form": "社長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "社长｜报社、合作社、出版社等机构的负责人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '583bb385-0709-452e-bca1-846a97360e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96066, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "社长", "is_correct": true, "explanation": "正确。社长（shè zhǎng）指报社、合作社等机构的负责人。"}, {"text": "设厂", "is_correct": false, "explanation": "chǎng 与 zhǎng 只差声母 ch 与 zh，声调相同；设厂意思是建立工厂。"}, {"text": "社章", "is_correct": false, "explanation": "zhāng（第一声）与 zhǎng（第三声）声调不同；社章意思是社团的章程。"}, {"text": "设障", "is_correct": false, "explanation": "zhàng（第四声）与 zhǎng（第三声）声调不同；设障意思是设置障碍。"}], "explanations": {"社长": "正确。社长（shè zhǎng）指报社、合作社等机构的负责人。", "设厂": "chǎng 与 zhǎng 只差声母 ch 与 zh，声调相同；设厂意思是建立工厂。", "社章": "zhāng（第一声）与 zhǎng（第三声）声调不同；社章意思是社团的章程。", "设障": "zhàng（第四声）与 zhǎng（第三声）声调不同；设障意思是设置障碍。"}, "sentence_index": null, "correct_answer": "社长"}, "level_3": {"options": [{"text": "校长", "is_correct": false, "explanation": "语义：“校长”指学校的负责人，与前面的“报社”冲突。"}, {"text": "社长", "is_correct": true, "explanation": "正确。社长是报社的负责人，“报社的社长很忙”自然。"}, {"text": "厂长", "is_correct": false, "explanation": "语义：“厂长”指工厂的负责人，与“报社”不符。"}, {"text": "班长", "is_correct": false, "explanation": "搭配：报社里不设“班”，不能说“报社的班长”。"}], "explanations": {"校长": "语义：“校长”指学校的负责人，与前面的“报社”冲突。", "社长": "正确。社长是报社的负责人，“报社的社长很忙”自然。", "厂长": "语义：“厂长”指工厂的负责人，与“报社”不符。", "班长": "搭配：报社里不设“班”，不能说“报社的班长”。"}, "sentence_index": 0, "correct_answer": "社长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们组的社长每天收作业。", "explanation": "这里应该用〈组长〉。社长指社团、报社、合作社等机构的负责人，班组里管事的人要用组长。"}, {"text": "这所学校的社长很严格。", "explanation": "这里应该用〈校长〉。社长不用于学校，学校的负责人要说校长。"}, {"text": "这所医院的社长每周来查房。", "explanation": "这里应该用〈院长〉。医院的负责人是院长，社长只用于社团、报社、合作社等机构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96066, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "团长", "is_correct": false, "explanation": "语义：“团长”指剧团、团体的负责人，与“出版社”不符。"}, {"text": "社长", "is_correct": true, "explanation": "正确。社长是出版社的负责人，“亲自看稿子”与其身份相符。"}, {"text": "司令", "is_correct": false, "explanation": "语义：“司令”是军队的指挥官，不是出版社的负责人。"}, {"text": "站长", "is_correct": false, "explanation": "语义：“站长”指车站、站点的负责人，与“出版社”冲突。"}], "explanations": {"团长": "语义：“团长”指剧团、团体的负责人，与“出版社”不符。", "社长": "正确。社长是出版社的负责人，“亲自看稿子”与其身份相符。", "司令": "语义：“司令”是军队的指挥官，不是出版社的负责人。", "站长": "语义：“站长”指车站、站点的负责人，与“出版社”冲突。"}, "sentence_index": 6, "correct_answer": "社长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所幼儿园的社长每周都来园里查看。", "explanation": "这里应该用〈园长〉。社长不用于幼儿园，幼儿园的负责人要说园长。"}, {"text": "这个车站的社长今天很忙。", "explanation": "这里应该用〈站长〉。社长不用于车站，车站的负责人要说站长。"}, {"text": "这支球队的社长带头训练。", "explanation": "这里应该用〈队长〉。社长不用于球队，球队里带头的人要说队长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96066, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只社长很热心。", "corrected_sentence": "这位社长很热心。", "error_description": "量词错误：“社长”指人，应用量词“位”（或“个”）；“只”用于动物，不能说“这只社长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96066, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "合作社刚选出着新社长。", "corrected_sentence": "合作社刚选出了新社长。", "error_description": "体标错误：“选出”是已完成的动作，应用“了”；“着”表示持续状态，与“刚”冲突，应说“刚选出了新社长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96067, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "修建", "is_correct": false, "explanation": "修建指建造，与“禁”（不许）没有反义关系。"}, {"text": "允许", "is_correct": true, "explanation": "正确。允许与“禁”（不许）是反义词，表示准许。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论指交换意见，与“禁”没有反义关系。"}, {"text": "解释", "is_correct": false, "explanation": "解释指说明道理，与“禁”没有反义关系。"}], "correct_answer": "允许", "explanations": {"修建": "修建指建造，与“禁”（不许）没有反义关系。", "允许": "正确。允许与“禁”（不许）是反义词，表示准许。", "讨论": "讨论指交换意见，与“禁”没有反义关系。", "解释": "解释指说明道理，与“禁”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96067, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "种植", "is_correct": false, "explanation": "种植指栽培植物，与“禁”（不许）没有反义关系。"}, {"text": "允许", "is_correct": true, "explanation": "正确。允许与“禁”（不许）是反义词，表示准许。"}, {"text": "观察", "is_correct": false, "explanation": "观察指仔细看，与“禁”没有反义关系。"}, {"text": "收集", "is_correct": false, "explanation": "收集指聚拢、搜集，与“禁”没有反义关系。"}], "correct_answer": "允许", "explanations": {"种植": "种植指栽培植物，与“禁”（不许）没有反义关系。", "允许": "正确。允许与“禁”（不许）是反义词，表示准许。", "观察": "观察指仔细看，与“禁”没有反义关系。", "收集": "收集指聚拢、搜集，与“禁”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96067, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "禁是不让做，不许做。", "primary_collocate": null, "pronunciation": "jìn", "ipa": "tɕin˥˩", "syllable_count": 1, "sentences": [{"text": "学校禁手机。", "target_word": "禁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医院里禁烟，请到外面去。", "target_word": "禁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小区禁养大狗。", "target_word": "禁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条路禁车，你走别的路吧。", "target_word": "禁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家商场禁宠物入内，门口有牌子。", "target_word": "禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里禁停车，车要停到停车场。", "target_word": "禁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林公园里禁火，游客不能带打火机。", "target_word": "禁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年这个城市禁了摩托车，路上安静多了。", "target_word": "禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里禁大声说话，所以大家都很安静。", "target_word": "禁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园禁钓鱼，大家都在草地上玩。", "target_word": "禁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "禁了", "label": "体标"}, {"form": "禁过", "label": "体标"}, {"form": "禁烟", "label": "复合"}], "register": "中性", "sense_fingerprint": "禁｜规定不让做、不许做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '583bb385-0709-452e-bca1-846a97360e52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96067, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "禁", "is_correct": true, "explanation": "正确。禁（jìn）意思是不许、不让做。"}, {"text": "金", "is_correct": false, "explanation": "jīn（第一声）与 jìn（第四声）声调不同；金意思是金子。"}, {"text": "紧", "is_correct": false, "explanation": "jǐn（第三声）与 jìn（第四声）声调不同；紧意思是紧张、紧密。"}, {"text": "静", "is_correct": false, "explanation": "jìng 与 jìn 韵尾不同（ng 与 n）；静意思是安静。"}, {"text": "今", "is_correct": false, "explanation": "jīn（第一声）与 jìn（第四声）声调不同；今意思是现在、今天。"}], "explanations": {"禁": "正确。禁（jìn）意思是不许、不让做。", "金": "jīn（第一声）与 jìn（第四声）声调不同；金意思是金子。", "紧": "jǐn（第三声）与 jìn（第四声）声调不同；紧意思是紧张、紧密。", "静": "jìng 与 jìn 韵尾不同（ng 与 n）；静意思是安静。", "今": "jīn（第一声）与 jìn（第四声）声调不同；今意思是现在、今天。"}, "sentence_index": null, "correct_answer": "禁"}, "level_3": {"options": [{"text": "鼓励", "is_correct": false, "explanation": "配价：“鼓励”要接动作或人，不能直接接“手机”作宾语。"}, {"text": "禁", "is_correct": true, "explanation": "正确。禁是“不许”的意思，“学校禁手机”即不许带手机。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”的对象是人或活动，“欢迎手机”不成立。"}, {"text": "讲", "is_correct": false, "explanation": "搭配：“讲”不与“手机”这类物品搭配，“学校讲手机”不通。"}], "explanations": {"鼓励": "配价：“鼓励”要接动作或人，不能直接接“手机”作宾语。", "禁": "正确。禁是“不许”的意思，“学校禁手机”即不许带手机。", "欢迎": "语义：“欢迎”的对象是人或活动，“欢迎手机”不成立。", "讲": "搭配：“讲”不与“手机”这类物品搭配，“学校讲手机”不通。"}, "sentence_index": 0, "correct_answer": "禁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府禁了每户的购买数量。", "explanation": "这里应该用〈限制〉。禁是完全不许做某事，不能用于数量；〈限制〉可以限定数量。"}, {"text": "多喝水能禁感冒。", "explanation": "这里应该用〈预防〉。禁是依规定或权威不许人做某事，“感冒”不是人的行为，不能用禁。"}, {"text": "大雨禁了我们出门。", "explanation": "这里应该用〈阻止〉。禁是依规定或权威不许做某事，“大雨”不能下禁令，只能说阻止。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96067, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "禁", "is_correct": true, "explanation": "正确。禁（jìn）意思是不许、不让做。"}, {"text": "净", "is_correct": false, "explanation": "jìng 与 jìn 韵尾不同（ng 与 n）；净意思是干净。"}, {"text": "筋", "is_correct": false, "explanation": "jīn（第一声）与 jìn（第四声）声调不同；筋意思是筋骨。"}, {"text": "谨", "is_correct": false, "explanation": "jǐn（第三声）与 jìn（第四声）声调不同；谨意思是谨慎。"}, {"text": "巾", "is_correct": false, "explanation": "jīn（第一声）与 jìn（第四声）声调不同；巾意思是毛巾。"}], "explanations": {"禁": "正确。禁（jìn）意思是不许、不让做。", "净": "jìng 与 jìn 韵尾不同（ng 与 n）；净意思是干净。", "筋": "jīn（第一声）与 jìn（第四声）声调不同；筋意思是筋骨。", "谨": "jǐn（第三声）与 jìn（第四声）声调不同；谨意思是谨慎。", "巾": "jīn（第一声）与 jìn（第四声）声调不同；巾意思是毛巾。"}, "sentence_index": null, "correct_answer": "禁"}, "level_3": {"options": [{"text": "点", "is_correct": false, "explanation": "语义：“点火”是生火，与“禁火”的规定及“不能带打火机”的语境冲突。"}, {"text": "禁", "is_correct": true, "explanation": "正确。禁是“不许”的意思，与“禁火”的规定相符。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧火”与前一分句的“禁火”规定相矛盾。"}, {"text": "带", "is_correct": false, "explanation": "搭配：“带”多接物品，“带火”不通，且与“不能带打火机”冲突。"}], "explanations": {"点": "语义：“点火”是生火，与“禁火”的规定及“不能带打火机”的语境冲突。", "禁": "正确。禁是“不许”的意思，与“禁火”的规定相符。", "烧": "语义：“烧火”与前一分句的“禁火”规定相矛盾。", "带": "搭配：“带”多接物品，“带火”不通，且与“不能带打火机”冲突。"}, "sentence_index": 6, "correct_answer": "禁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国家禁了那项旧规定。", "explanation": "这里应该用〈废除〉。禁是不许人做某事，“旧规定”不是行为，不能用禁。"}, {"text": "小树禁了视线。", "explanation": "这里应该用〈阻挡〉。禁用于不许做的行为，“视线”不是行为，不能用禁。"}, {"text": "法院禁了那项判决。", "explanation": "这里应该用〈撤销〉。禁是不许人做某事，已经作出的判决不能用禁来撤回。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96067, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个湖禁得游泳，大家别下去。", "corrected_sentence": "这个湖禁游泳，大家别下去。", "error_description": "结构错误：“得”只用于可能补语（如“禁得起”“禁得住”），“禁”后直接接宾语，应说“禁游泳”，不能说“禁得游泳”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96067, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校把手机禁。", "corrected_sentence": "学校把手机禁了。", "error_description": "体标缺失：“把”字句中动词“禁”后要带“了”或补语，说“把手机禁了”，不能说“把手机禁”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046611ce-cb3c-44d9-9e8b-90ca8b4172c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
