INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96069, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "笔记是上课或看书时，用笔记下来的重要东西。", "primary_collocate": null, "pronunciation": "bǐ jì", "ipa": "pi˨˩˦ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "上课的时候，我喜欢记笔记。", "target_word": "笔记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，重要的内容要写在笔记里。", "target_word": "笔记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的笔记写得又清楚又漂亮。", "target_word": "笔记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试以前，我向同学借了笔记。", "target_word": "笔记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能把你的笔记借给我看看吗？", "target_word": "笔记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天晚上都会整理一下当天的笔记。", "target_word": "笔记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份笔记很有用，我想复印一份。", "target_word": "笔记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他忘了带笔记，只好看书上的内容。", "target_word": "笔记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在书的旁边写着很多笔记。", "target_word": "笔记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的笔记丢了，明天的考试怎么办？", "target_word": "笔记", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "笔记本", "label": "复合"}, {"form": "读书笔记", "label": "复合"}, {"form": "筆記", "label": "繁体"}], "register": "通用", "sense_fingerprint": "名词，上课或看书时用笔记下来的重要内容，常说记笔记、借笔记", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea0b2d16-fd3c-4652-81a5-d83fbc5fa0b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96069, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "笔记", "is_correct": true, "explanation": "“笔记”在“记”后作宾语，“记笔记”指把重要内容记下来。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调不是可以“记”下的东西，句意不通。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是写字的板子，不是可以“记”下的东西。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，不是要记下的内容。"}], "explanations": {"笔记": "“笔记”在“记”后作宾语，“记笔记”指把重要内容记下来。", "空调": "语义：空调不是可以“记”下的东西，句意不通。", "黑板": "语义：黑板是写字的板子，不是可以“记”下的东西。", "书包": "语义：书包是装东西的袋子，不是要记下的内容。"}, "sentence_index": 0, "correct_answer": "笔记"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用笔记写名字。", "explanation": "这里应该用〈笔〉。笔记指记下来的内容，不是写字的工具。"}, {"text": "他写了三只笔记。", "explanation": "这里应该用〈页〉。量词“只”用于动物等，不用于笔记。"}, {"text": "他渴了，喝了一杯笔记。", "explanation": "这里应该用〈水〉。笔记是记下来的内容，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96069, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "笔记", "is_correct": true, "explanation": "“笔记”是可以复印的纸本内容，与“有用”“复印”相合。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不能复印，与“复印一份”不合。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：手机用量词“部”，不说“这份手机”。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭不能复印，与“复印一份”冲突。"}], "explanations": {"笔记": "“笔记”是可以复印的纸本内容，与“有用”“复印”相合。", "花": "语义：花不能复印，与“复印一份”不合。", "手机": "搭配：手机用量词“部”，不说“这份手机”。", "饭": "语义：饭不能复印，与“复印一份”冲突。"}, "sentence_index": 6, "correct_answer": "笔记"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他累了，坐在笔记上休息。", "explanation": "这里应该用〈椅子〉。笔记是记下来的内容，不是坐的东西。"}, {"text": "他用笔记玩游戏。", "explanation": "这里应该用〈游戏机〉。笔记是记下的内容或本子，不能用来玩游戏。"}, {"text": "他用笔记把窗户擦得很亮。", "explanation": "这里应该用〈抹布〉。笔记指记下的内容，不能用来擦东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96069, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有两只笔记，都很整齐。", "corrected_sentence": "他有两份笔记，都很整齐。", "error_description": "错误形式：“两只笔记”。正确形式：“两份笔记”。“笔记”用量词“份”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96069, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把笔记的整理完了。", "corrected_sentence": "他把笔记整理完了。", "error_description": "错误形式：“把笔记的整理完了”。正确形式：“把笔记整理完了”。“笔记”作“整理”的宾语，中间不能插入“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2d9beb-2c4e-4fe3-b2dd-374d86aa5d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
