INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96072, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "神话传说中的灵异生物；也形容机灵可爱的人。", "primary_collocate": null, "pronunciation": "jīng líng", "ipa": "tɕiŋ˥ liŋ˧˥", "syllable_count": 2, "sentences": [{"text": "古代传说里，森林里住着许多精灵。", "target_word": "精灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神话中的精灵常常守护着泉水。", "target_word": "精灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们说，山里的精灵会保护旅人。", "target_word": "精灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人相信河里有精灵。", "target_word": "精灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小女孩又聪明又可爱，像个精灵。", "target_word": "精灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都叫她精灵，因为她又活泼又可爱。", "target_word": "精灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的女儿是家里的精灵，天天笑个不停。", "target_word": "精灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传说月亮上有一个精灵在跳舞。", "target_word": "精灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子机灵又可爱，真像一个精灵。", "target_word": "精灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那本神话书里写了不少精灵的故事。", "target_word": "精灵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小精灵", "label": "复合"}], "register": "中性", "sense_fingerprint": "神话传说里的灵异生物，也比喻机灵可爱的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea7a4939-1ea5-4472-88d4-95bdbfe97d09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96072, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "精灵", "is_correct": true, "explanation": "精灵：神话传说中的灵异生物，也形容机灵可爱的人。"}, {"text": "警铃", "is_correct": false, "explanation": "jǐng（第三声）与 jīng（第一声）声调不同，意思是报警用的铃。"}, {"text": "清灵", "is_correct": false, "explanation": "qīng 与 jīng 声母不同（送气与不送气），意思是清脆灵动。"}, {"text": "金陵", "is_correct": false, "explanation": "jīn 与 jīng 韵母不同（少了 ng），意思是南京的旧称。"}], "explanations": {"精灵": "精灵：神话传说中的灵异生物，也形容机灵可爱的人。", "警铃": "jǐng（第三声）与 jīng（第一声）声调不同，意思是报警用的铃。", "清灵": "qīng 与 jīng 声母不同（送气与不送气），意思是清脆灵动。", "金陵": "jīn 与 jīng 韵母不同（少了 ng），意思是南京的旧称。"}, "sentence_index": null, "correct_answer": "精灵"}, "level_3": {"options": [{"text": "课桌", "is_correct": false, "explanation": "语义：“住着许多”的对象应是能居住的生物，课桌不能住在森林里。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“住”要求有生命的施事，“石头”不能作“住”的主语。"}, {"text": "精灵", "is_correct": true, "explanation": "精灵：传说中的灵异生物，可以住在森林里。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟不会住在森林里，与“古代传说”的语境不符。"}], "explanations": {"课桌": "语义：“住着许多”的对象应是能居住的生物，课桌不能住在森林里。", "石头": "配价：“住”要求有生命的施事，“石头”不能作“住”的主语。", "精灵": "精灵：传说中的灵异生物，可以住在森林里。", "闹钟": "语义：闹钟不会住在森林里，与“古代传说”的语境不符。"}, "sentence_index": 0, "correct_answer": "精灵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在河边看见一棵精灵，它在水面上跳舞。", "explanation": "这里应该用〈个〉。棵用于树木，不用来数灵异生物。"}, {"text": "我在河边捡到一块精灵，回家后它就不见了。", "explanation": "这里应该用〈个〉。块用于成块的东西，不能用来数精灵。"}, {"text": "传说山里住着一张精灵。", "explanation": "这里应该用〈个〉。张用于纸、桌子等平面的东西，不能用来数精灵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '235d198e-2778-4fda-9921-2382f6b79731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96072, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "精灵", "is_correct": true, "explanation": "精灵：神话传说中的灵异生物，也形容机灵可爱的人。"}, {"text": "精英", "is_correct": false, "explanation": "líng（第二声）与 yīng（第一声）声母和声调都不同，意思是精华、优秀的人。"}, {"text": "经营", "is_correct": false, "explanation": "líng 与 yíng 声母不同，意思是经营、管理。"}, {"text": "净零", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，意思是排放量与吸收量相抵为零。"}], "explanations": {"精灵": "精灵：神话传说中的灵异生物，也形容机灵可爱的人。", "精英": "líng（第二声）与 yīng（第一声）声母和声调都不同，意思是精华、优秀的人。", "经营": "líng 与 yíng 声母不同，意思是经营、管理。", "净零": "jìng（第四声）与 jīng（第一声）声调不同，意思是排放量与吸收量相抵为零。"}, "sentence_index": null, "correct_answer": "精灵"}, "level_3": {"options": [{"text": "精灵", "is_correct": true, "explanation": "精灵：这里指机灵可爱的人，与“天天笑个不停”的语境相合。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶不会笑，不能指家里天天笑个不停的孩子。"}, {"text": "台灯", "is_correct": false, "explanation": "语义：台灯不会笑，不能指家里天天笑个不停的孩子。"}, {"text": "木头", "is_correct": false, "explanation": "配价：“笑”要求有生命的施事，“木头”不能作主语。"}], "explanations": {"精灵": "精灵：这里指机灵可爱的人，与“天天笑个不停”的语境相合。", "花瓶": "语义：花瓶不会笑，不能指家里天天笑个不停的孩子。", "台灯": "语义：台灯不会笑，不能指家里天天笑个不停的孩子。", "木头": "配价：“笑”要求有生命的施事，“木头”不能作主语。"}, "sentence_index": 6, "correct_answer": "精灵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个女人被叫作精灵，因为她总爱用美貌勾引男人。", "explanation": "这里用的是“勾引男人的女妖”的意思，应该用〈妖精〉。精灵在这里指神话中的灵异生物或机灵可爱的人，不指这种女人。"}, {"text": "神话里说，泉水边有一条精灵。", "explanation": "这里应该用〈个〉。条用于细长的东西，不能用来数精灵。"}, {"text": "妈妈给我买了一块精灵做礼物。", "explanation": "这里应该用〈个〉。块用于成块的东西，不能用来数精灵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '235d198e-2778-4fda-9921-2382f6b79731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96072, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的孙子是棵精灵，总爱逗大家笑。", "corrected_sentence": "他的孙子是个精灵，总爱逗大家笑。", "error_description": "量词错误：错误形式是“棵精灵”，正确形式是“个精灵”。“棵”用于树木，不能用来数人，指人要用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '235d198e-2778-4fda-9921-2382f6b79731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96072, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那本书里有一棵会说话的精灵。", "corrected_sentence": "那本书里有一个会说话的精灵。", "error_description": "量词错误：错误形式是“一棵会说话的精灵”，正确形式是“一个会说话的精灵”。“棵”用于树木，不用来数精灵。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '235d198e-2778-4fda-9921-2382f6b79731') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
