INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96073, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "编写是把想法或材料整理好，写成书或文章。", "primary_collocate": null, "pronunciation": "biān xiě", "ipa": "pjɛn˥ ɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "王老师正在为小学生编写一本新的语文教材。", "target_word": "编写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把多年的想法整理好，编写成了一本书。", "target_word": "编写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们几个同学一起编写了一本家乡菜食谱。", "target_word": "编写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们为学校编写一份学习指南。", "target_word": "编写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她编写的故事书很受小朋友喜欢。", "target_word": "编写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把自己的经验编写成一篇文章。", "target_word": "编写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本词典是十几位专家一起编写的。", "target_word": "编写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编写这本书需要很多时间和耐心。", "target_word": "编写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李正在编写一本英语学习手册，明天要交给老师。", "target_word": "编写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请他编写一份新员工的学习材料。", "target_word": "编写", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "编写了", "label": "完成体"}, {"form": "编写过", "label": "经历体"}, {"form": "编写者", "label": "复合"}, {"form": "編寫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把想法或材料整理好，写成教材、手册等书或文章", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cf0b04c-87ef-4e5a-b3c9-d0d876e54ee1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96073, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”的对象是食物，不能用于教材。"}, {"text": "编写", "is_correct": true, "explanation": "“编写”指把材料整理成书，与“一本新的语文教材”搭配，符合句意。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”的对象是植物，不能用于教材。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：“提高”的宾语是水平、质量，不能说“提高一本教材”。"}], "explanations": {"烹饪": "语义：“烹饪”的对象是食物，不能用于教材。", "编写": "“编写”指把材料整理成书，与“一本新的语文教材”搭配，符合句意。", "种植": "语义：“种植”的对象是植物，不能用于教材。", "提高": "搭配：“提高”的宾语是水平、质量，不能说“提高一本教材”。"}, "sentence_index": 0, "correct_answer": "编写"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上都编写作业。", "explanation": "这里应该用〈写〉。作业是写出来的，“编写”指把材料整理成书或文稿。"}, {"text": "她每年冬天都为家人编写毛衣。", "explanation": "这里应该用〈编织〉。毛衣是用毛线编织出来的，“编写”用于书籍、文稿等资料。"}, {"text": "他每天早上都编写三公里。", "explanation": "这里应该用〈跑〉。三公里是跑出来的，“编写”指把材料整理成书或文稿，不能用于距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96073, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浇灌", "is_correct": false, "explanation": "语义：“浇灌”的对象是植物，不能用于词典。"}, {"text": "编写", "is_correct": true, "explanation": "“编写”指把资料整理成书，与“这本词典”搭配，符合句意。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”的对象是房间或场所，不能说打扫词典。"}, {"text": "烧制", "is_correct": false, "explanation": "搭配：“烧制”用于陶瓷、砖瓦等，不说烧制词典。"}], "explanations": {"浇灌": "语义：“浇灌”的对象是植物，不能用于词典。", "编写": "“编写”指把资料整理成书，与“这本词典”搭配，符合句意。", "打扫": "语义：“打扫”的对象是房间或场所，不能说打扫词典。", "烧制": "搭配：“烧制”用于陶瓷、砖瓦等，不说烧制词典。"}, "sentence_index": 6, "correct_answer": "编写"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在墙上编写了一幅壁画。", "explanation": "这里应该用〈绘制〉。壁画是用颜料绘制出来的，“编写”指把资料整理成文字或书籍。"}, {"text": "孩子们在沙滩上编写了一座城堡。", "explanation": "这里应该用〈堆〉。城堡是用沙子堆出来的，“编写”不能用于建造实体物件。"}, {"text": "他用纸编写了一只纸鹤。", "explanation": "这里应该用〈折〉。纸鹤是把纸折出来的，“编写”指把材料整理成书或文字，不能用于折纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96073, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把这些笔记编写。", "corrected_sentence": "她把这些笔记编写成一本书。", "error_description": "错误：“把”字句中“编写”后缺少补语。应为“编写成一本书”。“成”表示笔记被整理成一本书。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96073, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一个人把一本英语教材编写。", "corrected_sentence": "她一个人把一本英语教材编写完了。", "error_description": "错误：“把”字句中“编写”后缺少补语。应为“编写完了”。“完了”表示这本教材已经编写完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab82dc67-8bb1-4235-a559-ce3bba195325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
